import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Delete a shopping cart by cartId (aimall_backend_carts).
 *
 * Remove a shopping cart identified by UUID. This is a hard delete operation,
 * as the aimall_backend_carts schema does not define any soft deletion
 * strategy. Related cart items are automatically removed via cascading
 * relations defined in the schema.
 *
 * Delete operations validate user authorization (owner only). Attempts to
 * delete non-existent or unauthorized carts result in error. Deletion is
 * irreversible and logged for compliance and audit. Used for cart abandonment
 * cleanup, session invalidation, or admin troubleshooting.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (payload)
 * @param props.cartId - UUID of the shopping cart to be deleted
 * @returns Void
 * @throws {Error} When the cart does not exist
 * @throws {Error} When attempting to delete a cart not owned by the customer
 */
export async function delete__aimall_backend_customer_carts_$cartId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, cartId } = props;

  // Step 1: Fetch cart and check existence
  const cart = await MyGlobal.prisma.aimall_backend_carts.findUnique({
    where: { id: cartId },
    select: {
      id: true,
      aimall_backend_customer_id: true,
    },
  });
  if (!cart) throw new Error("Cart not found");

  // Step 2: Authorization check (ownership)
  if (cart.aimall_backend_customer_id !== customer.id) {
    throw new Error("Unauthorized: only the owner may delete their cart");
  }

  // Step 3: Hard delete (cascade deletes related cart items)
  await MyGlobal.prisma.aimall_backend_carts.delete({
    where: { id: cartId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Soft deletes a community post by postId; sets deleted_at but keeps record.
 *
 * Soft deletes a post in the community by updating the deleted_at field to the
 * current timestamp. This disables regular retrieval for general users but
 * retains the record for audit and potential restoration. Only the original
 * author (seller) may delete; ownership validation and permission checks are
 * enforced. Attempting to delete posts not found, already deleted, or without
 * permission returns errors. Hard deletion requires additional intervention or
 * future schema extensions.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller (ownership/authorization enforced)
 * @param props.postId - Unique identifier of the post to delete (soft delete)
 * @returns Void
 * @throws {Error} When post not found
 * @throws {Error} When post is already deleted
 * @throws {Error} When the seller is not the post's owner
 */
export async function delete__aimall_backend_seller_posts_$postId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, postId } = props;
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post) throw new Error("Post not found");
  if (post.deleted_at) throw new Error("Post already deleted");
  if (!post.customer_id || post.customer_id !== seller.id)
    throw new Error(
      "Not authorized: only the post's owner may delete this post",
    );

  await MyGlobal.prisma.aimall_backend_posts.update({
    where: { id: postId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Permanently delete a configuration entity by ID (hard delete,
 * aimall_backend_configurations table).
 *
 * This function performs a hard delete of the configuration record specified by
 * configurationId. The operation is irreversible and the record is permanently
 * removed from the database. No soft delete is performed, as the model does not
 * support it.
 *
 * Security: Only system administrators may perform this operation (enforced by
 * the administrator authentication decorator).
 *
 * @param props - Request object.
 * @param props.administrator - Authenticated administrator payload (must be
 *   active).
 * @param props.configurationId - The unique UUID of the system configuration
 *   entity to delete.
 * @returns Returns nothing on success.
 * @throws {Error} If the configuration does not exist, throws an Error with
 *   message "Configuration not found" and status 404 (Not Found).
 */
export async function delete__aimall_backend_administrator_configurations_$configurationId(props: {
  administrator: AdministratorPayload;
  configurationId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { configurationId } = props;

  // Check configuration existence; if not found, throw 404
  const config = await MyGlobal.prisma.aimall_backend_configurations.findFirst({
    where: { id: configurationId },
  });
  if (!config) {
    const error: Error & { status?: number } = new Error(
      "Configuration not found",
    );
    error.status = 404;
    throw error;
  }

  // Hard delete (permanently remove the row)
  await MyGlobal.prisma.aimall_backend_configurations.delete({
    where: { id: configurationId },
  });
  // Return void (success)
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Hard deletes a product from the product catalog by its UUID.
 *
 * This operation removes the product row from 'aimall_backend_products' table.
 * Only system administrators may perform this operation. Customers cannot
 * access this endpoint.
 *
 * If the product is still referenced by dependent entities (e.g., orders),
 * deletion will fail due to foreign key constraints, and an error will be
 * thrown.
 *
 * All delete attempts should be logged for audit and security, but this is
 * handled elsewhere.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   deletion.
 * @param props.productId - UUID of the product to be deleted.
 * @returns Void
 * @throws {Error} When the product is still referenced or database constraints
 *   block deletion.
 * @throws {Error} When the product does not exist.
 */
export async function delete__aimall_backend_administrator_products_$productId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, productId } = props;

  try {
    await MyGlobal.prisma.aimall_backend_products.delete({
      where: { id: productId },
    });
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      // Foreign key constraint violation (currently referenced elsewhere)
      if (error.code === "P2003") {
        throw new Error(
          "Cannot delete product: It is referenced by other entities (e.g., orders, assignments, reviews).",
        );
      }
      // Record not found
      if (error.code === "P2025") {
        throw new Error("Product does not exist.");
      }
    }
    throw new Error("Failed to delete product: " + (error as Error).message);
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Soft deletes a community post by setting deleted_at to the current timestamp.
 *
 * The post remains in the system for audit and potential restoration but is no
 * longer visible in standard queries. Only the original author is permitted to
 * delete their own post. Attempts to delete posts not owned or already deleted
 * will result in an error.
 *
 * @param props - Request properties.
 * @param props.customer - Authenticated customer performing the delete request.
 * @param props.postId - Unique identifier of the post to soft delete (UUID).
 * @returns Void
 * @throws {Error} If the post is not found, already deleted, or the customer
 *   does not own the post.
 */
export async function delete__aimall_backend_customer_posts_$postId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, postId } = props;
  // Fetch the post by ID
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post) throw new Error("Post not found.");

  // Check if already soft-deleted
  if (post.deleted_at !== null && post.deleted_at !== undefined) {
    throw new Error("Post already deleted.");
  }

  // Check if current user is the post's author
  if (!post.customer_id || post.customer_id !== customer.id) {
    throw new Error("Unauthorized: You can only delete your own posts.");
  }

  // Soft delete: set deleted_at and updated_at to now
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.aimall_backend_posts.update({
