import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Permanently deletes a product from the catalog by unique productId for the
 * authenticated seller.
 *
 * This endpoint performs a hard delete (non-recoverable) from
 * aimall_backend_products by UUID. Only the owning seller may delete their own
 * product. Attempts to delete products owned by another seller are forbidden.
 * If the product is referenced by dependent data (such as historical order
 * records), the deletion is blocked and an error is thrown.
 *
 * All delete attempts are subject to audit, and a 404 error is thrown if the
 * product does not exist. On referential integrity error (e.g., the product is
 * still referenced), a conflict error is thrown. No content is returned on
 * success.
 *
 * @param props - The request properties
 * @param props.seller - The authenticated seller (must match the product's
 *   owner)
 * @param props.productId - UUID of the product to delete from the catalog
 * @returns Void
 * @throws {Error} 404 if the product is not found
 * @throws {Error} 403 if the seller does not own the product
 * @throws {Error} 409 if the product cannot be deleted due to existing
 *   references (e.g., in orders)
 */
export async function delete__aimall_backend_seller_products_$productId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, productId } = props;

  // Lookup product (must exist)
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) throw new Error("Product not found");

  // Confirm ownership (must be seller's own product)
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: You are not the owner of this product");
  }

  // Attempt hard delete (will fail if references exist)
  try {
    await MyGlobal.prisma.aimall_backend_products.delete({
      where: { id: productId },
    });
  } catch (error: unknown) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2003" // foreign key constraint failure
    ) {
      throw new Error(
        "Conflict: Product cannot be deleted because it is still referenced by other records",
      );
    }
    throw error;
  }
}

