/**
 * Soft-delete a product review by reviewId (set deleted_at timestamp).
 *
 * This endpoint marks a product review as deleted by updating the deleted_at
 * column with the current timestamp for the record identified by reviewId. Soft
 * deletion preserves the data for audit and compliance while hiding it from
 * normal user-facing queries. Only the customer who authored the review or an
 * authorized administrator can invoke this deletion; unauthorized attempts are
 * rejected and logged for security compliance.
 *
 * The operation implements full business logic for soft delete: all result sets
 * exclude rows where deleted_at is not null, and restores are only possible via
 * audit/admin special flows. Hard/physical deletion is never performed via this
 * API endpoint to ensure legal and operational defensibility.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer
 * @param props.reviewId - The UUID of the review to soft-delete
 * @returns Void
 * @throws {Error} If the review does not exist
 * @throws {Error} If the review is already deleted
 * @throws {Error} If the customer is not the review author
 */
export async function delete__aimall_backend_customer_reviews_$reviewId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, reviewId } = props;

  // 1. Fetch the review by ID, retrieve minimal fields
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { customer_id: true, deleted_at: true },
  });
  if (!review) {
    throw new Error("Review not found.");
  }

  // 2. Cannot delete if already soft-deleted
  if (review.deleted_at !== null) {
    throw new Error("This review has already been deleted.");
  }

  // 3. Ownership authorization: only author can delete
  if (review.customer_id !== customer.id) {
    throw new Error("Unauthorized: Only the author may delete this review.");
  }

  // 4. Update the deleted_at timestamp (soft delete)
  await MyGlobal.prisma.aimall_backend_reviews.update({
    where: { id: reviewId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });

  return;
}

