import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Logically deletes a comment by soft-deleting (setting deleted_at) in
 * aimall_backend_comments.
 *
 * Only allows deletion by the comment's author (authenticated customer). Hard
 * deletes are disallowed; deleted_at is set for audit/compliance.
 *
 * @param props -
 *
 *   - Customer: Authenticated CustomerPayload (must own the comment)
 *   - CommentId: UUID of the comment to soft-delete
 *
 * @returns Void
 * @throws {Error} If comment not found or already deleted
 * @throws {Error} If the user is not the author of the comment
 */
export async function delete__aimall_backend_customer_comments_$commentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, commentId } = props;

  // Fetch the comment by primary key, only if not already soft deleted
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: commentId },
    select: { id: true, customer_id: true, deleted_at: true },
  });
  if (!comment || comment.deleted_at) {
    throw new Error("Comment not found");
  }
  // Ownership check: customer_id must match
  if (comment.customer_id !== customer.id) {
    throw new Error("Forbidden: not the author of this comment");
  }
  const now = toISOStringSafe(new Date());

  // Update the comment with deleted_at, updated_at
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });
  // No return
}

