/**
 * Delete a coupon voucher record (Coupon table, admin-only, hard delete).
 *
 * Removes (hard deletes) a coupon/voucher record identified by couponId.
 * Adheres to business and compliance requirements—real deletion occurs since
 * there is no schema provision for soft/historical state. Only system
 * administrators, service automation, or compliance enforcement code may call
 * this endpoint directly.
 *
 * A successful operation purges the row. Errors are returned for missing or
 * already-removed UUIDs. Deletion is permitted only for coupons with status
 * 'issued'. Deletion is not permitted for 'redeemed' or 'expired' coupons.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   delete
 * @param props.couponId - UUID of the coupon to delete (voucher)
 * @returns Void
 * @throws {Error} When coupon does not exist
 * @throws {Error} When the coupon cannot be deleted due to its status
 */
export async function delete__aimall_backend_administrator_coupons_$couponId(props: {
  administrator: AdministratorPayload;
  couponId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, couponId } = props;
  // Fetch the coupon record by ID
  const coupon = await MyGlobal.prisma.aimall_backend_coupons.findUnique({
    where: { id: couponId },
  });
  if (!coupon) {
    throw new Error("Coupon not found");
  }
  // Business: Deletion allowed only for 'issued' coupons
  if (coupon.status !== "issued") {
    throw new Error("Cannot delete redeemed or expired coupons");
