 *   (optional/null for external SSO)
 * @param props.body.status - Initial status (active, pending, etc.)
 * @returns Newly registered customer (fully populated with id and timestamps)
 * @throws {Error} On DB constraint violation (e.g., duplicate email/phone)
 */
export async function post__aimall_backend_customers(props: {
  body: IAimallBackendCustomer.ICreate;
}): Promise<IAimallBackendCustomer> {
  const { body } = props;

  // Generate new UUID and system timestamps
  const id = v4() as string & tags.Format<"uuid">;
