/**
 * Delete (unlink) an external account linkage for a customer (Actors DB).
 *
 * Delete the linkage between a customer's account and a specific external
 * (federated) account. This is used for de-linking OAuth/OpenID logins, account
 * unlinking UI, or in response to a federated identity compromise request.
 *
 * As no soft delete field exists, this operation performs a hard delete of the
 * external account record. Only the customer or a privileged admin may perform
 * this delete. All operations are fully audited for compliance.
 *
 * Related login tokens via the provider may be invalidated after removal, and
 * re-linking would require fresh OAuth verification.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer JWT payload. Must match the
 *   account being managed.
 * @param props.customerId - Unique identifier of the customer whose external
 *   account link is being deleted
 * @param props.externalAccountId - Unique identifier of the external account
 *   linkage being deleted
 * @returns Void
 * @throws {Error} When the customer does not match the authenticated user
 * @throws {Error} When the external account does not exist or is not linked to
 *   the customer
 */
export async function delete__aimall_backend_customer_customers_$customerId_externalAccounts_$externalAccountId(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  externalAccountId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Step 1: Authorization - only the customer who owns the account can perform this operation
  if (props.customer.id !== props.customerId) {
    throw new Error(
      "Unauthorized: You may only manage your own external accounts.",
    );
  }

  // Step 2: Find and verify ownership of external account
  const external =
    await MyGlobal.prisma.aimall_backend_external_accounts.findFirst({
      where: {
        id: props.externalAccountId,
        customer_id: props.customerId,
      },
    });
  if (!external) {
    throw new Error("External account not found for this customer.");
  }

  // Step 3: Hard delete the external account (no soft-delete field present)
  await MyGlobal.prisma.aimall_backend_external_accounts.delete({
    where: { id: props.externalAccountId },
  });
}

