import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Deletes a support ticket by its UUID (hard deletion, no soft deletion).
 *
 * This endpoint allows platform administrators to delete a support ticket by
 * UUID. As the "aimall_backend_support_tickets" model has no soft-delete field,
 * this is a true (hard) delete: the ticket is permanently removed and cannot be
 * restored.
 *
 * An audit log entry is created for compliance and traceability. Business logic
 * forbids deletion if the ticket has status 'pending'. Only administrators
 * (validated via AdministratorAuth) may perform this operation.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   deletion
 * @param props.supportTicketId - UUID of the support ticket to delete
 * @returns Void
 * @throws {Error} If the support ticket does not exist
 * @throws {Error} If the ticket is in 'pending' status and cannot be deleted
 */
export async function delete__aimall_backend_administrator_supportTickets_$supportTicketId(props: {
  administrator: AdministratorPayload;
  supportTicketId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, supportTicketId } = props;

  // 1. Fetch the ticket
  const ticket =
    await MyGlobal.prisma.aimall_backend_support_tickets.findUnique({
      where: { id: supportTicketId },
    });
  if (ticket == null) {
    throw new Error("Support ticket not found");
  }

  // 2. Check that the ticket is not pending
  if (ticket.status === "pending") {
    throw new Error("Cannot delete a ticket in pending status");
  }

  // 3. Hard delete the support ticket
  await MyGlobal.prisma.aimall_backend_support_tickets.delete({
    where: { id: supportTicketId },
  });

  // 4. Write an audit log entry for traceability
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "SUPPORT_TICKET_DELETE",
      event_target: supportTicketId,
      ip_address: undefined,
      outcome: "SUCCESS",
      detail_json: undefined,
      created_at: toISOStringSafe(new Date()),
    },
  });
}

