    );
    if (activeReply) {
      throw new Error(
        "Cannot delete parent comment with active (non-deleted) replies",
      );
    }
  }

  // Step 6: Perform the soft-delete by setting deleted_at to the current ISO string
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
  // You would insert an audit log here if audit system is in place.
}

