 * @throws {Error} When a channel with the provided code already exists, or on
 *   DB error
 */
export async function post__aimall_backend_administrator_channels(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendChannel.ICreate;
}): Promise<IAimallBackendChannel> {
