import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Deletes (archives) an order by its UUID. As an administrator, soft-deletes by
 * updating archived_at (if present), otherwise does a hard delete. Throws
 * errors for missing or already-archived orders, or orders in states that
 * cannot be archived.
 *
 * This endpoint allows platform administrators to logically delete (archive) an
 * order record by ID. If the aimall_backend_orders model contains an
 * 'archived_at' field, the operation soft-deletes by updating this timestamp;
 * if not, a hard delete would be performed. The operation is blocked for orders
 * already archived or in finalized/fulfilled status (e.g. delivered, cancelled,
 * returned, refunded). Deletions are strictly allowed only for administrators
 * and never affect related records such as order items, payments, or
 * shipments.
 *
 * @param props - Props object with authentication and orderId.
 * @param props.administrator - The authenticated administrator
 *   (AdministratorPayload).
 * @param props.orderId - The UUID of the order to archive/delete.
 * @returns Void
 * @throws {Error} When order is not found, already archived, or in a finalized
 *   status.
 */
export async function delete__aimall_backend_administrator_orders_$orderId(props: {
  administrator: AdministratorPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, orderId } = props;

  // Fetch minimal fields for business validation
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { id: true, archived_at: true, order_status: true },
  });
  if (!order) throw new Error("Order not found");

  // Prevent double archiving
  if (order.archived_at !== null) throw new Error("Order is already archived");

  // Business rule: orders that are finalized cannot be archived (configurable list)
  const finalizedStatuses = ["delivered", "cancelled", "returned", "refunded"];
  if (finalizedStatuses.includes(order.order_status)) {
    throw new Error(
      `Cannot archive an order with finalized status ('${order.order_status}')`,
    );
  }

  // Soft delete (archive) by updating archived_at and updated_at
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.aimall_backend_orders.update({
    where: { id: orderId },
    data: {
      archived_at: now,
      updated_at: now,
    },
  });
}

