import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCart";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Creates a new shopping cart instance, assigned either to a customer or an
 * anonymous session.
 *
 * Ensures uniqueness: only one cart per customer or session can exist at any
 * time. Automatically assigns creation and update timestamps if not provided.
 * Enforces that at least one of customer ID or session token is supplied.
 *
 * Admins can create carts for any customer or guest session; the function
 * enforces referential integrity and raises errors on uniqueness violations.
 *
 * @param props - Request parameters
 * @param props.administrator - Authenticated administrator creating the cart
 *   (privileged)
 * @param props.body - Cart creation data (customer_id and/or session_token,
 *   optionally timestamps)
 * @returns The created cart with all key fields and current item count
 * @throws {Error} When both aimall_backend_customer_id and session_token are
 *   missing
 * @throws {Error} When a cart already exists for the provided customer or
 *   session_token
 */
export async function post__aimall_backend_administrator_carts(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendCart.ICreate;
}): Promise<IAimallBackendCart> {
  const { administrator, body } = props;

  // Enforce that at least one of customer ID or session_token is present
  if (!body.aimall_backend_customer_id && !body.session_token) {
    throw new Error(
      "Either aimall_backend_customer_id or session_token must be provided",
    );
  }

  // Uniqueness: If creating for a customer, ensure no cart exists for that customer
  if (body.aimall_backend_customer_id) {
    const customerCart = await MyGlobal.prisma.aimall_backend_carts.findFirst({
      where: { aimall_backend_customer_id: body.aimall_backend_customer_id },
    });
    if (customerCart) {
      throw new Error("A cart already exists for this customer");
    }
  } else if (body.session_token) {
    // Uniqueness: If creating for a guest cart, ensure no cart exists with that session_token
    const guestCart = await MyGlobal.prisma.aimall_backend_carts.findFirst({
      where: { session_token: body.session_token },
    });
    if (guestCart) {
      throw new Error("A cart already exists for this session");
    }
  }

  // UUID and timestamps: always generate with correct type
  const cartId = v4() as string & tags.Format<"uuid">;
  const created_at: string & tags.Format<"date-time"> = body.created_at
    ? toISOStringSafe(body.created_at)
    : toISOStringSafe(new Date());
  const updated_at: string & tags.Format<"date-time"> = body.updated_at
    ? toISOStringSafe(body.updated_at)
    : toISOStringSafe(new Date());

  const created = await MyGlobal.prisma.aimall_backend_carts.create({
    data: {
      id: cartId,
      aimall_backend_customer_id: body.aimall_backend_customer_id ?? null,
      session_token: body.session_token ?? null,
      created_at,
      updated_at,
    },
  });

  const cart_items_count =
    await MyGlobal.prisma.aimall_backend_cart_items.count({
      where: { aimall_backend_cart_id: created.id },
    });

  return {
    id: created.id as string & tags.Format<"uuid">,
    aimall_backend_customer_id: created.aimall_backend_customer_id ?? undefined,
    session_token: created.session_token ?? undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    cart_items_count,
  };
}

