import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCoupon";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Fetches a single coupon's detailed schema record by its UUID identifier,
 * restricted to the requesting customer.
 *
 * Provides a complete atomic snapshot of code, campaign connection, status
 * (issued, redeemed, expired), customer assignment, and relevant timestamps.
 * Role-based access rules: customers may request only their own coupons; admins
 * can access any coupon by other methods.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 *   (authorization enforced)
 * @param props.couponId - UUID of the coupon to query for full details
 * @returns The detailed coupon voucher record as described in
 *   IAimallBackendCoupon
 * @throws {Error} When the coupon does not exist or is not assigned to this
 *   customer
 */
export async function get__aimall_backend_customer_coupons_$couponId(props: {
  customer: CustomerPayload;
  couponId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendCoupon> {
  const { customer, couponId } = props;

  const coupon = await MyGlobal.prisma.aimall_backend_coupons.findFirst({
    where: {
      id: couponId,
      customer_id: customer.id,
    },
  });

  if (!coupon) throw new Error("Coupon not found");

  return {
    id: coupon.id,
    discount_campaign_id: coupon.discount_campaign_id,
    customer_id: coupon.customer_id ?? null,
    code: coupon.code,
    status: coupon.status,
    issued_at: toISOStringSafe(coupon.issued_at),
    expires_at: toISOStringSafe(coupon.expires_at),
    redeemed_at: coupon.redeemed_at
      ? toISOStringSafe(coupon.redeemed_at)
      : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Creates a new order in the database.
 *
 * This endpoint allows an authenticated seller to create a new order. It
 * requires that all referenced foreign keys (customer, seller, address) exist,
 * and that the seller matches the authenticated seller. If order_number is not
 * provided or is empty, a unique business order number is generated. All UUIDs
 * and date fields are handled as branded types; native Date is never used. The
 * resulting object strictly complies with the IAimallBackendOrder API
 * contract.
 *
 * @param props - Object containing the authenticated seller and the order
 *   creation data
 * @param props.seller - The currently authenticated seller performing this
 *   operation
 * @param props.body - The business input required to create the order according
 *   to IAimallBackendOrder.ICreate
 * @returns The created IAimallBackendOrder object with all business and
 *   system-generated fields populated
 * @throws {Error} If the seller is not authorized or any referenced entity does
 *   not exist or the order_number is not unique
 */
export async function post__aimall_backend_seller_orders(props: {
  seller: SellerPayload;
  body: IAimallBackendOrder.ICreate;
}): Promise<IAimallBackendOrder> {
  const { seller, body } = props;

  // Authorization: seller_id in body must match authenticated seller
  if (body.seller_id !== seller.id) {
    throw new Error(
      "You are only authorized to create orders for your own seller account",
    );
  }

  // Foreign key validations
  const [customerExists, sellerExists, addressExists] = await Promise.all([
    MyGlobal.prisma.aimall_backend_customers.findFirst({
      where: { id: body.customer_id },
    }),
    MyGlobal.prisma.aimall_backend_sellers.findFirst({
      where: { id: body.seller_id },
    }),
    MyGlobal.prisma.aimall_backend_addresses.findFirst({
      where: { id: body.address_id },
    }),
  ]);
  if (!customerExists) throw new Error("Customer not found");
  if (!sellerExists) throw new Error("Seller not found");
  if (!addressExists) throw new Error("Address not found");

  // Unique order_number logic (generate if missing or empty, else check for duplicates)
  let order_number = body.order_number;
  if (!order_number || order_number.trim() === "") {
    let unique = false;
    do {
      // Generate: ORD-YYYYMMDD-RAND4
      const now = new Date();
      const ymd = now.toISOString().slice(0, 10).replace(/-/g, "");
      const rand = Math.floor(Math.random() * 10000)
        .toString()
        .padStart(4, "0");
      order_number = `ORD-${ymd}-${rand}`;
      unique = !(await MyGlobal.prisma.aimall_backend_orders.findFirst({
        where: { order_number },
      }));
    } while (!unique);
  } else {
    // If provided, ensure it's unique
    const exists = await MyGlobal.prisma.aimall_backend_orders.findFirst({
      where: { order_number },
    });
    if (exists) throw new Error("Order number already exists");
  }

  // Create order
  const id = v4() as string & tags.Format<"uuid">;
  const created_at = toISOStringSafe(new Date());
  const updated_at = created_at;
  const archived_at = null;
  const created = await MyGlobal.prisma.aimall_backend_orders.create({
    data: {
      id,
      customer_id: body.customer_id,
      seller_id: body.seller_id,
      address_id: body.address_id,
      order_number,
      order_status: body.order_status,
      total_amount: body.total_amount,
      currency: body.currency,
      created_at,
      updated_at,
      archived_at,
    },
  });

  return {
    id,
    customer_id: created.customer_id,
    seller_id: created.seller_id,
    address_id: created.address_id,
    order_number: created.order_number,
    order_status: created.order_status,
    total_amount: created.total_amount,
    currency: created.currency,
    created_at,
    updated_at,
    archived_at: null,
  } satisfies IAimallBackendOrder;
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Create a new community post/thread/Q&A.
 *
 * Allows any authenticated customer to publish a new community post. Receives
 * post details (title, body, is_private, etc.) as the request body, with atomic
 * fields matching the aimall_backend_posts schema. The system will store the
 * post and return the full record as confirmation.
 *
 * This operation assigns post authorship based on authentication. The input
 * body MAY supply a customer_id for compatibility, but it is ignored and
 * overwritten with the authenticated customer. Post creation may be subject to
 * moderation depending on content or site policy.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the post
 *   creation (CustomerPayload)
 * @param props.body - Post creation details (title, body, is_private)
 * @returns The created community post record with full system and audit fields
 *   populated, suitable for display or further logic.
 * @throws {Error} If database write fails or Prisma returns unexpected
 *   structure (should not occur if input DTO is valid)
 */
export async function post__aimall_backend_customer_posts(props: {
  customer: CustomerPayload;
  body: IAimallBackendPost.ICreate;
}): Promise<IAimallBackendPost> {
  const { customer, body } = props;

  // All date fields must be ISO string (string & tags.Format<'date-time'>), never Date.
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  // Ignore customer_id in body for security: always assign to authenticated user.
  const created = await MyGlobal.prisma.aimall_backend_posts.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      customer_id: customer.id,
      title: body.title,
      body: body.body,
      is_private: body.is_private,
      view_count: 0,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Return all expected fields with proper branding/formats.
  return {
    id: created.id,
    customer_id: created.customer_id,
    title: created.title,
    body: created.body,
    is_private: created.is_private,
    view_count: created.view_count,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Soft-delete a reply (child comment) under a parent comment thread (set
 * deleted_at).
 *
 * Only the comment's author can perform this action. If the comment was already
 * deleted, or if the parent relationship does not match, or if the user is not
 * the author, the action fails with an appropriate error. No data is
 * lost—deleted_at is set for audit and compliance purposes.
 *
 * @param props - Operation properties
 * @param props.customer - The authenticated customer payload
 * @param props.commentId - UUID of the parent comment (thread)
 * @param props.childCommentId - UUID of the child comment to be soft-deleted
 * @returns Void
 * @throws {Error} If child comment does not exist, parent-child relationship is
 *   invalid, comment is already deleted, or user is not the author
 */
export async function delete__aimall_backend_customer_comments_$commentId_comments_$childCommentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, commentId, childCommentId } = props;

  // Fetch the target child comment (direct reply)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: childCommentId },
    select: { id: true, parent_id: true, customer_id: true, deleted_at: true },
  });
  if (!comment) throw new Error("Comment not found");

  // Validate parent-child relationship
  if (comment.parent_id !== commentId)
    throw new Error("Parent comment mismatch");

  // Ensure not already soft-deleted
  if (comment.deleted_at) throw new Error("Comment already deleted");

  // Only the author may perform this deletion
  if (comment.customer_id !== customer.id)
    throw new Error("Unauthorized: only the comment author may delete");

  // Soft-delete: set deleted_at (with current date-time string)
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: childCommentId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
