/**
 * Create a new coupon (Coupon table, voucher issuance).
 *
 * Inserts (creates) a new coupon/voucher record. Only administrators or backend
 * automation should call this endpoint, which directly issues a new coupon to
 * the identified campaign (and optionally a customer, for personalized
 * vouchers). All fields required by the coupon creation DTO
 * (IAimallBackendCoupon.ICreate) must be provided, including issuance/expiry
 * dates, campaign, and unique code. Business rules for code uniqueness,
 * campaign relationship, and lifecycle state are enforced.
 *
 * Successful creation returns the full new row as per the coupon schema.
 * Creation events are logged for compliance/auditability; errors arise on
 * constraint violation (e.g., duplicate code or conflicting status).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator (must be active)
 * @param props.body - Coupon issuance payload (voucher DTO)
 * @returns The full created coupon as stored in the database
 * @throws {Error} When code uniqueness or campaign constraints are violated
 */
export async function post__aimall_backend_administrator_coupons(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendCoupon.ICreate;
}): Promise<IAimallBackendCoupon> {
  const { administrator, body } = props;
  const created = await MyGlobal.prisma.aimall_backend_coupons.create({
    data: {
      id: v4() as string & tags.Format<"uuid">, // always generate new UUID
      discount_campaign_id: body.discount_campaign_id,
      customer_id: body.customer_id ?? null,
      code: body.code,
      status: body.status,
      issued_at: body.issued_at,
      expires_at: body.expires_at,
      redeemed_at: null,
    },
  });
  return {
    id: created.id,
    discount_campaign_id: created.discount_campaign_id,
    customer_id: created.customer_id ?? null,
    code: created.code,
    status: created.status,
    issued_at: toISOStringSafe(created.issued_at),
    expires_at: toISOStringSafe(created.expires_at),
    redeemed_at: created.redeemed_at
      ? toISOStringSafe(created.redeemed_at)
      : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAdministrator";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create a new platform administrator account (Actors domain).
 *
 * Creates a new administrator account, referencing the
 * aimall_backend_administrators schema. Only authenticated super administrators
 * or permission managers may invoke this operation (authorization handled
 * upstream).
 *
 * On successful creation, an audit log entry is recorded as required by
 * compliance. Account status can be set via input (active, pending, etc).
 * Sensitive credentials such as password are managed externally and not part of
 * this operation.
 *
 * @param props - Request properties
 * @param props.administrator - The currently authenticated administrator
 *   performing the creation
 * @param props.body - Administrator account data: permission_id, email, display
 *   name, and status
 * @returns The newly created administrator resource as confirmation and for
 *   profile display
 * @throws {Error} If the email is already used, permission_id is invalid, or
 *   database errors occur
 */
export async function post__aimall_backend_administrator_administrators(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAdministrator.ICreate;
}): Promise<IAimallBackendAdministrator> {
  const now = toISOStringSafe(new Date());

  // Create administrator record
  const created = await MyGlobal.prisma.aimall_backend_administrators.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      permission_id: props.body.permission_id,
      email: props.body.email,
      name: props.body.name,
      status: props.body.status,
      created_at: now,
      updated_at: now,
    },
  });

  // Write audit log for compliance
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: props.administrator.id,
      event_type: "ADMIN_CREATE",
      event_target: props.body.email,
      outcome: "SUCCESS",
      created_at: now,
    },
  });

  // Return full administrator profile resource
  return {
    id: created.id,
    permission_id: created.permission_id,
    email: created.email,
    name: created.name,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * 소프트 삭제: 채널 하위의 섹션을 논리적으로 삭제합니다.
 *
 * 이 함수는 특정 채널과 섹션 ID로 주어진 섹션을 소프트 삭제(논리 삭제)합니다. '삭제'란 실제 레코드 삭제가 아닌 deleted_at
 * 필드를 현재 시각으로 마킹하는 것을 의미합니다. 섹션이 존재하지 않거나 이미 삭제된 경우, 또는 채널이 일치하지 않으면 404 에러를
 * 반환합니다. 삭제 이벤트는 aimall_backend_audit_logs에 감사 로그로 남깁니다.
 *
 * @param props - 요청 파라미터
 * @param props.administrator - 인증된 관리자 페이로드
 * @param props.channelId - 소속 채널 UUID
 * @param props.sectionId - 삭제 대상 섹션 UUID
 * @returns 없음(void)
 * @throws {Error} 섹션이 존재하지 않거나 이미 삭제된 경우 (404)
 */
export async function delete__aimall_backend_administrator_channels_$channelId_sections_$sectionId(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  sectionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, channelId, sectionId } = props;

  // 1. 삭제 전 대상을 검증한다 (존재, 채널 일치, 삭제 안됨)
  const section = await MyGlobal.prisma.aimall_backend_sections.findFirst({
    where: {
      id: sectionId,
      channel_id: channelId,
      deleted_at: null,
    },
  });
  if (!section) {
    const err = new Error("Section not found");
    (err as any).status = 404;
    throw err;
  }

  // 2. 현재 시각 ISO 문자열 준비
  const now = toISOStringSafe(new Date());

  // 3. 소프트 삭제 처리
  await MyGlobal.prisma.aimall_backend_sections.update({
    where: { id: sectionId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });

  // 4. 감사 로그 기록
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "SECTION_DELETE",
      event_target: sectionId,
      outcome: "SUCCESS",
      detail_json: JSON.stringify({ channelId }),
      created_at: now,
    },
  });

  // 5. 반환 없음
  return;
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * 하드 삭제: 특정 상품(productId)의 옵션(productOptionId)을 완전히 삭제합니다.
 *
 * Aimall_backend_product_options에서 주어진 옵션 ID와 상품 ID를 검증 후, 종속성(sku, 주문 아이템)이 없을
 * 때만 영구 삭제를 수행합니다.
 *
 * @param props - 요청 파라미터
 * @param props.administrator - 인증된 관리자 페이로드
 * @param props.productId - 옵션이 소속된 상품의 UUID
 * @param props.productOptionId - 삭제할 상품 옵션의 UUID
 * @returns Void (성공시 아무 결과 반환하지 않음)
 * @throws {Error} - 옵션이 해당 상품에 존재하지 않거나 종속성이 존재할 때, 또는 삭제 실패시
 */
export async function delete__aimall_backend_administrator_products_$productId_productOptions_$productOptionId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  productOptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, productId, productOptionId } = props;

  // 1. 옵션 존재/소속 상품 확인
  const option =
    await MyGlobal.prisma.aimall_backend_product_options.findUnique({
      where: { id: productOptionId },
      select: { id: true, product_id: true },
    });
  if (!option || option.product_id !== productId) {
    throw new Error("해당 상품에 지정된 옵션이 존재하지 않습니다.");
  }

  // 2. SKU 및 주문 아이템 종속성 확인
  const referencedSku = await MyGlobal.prisma.aimall_backend_skus.findFirst({
    where: { product_id: productId },
    select: { id: true },
  });
  const referencedOrderItem =
    await MyGlobal.prisma.aimall_backend_order_items.findFirst({
      where: { product_option_id: productOptionId },
      select: { id: true },
    });

  if (referencedSku || referencedOrderItem) {
    throw new Error(
      "이 옵션은 SKU 또는 주문 내역에 의해 참조되고 있어 삭제할 수 없습니다.",
    );
  }

  // 3. 하드 삭제 수행
  await MyGlobal.prisma.aimall_backend_product_options.delete({
    where: { id: productOptionId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendFaq } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendFaq";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create a new FAQ entry (knowledge base record).
 *
 * Add a new FAQ record representing a knowledge base entry. Requires complete
 * input for question, answer, category, visible, and sort_order fields as
 * described in the schema. This operation is permitted to administrator or
 * knowledge manager roles; guests/customers may not add FAQs by policy.
 *
 * All values are validated for normalization and correct answer/question scope.
 * Audit trail is ensured for all creations for compliance and reporting.
 * Returns the full inserted record for admin review.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload. Must be
 *   present and valid for operation.
 * @param props.body - FAQ creation data, including question, answer, category,
 *   visible flag, and sort_order (manual sort index).
 * @returns The new FAQ record, normalized and including id and timestamps.
 * @throws {Error} When a FAQ entry with the same category and sort_order
 *   already exists.
 */
export async function post__aimall_backend_administrator_faqs(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendFaq.ICreate;
}): Promise<IAimallBackendFaq> {
  const { administrator, body } = props;

  // Admin authentication enforced by decorator/parameter
  // Uniqueness: ensure no duplicate (category, sort_order)
  const existing = await MyGlobal.prisma.aimall_backend_faqs.findFirst({
    where: {
      category: body.category,
      sort_order: body.sort_order,
    },
    select: { id: true },
  });
  if (existing) {
    throw new Error(
      `FAQ with category '${body.category}' and sort_order '${body.sort_order}' already exists.`,
    );
  }

  // Prepare timestamps
  const now = toISOStringSafe(new Date());
  // Generate new ID
  // v4() returns a string, but we want to guarantee branding statically
  // Here, parse as IAimallBackendFaq['id'] type (string & tags.Format<'uuid'>) via variable
  const faqId = v4();

  // Insert new record
  const created = await MyGlobal.prisma.aimall_backend_faqs.create({
    data: {
      id: faqId,
      question: body.question,
      answer: body.answer,
      category: body.category,
      sort_order: body.sort_order,
      visible: body.visible,
      created_at: now,
      updated_at: now,
    },
  });

