import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Hard delete a product option for a specific product (hard delete;
 * aimall_backend_product_options).
 *
 * Hard delete a product option from aimall_backend_product_options, identified
 * by both product and product option UUIDs. Option records are removed entirely
 * since the schema does not support soft deletion. This endpoint is accessible
 * only to sellers owning the product.
 *
 * Only product options directly owned by the target product can be deleted, and
 * all dependency checks are enforced (such as referenced SKUs or order items).
 * On successful deletion, the record is removed and the endpoint returns no
 * content. Unauthorized, non-existent, or dependency-linked options cannot be
 * removed, and such attempts produce error responses.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller attempting to delete the
 *   product option.
 * @param props.productId - UUID of the product to which the deleted product
 *   option belongs.
 * @param props.productOptionId - UUID of the product option being deleted.
 * @returns Void on successful deletion; throws error if dependencies or
 *   authorization fail.
 * @throws {Error} If the product does not exist, the seller does not own the
 *   product, the product option does not exist or does not belong to the
 *   product, or if the product option is referenced by dependent records.
 */
export async function delete__aimall_backend_seller_products_$productId_productOptions_$productOptionId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  productOptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, productId, productOptionId } = props;

  // 1. Fetch the product and verify seller ownership
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
    select: { id: true, seller_id: true },
  });
  if (!product) {
    throw new Error("Product not found");
  }
  if (product.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Only the owner seller may delete product options from this product.",
    );
  }

  // 2. Fetch the product option and verify linkage
  const productOption =
    await MyGlobal.prisma.aimall_backend_product_options.findUnique({
      where: { id: productOptionId },
      select: { id: true, product_id: true },
    });
  if (!productOption) {
    throw new Error("Product option not found");
  }
  if (productOption.product_id !== productId) {
    throw new Error("Product option does not belong to the specified product.");
  }

  // 3. Check for dependencies in cart_items
  const cartItemDependency =
    await MyGlobal.prisma.aimall_backend_cart_items.findFirst({
      where: { aimall_backend_product_option_id: productOptionId },
      select: { id: true },
    });
  if (cartItemDependency) {
    throw new Error(
      "Product option is referenced in at least one cart item and cannot be deleted.",
    );
  }

  // 4. Check for dependencies in order_items
  const orderItemDependency =
    await MyGlobal.prisma.aimall_backend_order_items.findFirst({
      where: { product_option_id: productOptionId },
      select: { id: true },
    });
  if (orderItemDependency) {
    throw new Error(
      "Product option is referenced in at least one order item and cannot be deleted.",
    );
  }

  // 5. Perform hard delete from product_options
  await MyGlobal.prisma.aimall_backend_product_options.delete({
    where: { id: productOptionId },
  });
}

