/**
 * Creates a new product taxonomy category for the platform's product
 * classification (seller only).
 *
 * Validates inputs, verifies parent category (if any), and ensures category
 * name uniqueness within the same parent scope as required by business rules.
 * Only authenticated sellers can call this function (authorization handled by
 * the controller/decorator). No native Date is used; UUIDs are generated with
 * v4() and strictly typed. Returns the created category record.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the operation
 * @param props.body - Category definition data (name, parent_id, depth) for
 *   creation
 * @returns The newly created IAimallBackendCategory object
 * @throws {Error} If the parent category does not exist
 * @throws {Error} If category name is not unique within the same parent
 */
export async function post__aimall_backend_seller_categories(props: {
  seller: SellerPayload;
  body: IAimallBackendCategory.ICreate;
}): Promise<IAimallBackendCategory> {
  const { seller, body } = props;

  // If parent_id is specified, it must reference an existing category
  if (body.parent_id !== undefined && body.parent_id !== null) {
    const parent = await MyGlobal.prisma.aimall_backend_categories.findUnique({
      where: { id: body.parent_id },
    });
    if (!parent) {
      throw new Error("Parent category does not exist.");
    }
  }

  // Enforce uniqueness of [parent_id, name]
  const dupe = await MyGlobal.prisma.aimall_backend_categories.findFirst({
    where: { parent_id: body.parent_id ?? null, name: body.name },
  });
  if (dupe) {
    throw new Error("Category name must be unique within the same parent.");
  }

  // Insert new category. UUID generated by v4().
  const created = await MyGlobal.prisma.aimall_backend_categories.create({
    data: {
      id: v4(),
      parent_id: body.parent_id ?? null,
      name: body.name,
      depth: body.depth,
    },
    select: {
      id: true,
      parent_id: true,
      name: true,
      depth: true,
    },
  });

  // Output all fields with explicit types
  return {
    id: created.id,
    parent_id: created.parent_id ?? null,
    name: created.name,
    depth: created.depth,
  } satisfies IAimallBackendCategory;
}

