/**
 * Creates a new discount campaign in the AIMall backend.
 *
 * Allows administrators to register a new discount campaign, enforcing unique
 * code, presence of all required fields, date range validity, and nonnegative
 * max uses per user. The newly created campaign entity is returned after
 * creation.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must have
 *   active status)
 * @param props.body - Discount campaign data; code, name, type, stackability,
 *   priority, date range, max uses, description
 * @returns The newly created discount campaign entity
 * @throws {Error} When the campaign code already exists, or business rules are
 *   violated (e.g., invalid dates, negative max uses)
 */
export async function post__aimall_backend_administrator_discountCampaigns(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendDiscountCampaign.ICreate;
}): Promise<IAimallBackendDiscountCampaign> {
  const { administrator, body } = props;

  // 1. Enforce uniqueness of campaign code
  const exists =
    await MyGlobal.prisma.aimall_backend_discount_campaigns.findUnique({
      where: { code: body.code },
    });
  if (exists) throw new Error("Discount campaign code already exists.");

  // 2. Validate business constraints
  if (body.start_at >= body.end_at)
    throw new Error("start_at must be before end_at");
  if (
    body.max_uses_per_user !== null &&
    body.max_uses_per_user !== undefined &&
