        code: body.code,
        type: body.type,
        status: body.status,
        stackable: body.stackable,
        start_at: toISOStringSafe(body.start_at),
        end_at: toISOStringSafe(body.end_at),
        max_uses_per_user: body.max_uses_per_user ?? null,
        priority: body.priority,
        description: body.description ?? null,
      },
    });

  // 5. Return API type, ensuring all datetimes are branded ISO strings
  return {
    id: created.id,
    name: created.name,
    code: created.code,
    type: created.type,
    status: created.status,
    stackable: created.stackable,
    start_at: toISOStringSafe(created.start_at),
