import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Soft-delete a comment on a review (logical redaction/audit).
 *
 * Performs a soft delete on a comment associated with a product review by
 * setting the deleted_at timestamp in aimall_backend_comments. The record is
 * logically hidden from all normal listings, retaining full auditability per
 * compliance rules.
 *
 * Only allowed for the author, moderators, or admin roles. Deletion of parent
 * comments may be restricted if there are active replies/comments for
 * referential integrity.
 *
 * Error handling for non-existent comment, already deleted, or permission
 * denied conditions. Audit logs are updated whenever a comment is deleted.
 *
 * @param props - administrator: The authenticated administrator performing the
 *   deletion reviewId: Review UUID the comment belongs to. commentId: UUID of
 *   the comment to be deleted.
 * @returns Void
 * @throws {Error} If no such active comment exists, if already deleted, or if
 *   child replies are still alive.
 */
export async function delete__aimall_backend_administrator_reviews_$reviewId_comments_$commentId(props: {
  administrator: AdministratorPayload;
  reviewId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, reviewId, commentId } = props;
  // 1. Find the comment for this review, only alive ones
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      review_id: reviewId,
      deleted_at: null,
    },
  });
  if (!comment) throw new Error("Comment does not exist or already deleted");

  // 2. Check referential integrity (no active child comments)
  const child = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: { parent_id: commentId, deleted_at: null },
  });
  if (child) throw new Error("Cannot delete comment with active replies.");

  // 3. Soft delete: set deleted_at, updated_at to now
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });

  // 4. Write audit log
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4(),
      actor_id: administrator.id,
      event_type: "SOFT_DELETE_COMMENT",
      event_target: commentId,
      outcome: "SUCCESS",
      created_at: now,
    },
  });
}

