import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Deletes (hard delete) a product bundle relationship, removing the association
 * between the master product and its component product.
 *
 * This operation is only available to authorized sellers/administrators.
 * Ensures correct ownership before invoking. Deletion is permanent as the table
 * lacks soft delete fields like 'deleted_at'. Returns 204 (no content) on
 * success, 404 if not found, 403 if forbidden.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller context (SellerPayload)
 * @param props.productId - ID of the product acting as bundle master
 * @param props.productBundleId - ID of the bundle relation to delete
 * @returns Void (204 No content)
 * @throws {Error} 404 if bundle not found or does not belong to product; 403 if
 *   seller does not own bundle master product
 */
export async function delete__aimall_backend_seller_products_$productId_productBundles_$productBundleId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  productBundleId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, productId, productBundleId } = props;

  // 1. Find the bundle relation
  const bundle =
    await MyGlobal.prisma.aimall_backend_product_bundles.findUnique({
      where: { id: productBundleId },
    });
  if (!bundle) throw new Error("Product bundle not found"); // 404
  if (bundle.bundle_product_id !== productId)
    throw new Error("Product bundle does not belong to specified product"); // 404

  // 2. Verify seller owns the bundle product
  const bundleProduct =
    await MyGlobal.prisma.aimall_backend_products.findUnique({
      where: { id: productId },
    });
  if (!bundleProduct) throw new Error("Bundle master product not found"); // 404
  if (bundleProduct.seller_id !== seller.id)
    throw new Error("Forbidden: Not authorized to delete this bundle"); // 403

  // 3. Delete the bundle relation (hard delete)
  await MyGlobal.prisma.aimall_backend_product_bundles.delete({
    where: { id: productBundleId },
  });
}

