import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCart";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Creates a new shopping cart instance for a customer or anonymous session,
 * enforcing single active cart constraint.
 *
 * This function ensures only one active cart exists per customer or session by
 * checking for existing carts and throwing a conflict error if found.
 * Timestamps are set automatically if omitted. Customer authentication is
 * enforced to prevent cross-customer cart creation.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer creating the cart (payload
 *   from CustomerAuth)
 * @param props.body - The cart creation payload (may contain customer_id or
 *   session_token)
 * @returns The newly created cart, including all assigned fields and
 *   cart_items_count = 0
 * @throws {Error} When neither customer_id nor session_token is provided
 * @throws {Error} When customer_id does not match the authenticated customer
 * @throws {Error} When a cart already exists for the provided customer_id or
 *   session_token
 */
export async function post__aimall_backend_customer_carts(props: {
  customer: CustomerPayload;
  body: IAimallBackendCart.ICreate;
}): Promise<IAimallBackendCart> {
  const { customer, body } = props;

  // Validate input: must provide either aimall_backend_customer_id or session_token
  if (!body.aimall_backend_customer_id && !body.session_token) {
    throw new Error(
      "Either aimall_backend_customer_id or session_token must be provided",
    );
  }

  // If a customer ID is provided, it must match the authenticated customer
  if (
    body.aimall_backend_customer_id &&
    body.aimall_backend_customer_id !== customer.id
  ) {
    throw new Error(
      "Authenticated customer does not match the provided aimall_backend_customer_id",
    );
  }

  // Uniqueness check: cart for this customer_id
  if (body.aimall_backend_customer_id) {
    const existingByCustomer =
      await MyGlobal.prisma.aimall_backend_carts.findFirst({
        where: { aimall_backend_customer_id: body.aimall_backend_customer_id },
      });
    if (existingByCustomer)
      throw new Error("A cart already exists for this customer");
  }

  // Uniqueness check: cart for this session_token
  if (body.session_token) {
    const existingBySession =
      await MyGlobal.prisma.aimall_backend_carts.findFirst({
        where: { session_token: body.session_token },
      });
    if (existingBySession)
      throw new Error("A cart already exists for this anonymous session");
  }

  // Prepare timestamps using toISOStringSafe
  const now = toISOStringSafe(new Date());

  // Create the cart
  const created = await MyGlobal.prisma.aimall_backend_carts.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      aimall_backend_customer_id: body.aimall_backend_customer_id ?? undefined,
      session_token: body.session_token ?? undefined,
      created_at: body.created_at ?? now,
      updated_at: body.updated_at ?? now,
    },
  });

  // Return per IAimallBackendCart DTO (cart_items_count is always 0 at creation)
  return {
    id: created.id,
    aimall_backend_customer_id: created.aimall_backend_customer_id ?? undefined,
    session_token: created.session_token ?? undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    cart_items_count: 0,
  };
}

