import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Hard delete a product category by ID.
 *
 * Deletes (hard, irreversible) a product category record, removing it from
 * taxonomy. Before deletion, dependency checks are enforced (e.g., no related
 * products exist/child categories reassigned) to avoid orphaned references.
 * Returns 204 (no content) on success or 404 if not found. Only available to
 * users with appropriate permissions (administrator).
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated admin performing the operation
 * @param props.categoryId - UUID of the category to delete
 * @returns Void
 * @throws {Error} When the category does not exist
 * @throws {Error} When category still has products
 * @throws {Error} When category still has child categories
 */
export async function delete__aimall_backend_administrator_categories_$categoryId(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { categoryId } = props;

  // 1. Verify category exists
  const category = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
    select: { id: true },
  });
  if (!category) throw new Error("Category not found");

  // 2. Check for assigned products
  const productCount = await MyGlobal.prisma.aimall_backend_products.count({
    where: { category_id: categoryId },
  });
  if (productCount > 0)
    throw new Error("Cannot delete: category still has products");

  // 3. Check for child categories
  const childCount = await MyGlobal.prisma.aimall_backend_categories.count({
    where: { parent_id: categoryId },
  });
  if (childCount > 0)
    throw new Error("Cannot delete: category still has child categories");

  // 4. Delete the category
  await MyGlobal.prisma.aimall_backend_categories.delete({
    where: { id: categoryId },
  });
}

