/**
 * Delete/remove a single order item from an order (Order Items table).
 *
 * Removes a single order item line from a given order record, specified by both
 * parent order UUID and order item UUID. Only possible if the parent order is
 * open and mutable. The action does not affect the parent order's existence but
 * will cause recalculation of total amounts in subsequent operations.
 *
 * Permitted for sellers/administrators and, in some business workflows, the
 * order-owning customer. Operation returns an appropriate confirmation or error
 * if not found or not permissible.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator user
 * @param props.orderId - UUID of the parent order
 * @param props.orderItemId - UUID of the order item to remove
 * @returns Void
 * @throws {Error} When the order does not exist, is locked/finalized, or the
 *   item is not found
 */
export async function delete__aimall_backend_administrator_orders_$orderId_orderItems_$orderItemId(props: {
  administrator: AdministratorPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, orderId, orderItemId } = props;

  // Step 1: Fetch the order and ensure it's open/mutable
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { id: true, order_status: true, archived_at: true },
  });
  if (!order) throw new Error("Order not found");
  if (
    ["delivered", "cancelled", "returned"].includes(order.order_status) ||
    order.archived_at !== null
  ) {
    throw new Error("Order is locked or finalized and cannot be modified");
  }

  // Step 2: Fetch the order item, ensure it belongs to the order
  const item = await MyGlobal.prisma.aimall_backend_order_items.findFirst({
    where: { id: orderItemId, order_id: orderId },
    select: { id: true },
  });
  if (!item) throw new Error("Order item not found for this order");

  // Step 3: Delete the order item (hard delete)
  await MyGlobal.prisma.aimall_backend_order_items.delete({
    where: { id: orderItemId },
  });

  // No return value (void)
}

