/**
 * Delete/remove a single order item from an order (Order Items table).
 *
 * Removes a single order item line from a given order record, specified by both
 * parent order UUID and order item UUID. Only possible if the parent order is
 * open and mutable. The action does not affect the parent order's existence but
 * will cause recalculation of total amounts in subsequent operations.
 *
 * Permitted for sellers/administrators and, in some business workflows, the
 * order-owning customer. Operation returns an appropriate confirmation or error
 * if not found or not permissible.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request
 * @param props.orderId - UUID of the parent order from which the item will be
 *   removed
 * @param props.orderItemId - UUID of the order item to delete
 * @returns Void
 * @throws {Error} When order is not found
 * @throws {Error} When the order does not belong to the customer
 * @throws {Error} When the order is not open/mutable (e.g., cancelled, shipped,
 *   delivered, archived)
 * @throws {Error} When the order item does not exist or is not part of the
 *   specified order
 */
export async function delete__aimall_backend_customer_orders_$orderId_orderItems_$orderItemId(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, orderId, orderItemId } = props;

  // 1. Fetch the order, ensure it exists
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");

  // 2. Authorization: must belong to the current customer
  if (order.customer_id !== customer.id) {
    throw new Error("Forbidden: This order does not belong to you");
  }

  // 3. Mutability: allow only if order is not finalized/archived/cancelled/shipped/delivered
  const immutableStatuses = ["cancelled", "archived", "shipped", "delivered"];
  if (immutableStatuses.includes(order.order_status)) {
    throw new Error("Order is not modifiable in current status");
  }

  // 4. Fetch the order item, ensure it exists and is attached to this order
  const orderItem = await MyGlobal.prisma.aimall_backend_order_items.findUnique(
    { where: { id: orderItemId } },
  );
  if (!orderItem || orderItem.order_id !== orderId) {
    throw new Error("Order item not found for this order");
  }

  // 5. Delete the order item
  await MyGlobal.prisma.aimall_backend_order_items.delete({
    where: { id: orderItemId },
  });
}

