import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Creates a new order in the database for an authenticated customer.
 *
 * This endpoint ensures security and business integrity by requiring that the
 * calling user (customer) matches the customer_id in the order body. All
 * references (customer, seller, address) are strictly validated for existence,
 * preventing orphan orders. If order_number is omitted, the system generates a
 * unique, business-formatted identifier (ORD-YYYYMMDD-XXXX). All fields (UUIDs,
 * dates) are properly branded and formatted. The created order includes all
 * business attributes as required by the domain model; archived_at is always
 * null for a new order.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer JWT payload; only this user
 *   can submit their own orders
 * @param props.body - All business fields required to create a new order as per
 *   IAimallBackendOrder.ICreate
 * @returns The created order record with all business data and unique
 *   identifiers
 * @throws {Error} When the authenticated customer does not match
 *   body.customer_id
 * @throws {Error} When the customer, seller, or address does not exist
 * @throws {Error} When a duplicate order_number exists
 */
export async function post__aimall_backend_customer_orders(props: {
  customer: CustomerPayload;
  body: IAimallBackendOrder.ICreate;
}): Promise<IAimallBackendOrder> {
  const { customer, body } = props;

  // Step 1: Ensure the authenticated customer matches the customer_id in the order body
  if (customer.id !== body.customer_id) {
    throw new Error("Authenticated customer does not match body.customer_id");
  }

  // Step 2: Check for existence of referenced customer (MUST BE ACTIVE, enforced upstream in CustomerAuth)
  const customerRec = await MyGlobal.prisma.aimall_backend_customers.findUnique(
    {
      where: { id: body.customer_id },
      select: { id: true },
    },
  );
  if (!customerRec) {
    throw new Error("Customer not found");
  }

  // Step 3: Check for existence of referenced seller
  const sellerRec = await MyGlobal.prisma.aimall_backend_sellers.findUnique({
    where: { id: body.seller_id },
    select: { id: true },
  });
  if (!sellerRec) {
    throw new Error("Seller not found");
  }

  // Step 4: Check for existence of referenced address
  const addressRec = await MyGlobal.prisma.aimall_backend_addresses.findUnique({
    where: { id: body.address_id },
    select: { id: true },
  });
  if (!addressRec) {
    throw new Error("Address not found");
  }

  // Step 5: Prepare new order data (UUID, timestamps, and order_number)
  const id = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // Step 6: Generate order_number if not provided
  let orderNumber = body.order_number;
  if (!orderNumber) {
    const yyyymmdd = now.slice(0, 10).replace(/-/g, "");
    orderNumber = `ORD-${yyyymmdd}-${Math.floor(1000 + Math.random() * 9000)}`;
  }

  // Step 7: Ensure uniqueness of order_number
  const existingOrder = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { order_number: orderNumber },
    select: { id: true },
  });
  if (existingOrder) {
    throw new Error("Duplicate order_number");
  }

  // Step 8: Create the order (dates and ids properly branded, archived_at omitted — will be null)
  await MyGlobal.prisma.aimall_backend_orders.create({
    data: {
      id,
      customer_id: body.customer_id,
      seller_id: body.seller_id,
      address_id: body.address_id,
      order_number: orderNumber,
      order_status: body.order_status,
      total_amount: body.total_amount,
      currency: body.currency,
      created_at: now,
      updated_at: now,
    },
  });

  // Step 9: Return record conforming to IAimallBackendOrder (archived_at always null at creation)
  return {
    id,
    customer_id: body.customer_id,
    seller_id: body.seller_id,
    address_id: body.address_id,
    order_number: orderNumber,
    order_status: body.order_status,
    total_amount: body.total_amount,
    currency: body.currency,
    created_at: now,
    updated_at: now,
    archived_at: null,
  } as IAimallBackendOrder;
}

