import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Creates a new attachment entry in the aimall_backend_attachments table based
 * on provided metadata (file URI, file type, file size, and linkage to post,
 * comment, or review).
 *
 * File uploads themselves happen out-of-band; only metadata/reference is stored
 * in this call. Appropriate for use by client-side applications or admin tools
 * that need to store references to user-uploaded materials. Ensures policy
 * compliance by associating attachments only to allowed entities (post,
 * comment, or review, one foreign key per record; others null). Requires
 * administrator authentication and write permissions (validated at
 * controller/decorator).
 *
 * @param props - Request parameter object
 * @param props.administrator - Authenticated and active administrator (already
 *   validated by controller auth decorator)
 * @param props.body - Attachment data for file/media to register (file URI,
 *   metadata, and linkage).
 * @returns The newly created attachment record with persisted ID, linkage, and
 *   file metadata
 * @throws {Error} On database errors (e.g., invalid parent association,
 *   referential integrity violation)
 */
export async function post__aimall_backend_administrator_attachments(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAttachment.ICreate;
}): Promise<IAimallBackendAttachment> {
  const { body } = props;

  // Generate a new UUID and created_at ISO string for the record
  const id: string & tags.Format<"uuid"> = v4() as string & tags.Format<"uuid">;
  const created_at: string & tags.Format<"date-time"> = toISOStringSafe(
    new Date(),
  );

  // Persist the attachment record (all linkage fields nullable; policy compliance enforced externally)
  const created = await MyGlobal.prisma.aimall_backend_attachments.create({
    data: {
      id,
      post_id: body.post_id ?? null,
      comment_id: body.comment_id ?? null,
      review_id: body.review_id ?? null,
      file_uri: body.file_uri,
      file_type: body.file_type,
      file_size: body.file_size,
      created_at,
    },
  });

  // Return a fully-typed IAimallBackendAttachment
  return {
    id: created.id as string & tags.Format<"uuid">,
    post_id: created.post_id as
      | (string & tags.Format<"uuid">)
      | null
      | undefined,
    comment_id: created.comment_id as
      | (string & tags.Format<"uuid">)
      | null
      | undefined,
    review_id: created.review_id as
      | (string & tags.Format<"uuid">)
      | null
      | undefined,
    file_uri: created.file_uri,
    file_type: created.file_type,
    file_size: created.file_size,
    created_at: toISOStringSafe(created.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Performs a soft delete on a review comment as the customer (author).
 *
 * Sets deleted_at to current timestamp, thus hiding the comment from normal
 * listings. Only the author (customer) of the comment may delete it. Fails if
 * not found, already deleted, or author mismatch. Admin/moderator cases are
 * separately authorized. Audit log is assumed to be handled separately.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer payload (comment author)
 * @param props.reviewId - The UUID of the review this comment belongs to
 * @param props.commentId - The UUID of the comment to soft-delete
 * @returns Void
 * @throws {Error} When the comment does not exist
 * @throws {Error} When the comment is already deleted
 * @throws {Error} When the customer is not the comment author
 */
export async function delete__aimall_backend_customer_reviews_$reviewId_comments_$commentId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, reviewId, commentId } = props;
  // Fetch comment by id & review_id
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      review_id: reviewId,
    },
  });
  if (!comment) throw new Error("Comment not found");
  if (comment.deleted_at) throw new Error("Comment already deleted");
  if (comment.customer_id !== customer.id) {
    throw new Error(
      "Permission denied: only the author may delete this comment",
    );
  }
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
  return;
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
