/**
 * Permanently deletes a channel assignment (hard remove) for a product by
 * channelAssignmentId.
 *
 * This function ensures that sellers can only delete assignments for their own
 * products; administrators have broader permissions (not handled here). The
 * deletion is irreversible (hard delete), in line with
 * aimall_backend_channel_assignments schema, which has no soft delete.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller executing the deletion
 * @param props.productId - The target product's UUID
 * @param props.channelAssignmentId - The distinct UUID of the assignment to
 *   remove
 * @returns Void
 * @throws {Error} If assignment record does not exist (404), does not belong to
 *   product, or seller is unauthorized to delete it
 */
export async function delete__aimall_backend_seller_products_$productId_channelAssignments_$channelAssignmentId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  channelAssignmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, productId, channelAssignmentId } = props;

  // 1. Fetch the channel assignment by ID
  const assignment =
    await MyGlobal.prisma.aimall_backend_channel_assignments.findUnique({
      where: { id: channelAssignmentId },
    });
  if (!assignment) throw new Error("Channel assignment not found");

  // 2. Confirm assignment belongs to requested product
  if (assignment.product_id !== productId) {
    throw new Error("Assignment does not belong to the specified product");
  }

  // 3. Authorization: ensure seller owns the product
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id) {
    throw new Error("Unauthorized: The seller does not own this product");
  }

  // 4. Hard delete the assignment (irreversible)
  await MyGlobal.prisma.aimall_backend_channel_assignments.delete({
    where: { id: channelAssignmentId },
  });
  // 5. (Optional: Audit logging would occur here if auditing is required)
}

