/**
 * Updates metadata fields for an attachment (file_uri, file_type, file_size).
 *
 * Performs a full update on attachment metadata for a specified attachmentId
 * using provided attributes (file URI, type, size) in accordance with the
 * aimall_backend_attachments schema. This is suitable for correcting incorrect
 * references, updating file type, or modifying metadata after moderation. May
 * not be used to update file content itself; file lifecycle is managed
 * externally. Requires administrative privileges (verified by decorator).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   operation
 * @param props.attachmentId - The attachment's unique id (UUID)
 * @param props.body - Updatable fields (file_uri, file_type, file_size)
 * @returns The updated attachment record with all fields populated
 * @throws {Error} If the attachment does not exist, or the id is invalid
 */
export async function put__aimall_backend_administrator_attachments_$attachmentId(props: {
  administrator: AdministratorPayload;
  attachmentId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IUpdate;
}): Promise<IAimallBackendAttachment> {
  const { attachmentId, body } = props;

  // Fetch the attachment to confirm existence
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
    });
  if (!attachment) throw new Error("Attachment not found");

  // Update only metadata fields (no linkage editing via API)
  const updated = await MyGlobal.prisma.aimall_backend_attachments.update({
    where: { id: attachmentId },
    data: {
      file_uri: body.file_uri ?? undefined,
      file_type: body.file_type ?? undefined,
      file_size: body.file_size ?? undefined,
    },
  });

  // Return as per IAimallBackendAttachment type, ensuring correct date-time branding
  return {
    id: updated.id,
    post_id: updated.post_id ?? null,
    comment_id: updated.comment_id ?? null,
    review_id: updated.review_id ?? null,
    file_uri: updated.file_uri,
    file_type: updated.file_type,
    file_size: updated.file_size,
    created_at: toISOStringSafe(updated.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
