/**
 * 커뮤니티 스냅샷의 메타데이터(캡션, 미디어 URI)를 수정합니다.
 *
 * 지정된 snapshotId의 커뮤니티 스냅샷 레코드에 대해, IAimallBackendSnapshot.IUpdate로 전달된
 * caption이나 media_uri를 변경합니다. 관리자는 본 메서드를 통해 커뮤니티 순간 포착(스냅샷)의 설명(캡션)이나 미디어 파일
 * 경로를 교정/검수/재지정할 수 있습니다. 엔티티 참조(연결)나 시스템 생성 필드(id, created_at 등)는 변경할 수 없습니다.
 * 파일 자체의 교체는 수행하지 않습니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.administrator - 인증된 관리자 페이로드(관리자만 호출 허용)
 * @param props.snapshotId - 수정할 스냅샷의 UUID
 * @param props.body - 변경할 캡션/미디어URI(중 최소 1개는 포함해야 함)
 * @returns 변경된 스냅샷 기록(IAimallBackendSnapshot)
 * @throws {Error} 스냅샷을 찾지 못한 경우(존재하지 않는 UUID)
 */
export async function put__aimall_backend_administrator_snapshots_$snapshotId(props: {
  administrator: AdministratorPayload;
  snapshotId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IUpdate;
}): Promise<IAimallBackendSnapshot> {
  const { administrator, snapshotId, body } = props;

  // 관리자 인증은 데코레이터 및 payload로 이미 선제적 검증됨

  // 1. 스냅샷 조회 및 존재성 확인
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot) throw new Error("Snapshot not found");

  // 2. 전달된 필드(caption, media_uri)만 부분 업데이트
  const updated = await MyGlobal.prisma.aimall_backend_snapshots.update({
    where: { id: snapshotId },
    data: {
      media_uri: body.media_uri ?? undefined,
      caption: body.caption ?? undefined,
    },
  });

  // 3. 결과 반환 (created_at 타입 안전 변환)
  return {
    id: updated.id,
    product_id: updated.product_id ?? undefined,
    post_id: updated.post_id ?? undefined,
    customer_id: updated.customer_id ?? undefined,
    media_uri: updated.media_uri,
    caption: updated.caption ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
