import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update an AIMall administrator record (Actors domain).
 *
 * Update an administrator record's information for an existing platform admin
 * account identified by administratorId. The request body includes new values
 * for permission_id, name, status, and may include email if required. Business
 * logic ensures that changes are allowed only by admins with sufficient
 * permission. All changes are logged for compliance, supporting security
 * reviews or escalation.
 *
 * The update operation never modifies sensitive authentication data (like
 * password), which is handled via dedicated flows. The response returns the
 * updated administrator record including all main attributes and audit
 * information for display or further inspection.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator making the request
 * @param props.administratorId - UUID of the administrator to update
 * @param props.body - Fields to update: permission_id, email, name, status,
 *   updated_at
 * @returns The updated administrator record
 * @throws {Error} When the target administrator does not exist or admin
 *   attempts to self-escalate permission
 */
export async function put__aimall_backend_administrator_administrators_$administratorId(props: {
  administrator: AdministratorPayload;
  administratorId: string & tags.Format<"uuid">;
  body: IAimallBackendAdministrator.IUpdate;
}): Promise<IAimallBackendAdministrator> {
  const { administrator, administratorId, body } = props;

  // Security: cannot self-elevate permission/role
  if (
    administrator.id === administratorId &&
    administrator.permission_id !== body.permission_id
  ) {
    throw new Error("Administrators may not update their own permission/role.");
  }

  // Fetch the target administrator
  const target = await MyGlobal.prisma.aimall_backend_administrators.findUnique(
    {
      where: { id: administratorId },
    },
  );
  if (!target) {
    throw new Error("Administrator not found.");
  }

  // Optionally, verify permission hierarchy rules here (not implemented)

  // Execute the update
  const updated = await MyGlobal.prisma.aimall_backend_administrators.update({
    where: { id: administratorId },
    data: {
      permission_id: body.permission_id,
      email: body.email,
      name: body.name,
      status: body.status,
      updated_at: body.updated_at,
    },
  });

  return {
    id: updated.id,
    permission_id: updated.permission_id,
    email: updated.email,
    name: updated.name,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Delete a support ticket by ID (seller hard delete).
 *
 * This endpoint allows a seller to permanently delete their own support ticket.
 * Hard deletion: If deleted, the record is irrevocably removed. Only the seller
 * who created the ticket can perform this operation; other sellers are
 * forbidden. The action is logged to the audit trail for compliance. Attempts
 * to delete non-existent or unauthorized tickets result in errors. (Admins may
 * have separate endpoints.)
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller payload (must match ticket
 *   requester_id)
 * @param props.supportTicketId - UUID of the support ticket to delete
 * @returns Void
 * @throws {Error} When the support ticket does not exist
 * @throws {Error} When the seller is not the ticket's creator
 */
export async function delete__aimall_backend_seller_supportTickets_$supportTicketId(props: {
  seller: SellerPayload;
  supportTicketId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, supportTicketId } = props;
  // Fetch the support ticket by ID
  const ticket =
    await MyGlobal.prisma.aimall_backend_support_tickets.findUnique({
      where: { id: supportTicketId },
    });
  if (!ticket) throw new Error("Support ticket not found");
  // Authorization: Only ticket creator (seller) can delete
  if (ticket.requester_id !== seller.id) {
    throw new Error(
      "Unauthorized: Only the ticket owner may delete this support ticket",
    );
  }
  // Hard delete the support ticket
  await MyGlobal.prisma.aimall_backend_support_tickets.delete({
    where: { id: supportTicketId },
  });
  // Write audit log entry for traceability
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: seller.id,
      event_type: "SUPPORT_TICKET_DELETE",
      event_target: supportTicketId,
      ip_address: undefined,
      outcome: "SUCCESS",
      detail_json: undefined,
      created_at: toISOStringSafe(new Date()),
    },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Hard delete a coupon from the aimall_backend_coupons table.
 *
 * This operation performs a hard deletion of a coupon, but only for coupons in
 * 'issued' or 'invalidated' status. If the coupon is redeemed, expired, or not
 * eligible, deletion will be rejected. This can only be performed by
 * authenticated administrator roles.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 * @param props.discountCampaignId - Discount campaign's unique identifier
 * @param props.couponId - Coupon's unique identifier for deletion
 * @returns Void (no content on success)
 * @throws {Error} If not found, or if coupon is not eligible for deletion
 */
export async function delete__aimall_backend_administrator_discountCampaigns_$discountCampaignId_coupons_$couponId(props: {
  administrator: AdministratorPayload;
  discountCampaignId: string & tags.Format<"uuid">;
  couponId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, discountCampaignId, couponId } = props;
  // Step 1: Find the coupon with the right ID and campaign
  const coupon = await MyGlobal.prisma.aimall_backend_coupons.findFirst({
    where: {
      id: couponId,
      discount_campaign_id: discountCampaignId,
    },
  });
  if (!coupon) throw new Error("Coupon not found");

  // Step 2: Validate coupon status for deletion
  if (!(coupon.status === "issued" || coupon.status === "invalidated")) {
    throw new Error(
      "Coupon is not eligible for deletion (must be issued or invalidated status)",
    );
  }

  // Step 3: Reject if coupon has been redeemed
  if (coupon.redeemed_at !== null && coupon.redeemed_at !== undefined) {
    throw new Error("Coupon has already been redeemed and cannot be deleted");
  }

  // Step 4: Reject if expired (expires_at before now)
  const now = new Date();
  const couponExpiresAt = new Date(coupon.expires_at);
  if (couponExpiresAt < now) {
    throw new Error("Coupon is expired and cannot be deleted");
  }

  // Step 5: Hard delete
  await MyGlobal.prisma.aimall_backend_coupons.delete({
    where: { id: couponId },
  });
  // (Optional: Audit log could be added here if required)
}

import { MyGlobal } from "../MyGlobal";
