/**
 * Permanently delete (hard) a shipment record from an order in
 * aimall_backend_shipments.
 *
 * Remove (hard delete) a shipment record linked to an order from the
 * aimall_backend_shipments table. This delete is permanent due to lack of a
 * soft-delete schema field. Only actors directly responsible for the order
 * fulfillment (seller, admin) are permitted to invoke this endpoint. Common
 * scenarios include error correction, fulfillment rollback, or audit-driven
 * cleanup. Strong validation prevents removal if it impacts compliance or
 * tracking integrity.
 *
 * Returns no content; success is indicated by HTTP status only.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the operation
 * @param props.orderId - Unique identifier of the order whose shipment record
 *   is being deleted
 * @param props.shipmentId - Unique identifier of the shipment record to remove
 * @returns Void
 * @throws {Error} When the shipment or order is not found, or if the seller
 *   does not own the order
 */
export async function delete__aimall_backend_seller_orders_$orderId_shipments_$shipmentId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  shipmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, shipmentId } = props;

  // 1. Fetch shipment and validate existence
  const shipment = await MyGlobal.prisma.aimall_backend_shipments.findUnique({
    where: { id: shipmentId },
  });
  if (!shipment) throw new Error("Shipment not found");

  // 2. Validate shipment belongs to the specified order
  if (shipment.order_id !== orderId) {
    throw new Error("Shipment does not belong to the given order");
  }

  // 3. Fetch the order and validate seller ownership
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id) {
    throw new Error("Unauthorized: You do not own this order");
  }

  // 4. Perform the hard delete
  await MyGlobal.prisma.aimall_backend_shipments.delete({
    where: { id: shipmentId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Delete or archive a snapshot record linked to a review, using reviewId and
 * snapshotId for record identification.
 *
 * Only an authorized seller may perform this action. The function checks that
 * the snapshot exists, is linked to the review, and that the seller owns the
 * product under review. Implements hard delete (no soft delete in model).
 *
 * @param props - Operation parameters
 * @param props.seller - Seller account payload (must be approved/authorized)
 * @param props.reviewId - UUID of the review whose snapshot to delete
 * @param props.snapshotId - UUID of the snapshot to delete
 * @returns Void when successfully deleted; throws error if not found or
 *   unauthorized
 * @throws {Error} Throws when snapshot or review not found, or if the seller is
 *   not authorized to delete the snapshot
 */
export async function delete__aimall_backend_seller_reviews_$reviewId_snapshots_$snapshotId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, reviewId, snapshotId } = props;

  // Find the snapshot
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
    select: { id: true, product_id: true },
  });
  if (!snapshot) throw new Error("Snapshot not found");

  // Find the review
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { id: true, product_id: true },
  });
  if (!review) throw new Error("Review not found");

  // Snap must link to this review by product
  if (!snapshot.product_id || !review.product_id)
    throw new Error("Invalid association");
  if (snapshot.product_id !== review.product_id)
    throw new Error("Snapshot not attached to this review");

  // Seller must own the product being reviewed
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { id: true, seller_id: true },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id)
    throw new Error("Unauthorized: Seller does not own this product");

  // Delete the snapshot
  await MyGlobal.prisma.aimall_backend_snapshots.delete({
    where: { id: snapshotId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSku";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update an existing SKU in the catalog.
 *
 * Update the details of an existing SKU specified by its unique identifier.
 * Input body must conform to the update DTO reflecting the underlying schema's
 * atomic SKU fields. Used by authorized administrators or product managers
 * only.
 *
 * Typical use cases include correcting SKU codes, reassigning SKUs to products,
 * or aligning SKU definitions after product option updates. All changes are
 * validated for referential and uniqueness constraints. Comprehensive auditing
 * is associated with this operation. Errors include constraint violation,
 * unauthorized access, or resource not found.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator (must be 'active')
 * @param props.skuId - The unique identifier of the SKU to update
 * @param props.body - The update object for the SKU (sku_code optional)
 * @returns The persisted SKU after update
 * @throws {Error} When administrator is unauthorized or inactive
 * @throws {Error} When SKU does not exist
 * @throws {Error} When unique constraint or referential integrity errors occur
 */
export async function put__aimall_backend_administrator_skus_$skuId(props: {
  administrator: AdministratorPayload;
  skuId: string & tags.Format<"uuid">;
  body: IAimallBackendSku.IUpdate;
}): Promise<IAimallBackendSku> {
  const { administrator, skuId, body } = props;

  // Defensive: Revalidate administrator status (decorator should ensure but double check)
  const admin = await MyGlobal.prisma.aimall_backend_administrators.findUnique({
    where: { id: administrator.id },
    select: { id: true, status: true },
  });
  if (!admin || admin.status !== "active") {
    throw new Error("Unauthorized: Administrator not found or not active");
  }

  // Confirm SKU existence before update
  const exist = await MyGlobal.prisma.aimall_backend_skus.findUnique({
    where: { id: skuId },
    select: { id: true },
  });
  if (!exist) {
    throw new Error("SKU not found");
  }

  // Prepare update: only update fields provided in the body
  try {
    const updated = await MyGlobal.prisma.aimall_backend_skus.update({
      where: { id: skuId },
      data: {
        sku_code: body.sku_code ?? undefined,
      },
    });
    return {
      id: updated.id,
      product_id: updated.product_id,
      sku_code: updated.sku_code,
    };
  } catch (err) {
    // Prisma unique constraint violation error codes start with 'P'
    if (
      typeof err === "object" &&
      err !== null &&
      "code" in err &&
      typeof (err as any).code === "string" &&
      (err as any).code.startsWith("P")
    ) {
      throw new Error("Constraint violation: " + (err as any).message);
    }
    throw err;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
