import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Delete (or hard-delete) a snapshot (photo/media) entity attached to a post.
 *
 * This endpoint deletes an existing snapshot/media from a post in the community
 * system. It first verifies the existence of the specified snapshot (by
 * snapshotId) and its association with the specified post (by postId). If
 * either the snapshot or the post does not exist, a 404 error is thrown.
 *
 * IMPORTANT: The schema does not link posts or snapshots to sellers; therefore,
 * seller authorization enforcement for cross-ownership is not possible in this
 * implementation. Only existence checks can be performed. If business logic
 * changes in the future to provide a linkage between posts, snapshots, and
 * sellers, authorization enforcement should be implemented accordingly.
 *
 * Performs a hard delete of the snapshot, as the snapshot model does not
 * implement soft delete (deleted_at field is absent). Ensures compliance with
 * schema constraints and avoids unintentional retention.
 *
 * @param props - Operation parameters
 * @param props.seller - Authenticated seller payload (seller must be logged in
 *   and approved)
 * @param props.postId - UUID of the parent post
 * @param props.snapshotId - UUID of the snapshot to delete
 * @returns Void (no content returned on success)
 * @throws {Error} When the snapshot or post does not exist (404 Not Found)
 */
export async function delete__aimall_backend_seller_posts_$postId_snapshots_$snapshotId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, postId, snapshotId } = props;

  // 1. Verify the snapshot exists and is linked to the specified post
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findFirst({
    where: {
      id: snapshotId,
      post_id: postId,
    },
  });
  if (!snapshot) {
    throw new Error("Snapshot or Post not found");
  }

  // 2. Verify the post exists (cannot enforce seller authorization due to schema limitation)
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post) {
    throw new Error("Snapshot or Post not found");
  }

  // 3. Perform hard delete (no soft-delete possible: deleted_at does not exist on snapshots)
  await MyGlobal.prisma.aimall_backend_snapshots.delete({
    where: { id: snapshotId },
  });
  // No content returned per OpenAPI contract
}

