/**
 * Permanently delete a file/media attachment for a comment by IDs.
 *
 * Removal is permanent and cannot be undone, and is permitted for comment
 * authors (customers) or administrators with necessary rights. No soft-delete
 * supported by the schema. Any file storage associated with file_uri must be
 * handled according to external object store policies.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer (must be comment author)
 * @param props.commentId - UUID PK of the parent comment for the attachment
 * @param props.attachmentId - UUID PK of the attachment to delete
 * @returns Void
 * @throws {Error} If the attachment does not exist or does not belong to the
 *   given comment
 * @throws {Error} If the requesting customer is not the author of the comment
 */
export async function delete__aimall_backend_customer_comments_$commentId_attachments_$attachmentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, commentId, attachmentId } = props;

  // 1. Find the attachment and verify linkage to comment
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
    });
  if (!attachment || attachment.comment_id !== commentId) {
    throw new Error("Attachment not found");
  }

  // 2. Find the comment and verify authorship
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: commentId },
  });
  if (!comment || comment.customer_id !== customer.id) {
    throw new Error("Forbidden: Only the author can delete this attachment");
  }

  // 3. Delete the attachment
  await MyGlobal.prisma.aimall_backend_attachments.delete({
    where: { id: attachmentId },
  });
  // Note: physical file deletion from file_uri must be performed by external file storage deletion logic as per business rules.
}

import { MyGlobal } from "../MyGlobal";
