/**
 * Updates a catalog product in aimall_backend_products by unique productId.
 *
 * Only administrators (authenticated via payload) may update products with this
 * endpoint. Allows updating of mutable product fields (title, description,
 * category_id, main_thumbnail_uri, status). Enforces unique title per seller,
 * verifies references, updates updated_at to now, and returns the updated
 * product entity.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator making the
 *   request (payload)
 * @param props.productId - UUID of the target product to update
 * @param props.body - DTO fields for updating the product
 * @returns The updated IAimallBackendProduct entity reflecting changes
 * @throws {Error} When the product does not exist, or constraints/foreign keys
 *   are violated
 */
export async function put__aimall_backend_administrator_products_$productId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProduct.IUpdate;
}): Promise<IAimallBackendProduct> {
  const { administrator, productId, body } = props;
  // 1. Confirm the product exists
  const existing = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!existing) throw new Error("Product does not exist");
  try {
    // 2. Update permissible fields only
    const updated = await MyGlobal.prisma.aimall_backend_products.update({
      where: { id: productId },
      data: {
        category_id: body.category_id ?? undefined,
        title: body.title ?? undefined,
        description: body.description ?? undefined,
        main_thumbnail_uri: body.main_thumbnail_uri ?? undefined,
        status: body.status ?? undefined,
        updated_at: toISOStringSafe(new Date()),
      },
    });
    // 3. Return all product fields, mapping Date fields to strings
    return {
      id: updated.id,
      category_id: updated.category_id,
      seller_id: updated.seller_id,
      title: updated.title,
      description: updated.description ?? undefined,
      main_thumbnail_uri: updated.main_thumbnail_uri ?? undefined,
      status: updated.status,
      created_at: toISOStringSafe(updated.created_at),
      updated_at: toISOStringSafe(updated.updated_at),
    };
  } catch (error: any) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new Error("Duplicate product title for this seller");
    }
    throw new Error(error.message);
  }
}

