/**
 * Delete/remove a single order item from an order (Order Items table).
 *
 * Removes a single order item line from a given order record, specified by both
 * parent order UUID and order item UUID. Only possible if the parent order is
 * open and mutable (order status = 'pending'). The action does not affect the
 * parent order's existence but will cause recalculation of total amounts in
 * subsequent operations.
 *
 * Permitted for sellers/administrators and, in some business workflows, the
 * order-owning customer. Operation returns an appropriate confirmation or error
 * if not found, not permissible, or not authorized.
 *
 * @param props - The input props.
 * @param props.seller - The authenticated seller account.
 * @param props.orderId - UUID of the parent order from which the item will be
 *   removed.
 * @param props.orderItemId - UUID of the order item to delete.
 * @returns Void
 * @throws {Error} When the order item or order is not found.
 * @throws {Error} When the order item does not belong to the order.
 * @throws {Error} When the seller does not own the order.
 * @throws {Error} When the order is finalized (not pending).
 */
export async function delete__aimall_backend_seller_orders_$orderId_orderItems_$orderItemId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, orderId, orderItemId } = props;

  // 1. Fetch order item and check it belongs to the target order
  const orderItem = await MyGlobal.prisma.aimall_backend_order_items.findUnique(
    {
      where: { id: orderItemId },
    },
  );
  if (!orderItem) throw new Error("Order item not found");
  if (orderItem.order_id !== orderId)
    throw new Error("Order item does not belong to order");

  // 2. Fetch order and check seller ownership
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id)
    throw new Error("Unauthorized: Seller does not own this order");

  // 3. Order mutability check (only pending orders are mutable)
  if (order.order_status !== "pending") {
    throw new Error("Order is finalized and cannot be modified");
  }

  // 4. Hard delete (schema has no soft delete fields)
  await MyGlobal.prisma.aimall_backend_order_items.delete({
    where: { id: orderItemId },
  });
}

