import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Permanently remove a coupon redemption event.
 *
 * Hard delete from the event/audit log. Only available to administrator/support
 * roles with permissible access. Not permitted for resolved/closed/caseful
 * fraud events (deletion is blocked if redemption_status is 'resolved',
 * 'closed', or 'caseful_fraud'). Fully removes the record and logs the
 * operation for auditing purposes. Returns no content. Throws if the record
 * does not exist or is not deletable.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   deletion
 * @param props.couponId - Coupon under which the redemption event is deleted
 *   (UUID)
 * @param props.couponRedemptionId - Redemption event unique identifier to
 *   delete (UUID)
 * @returns Void
 * @throws {Error} When coupon redemption event does not exist or is locked by
 *   status
 */
export async function delete__aimall_backend_administrator_coupons_$couponId_couponRedemptions_$couponRedemptionId(props: {
  administrator: AdministratorPayload;
  couponId: string & tags.Format<"uuid">;
  couponRedemptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, couponId, couponRedemptionId } = props;
  // 1. Find coupon_redemption by id & coupon_id
  const redemption =
    await MyGlobal.prisma.aimall_backend_coupon_redemptions.findFirst({
      where: { id: couponRedemptionId, coupon_id: couponId },
    });
  if (!redemption) {
    throw new Error(
      "Coupon redemption event not found or does not match coupon.",
    );
  }
  // 2. Block delete for locked statuses
  const forbiddenStatus = ["resolved", "closed", "caseful_fraud"] as const;
  if (forbiddenStatus.includes(redemption.redemption_status)) {
    throw new Error(
      "This coupon redemption event is locked and cannot be deleted.",
    );
  }
  // 3. Hard delete
  await MyGlobal.prisma.aimall_backend_coupon_redemptions.delete({
    where: { id: couponRedemptionId },
  });
  // 4. Write audit log for compliance
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "COUPON_REDEMPTION_DELETE",
      event_target: couponRedemptionId,
      outcome: "SUCCESS",
      created_at: toISOStringSafe(new Date()),
    },
  });
  // Done
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Permanently delete a specific child category under a parent.
 *
 * This function permanently deletes a child category in the
 * aimall_backend_categories table, under a specified parent category. It first
 * checks that the target category's parent_id matches the provided parent, and
 * then verifies that the category is not referenced as a parent by any other
 * categories (i.e., it has no children) and is not assigned to any products. If
 * all checks pass, the category is hard-deleted. Otherwise, a clear error is
 * thrown for each business rule violation.
 *
 * Restrictions:
 *
 * - Only administrator users may perform this operation.
 * - Category must exist, and its parent_id must match categoryId.
 * - Category cannot be deleted if it has subcategories, or is assigned to any
 *   products.
 * - The operation is a hard delete (no soft delete/deleted_at field exists).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   valid and active)
 * @param props.categoryId - UUID of the parent category (the direct parent
 *   under which the child sits)
 * @param props.childCategoryId - UUID of the target child category for deletion
 * @returns Void
 * @throws {Error} When the child category does not exist
 * @throws {Error} When the parent-child relationship does not match
 * @throws {Error} When the target category has subcategories (children) still
 *   present
 * @throws {Error} When the category is still assigned to one or more products
 */
export async function delete__aimall_backend_administrator_categories_$categoryId_childCategories_$childCategoryId(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
  childCategoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, categoryId, childCategoryId } = props;

  // 1. Fetch category for existence and parent validation
  const child = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: childCategoryId },
  });
  if (!child) throw new Error("Child category not found");
  if (child.parent_id !== categoryId) {
    throw new Error("Parent/child relationship mismatch");
  }

  // 2. Ensure the category is not a parent for any existing categories (no children)
  const childrenCount = await MyGlobal.prisma.aimall_backend_categories.count({
    where: { parent_id: childCategoryId },
  });
  if (childrenCount > 0) {
    throw new Error("Cannot delete: category has active subcategories");
  }

  // 3. Ensure the category is not assigned to any products
  const productCount = await MyGlobal.prisma.aimall_backend_products.count({
    where: { category_id: childCategoryId },
  });
  if (productCount > 0) {
    throw new Error("Cannot delete: category is assigned to products");
  }

  // 4. Hard delete (permanent)
  await MyGlobal.prisma.aimall_backend_categories.delete({
    where: { id: childCategoryId },
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Soft-delete a reply (child comment) under a thread (set deleted_at).
 *
 * Performs soft deletion of a reply under a parent comment thread, following
 * audit and compliance requirements. The system sets deleted_at for the
 * specified childCommentId (only if its parent_id matches the specified parent
 * commentId), rather than removing the row. Access control ensures only the
 * author or a platform administrator can delete. Soft-deleted comments are
 * hidden in regular query results but persist for audit trace and restoration
 * windows.
 *
 * Error handling includes invalid IDs, non-existent parent/child, or attempts
 * to delete already-deleted comments. No comment body or data is lost, aligning
 * with policy for GDPR compliance and community governance.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   deletion (must be active, as enforced by decorator)
 * @param props.commentId - UUID of the parent comment thread
 * @param props.childCommentId - UUID of the child comment to be soft-deleted
 * @returns Void (throws Error if the child comment does not exist, parent is
 *   mismatched, or already soft-deleted)
 * @throws {Error} If child comment not found
 * @throws {Error} If parent-child relationship is mismatched
 * @throws {Error} If comment is already deleted
 */
export async function delete__aimall_backend_administrator_comments_$commentId_comments_$childCommentId(props: {
  administrator: AdministratorPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, commentId, childCommentId } = props;

  // Fetch the child comment by ID, selecting only required fields for validation
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: childCommentId },
    select: {
      id: true,
      parent_id: true,
      deleted_at: true,
    },
  });

  // Error if comment is not found
  if (!comment) throw new Error("Child comment not found");

  // Error if the comment's parent doesn't match the provided parent
  if (comment.parent_id !== commentId)
    throw new Error("Mismatched parent for this child comment");

  // Error if already soft-deleted
  if (comment.deleted_at !== null) throw new Error("Comment already deleted");

  // Soft-delete: set deleted_at and updated_at to the current timestamp (ISO string)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: childCommentId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });
}

