}): Promise<IAimallBackendReview> {
  const { customer, reviewId, body } = props;

  // Fetch and validate review existence
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) throw new Error("Review not found");
  if (review.deleted_at !== null)
    throw new Error("Cannot edit a deleted review");
  if (review.customer_id !== customer.id)
    throw new Error("Unauthorized: You may only edit your own reviews");

  // At least one updatable field must be provided
  if (
    body.title === undefined &&
    body.body === undefined &&
    body.rating === undefined
  ) {
    throw new Error(
      "At least one field (title, body, or rating) must be provided for update",
    );
  }
  // Enforce rating 1–5 if provided
  if (body.rating !== undefined && (body.rating < 1 || body.rating > 5)) {
    throw new Error("Rating must be between 1 and 5 (inclusive)");
  }

  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  // Update allowed fields only
  const updated = await MyGlobal.prisma.aimall_backend_reviews.update({
    where: { id: reviewId },
    data: {
      ...(body.title !== undefined ? { title: body.title } : {}),
      ...(body.body !== undefined ? { body: body.body } : {}),
      ...(body.rating !== undefined ? { rating: body.rating } : {}),
      updated_at: now,
    },
  });

  // Prepare return object, ensuring all dates are strings and brands are preserved
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    product_id: updated.product_id,
    title: updated.title,
    body: updated.body,
    rating: updated.rating,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

