/**
 * Update an existing product in the aimall_backend_products catalog by unique
 * productId.
 *
 * Only the owning seller can update their own products (by matching seller.id
 * to product.seller_id). Permissible updates include title, description,
 * category, status, and main_thumbnail_uri. All changes will update the
 * updated_at timestamp. Illegal updates or ownership errors will throw errors.
 *
 * @param props - Update request parameters
 * @param props.seller SellerPayload - Authenticated seller context, must match
 *   product's seller_id
 * @param props.productId String & tags.Format<'uuid'> - UUID of the product to
 *   update
 * @param props.body IAimallBackendProduct.IUpdate - Fields to update (all
 *   optional)
 * @returns IAimallBackendProduct - The updated product with all fields,
 *   including proper date-time formatting for API compatibility
 * @throws {Error} If product does not exist, seller is not owner, invalid
 *   category_id, or FK/reference integrity fails.
 */
export async function put__aimall_backend_seller_products_$productId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProduct.IUpdate;
}): Promise<IAimallBackendProduct> {
  const { seller, productId, body } = props;

  // 1. Fetch product; throw if not found
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) {
    throw new Error("Product not found");
  }
  // 2. Ensure only the owner can update
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: You do not own this product");
  }
  // 3. If updating category_id, must exist
  if (body.category_id !== undefined) {
    const category = await MyGlobal.prisma.aimall_backend_categories.findUnique(
      { where: { id: body.category_id } },
    );
    if (!category) {
      throw new Error("Invalid category_id");
    }
  }
  // 4. Update fields (only provided ones), updated_at always
  const updated = await MyGlobal.prisma.aimall_backend_products.update({
    where: { id: productId },
    data: {
      category_id: body.category_id ?? undefined,
      title: body.title ?? undefined,
      description:
        body.description === null ? null : (body.description ?? undefined),
      main_thumbnail_uri:
        body.main_thumbnail_uri === null
          ? null
          : (body.main_thumbnail_uri ?? undefined),
      status: body.status ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // 5. Return, mapping date fields (no native Date)
  return {
    id: updated.id,
    category_id: updated.category_id,
    seller_id: updated.seller_id,
    title: updated.title,
    description: updated.description ?? undefined,
    main_thumbnail_uri: updated.main_thumbnail_uri ?? undefined,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

