/**
 * Link a new external account to the customer (Actors DB).
 *
 * This creates a new external (federated/OAuth) account linkage for the target
 * customer, typically used in account recovery, admin onboarding, or social
 * login linking. Only administrators can use this endpoint.
 *
 * Validates that the external account (provider + external_user_id) is not
 * already linked to a different customer, and that the customer exists. Fails
 * if an external account with the requested provider and user ID is already
 * linked elsewhere.
 *
 * @param props - The request properties
 * @param props.administrator - Authenticated administrator performing the
 *   action
 * @param props.customerId - Unique identifier of the customer to link the
 *   external account to
 * @param props.body - External account provider/user to link
 * @returns Newly created external account record matching the DTO
 *   IAIMallBackendExternalAccount
 * @throws {Error} If the target customer does not exist
 * @throws {Error} If the external account is already linked to another customer
 */
export async function post__aimall_backend_administrator_customers_$customerId_externalAccounts(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAIMallBackendExternalAccount.ICreate;
}): Promise<IAIMallBackendExternalAccount> {
  const { administrator, customerId, body } = props;

  // 1. Ensure the customer exists
  const customer = await MyGlobal.prisma.aimall_backend_customers.findUnique({
    where: { id: customerId },
  });
  if (!customer) {
    throw new Error("Target customer not found");
  }

  // 2. Ensure uniqueness: external account (provider + external_user_id) is not already linked
  const duplicate =
    await MyGlobal.prisma.aimall_backend_external_accounts.findFirst({
      where: {
        provider: body.provider,
        external_user_id: body.external_user_id,
      },
    });
  if (duplicate) {
    throw new Error("This external account is already linked to another user");
  }

  // 3. Prepare new ids and timestamps
  const id = v4() as string & tags.Format<"uuid">;
  const linked_at = toISOStringSafe(new Date());

  // 4. Create the new external account record
  const created = await MyGlobal.prisma.aimall_backend_external_accounts.create(
    {
      data: {
        id,
        customer_id: customerId,
        provider: body.provider,
        external_user_id: body.external_user_id,
        linked_at,
      },
    },
  );

  // 5. Return the crafted DTO
  return {
    id: created.id,
    customer_id: created.customer_id,
    provider: created.provider,
    external_user_id: created.external_user_id,
    linked_at: toISOStringSafe(created.linked_at),
  };
}

