/**
 * Updates a coupon voucher (identified by couponId) with the given fields.
 *
 * This function allows administrators to modify an existing coupon's properties
 * such as assignment, status, code, and dates. All business logic checks must
 * be performed upstream; fields not provided in the update payload are left
 * unchanged.
 *
 * Authorization is strictly enforced: only active administrators may invoke
 * this operation.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator payload (must be
 *   active)
 * @param props.couponId - UUID of the coupon voucher to update
 * @param props.body - The partial update payload (fields from
 *   IAimallBackendCoupon.IUpdate)
 * @returns The updated coupon row, fully normalized and with ISO-branded date
 *   fields
 * @throws {Error} If the administrator is not active, or the coupon is not
 *   found
 */
export async function put__aimall_backend_administrator_coupons_$couponId(props: {
  administrator: AdministratorPayload;
  couponId: string & tags.Format<"uuid">;
  body: IAimallBackendCoupon.IUpdate;
}): Promise<IAimallBackendCoupon> {
  const { administrator, couponId, body } = props;

  // Step 1: Authorization enforcement
  if (administrator.status !== "active") {
    throw new Error(
      "Unauthorized: Only active administrators can update coupons",
    );
  }

  // Step 2: Lookup coupon by primary key
  const found = await MyGlobal.prisma.aimall_backend_coupons.findUnique({
    where: { id: couponId },
  });
  if (!found) throw new Error("Coupon not found");

  // Step 3: Prepare update fields (only fields present in the DTO)
  const updated = await MyGlobal.prisma.aimall_backend_coupons.update({
    where: { id: couponId },
    data: {
      // customer_id is nullable, must distinguish undefined vs null
      ...(body.customer_id !== undefined && {
        customer_id: body.customer_id,
      }),
      // code is optional
      ...(body.code !== undefined && { code: body.code }),
      // status is optional
      ...(body.status !== undefined && { status: body.status }),
      // issued_at/expires_at/redeemed_at: clean null/undefined and apply toISOStringSafe
      ...(body.issued_at !== undefined && {
        issued_at: toISOStringSafe(body.issued_at),
      }),
      ...(body.expires_at !== undefined && {
        expires_at: toISOStringSafe(body.expires_at),
      }),
      // redeemed_at is nullable
      ...(body.redeemed_at !== undefined && {
        redeemed_at:
          body.redeemed_at === null ? null : toISOStringSafe(body.redeemed_at),
      }),
    },
  });

  // Step 4: Normalize all date fields in response
  return {
    id: updated.id,
    discount_campaign_id: updated.discount_campaign_id,
    customer_id: updated.customer_id ?? null,
    code: updated.code,
    status: updated.status,
    issued_at: toISOStringSafe(updated.issued_at),
    expires_at: toISOStringSafe(updated.expires_at),
    redeemed_at:
      updated.redeemed_at === null || updated.redeemed_at === undefined
        ? null
        : toISOStringSafe(updated.redeemed_at),
  };
}

