 * @returns The persisted product option entity with all fields, including
 *   generated UUID
 * @throws {Error} If product does not exist
 * @throws {Error} If seller does not own product
 * @throws {Error} If duplicate product option exists
 */
export async function post__aimall_backend_seller_products_$productId_productOptions(props: {
