  // Ownership enforcement: product must exist and be owned by seller
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
    select: { seller_id: true },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: Seller does not own this product");
  }

  // Uniqueness enforcement: [product_id, name, value] must not exist
  const duplicate =
    await MyGlobal.prisma.aimall_backend_product_options.findFirst({
      where: {
        product_id: productId,
        name: body.name,
        value: body.value,
      },
      select: { id: true },
    });
  if (duplicate) {
    throw new Error(
      "Duplicate product option exists for this product (name and value must be unique per product)",
    );
  }

  // Create new product option record, generate id with correct UUID branding
  const created = await MyGlobal.prisma.aimall_backend_product_options.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      product_id: productId,
      name: body.name,
      value: body.value,
    } satisfies IAimallBackendProductOption,
  });

  return created;
}

