import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create new product bundle for a product (as bundle group).
 *
 * Associates the specified product (the bundle group) with a component product,
 * indicating if inclusion is required and how many are included per bundle.
 * Enforces that only an authenticated seller owning the main product can add
 * bundles, that all referenced products exist, and does not allow duplicate
 * component assignments.
 *
 * @param props - Function inputs
 * @param props.seller - Authenticated seller payload (must own main product)
 * @param props.productId - Product ID for bundle group (must be owned by
 *   seller)
 * @param props.body - Bundle creation data (component product, required,
 *   quantity)
 * @returns The created bundle relationship record
 * @throws {Error} If seller does not own the product, either product does not
 *   exist, or bundle is duplicate
 */
export async function post__aimall_backend_seller_products_$productId_productBundles(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProductBundle.ICreate;
}): Promise<IAimallBackendProductBundle> {
  const { seller, productId, body } = props;

  // Step 1: Verify seller owns the bundle group product
  const master = await MyGlobal.prisma.aimall_backend_products.findFirst({
    where: { id: productId, seller_id: seller.id },
  });
  if (!master)
    throw new Error(
      "Forbidden: Seller does not own this product or product does not exist.",
    );

  // Step 2: Make sure component product exists
  const component = await MyGlobal.prisma.aimall_backend_products.findFirst({
    where: { id: body.component_product_id },
  });
  if (!component) throw new Error("Component product does not exist.");

  // Step 3: Uniqueness enforcement (one bundle per master+component allowed)
  const exists = await MyGlobal.prisma.aimall_backend_product_bundles.findFirst(
    {
      where: {
        bundle_product_id: productId,
        component_product_id: body.component_product_id,
      },
    },
  );
  if (exists)
    throw new Error(
      "Bundle for this component already exists for this product.",
    );

  // Step 4: Create the bundle relationship
  const created = await MyGlobal.prisma.aimall_backend_product_bundles.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      bundle_product_id: productId,
      component_product_id: body.component_product_id,
      is_required: body.is_required,
      quantity: body.quantity,
    },
  });

  // Step 5: Return the IAimallBackendProductBundle response, strictly typed
  return {
    id: created.id,
    bundle_product_id: created.bundle_product_id,
    component_product_id: created.component_product_id,
    is_required: created.is_required,
    quantity: created.quantity,
  };
}

