/**
 * Retrieves a single child comment under a given parent comment.
 *
 * - Verifies the parent comment exists and is not soft-deleted.
 * - Finds the child comment matching id, parent_id, and not soft-deleted.
 * - Excludes soft-deleted comments from results, as per audit requirements.
 * - Ensures access control: only the author (customer) can view private comments.
 * - Returns detailed comment info per IAimallBackendComment DTO specification.
 *
 * @param props - Request parameter and authentication object
 * @param props.customer - The authenticated customer making the request (access
 *   enforcement)
 * @param props.commentId - The UUID of the parent comment (thread root)
 * @param props.childCommentId - The UUID of the child (reply) comment
 * @returns `{IAimallBackendComment}` - The detailed comment DTO object
 * @throws {Error} If the parent or child comment does not exist, does not match
 *   thread, is soft deleted, or access is forbidden
 */
export async function get__aimall_backend_customer_comments_$commentId_comments_$childCommentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendComment> {
  const { customer, commentId, childCommentId } = props;

  // Step 1: Ensure parent comment exists and is not soft-deleted
  const parent = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      deleted_at: null,
    },
  });
  if (!parent) {
    throw new Error("Parent comment not found or has been deleted.");
  }

  // Step 2: Retrieve child comment, ensure it is a direct child and not soft-deleted
  const child = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: childCommentId,
      parent_id: commentId,
      deleted_at: null,
    },
  });
  if (!child) {
    throw new Error(
      "Child comment not found, is not a direct child, or has been deleted.",
    );
  }

  // Step 3: Authorization: only the author can view private comments
  if (child.is_private && child.customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: Only the author can view this private comment.",
    );
  }

  // Step 4: Map to DTO, converting dates to ISO8601 strings and applying nulls correctly
  return {
    id: child.id,
    post_id: child.post_id ?? null,
    review_id: child.review_id ?? null,
    parent_id: child.parent_id ?? null,
    customer_id: child.customer_id ?? null,
    body: child.body,
    is_private: child.is_private,
    created_at: toISOStringSafe(child.created_at),
    updated_at: toISOStringSafe(child.updated_at),
    deleted_at: child.deleted_at ? toISOStringSafe(child.deleted_at) : null,
  };
}

