 *
 * This operation permanently deletes a behavioral tracking record from the
 * Actors domain based on customer ownership. Only the owner of the record
 * (authenticated customer) may execute this operation. If the record does not
 * exist, a 404 error is thrown. If the record does not belong to the current
 * customer, a 403 error is thrown. This is an irreversible, hard delete; there
 * is no soft delete option per schema.
 *
 * @param props - Function parameters
 * @param props.customer - The authenticated customer payload (must be the
 *   record owner)
 * @param props.customerId - The unique identifier of the customer whose record
 *   is to be deleted (for route path; must match the authenticated customer)
 * @param props.behaviorTrackingId - Unique identifier of the behavior tracking
 *   event to delete
 * @returns Void (on success)
 * @throws {Error} When the record is not found (404)
 * @throws {Error} When the user is not authorized to delete this record (403)
 */
export async function delete__aimall_backend_customer_customers_$customerId_behaviorTrackings_$behaviorTrackingId(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  behaviorTrackingId: string & tags.Format<"uuid">;
