/**
 * Create a channel assignment for a seller's product (register product to
 * channel).
 *
 * This endpoint allows authenticated sellers to assign a product they own to a
 * new channel, registering it for listing or management purposes on that
 * platform. It creates a new aimall_backend_channel_assignments record linking
 * the specified product to the desired channel and records the assignment
 * timestamp.
 *
 * Input validation ensures that the referenced product and channel are valid
 * and not already assigned together. Access control restricts creation to
 * sellers (for their own products). Duplicate assignment is prevented by the
 * unique constraint in the schema.
 *
 * Upon successful creation, the full assignment record is returned. Errors are
 * thrown for invalid or duplicate requests, or on insufficient permission.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the assignment
 * @param props.productId - Unique identifier of the target product for
 *   assignment
 * @param props.body - Input defining the channel assignment (channel_id,
 *   assigned_at)
 * @returns The created channel assignment record referencing both product and
 *   channel
 * @throws {Error} When the product does not exist, is not owned by this seller,
 *   the channel does not exist, or the assignment already exists
 */
export async function post__aimall_backend_seller_products_$productId_channelAssignments(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendChannelAssignment.ICreate;
}): Promise<IAimallBackendChannelAssignment> {
  const { seller, productId, body } = props;

  // Step 1: Verify the product exists and is owned by this seller
  const product = await MyGlobal.prisma.aimall_backend_products.findFirst({
    where: {
      id: productId,
      seller_id: seller.id,
    },
  });
  if (!product) {
    throw new Error(
      "Product not found or you do not have permission to assign.",
    );
  }

  // Step 2: Verify the channel exists
  const channel = await MyGlobal.prisma.aimall_backend_channels.findFirst({
    where: { id: body.channel_id },
  });
  if (!channel) {
    throw new Error("Channel not found.");
  }

  // Step 3: Prevent duplicate assignment
  const duplicate =
    await MyGlobal.prisma.aimall_backend_channel_assignments.findFirst({
      where: {
        product_id: productId,
        channel_id: body.channel_id,
      },
    });
  if (duplicate) {
    throw new Error("Assignment already exists for this product and channel.");
  }

  // Step 4: Create the assignment (UUID generated, dates as string)
  const assignmentInput = {
    id: v4() as string & tags.Format<"uuid">,
    product_id: productId,
    channel_id: body.channel_id,
    assigned_at: toISOStringSafe(body.assigned_at),
  } satisfies IAimallBackendChannelAssignment;

  const created =
    await MyGlobal.prisma.aimall_backend_channel_assignments.create({
      data: assignmentInput,
    });

  return {
    id: created.id,
    product_id: created.product_id,
    channel_id: created.channel_id,
    assigned_at: toISOStringSafe(created.assigned_at),
  };
}

