 */
export async function get__aimall_backend_customer_carts_$cartId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendCart> {
  const { customer, cartId } = props;

  // 1. Find the cart by ID
  const cart = await MyGlobal.prisma.aimall_backend_carts.findFirst({
    where: { id: cartId },
  });

  // 2. 404 if not found
  if (!cart) throw new Error("Cart not found");

