 * archived.
 *
 * - Only the owning seller may update their order (checked via seller_id).
 * - All changes are blocked if the order is archived (archived_at is not null).
 * - Only permitted fields (address_id, order_status, total_amount, currency,
 *   updated_at) can be updated.
 * - All date and UUID values are handled with strict branding and conversion.
 *
 * @param props - Properties for this provider
 * @param props.seller - The authenticated seller making the request (must match
 *   order's seller_id)
 * @param props.orderId - UUID of the order to update
 * @param props.body - The updater request body (fields allowed to change)
 * @returns Updated IAimallBackendOrder record, with all fields correctly
 *   branded and typed
 * @throws {Error} When the order does not exist
 * @throws {Error} When the seller does not own the order
 * @throws {Error} When the order is archived (immutable)
 */
export async function put__aimall_backend_seller_orders_$orderId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrder.IUpdate;
