      total_amount:
        body.total_amount === undefined ? undefined : body.total_amount,
      currency: body.currency === undefined ? undefined : body.currency,
      updated_at: toISOStringSafe(body.updated_at),
    },
  });

  // 3. Return the updated order: convert all date fields to properly branded strings; archived_at can be null
  return {
    id: updated.id as string & tags.Format<"uuid">,
    customer_id: updated.customer_id as string & tags.Format<"uuid">,
    seller_id: updated.seller_id as string & tags.Format<"uuid">,
    address_id: updated.address_id as string & tags.Format<"uuid">,
    order_number: updated.order_number,
    order_status: updated.order_status,
    total_amount: updated.total_amount,
    currency: updated.currency,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    archived_at:
      updated.archived_at !== null && updated.archived_at !== undefined
        ? toISOStringSafe(updated.archived_at)
