import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Hard delete a specific SKU for a product.
 *
 * Permanently removes a SKU record for the specified product. This function
 * enforces referential integrity rules: it rejects deletion if the SKU is still
 * referenced by existing order items or inventory snapshots. If the SKU does
 * not belong to the provided product or does not exist, an error is thrown.
 * Only administrators with valid authentication may perform this operation.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator payload
 * @param props.productId - UUID of the parent product to which the SKU belongs
 * @param props.skuId - UUID of the SKU (variant) to be deleted
 * @returns Void
 * @throws {Error} If the SKU does not exist or does not belong to the specified
 *   product
 * @throws {Error} If the SKU is referenced by an order item
 * @throws {Error} If the SKU is referenced by an inventory snapshot
 */
export async function delete__aimall_backend_administrator_products_$productId_skus_$skuId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, productId, skuId } = props;

  // Step 1: Ensure SKU exists and is subordinate to the declared product
  const sku = await MyGlobal.prisma.aimall_backend_skus.findFirst({
    where: {
      id: skuId,
      product_id: productId,
    },
  });
  if (!sku) {
    throw new Error("SKU not found or is not subordinate to specified product");
  }

  // Step 2: Prevent deletion if SKU is referenced in any order item (via product_option_id)
  const orderItem = await MyGlobal.prisma.aimall_backend_order_items.findFirst({
    where: { product_option_id: skuId },
  });
  if (orderItem) {
    throw new Error(
      "Cannot delete SKU: It is referenced by at least one order item",
    );
  }

  // Step 3: Prevent deletion if SKU is referenced by any inventory snapshot
  const snapshot =
    await MyGlobal.prisma.aimall_backend_inventory_snapshots.findFirst({
      where: { sku_id: skuId },
    });
  if (snapshot) {
    throw new Error(
      "Cannot delete SKU: It is referenced by at least one inventory snapshot",
    );
  }

  // Step 4: Delete the SKU
  await MyGlobal.prisma.aimall_backend_skus.delete({
    where: { id: skuId },
  });
}

