 * Permits updating permissible fields such as session_token. Only the cart's
 * owner may perform the update. session_token, if provided, must be unique
 * among all carts. updated_at MUST be set to the update time; should be an
 * ISO8601 string.
 *
 * @param props - Props for update
 * @param props.customer - The authenticated customer (JWT payload)
 * @param props.cartId - UUID of cart to update
 * @param props.body - Fields to update (session_token, updated_at)
 * @returns The updated IAimallBackendCart object with proper field types and
 *   branding
 * @throws {Error} If cart is not found, or user does not own it
 * @throws {Error} If session_token is already used by another cart
 */
export async function put__aimall_backend_customer_carts_$cartId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IAimallBackendCart.IUpdate;
}): Promise<IAimallBackendCart> {
  const { customer, cartId, body } = props;

  // Step 1: Find cart and check ownership
  const cart = await MyGlobal.prisma.aimall_backend_carts.findUnique({
    where: { id: cartId },
  });
  if (!cart || cart.aimall_backend_customer_id !== customer.id) {
    throw new Error("Cart not found or access denied.");
  }

  // Step 2: Enforce session_token uniqueness if updating to non-null
  if (body.session_token !== undefined && body.session_token !== null) {
    const taken = await MyGlobal.prisma.aimall_backend_carts.findFirst({
      where: {
        session_token: body.session_token,
        NOT: { id: cartId },
      },
    });
    if (taken) {
      throw new Error(
        "The given session_token is already in use by another cart.",
      );
    }
  }

  // Step 3: Update fields inline (no intermediates)
  const updated = await MyGlobal.prisma.aimall_backend_carts.update({
    where: { id: cartId },
    data: {
      session_token: body.session_token ?? undefined,
      updated_at: body.updated_at,
    },
  });

  // Step 4: Return IAimallBackendCart object, ensuring correct types & branding
  return {
    id: updated.id,
    aimall_backend_customer_id: updated.aimall_backend_customer_id ?? undefined,
    session_token: updated.session_token ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    // cart_items_count not provided; requires separate aggregation
  };
}

