import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Provides detailed metadata for a specific media/file attachment linked to a
 * product review.
 *
 * Only the seller of the reviewed product can access this media file's
 * metadata. Ensures that the requested attachment both belongs to the target
 * review and that the review is for a product owned by the authenticated
 * seller.
 *
 * Used for display in attachment detail modals, downloads, or admin audits.
 * Throws error on not-found, mismatched review, or permissions failure.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller payload (must own the product)
 * @param props.reviewId - UUID of the product review
 * @param props.attachmentId - UUID of the attachment to fetch
 * @returns Attachment metadata for the product review
 *   (IAimallBackendAttachment)
 * @throws {Error} If the attachment, review, or product does not exist, if the
 *   attachment is not linked to the review, or if the seller does not own the
 *   product
 */
export async function get__aimall_backend_seller_reviews_$reviewId_attachments_$attachmentId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendAttachment> {
  const { seller, reviewId, attachmentId } = props;

  // Step 1: Find the attachment
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
    });
  if (!attachment) {
    throw new Error("Attachment not found");
  }

  // Step 2: Ensure that attachment belongs to the given review
  if (attachment.review_id !== reviewId) {
    throw new Error("Attachment does not belong to the specified review");
  }

  // Step 3: Find the review
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) {
    throw new Error("Review not found");
  }

  // Step 4: Find the product for this review
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
  });
  if (!product) {
    throw new Error("Product not found");
  }

  // Step 5: Authorization: validate seller owns the product
  if (product.seller_id !== seller.id) {
    throw new Error("Unauthorized: You do not own this product");
  }

  // Step 6: Map and return the attachment (all type conversions handled)
  return {
    id: attachment.id,
    post_id: attachment.post_id ?? null,
    comment_id: attachment.comment_id ?? null,
    review_id: attachment.review_id ?? null,
    file_uri: attachment.file_uri,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    created_at: toISOStringSafe(attachment.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendProductBundle } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProductBundle";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create new product bundle for a specific product (as bundle group).
 *
 * This endpoint allows authorized administrators to create a bundle association
 * between a specified product (the bundle master/group) and a component
 * product, enabling the master product to be sold as a bundle containing the
 * specified component. All business and data validation is enforced: referenced
 * products must exist; the same association cannot be created twice (unique
 * constraint). On success, returns the full bundle association record.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator user performing the
 *   action (must be active)
 * @param props.productId - UUID of the product to act as bundle master (group)
 * @param props.body - DTO containing component_product_id (UUID), is_required
 *   (bool), quantity (int, min 1)
 * @returns The created product bundle association (IAimallBackendProductBundle)
 * @throws {Error} When the bundle (master) product does not exist
 * @throws {Error} When the component product does not exist
 * @throws {Error} When an association with this bundle-product and
 *   component-product already exists
 */
export async function post__aimall_backend_administrator_products_$productId_productBundles(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProductBundle.ICreate;
}): Promise<IAimallBackendProductBundle> {
  const { administrator, productId, body } = props;

  // 1. Validate master product exists
  const masterProduct =
    await MyGlobal.prisma.aimall_backend_products.findUnique({
      where: { id: productId },
    });
  if (!masterProduct)
    throw new Error("The bundle (master) product does not exist");

  // 2. Validate component product exists
  const componentProduct =
    await MyGlobal.prisma.aimall_backend_products.findUnique({
      where: { id: body.component_product_id },
    });
  if (!componentProduct)
    throw new Error("The component product does not exist");

  // 3. Enforce bundle-component uniqueness
  const exists =
    await MyGlobal.prisma.aimall_backend_product_bundles.findUnique({
      where: {
        bundle_product_id_component_product_id: {
          bundle_product_id: productId,
          component_product_id: body.component_product_id,
        },
      },
    });
  if (exists)
    throw new Error("This product-component bundle association already exists");

  // 4. Create the new bundle association
  const created = await MyGlobal.prisma.aimall_backend_product_bundles.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      bundle_product_id: productId,
      component_product_id: body.component_product_id,
      is_required: body.is_required,
      quantity: body.quantity,
    },
  });

  return {
    id: created.id,
    bundle_product_id: created.bundle_product_id,
    component_product_id: created.component_product_id,
    is_required: created.is_required,
    quantity: created.quantity,
  };
}

import { MyGlobal } from "../MyGlobal";
