/**
 * Get the details of a specific inventory change event (snapshot) for a given
 * SKU.
 *
 * Returns the atomic, historical record of inventory change — such as type
 * (sale, restock), quantity, actor, and timestamp. Only authorized
 * administrators can access this sensitive, audit-oriented endpoint.
 *
 * @param props - Request parameters
 * @param props.administrator - Authenticated administrator payload. Must have
 *   active status.
 * @param props.skuId - The SKU ID for ownership validation and snapshot context
 *   (UUID, required)
 * @param props.inventorySnapshotId - The inventory snapshot record's unique ID
 *   (UUID, required)
 * @returns Detailed inventory snapshot for the SKU and snapshot ID specified
 * @throws {Error} If no snapshot found for either SKU or snapshot ID
 *   combination
 */
export async function get__aimall_backend_administrator_skus_$skuId_inventorySnapshots_$inventorySnapshotId(props: {
  administrator: AdministratorPayload;
  skuId: string & tags.Format<"uuid">;
  inventorySnapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendInventorySnapshot> {
  const { skuId, inventorySnapshotId } = props;
  const snapshot =
    await MyGlobal.prisma.aimall_backend_inventory_snapshots.findFirst({
      where: {
        id: inventorySnapshotId,
        sku_id: skuId,
      },
      select: {
        id: true,
        sku_id: true,
        product_id: true,
        change_type: true,
        change_quantity: true,
        changed_by: true,
        created_at: true,
      },
    });
  if (!snapshot) throw new Error("Inventory snapshot not found");
  return {
    id: snapshot.id,
    sku_id: snapshot.sku_id,
    product_id: snapshot.product_id,
    change_type: snapshot.change_type,
    change_quantity: snapshot.change_quantity,
    changed_by: snapshot.changed_by,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Add a new section to an existing channel.
 *
 * Creates a section (such as homepage banner, featured product block, etc.)
 * under a specific channel by its UUID. Only administrators may perform this
 * action. The request payload supplies all normalized attributes. Enforces
 * uniqueness of code within channel and required fields.
 *
 * Upon success, the fully populated section entity is returned. Throws if
 * uniqueness constraint is violated.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator (must be active)
 * @param props.channelId - UUID of the channel to add the section to
 * @param props.body - Creation DTO for the section (required fields only)
 * @returns The newly created section entity (with all timestamps as string &
 *   tags.Format<'date-time'>)
 * @throws {Error} If the administrator account is not active, or code is not
 *   unique within channel
 */
export async function post__aimall_backend_administrator_channels_$channelId_sections(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  body: IAimallBackendSection.ICreate;
}): Promise<IAimallBackendSection> {
  const { administrator, channelId, body } = props;

  if (administrator.status !== "active") {
    throw new Error("Only active administrators may create sections");
  }

  const now = toISOStringSafe(new Date());
  const newSectionId = v4() as string & tags.Format<"uuid">;

  try {
    const created = await MyGlobal.prisma.aimall_backend_sections.create({
      data: {
        id: newSectionId,
        channel_id: channelId,
        code: body.code,
        name: body.name,
        display_order: body.display_order,
        enabled: body.enabled,
        created_at: now,
        updated_at: now,
      },
    });
    return {
      id: created.id,
      channel_id: created.channel_id,
      code: created.code,
      name: created.name,
      display_order: created.display_order,
      enabled: created.enabled,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at: created.deleted_at
        ? toISOStringSafe(created.deleted_at)
        : null,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      throw new Error(
        "A section with that code already exists for this channel",
      );
    }
    throw error;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Get a single comment for a post by commentId (Community, Comments).
 *
 * This endpoint returns the details of a single comment attached to a post,
 * with normalization by aimall_backend_comments. Sellers may only view comments
 * that are public (is_private === false). Handles not found (404) and access
 * denied (403) with error feedback.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request (role
 *   enforcement)
 * @param props.postId - UUID of the parent post
 * @param props.commentId - UUID of the comment to retrieve
 * @returns The normalized comment object, compliant with IAimallBackendComment
 *   structure
 * @throws {Error} When the comment is not found (404)
 * @throws {Error} When attempting to access a private/restricted comment (403)
 */
export async function get__aimall_backend_seller_posts_$postId_comments_$commentId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendComment> {
  const { seller, postId, commentId } = props;

  // Lookup the comment by composite key (id + post_id), and ensure it's not deleted
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      post_id: postId,
      deleted_at: null,
    },
  });

  // Not found: 404
  if (!comment) throw new Error("Comment not found");

  // Authorization: only sellers with rights can view private comments
  if (comment.is_private) {
    throw new Error("Access denied: comment is private");
  }

  // Return normalized object with datetime conversions
  return {
    id: comment.id,
    post_id: comment.post_id ?? null,
    review_id: comment.review_id ?? null,
    parent_id: comment.parent_id ?? null,
    customer_id: comment.customer_id ?? null,
    body: comment.body,
    is_private: comment.is_private,
    created_at: toISOStringSafe(comment.created_at),
    updated_at: toISOStringSafe(comment.updated_at),
    deleted_at: comment.deleted_at ? toISOStringSafe(comment.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Updates the fields of a category by its unique identifier.
 *
 * Updates the fields of a category (name, parent_id, depth) by its unique ID.
 * Requires seller authentication. Throws 404 if category not found, 403 if
 * unauthorized (handled by decorator), and 409/422 for validation or constraint
 * errors (see below).
 *
 * @param props - Seller: Authenticated seller payload categoryId: UUID of the
 *   category to update body: Fields to update (name, parent_id, depth)
 * @returns The updated IAimallBackendCategory entity
 * @throws {Error} If category not found (404)
 * @throws {Error} If unique constraint or foreign key constraint fails
 *   (409/422)
 */
export async function put__aimall_backend_seller_categories_$categoryId(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.IUpdate;
}): Promise<IAimallBackendCategory> {
  const { categoryId, body } = props;
  const category = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!category) {
    throw new Error("Category not found");
  }
  try {
    const updated = await MyGlobal.prisma.aimall_backend_categories.update({
      where: { id: categoryId },
      data: {
        parent_id: body.parent_id ?? undefined,
        name: body.name ?? undefined,
        depth: body.depth ?? undefined,
      },
    });
    return {
      id: updated.id,
      parent_id: updated.parent_id,
      name: updated.name,
      depth: updated.depth,
    };
  } catch (error: unknown) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code: string }).code === "P2002"
    ) {
      // Unique constraint violation (parent_id, name)
      throw new Error(
        "Duplicate category name under the same parent is not allowed.",
      );
    }
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code: string }).code === "P2003"
    ) {
      // Foreign key violation (parent_id doesn't exist in categories)
      throw new Error("The specified parent category does not exist.");
    }
    throw error;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSeller";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Update an existing seller's data (aimall_backend_sellers).
 *
 * This endpoint allows a seller to update their own seller profile data. Only
 * the seller matching the account (from props.seller) may perform the update;
 * editing other sellers is forbidden.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller (validated via SellerAuth)
 * @param props.sellerId - The unique identifier (UUID) of the seller to update
 * @param props.body - Update fields (business_name, email, contact_phone,
 *   status, updated_at)
 * @returns The updated seller record after modification
 * @throws {Error} When the seller to update does not exist
 * @throws {Error} If access is forbidden (seller does not match)
 */
export async function put__aimall_backend_seller_sellers_$sellerId(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IAimallBackendSeller.IUpdate;
}): Promise<IAimallBackendSeller> {
  const { seller, sellerId, body } = props;

  // Only the seller themselves can update their data
  if (seller.id !== sellerId) {
    throw new Error("Forbidden: You can only update your own seller profile.");
  }

  // Update the seller record
  let updated: Awaited<
    ReturnType<typeof MyGlobal.prisma.aimall_backend_sellers.update>
  >;
  try {
    updated = await MyGlobal.prisma.aimall_backend_sellers.update({
      where: { id: sellerId },
      data: {
        business_name: body.business_name,
        email: body.email,
        contact_phone: body.contact_phone,
        status: body.status,
        updated_at: toISOStringSafe(body.updated_at),
      },
    });
  } catch (err) {
    // Prisma throws if not found, treat as 404
    throw new Error("Seller not found");
  }

  return {
    id: updated.id,
    business_name: updated.business_name,
    email: updated.email,
    contact_phone: updated.contact_phone,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update a community post by postId as an administrator.
 *
 * Allows an authenticated administrator to update any post's mutable fields
 * (title, body, or privacy flag). Only the specified fields in the patch body
 * are updated; absent fields are left unchanged. The updated_at audit timestamp
 * is always refreshed. Throws an error if the postId does not exist.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   update
 * @param props.postId - The UUID of the post to update
 * @param props.body - Patch body: any mutable post fields to update
 *   (title/body/is_private)
 * @returns The full updated post record after modification
 * @throws {Error} When the postId does not reference any known post
 */
export async function put__aimall_backend_administrator_posts_$postId(props: {
  administrator: AdministratorPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendPost.IUpdate;
}): Promise<IAimallBackendPost> {
  const { postId, body } = props;

  // Throws if not found
  const post = await MyGlobal.prisma.aimall_backend_posts.findUniqueOrThrow({
    where: { id: postId },
  });

  // Only update fields present in the patch body; always set updated_at
  const updated = await MyGlobal.prisma.aimall_backend_posts.update({
    where: { id: postId },
    data: {
      title: body.title ?? undefined,
      body: body.body ?? undefined,
      is_private: body.is_private ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    customer_id: updated.customer_id ?? null,
    title: updated.title,
    body: updated.body,
    is_private: updated.is_private,
    view_count: updated.view_count,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
