import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create a new comment under the specified post (Community, Comments).
 *
 * This endpoint allows administrator users to create a comment on a post. The
 * request body must provide all required comment fields.
 *
 * - Requires administrator authentication.
 * - PostId parameter determines which post to comment.
 * - Body: main content of comment, privacy flag, and optionally parent or review
 *   ID.
 *
 * @param props Request parameters
 * @param props.administrator Authenticated administrator payload
 * @param props.postId Target post ID (UUID)
 * @param props.body Comment creation DTO (body, is_private, parent_id?,
 *   review_id?)
 * @returns The created comment, fully normalized
 * @throws {Error} If post not found or deleted
 */
export async function post__aimall_backend_administrator_posts_$postId_comments(props: {
  administrator: AdministratorPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.ICreate;
}): Promise<IAimallBackendComment> {
  const { administrator, postId, body } = props;

  // Step 1: Ensure the post exists and is not soft-deleted
  const post = await MyGlobal.prisma.aimall_backend_posts.findFirst({
    where: { id: postId, deleted_at: null },
    select: { id: true },
  });
  if (!post) {
    throw new Error("Post not found or already deleted");
  }

  // Step 2: Prepare audit timestamp
  const now = toISOStringSafe(new Date());

  // Step 3: Create the comment with strict schema mapping
  const created = await MyGlobal.prisma.aimall_backend_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      post_id: postId,
      review_id: body.review_id ?? null,
      parent_id: body.parent_id ?? null,
      customer_id: administrator.id,
      body: body.body,
      is_private: body.is_private,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // Step 4: Map result to IAimallBackendComment response object
  return {
    id: created.id,
    post_id: created.post_id,
    review_id: created.review_id,
    parent_id: created.parent_id,
    customer_id: created.customer_id,
    body: created.body,
    is_private: created.is_private,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendInventorySnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendInventorySnapshot";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create an inventory change snapshot for a SKU.
 *
 * Inserts a new audit/event row for inventory changes to a specific SKU,
 * capturing the atomic delta, actor (administrator), and event type. The SKU ID
 * is strictly enforced by the path parameter, overriding any input sku_id. All
 * fields are validated by input types, and privilege is guaranteed by the
 * authenticated administrator parameter; foreign key/product validity is
 * enforced by the database. Fails on constraint or referential errors. No
 * mutation occurs; each call generates a new immutable audit row.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator context (ID,
 *   permission, etc)
 * @param props.skuId - Target SKU UUID (from request path)
 * @param props.body - Inventory snapshot creation input (change type, amount,
 *   product reference).
 * @returns The new inventory snapshot row as persisted in the system.
 * @throws {Error} If SKU or product references are invalid, or privilege is
 *   missing (should not occur due to decorator).
 */
export async function post__aimall_backend_administrator_skus_$skuId_inventorySnapshots(props: {
  administrator: AdministratorPayload;
  skuId: string & tags.Format<"uuid">;
  body: IAimallBackendInventorySnapshot.ICreate;
}): Promise<IAimallBackendInventorySnapshot> {
  const { administrator, skuId, body } = props;

  // Prepare insertion fields
  const created =
    await MyGlobal.prisma.aimall_backend_inventory_snapshots.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
