/**
 * Update allowed (non-relational) fields on a loyalty transaction.
 *
 * Performs an in-place update on certain updatable fields (e.g., description,
 * type, expired_at, amount within policy) of a specific loyalty transaction
 * identified by its UUID. Enforced by compliance policy, only non-relational
 * fields may change; customer_id/order_id/coupon_id remain fixed for regulatory
 * and audit purposes. This operation is intended for administrative
 * corrections—such as reversal, description clarification, or corrected amount
 * type.
 *
 * Business logic must tightly restrict when and which transactions may be
 * changed, including time windows, compliance review workflow, and proper audit
 * logging, as required by the Discount & Loyalty System. Unauthorized attempts
 * must result in access denied and be logged for investigation.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator making the request
 *   (must be status 'active')
 * @param props.loyaltyTransactionId - UUID of loyalty transaction to update
 * @param props.body - Update fields to apply (amount, type, description,
 *   expired_at)
 * @returns Updated loyalty transaction object with all fields strictly mapped
 *   to the DTO
 * @throws {Error} When administrator is not active, loyalty transaction not
 *   found, or forbidden field update is attempted
 */
export async function put__aimall_backend_administrator_loyaltyTransactions_$loyaltyTransactionId(props: {
  administrator: AdministratorPayload;
  loyaltyTransactionId: string & tags.Format<"uuid">;
  body: IAimallBackendLoyaltyTransaction.IUpdate;
}): Promise<IAimallBackendLoyaltyTransaction> {
  const { administrator, loyaltyTransactionId, body } = props;

  // Authorization - defense in depth
  if (administrator.status !== "active") {
    throw new Error("Unauthorized: Administrator is not active");
  }

  // Fetch transaction; 404 if missing
  const record =
    await MyGlobal.prisma.aimall_backend_loyalty_transactions.findUnique({
      where: { id: loyaltyTransactionId },
    });
  if (!record) throw new Error("Loyalty transaction not found");

  // Update only allowed (scalar, non-relational) fields
  const updated =
    await MyGlobal.prisma.aimall_backend_loyalty_transactions.update({
      where: { id: loyaltyTransactionId },
      data: {
        amount: body.amount ?? undefined,
        type: body.type ?? undefined,
        description: body.description ?? undefined,
        expired_at: body.expired_at ?? undefined,
      },
    });

  return {
    id: updated.id as string & tags.Format<"uuid">,
    customer_id: updated.customer_id as string & tags.Format<"uuid">,
    order_id: updated.order_id
      ? (updated.order_id as string & tags.Format<"uuid">)
      : null,
    coupon_id: updated.coupon_id
      ? (updated.coupon_id as string & tags.Format<"uuid">)
      : null,
    amount: updated.amount,
    type: updated.type,
    description: updated.description ?? null,
    created_at: toISOStringSafe(updated.created_at),
    expired_at: updated.expired_at ? toISOStringSafe(updated.expired_at) : null,
  };
}

