 *
 * The operation inserts a normalized address record into
 * aimall_backend_addresses, enforcing referential integrity and uniqueness
 * constraints as defined in the schema.
 *
 * Only the account owner (customer) or administrative actors may use this
 * endpoint. The implementation ensures the new address is strictly associated
 * with the user in path parameter. If is_default is specified, the API ensures
 * it's the only default for the customer by unsetting others.
 *
 * Related endpoints: PUT for address updates, GET for address retrieval. Errors
 * include invalid input, exceeding allowed addresses, or access violations.
 *
 * @param props - The input parameters
 * @param props.administrator - The authenticated administrator performing the
 *   operation (injected via AdministratorAuth decorator)
 * @param props.customerId - The unique identifier (UUID) of the customer for
 *   whom the address is being added
 * @param props.body - Address creation details conforming to
 *   IAimallBackendAddress.ICreate (alias, recipient_name, phone, address_line1,
 *   address_line2, city, postal_code, country, is_default)
 * @returns The newly created address record as stored in the database,
 *   normalized and strictly typed
 * @throws {Error} When the customer does not exist
 * @throws {Error} When maximum allowed addresses per customer is exceeded (if
 *   such a rule is enforced at DB/API)
 */
export async function post__aimall_backend_administrator_customers_$customerId_addresses(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAimallBackendAddress.ICreate;
}): Promise<IAimallBackendAddress> {
  const { customerId, body } = props;

  // Step 1: Ensure the customer exists
  await MyGlobal.prisma.aimall_backend_customers.findUniqueOrThrow({
    where: { id: customerId },
    select: { id: true },
  });

  // Step 2: If is_default is true, unset is_default for any other address for this customer
  if (body.is_default) {
    await MyGlobal.prisma.aimall_backend_addresses.updateMany({
      where: { customer_id: customerId, is_default: true },
      data: {
        is_default: false,
        updated_at: toISOStringSafe(new Date()),
      },
    });
  }

  // Step 3: Insert new address (we generate a UUID for this address)
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.aimall_backend_addresses.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      customer_id: customerId,
      alias: body.alias,
      recipient_name: body.recipient_name,
      phone: body.phone,
      address_line1: body.address_line1,
      address_line2: body.address_line2 ?? undefined,
      city: body.city,
      postal_code: body.postal_code,
      country: body.country,
      is_default: body.is_default,
      updated_at: now,
    },
    select: {
      id: true,
      customer_id: true,
      alias: true,
      recipient_name: true,
      phone: true,
      address_line1: true,
      address_line2: true,
      city: true,
      postal_code: true,
      country: true,
      is_default: true,
      updated_at: true,
    },
  });

  // Step 4: Map to DTO contract (all fields already assigned; branding from Prisma is correct)
  return {
    ...created,
    updated_at: toISOStringSafe(created.updated_at), // Ensure proper branding
  };
}

