 * comment body and is_private flag. It verifies that the referenced post exists
 * and is not deleted. The created comment is owned by the seller (represented
 * by customer_id: null for now, as no seller_id polymorphic field exists), and
 * all audit fields are correctly set and formatted.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller account (must be approved)
 * @param props.postId - The UUID of the community post to comment on
 * @param props.body - The comment creation data (body text, is_private flag,
 *   optional parent/review)
 * @returns The newly created comment as a normalized, audit-compliant object
 * @throws {Error} When the specified post does not exist, is deleted, or is
 *   inaccessible
 */
export async function post__aimall_backend_seller_posts_$postId_comments(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.ICreate;
}): Promise<IAimallBackendComment> {
