  const post = await MyGlobal.prisma.aimall_backend_posts.findFirst({
    where: {
      id: postId,
      deleted_at: null,
    },
  });
  if (!post) {
    throw new Error("Post not found or is deleted");
  }

  // 2. Set the audit timestamps for creation & update
  const now = toISOStringSafe(new Date());

  // 3. Create the comment (seller authorship - customer_id remains null)
  const created = await MyGlobal.prisma.aimall_backend_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      post_id: postId,
      review_id: body.review_id ?? null,
      parent_id: body.parent_id ?? null,
      customer_id: null, // Seller authorship: customer_id is null
      body: body.body,
      is_private: body.is_private,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    post_id: created.post_id,
    review_id: created.review_id,
    parent_id: created.parent_id,
    customer_id: created.customer_id,
    body: created.body,
