 *
 * 게시글 및 스냅샷 데이터가 모두 존재하고 유효하게 연결되어 있는지 검증하며, 게시글이 비공개일 경우 본인만 접근할 수 있도록 권한을
 * 강제합니다.
 *
 * @param props - 요청 파라미터
 * @param props.customer - 인증된 고객 페이로드 (CustomerAuth)
 * @param props.postId - 조회 대상 커뮤니티 게시글 UUID
 * @param props.snapshotId - 상세 조회할 스냅샷(미디어) UUID
 * @returns {IAimallBackendSnapshot} 요청 스냅샷의 모든 단일 필드를 반환합니다 (product_id,
 *   post_id 등 포함)
 * @throws {Error} 게시글 또는 스냅샷이 존재하지 않거나 연결이 불일치할 때 (404)
 * @throws {Error} 비공개 게시글에 소유자가 아닌 사용자가 접근 시 (403)
 */
export async function get__aimall_backend_customer_posts_$postId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendSnapshot> {
  const { customer, postId, snapshotId } = props;

  // 1. 게시글 존재 여부 및 soft delete 확인
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post || post.deleted_at) {
    throw new Error("Post not found"); // 404
  }

  // 2. 스냅샷 존재 여부 및 게시글 연결 확인
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot || snapshot.post_id !== post.id) {
    throw new Error("Snapshot not found or not linked to post"); // 404
  }

  // 3. 비공개(Private) 게시글 권한 체크: 본인만 접근 가능
  if (post.is_private && customer.id !== post.customer_id) {
    throw new Error("Forbidden: Only post owner can access this private post"); // 403
  }

  // 4. 모든 필드 DTO 매핑 (Date 변환, 옵셔널 처리)
  return {
    id: snapshot.id,
    product_id: snapshot.product_id ?? undefined,
    post_id: snapshot.post_id ?? undefined,
    customer_id: snapshot.customer_id ?? undefined,
    media_uri: snapshot.media_uri,
    caption: snapshot.caption ?? undefined,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

