 * aimall_backend_product_options.
 *
 * Only sellers with ownership rights over the product or administrators with
 * sufficient privilege may call this endpoint. Detects and rejects attempts at
 * duplicate or invalid option creation (e.g., same name and value for a given
 * product). On success, returns the created product option with
 * system-generated UUID.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing this
 *   action
 * @param props.productId - The UUID of the product to whom the option will be
 *   attached
 * @param props.body - The product option creation payload (must include
 *   product_id, name, value)
 * @returns The created product option entity, including all fields
 * @throws {Error} If the referenced product does not exist
 * @throws {Error} If an option with the same (product_id, name, value) already
 *   exists
 */
export async function post__aimall_backend_administrator_products_$productId_productOptions(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProductOption.ICreate;
}): Promise<IAimallBackendProductOption> {
