  // Check that product exists
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
    select: { id: true },
  });
  if (!product) {
    throw new Error("Product not found");
  }

  // Duplicate option check (unique by product_id+name+value)
  const existing =
    await MyGlobal.prisma.aimall_backend_product_options.findFirst({
      where: {
        product_id: productId,
        name: body.name,
        value: body.value,
      },
      select: { id: true },
    });
  if (existing) {
    throw new Error(
      "Duplicate product option: Combination of name and value already exists for this product",
    );
  }

  // Create option - enforce no use of 'as', guarantee type with typia.assert
  const id = typia.assert<string & tags.Format<"uuid">>(v4());
  const created = await MyGlobal.prisma.aimall_backend_product_options.create({
    data: {
      id,
      product_id: productId,
      name: body.name,
