 * parent category (aimall_backend_categories).
 *
 * This function deletes a category only if:
 *
 * - The category exists and its parent_id matches the given parent
 * - The category is not referenced by any products
 * - The category does not have any child subcategories
 *
 * This operation is restricted to authenticated sellers and should be guarded
 * by business logic. Throws errors on violation.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller
 * @param props.categoryId - Parent category ID (must own the child)
 * @param props.childCategoryId - Child category ID to delete
 * @returns Void
 * @throws {Error} If the child does not exist, does not belong to parent, has
 *   products, or has subcategories
 */
export async function delete__aimall_backend_seller_categories_$categoryId_childCategories_$childCategoryId(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
  childCategoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, categoryId, childCategoryId } = props;

  // 1. Check if the child category exists and belongs to the parent
  const child = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: childCategoryId },
    select: { id: true, parent_id: true },
  });
  if (!child || child.parent_id !== categoryId) {
