      "Category not found or does not belong to the specified parent category.",
    );
  }

  // 2. Check if the category has any subcategories
  const hasChild = await MyGlobal.prisma.aimall_backend_categories.findFirst({
    where: { parent_id: childCategoryId },
    select: { id: true },
  });
