  // Enforce code uniqueness (if code provided and changed)
  if (
    body.code !== undefined &&
    body.code !== null &&
    body.code !== campaign.code
  ) {
    const exists =
      await MyGlobal.prisma.aimall_backend_discount_campaigns.findFirst({
        where: { code: body.code },
      });
    if (exists) throw new Error("A campaign with this code already exists");
  }

  // Extract next state for validation
  const next_status = body.status ?? campaign.status;
  const prev_status = campaign.status;
  if (prev_status === "ended" && next_status === "active") {
    throw new Error("Cannot transition campaign from ended back to active");
  }

  // Prepare start_at and end_at for logic enforcement (normalize with toISOStringSafe)
  const next_start_at =
    body.start_at !== undefined && body.start_at !== null
      ? toISOStringSafe(body.start_at)
      : toISOStringSafe(campaign.start_at);
  const next_end_at =
    body.end_at !== undefined && body.end_at !== null
      ? toISOStringSafe(body.end_at)
      : toISOStringSafe(campaign.end_at);

  // end_at >= start_at
  if (next_end_at < next_start_at) {
    throw new Error("end_at must not be earlier than start_at");
  }
  // end_at cannot be in the past
  const now = toISOStringSafe(new Date());
  if (body.end_at !== undefined && body.end_at !== null && next_end_at < now) {
    throw new Error("end_at cannot be set in the past");
  }

  // Prepare update input
  const updated =
    await MyGlobal.prisma.aimall_backend_discount_campaigns.update({
      where: { id: discountCampaignId },
      data: {
        name: body.name ?? undefined,
        code: body.code ?? undefined,
        type: body.type ?? undefined,
        status: body.status ?? undefined,
        stackable: body.stackable ?? undefined,
        start_at:
          body.start_at !== undefined && body.start_at !== null
            ? toISOStringSafe(body.start_at)
            : undefined,
        end_at:
          body.end_at !== undefined && body.end_at !== null
            ? toISOStringSafe(body.end_at)
            : undefined,
        max_uses_per_user:
          body.max_uses_per_user !== undefined
            ? body.max_uses_per_user
            : undefined,
        priority:
          body.priority !== undefined && body.priority !== null
            ? body.priority
            : undefined,
        description:
          body.description !== undefined ? body.description : undefined,
      },
    });

  // Return API contract-compliant object
  return {
    id: updated.id,
    name: updated.name,
    code: updated.code,
    type: updated.type,
    status: updated.status,
    stackable: updated.stackable,
    start_at: toISOStringSafe(updated.start_at),
    end_at: toISOStringSafe(updated.end_at),
    max_uses_per_user:
      updated.max_uses_per_user !== undefined &&
      updated.max_uses_per_user !== null
        ? updated.max_uses_per_user
        : null,
    priority: updated.priority,
    description: updated.description !== undefined ? updated.description : null,
  };
}

