/**
 * Fetch metadata and URI for a specific comment attachment by identifiers for
 * both parent comment and attachment UUID PK.
 *
 * This endpoint returns detail for a single attachment on a comment, only if
 * the requesting customer is the owner of the comment. Used for file preview,
 * download, or moderation. Throws an error if not authorized or not found.
 *
 * @param props - Request parameter object
 * @param props.customer - Authenticated customer (payload)
 * @param props.commentId - UUID of the parent comment linking the attachment
 * @param props.attachmentId - UUID PK of the attachment to fetch
 * @returns Attachment metadata and URI for download or preview
 * @throws {Error} When the attachment or comment is not found, or user is not
 *   authorized
 */
export async function get__aimall_backend_customer_comments_$commentId_attachments_$attachmentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendAttachment> {
  const { customer, commentId, attachmentId } = props;

  // Fetch the attachment by id and comment_id (exact match)
  const attachment = await MyGlobal.prisma.aimall_backend_attachments.findFirst(
    {
      where: {
        id: attachmentId,
        comment_id: commentId,
      },
    },
  );
  if (!attachment) throw new Error("Attachment not found");

  // Fetch the parent comment for customer verification
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: { id: commentId },
  });
  if (!comment) throw new Error("Comment not found");

  // Only allow the owner (creator) to access the comment's attachments
  if (comment.customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: Only the comment owner can access this attachment",
    );
  }

  return {
    id: attachment.id,
    post_id: attachment.post_id ?? null,
    comment_id: attachment.comment_id ?? null,
    review_id: attachment.review_id ?? null,
    file_uri: attachment.file_uri,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    created_at: toISOStringSafe(attachment.created_at),
  };
}

