import { IPageIAimallBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendProduct";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Advanced search and filter operation for products (aimall_backend_products)
 * by query and paginated.
 *
 * Search and filter products from the platform catalog by leveraging advanced
 * query and pagination features. This endpoint references the
 * aimall_backend_products model and supports multi-faceted queries, such as
 * category, seller, status, and keyword match against the product title and
 * description.
 *
 * The endpoint is available to any requesting party due to its role in powering
 * product search, advanced discovery, and backoffice product management tools.
 * The request body must conform to the expected DTO schema, encapsulating
 * search terms, filter options, pagination controls, and sorting preferences.
 * Results are strictly limited to normalized, non-deleted products per the
 * schema—sensitive details are withheld from the base response. The endpoint is
 * performance-optimized, enabling scalable product discovery as required by
 * frontend web/mobile layers. Output provides both data and necessary
 * pagination metadata, ensuring complete client handling.
 *
 * @param props Request properties
 * @param props.body Filtering and search criteria for product catalog advanced
 *   queries.
 * @returns Paginated list of products matching search and filter criteria.
 * @throws {Error} Database errors, type safety violations, or internal
 *   failures.
 */
export async function patch__aimall_backend_products(props: {
  body: IAimallBackendProduct.IRequest;
}): Promise<IPageIAimallBackendProduct> {
  const { body } = props;
  // Defensive defaults for page/limit
  const page = body.page != null && body.page >= 1 ? body.page : 1;
  const limit =
    body.limit != null && body.limit >= 1 && body.limit <= 100
      ? body.limit
      : 20;

  // Build where clause only with verified fields
  const where = {
    ...(body.title && {
      OR: [
        { title: { contains: body.title, mode: "insensitive" as const } },
        { description: { contains: body.title, mode: "insensitive" as const } },
      ],
    }),
    ...(body.category_id && { category_id: body.category_id }),
    ...(body.seller_id && { seller_id: body.seller_id }),
    ...(body.status && { status: body.status }),
    ...((body.created_at_from || body.created_at_to) && {
      created_at: {
        ...(body.created_at_from && { gte: body.created_at_from }),
        ...(body.created_at_to && { lte: body.created_at_to }),
      },
    }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_products.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_products.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      category_id: row.category_id,
      seller_id: row.seller_id,
      title: row.title,
      description: row.description ?? undefined,
      main_thumbnail_uri: row.main_thumbnail_uri ?? undefined,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrder";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Creates a new order in the database, initializing required business
 * attributes as specified in the 'aimall_backend_orders' Prisma schema.
 *
 * - Requires Administrator authentication (administrator parameter required)
 * - Verifies that customer, seller, and address IDs exist before creating the
 *   order
 * - If not provided, generates a unique business-facing order_number
 *   (ORD-YYYYMMDD-4DIGITS)
 * - Performs full referential integrity and ID checks. All date/datetime values
 *   handled as string & tags.Format<'date-time'>.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   operation
 * @param props.body - The order creation DTO (IAimallBackendOrder.ICreate)
 * @returns The newly created order as IAimallBackendOrder
 * @throws {Error} If provided customer, seller, or address does not exist, or
 *   if order_number generation fails due to collision
 */
export async function post__aimall_backend_administrator_orders(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendOrder.ICreate;
}): Promise<IAimallBackendOrder> {
  const { administrator, body } = props;

  // Step 1: Ensure all referenced entities exist
  const [customer, seller, address] = await Promise.all([
    MyGlobal.prisma.aimall_backend_customers.findUnique({
      where: { id: body.customer_id },
    }),
    MyGlobal.prisma.aimall_backend_sellers.findUnique({
      where: { id: body.seller_id },
    }),
    MyGlobal.prisma.aimall_backend_addresses.findUnique({
      where: { id: body.address_id },
    }),
  ]);
  if (!customer) throw new Error("Customer not found for order creation");
  if (!seller) throw new Error("Seller not found for order creation");
  if (!address) throw new Error("Address not found for order creation");

  // Step 2: Generate a unique order_number if not provided
  let order_number = body.order_number;
  if (!order_number) {
    // Format: ORD-YYYYMMDD-XXXX (4 random digits)
    const yyyyMMdd = toISOStringSafe(new Date()).slice(0, 10).replace(/-/g, "");
    let uniqueNumber: string | null = null;
    for (let i = 0; i < 10; ++i) {
      const candidate = `ORD-${yyyyMMdd}-${Math.floor(1000 + Math.random() * 9000)}`;
      const found = await MyGlobal.prisma.aimall_backend_orders.findUnique({
        where: { order_number: candidate },
      });
      if (!found) {
        uniqueNumber = candidate;
        break;
      }
    }
    if (!uniqueNumber) {
      throw new Error(
        "Failed to generate a unique order_number after multiple attempts",
      );
    }
    order_number = uniqueNumber;
  }

  // Step 3: Prepare id and timestamps
  const orderId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // Step 4: Create the order
  const order = await MyGlobal.prisma.aimall_backend_orders.create({
    data: {
      id: orderId,
      customer_id: body.customer_id,
      seller_id: body.seller_id,
      address_id: body.address_id,
      order_number,
      order_status: body.order_status,
      total_amount: body.total_amount,
      currency: body.currency,
      created_at: now,
      updated_at: now,
      // archived_at is omitted at creation (NULL)
    },
  });

  // Step 5: Transform output for DTO contract (all dates as string)
  return {
    id: order.id,
    customer_id: order.customer_id,
    seller_id: order.seller_id,
    address_id: order.address_id,
    order_number: order.order_number,
    order_status: order.order_status,
    total_amount: order.total_amount,
    currency: order.currency,
    created_at: toISOStringSafe(order.created_at),
    updated_at: toISOStringSafe(order.updated_at),
    archived_at: order.archived_at ? toISOStringSafe(order.archived_at) : null,
  };
}

