  if (order.seller_id !== seller.id) {
    throw new Error("Unauthorized: order does not belong to this seller");
  }

  // 2. Prepare all values for insertion
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.aimall_backend_shipments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      order_id: orderId,
      shipment_address_id: body.shipment_address_id,
      carrier: body.carrier,
      tracking_number: body.tracking_number ?? null,
      shipment_status: body.shipment_status,
      shipped_at: body.shipped_at ?? null,
      delivered_at: body.delivered_at ?? null,
      created_at: now,
    },
  });

  // 3. Return all properties, properly typed
  return {
    id: created.id,
    order_id: created.order_id,
    shipment_address_id: created.shipment_address_id,
    carrier: created.carrier,
    tracking_number: created.tracking_number,
    shipment_status: created.shipment_status,
    shipped_at: created.shipped_at ? toISOStringSafe(created.shipped_at) : null,
    delivered_at: created.delivered_at
      ? toISOStringSafe(created.delivered_at)
