import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create and upload a new review snapshot (user photo/media) for a product
 * review.
 *
 * Only authenticated sellers may add snapshots to reviews, and only if they own
 * the reviewed product. The snapshot is linked via product_id (not review id).
 *
 * @param props - Seller: The authenticated seller (must own the reviewed
 *   product) reviewId: The target review's UUID body: Snapshot creation fields
 *   (media_uri required; others optional)
 * @returns The created snapshot entity as IAimallBackendSnapshot
 * @throws {Error} When review does not exist
 * @throws {Error} When seller does not own the product for this review
 */
export async function post__aimall_backend_seller_reviews_$reviewId_snapshots(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.ICreate;
}): Promise<IAimallBackendSnapshot> {
  const { seller, reviewId, body } = props;

  // 1. Find the review record
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { id: true, product_id: true },
  });
  if (!review) throw new Error("Review not found");

  // 2. Check that seller owns the product
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product) throw new Error("Product for review not found");
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: Seller does not own this reviewed product");
  }

  // 3. Create the snapshot
  const now = toISOStringSafe(new Date());
  const created_at = body.created_at ?? now;
  const created = await MyGlobal.prisma.aimall_backend_snapshots.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      product_id: review.product_id,
      // No review_id field; customer_id = seller.id
      customer_id: seller.id,
      media_uri: body.media_uri,
      caption: body.caption ?? undefined,
      created_at: toISOStringSafe(created_at),
    },
  });

  // 4. Return the mapped DTO object
  return {
    id: created.id,
    product_id: created.product_id ?? undefined,
    post_id: created.post_id ?? undefined,
    customer_id: created.customer_id ?? undefined,
    media_uri: created.media_uri,
    caption: created.caption ?? undefined,
    created_at: toISOStringSafe(created.created_at),
  };
}

