/**
 * Delete an attachment on a post (hard delete, Community, Attachments).
 *
 * This endpoint removes an attachment from a post by attachmentId (and postId
 * scope). Since there is no deleted_at soft-delete field on
 * aimall_backend_attachments, this is a hard delete: the row is removed
 * permanently and the file is dereferenced. Only authorized users may perform
 * this action (uploader, moderator, admin).
 *
 * Errors include not found, access denied, or in-use constraints. On success,
 * attachment is deleted and no longer available via listing or detail
 * endpoints.
 *
 * @param props - Request properties
 * @param props.customer - The currently authenticated customer requesting the
 *   delete
 * @param props.postId - The ID of the parent post holding the attachment
 * @param props.attachmentId - The ID of the attachment to delete
 * @returns Void on successful hard delete of the attachment
 * @throws {Error} If attachment is not found
 * @throws {Error} If attachment does not belong to the specified post
 * @throws {Error} If the post is not found
 * @throws {Error} If the authenticated customer is not the post owner
 * @throws {Error} If there is a database constraint preventing deletion
 */
export async function delete__aimall_backend_customer_posts_$postId_attachments_$attachmentId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, postId, attachmentId } = props;

  // 1. Validate attachment existence and belonging
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
      select: { id: true, post_id: true },
    });
  if (!attachment) {
    throw new Error("Attachment not found.");
  }
  if (attachment.post_id !== postId) {
    throw new Error("Attachment does not belong to the specified post.");
  }

  // 2. Validate post existence and ownership
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
    select: { id: true, customer_id: true },
  });
  if (!post) {
    throw new Error("Post not found.");
  }
  if (post.customer_id !== customer.id) {
    throw new Error("Forbidden: Only post owner may delete an attachment.");
  }

  // 3. Perform hard delete (cascade removes attachment permanently)
  await MyGlobal.prisma.aimall_backend_attachments.delete({
    where: { id: attachmentId },
  });
}

