 *   (authorization checked at controller/middleware)
 * @param props.postId - UUID of the parent post holding the attachment
 * @param props.attachmentId - UUID of the attachment to delete
 * @returns Void
 * @throws {Error} When attachment or post is not found
 * @throws {Error} When authorization cannot be confirmed due to schema
 *   limitations
 */
export async function delete__aimall_backend_seller_posts_$postId_attachments_$attachmentId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<void> {
