/**
 * 리뷰의 스냅샷(aimall_backend_snapshots) 상세 정보를 반환합니다.
 *
 * 해당 리뷰(reviewId)에 속하는 스냅샷(snapshotId)의 모든 필드를 반환합니다. 리뷰와 스냅샷 간 연결관계(동일 상품
 * product_id) 유효성 검증을 수행하며, 존재하지 않거나 연결되지 않은 경우 404 에러를 반환합니다. 오직 해당 리뷰를 소유한
 * 셀러만 요청할 수 있으며, 권한이 없는 경우 "Forbidden" 에러를 반환합니다.
 *
 * @param props - 요청 프로퍼티 객체
 * @param props.seller - 인증된 셀러 정보(SellerPayload)
 * @param props.reviewId - 대상 리뷰 UUID
 * @param props.snapshotId - 조회할 스냅샷 UUID
 * @returns 상세 스냅샷 엔티티 정보
 * @throws {Error} 리뷰가 존재하지 않거나 셀러 소유가 아닐 때 (404/403)
 * @throws {Error} 스냅샷이 존재하지 않거나 연결되지 않을 때 (404)
 */
export async function get__aimall_backend_seller_reviews_$reviewId_snapshots_$snapshotId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendSnapshot> {
  const { seller, reviewId, snapshotId } = props;

  // 1. 리뷰 조회 및 소유 검증
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: {
      id: true,
      product_id: true,
      seller_id: true,
    },
  });
  if (!review) throw new Error("Review not found");
  if (review.seller_id !== seller.id) throw new Error("Forbidden");

  // 2. 스냅샷 조회
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
    select: {
      id: true,
      product_id: true,
      post_id: true,
      customer_id: true,
      media_uri: true,
      caption: true,
      created_at: true,
    },
  });
  if (!snapshot) throw new Error("Snapshot not found");

  // 3. 스냅샷-리뷰 매핑 검증 (동일 product_id)
  if (snapshot.product_id !== review.product_id)
    throw new Error("Snapshot does not belong to this review");

  // 4. 반환: DTO 변환 및 날짜 변환
  return {
    id: snapshot.id,
    product_id: snapshot.product_id ?? undefined,
    post_id: snapshot.post_id ?? undefined,
    customer_id: snapshot.customer_id ?? undefined,
    media_uri: snapshot.media_uri,
    caption: snapshot.caption ?? undefined,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

