 *
 * Adds a new order item line to an existing order using the parent order's
 * UUID. Input payload must supply all fields as per the
 * 'aimall_backend_order_items' schema (product, SKU/option, item name,
 * quantity, unit/total price). Use case includes administrator corrections,
 * seller adjustment after customer request, or test data.
 *
 * This function validates that the target order exists and is mutable (not
 * finalized, archived, or delivered), then inserts the provided order item. On
 * success, returns the newly created order item in full DTO format.
 *
 * @param props - Function parameters
 * @param props.administrator - The authenticated administrator performing this
 *   operation
 * @param props.orderId - UUID of the order to which a new item is added
 * @param props.body - Required fields for the new order item (see
 *   IAimallBackendOrderItem.ICreate)
 * @returns The newly created order item record compliant with
 *   IAimallBackendOrderItem
 * @throws {Error} If the order does not exist or is immutable (archived or
 *   delivered)
 */
export async function post__aimall_backend_administrator_orders_$orderId_orderItems(props: {
  administrator: AdministratorPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.ICreate;
}): Promise<IAimallBackendOrderItem> {
  const { administrator, orderId, body } = props;
  // Fetch and validate order mutability
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { id: true, order_status: true, archived_at: true },
  });
  if (!order) throw new Error("Order not found");
  if (order.archived_at !== null || order.order_status === "delivered")
    throw new Error("Cannot add order item to an archived or delivered order");

  typia.assert<IAimallBackendOrderItem.ICreate>(body);

  // Generate the new item UUID (ensuring proper typing)
  const newItemId = v4();

  // Create the order item in DB, faithfully propagating all values
  const created = await MyGlobal.prisma.aimall_backend_order_items.create({
    data: {
