import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Creates a new comment authored by an administrator on a product review.
 *
 * This function inserts a new comment (aimall_backend_comments) on the
 * specified review. It verifies the review's existence, checks parent comment
 * validity if a thread/reply is specified, and sets the author to an anonymous
 * admin (customer_id is null). Threading, privacy, and all audit fields are
 * handled as per schema. Dates are stored and returned in ISO8601 format.
 *
 * @param props.administrator - The authenticated administrator creating the
 *   comment.
 * @param props.reviewId - The UUID of the product review to which the comment
 *   is attached.
 * @param props.body - The comment creation payload (body, is_private, optional
 *   parent_id).
 * @returns The newly created comment as an IAimallBackendComment object.
 * @throws {Error} When the review does not exist.
 * @throws {Error} When a parent_id is given, but the parent comment is not
 *   found, not in this review, or deleted.
 */
export async function post__aimall_backend_administrator_reviews_$reviewId_comments(props: {
  administrator: AdministratorPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.ICreate;
}): Promise<IAimallBackendComment> {
  const { administrator, reviewId, body } = props;

  // 1. Ensure target review exists
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) throw new Error("Review not found");

  // 2. If parent_id is provided, verify it exists, matches current review, and is not deleted
  if (body.parent_id !== undefined && body.parent_id !== null) {
    const parent = await MyGlobal.prisma.aimall_backend_comments.findUnique({
      where: { id: body.parent_id },
    });
    if (
      !parent ||
      parent.review_id !== reviewId ||
      parent.deleted_at !== null
    ) {
      throw new Error("Parent comment not found in this review thread");
    }
  }

  // 3. Prepare timestamps
  const now = toISOStringSafe(new Date());

  // 4. Create comment with required fields (customer_id = null for admin-authored)
  const created = await MyGlobal.prisma.aimall_backend_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      post_id: null,
      review_id: reviewId,
      parent_id: body.parent_id ?? null,
      customer_id: null,
      body: body.body,
      is_private: body.is_private,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 5. Map the created comment to API structure, ensuring all date fields are ISO strings
  return {
    id: created.id,
    post_id: created.post_id,
    review_id: created.review_id,
    parent_id: created.parent_id,
    customer_id: created.customer_id,
    body: created.body,
    is_private: created.is_private,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at:
      created.deleted_at !== null && created.deleted_at !== undefined
        ? toISOStringSafe(created.deleted_at)
        : null,
  };
}

