 * authenticated seller.
 *
 * This endpoint enforces seller ownership: only the seller who owns the product
 * may retrieve its channel assignment detail. Useful for audits, compliance
 * validation, or troubleshooting channel/product visibility.
 *
 * Throws an error if the channel assignment does not exist, does not belong to
 * the given product, or the seller does not own the product.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller payload (must match product seller
 *   ID)
 * @param props.productId - Unique identifier of the product the assignment
 *   belongs to
 * @param props.channelAssignmentId - Unique identifier of the target channel
 *   assignment record
 * @returns The full channel assignment record details for the specified
 *   assignment ID
 * @throws {Error} When the assignment does not exist, is not matched to the
 *   product, or the seller does not own the product
 */
export async function get__aimall_backend_seller_products_$productId_channelAssignments_$channelAssignmentId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  channelAssignmentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendChannelAssignment> {
  const { seller, productId, channelAssignmentId } = props;

  // Lookup channel assignment by id
  const assignment =
    await MyGlobal.prisma.aimall_backend_channel_assignments.findUnique({
      where: { id: channelAssignmentId },
