import { IAimallBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCategory";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Updates a product category by its unique identifier (administrator only).
 *
 * Allows updating category `name`, `parent_id`, or `depth`. Enforces unique
 * sibling names for the same parent to maintain taxonomy integrity.
 *
 * @param props - Request parameters and payload
 * @param props.administrator - Authenticated administrator (authorization
 *   handled externally)
 * @param props.categoryId - Unique ID of the category to update
 * @param props.body - Fields to update (name, parent_id, depth)
 * @returns The updated IAimallBackendCategory entity
 * @throws {Error} 404 if category is not found
 * @throws {Error} 422 if uniqueness constraint (parent_id + name) is violated
 */
export async function put__aimall_backend_administrator_categories_$categoryId(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.IUpdate;
}): Promise<IAimallBackendCategory> {
  const { categoryId, body } = props;

  // 1. Fetch target category or throw 404 if not found
  const category = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!category) throw new Error("Category not found");

  // 2. If name or parent_id are being updated, ensure sibling uniqueness
  const shouldCheckConflict =
    (body.name !== undefined && body.name !== category.name) ||
    (body.parent_id !== undefined && body.parent_id !== category.parent_id);

  if (shouldCheckConflict) {
    const conflict = await MyGlobal.prisma.aimall_backend_categories.findFirst({
      where: {
        parent_id: body.parent_id ?? category.parent_id ?? null,
        name: body.name ?? category.name,
        NOT: { id: categoryId },
      },
    });
    if (conflict) {
      throw new Error(
        "A category with this name already exists for the same parent.",
      );
    }
  }

  // 3. Update only supplied fields; skip undefined
  const updated = await MyGlobal.prisma.aimall_backend_categories.update({
    where: { id: categoryId },
    data: {
      parent_id: body.parent_id ?? undefined,
      name: body.name ?? undefined,
      depth: body.depth ?? undefined,
    },
  });

  // 4. Return entity per IAimallBackendCategory
  return {
    id: updated.id,
    parent_id: updated.parent_id ?? null,
    name: updated.name,
    depth: updated.depth,
  };
}

