import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIAimallBackendCouponRedemption } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendCouponRedemption";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IAimallBackendCouponRedemption } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCouponRedemption";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Lists all coupon redemption records, paginated.
 *
 * Fetches an unfiltered, paginated list of all coupon redemption records from
 * the database. This provides detailed logs (success/failure, date, redemption
 * target, outcome) for analytics review and operational monitoring.
 *
 * Access is restricted to administrators as redemption data may include
 * sensitive user/order information.
 *
 * Returns default pagination (page 1, limit 20) and paginated list structure
 * conforming to IPageIAimallBackendCouponRedemption.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   request.
 * @returns Paginated page of coupon redemption records, including metadata.
 * @throws {Error} When called by a non-administrator or an inactive
 *   administrator.
 */
export async function get__aimall_backend_administrator_couponRedemptions(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendCouponRedemption> {
  const { administrator } = props;
  if (
    administrator.type !== "administrator" ||
    administrator.status !== "active"
  ) {
    throw new Error(
      "Forbidden: Only active administrators may access coupon redemptions.",
    );
  }

  // Default pagination parameters
  const page = 1 as number & tags.Type<"int32">;
  const limit = 20 as number & tags.Type<"int32">;
  const skip = (page - 1) * limit;

  // Query total count and paginated records in parallel
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.aimall_backend_coupon_redemptions.count(),
    MyGlobal.prisma.aimall_backend_coupon_redemptions.findMany({
      skip,
      take: limit,
      orderBy: { redeemed_at: "desc" },
    }),
  ]);

  // Build response in strict immutable, functional style
  return {
    pagination: {
      current: page,
      limit,
      records: total as number & tags.Type<"int32">,
      pages: Math.ceil(total / limit) as number & tags.Type<"int32">,
    },
    data: rows.map((row) => ({
