 *
 * Returns exact attachment metadata with full validation:
 *
 * - Ensures the attachment exists and is scoped to the given post.
 * - Enforces access restriction: only the seller who owns the post may view
 *   attachments.
 * - Throws precise errors for not found and forbidden cases.
 * - Never uses native Date type.
 *
 * @param props - Request params and seller authentication
 * @param props.seller - The authenticated seller account
 * @param props.postId - The post holding the attachment
 * @param props.attachmentId - The attachment to retrieve
 * @returns IAimallBackendAttachment - Complete attachment metadata object for
 *   authorized seller
 * @throws {Error} Attachment not found if the attachment does not exist or does
 *   not belong to the post
 * @throws {Error} Post not found if the post does not exist
 * @throws {Error} Forbidden if the seller does not own the post
 */
export async function get__aimall_backend_seller_posts_$postId_attachments_$attachmentId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendAttachment> {
