/**
 * Retrieves a single child comment under a given parent comment (admin).
 *
 * This function verifies the existence and non-soft-deleted status of the
 * parent comment, then fetches the child comment whose id matches
 * childCommentId and whose parent_id equals commentId. Returns comment details
 * including id, parent_id, post_id, review_id, customer_id, body, is_private,
 * created_at, updated_at, and deleted_at. Excludes comments with deleted_at set
 * (soft-deleted).
 *
 * Authorization: Only accessible to administrators (unrestricted view).
 *
 * @param props - Administrator: AdministratorPayload - Authenticated
 *   administrator user (authorization enforced by decorator) commentId: string
 *   & tags.Format<'uuid'> - Parent comment UUID childCommentId: string &
 *   tags.Format<'uuid'> - Child comment UUID under parent
 * @returns IAimallBackendComment - Detailed info for the specified child
 *   comment (thread integrity enforced)
 * @throws {Error} When the parent comment is not found, soft-deleted, or when
 *   the child comment either does not exist, is not linked to parent, or is
 *   soft-deleted
 */
export async function get__aimall_backend_administrator_comments_$commentId_comments_$childCommentId(props: {
  administrator: AdministratorPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendComment> {
  const { commentId, childCommentId } = props;

  // Verify parent comment exists and is not soft-deleted
  const parent = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: { id: commentId, deleted_at: null },
  });
  if (!parent) throw new Error("Parent comment not found or has been deleted");

  // Verify child comment exists, is under parent, and not soft-deleted
  const child = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: { id: childCommentId, parent_id: commentId, deleted_at: null },
  });
  if (!child)
    throw new Error(
      "Child comment not found, incorrect parent linkage, or has been deleted",
    );

  return {
    id: child.id,
    post_id: child.post_id ?? null,
    review_id: child.review_id ?? null,
    parent_id: child.parent_id ?? null,
    customer_id: child.customer_id ?? null,
    body: child.body,
    is_private: child.is_private,
    created_at: toISOStringSafe(child.created_at),
    updated_at: toISOStringSafe(child.updated_at),
    deleted_at: child.deleted_at ? toISOStringSafe(child.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
