import { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Fetch a paginated list of all community comments from the platform. This
 * endpoint exposes all comment records for administrative purposes, including
 * associations (posts, reviews, threads), authorship, and any soft-deletion
 * markers.
 *
 * Access to this data is strictly limited to administrator users for privacy,
 * moderation, and audit purposes.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator in context. Must
 *   be ACTIVE to use this endpoint.
 * @returns A paginated result of all comments, with proper relational and audit
 *   fields.
 * @throws {Error} When the administrator account is not active or not found.
 */
export async function get__aimall_backend_administrator_comments(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendComment> {
  const { administrator } = props;

  // Authorization: verify administrator is active
  const adminRecord =
    await MyGlobal.prisma.aimall_backend_administrators.findFirst({
      where: { id: administrator.id, status: "active" },
    });
  if (!adminRecord) throw new Error("Unauthorized: Administrator required");

  // Use defaults: page=1, limit=20; could be parameterized if needed
  const page = 1;
  const limit = 20;
  const skip = (page - 1) * limit;

  // Fetch data and total count
  const [totalRecords, comments] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.count(),
    MyGlobal.prisma.aimall_backend_comments.findMany({
      orderBy: [{ created_at: "desc" }],
      skip,
      take: limit,
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: totalRecords,
      pages: Math.ceil(totalRecords / limit),
    },
    data: comments.map((comment) => ({
      id: comment.id,
      post_id: comment.post_id ?? null,
      review_id: comment.review_id ?? null,
      parent_id: comment.parent_id ?? null,
      customer_id: comment.customer_id ?? null,
      body: comment.body,
      is_private: comment.is_private,
      created_at: toISOStringSafe(comment.created_at),
      updated_at: toISOStringSafe(comment.updated_at),
      deleted_at: comment.deleted_at
        ? toISOStringSafe(comment.deleted_at)
        : null,
    })),
  };
}

