import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Retrieve a specific comment by commentId for a seller's own product review.
 *
 * Fetches a uniquely identified comment (by id) linked to a given review
 * (reviewId), ensuring that the seller is authorized to access the comment. All
 * normalized fields, including privacy, thread, and timestamps, are returned
 * per IAimallBackendComment.
 *
 * Business rule: A seller can only access comments (including private or
 * deleted) for reviews associated to their products. If the review is not for a
 * product owned by the seller, or if the comment/review does not exist, an
 * error is thrown.
 *
 * @param props - Function parameters
 * @param props.seller - The authenticated seller (role: seller)
 * @param props.reviewId - UUID of the review the comment belongs to
 * @param props.commentId - UUID of the comment to retrieve
 * @returns A full IAimallBackendComment record if access is granted
 * @throws {Error} If the comment, related review, or relevant product is
 *   missing, or if the seller is not authorized
 */
export async function get__aimall_backend_seller_reviews_$reviewId_comments_$commentId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendComment> {
  const { seller, reviewId, commentId } = props;

  // Step 1: Find the comment (by id, review, and exclude soft-deleted)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      review_id: reviewId,
      deleted_at: null,
    },
    select: {
      id: true,
      post_id: true,
      review_id: true,
      parent_id: true,
      customer_id: true,
      body: true,
      is_private: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });

  if (!comment) throw new Error("Comment not found");

  // Step 2: Find the review and validate it belongs to a product of this seller
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { product_id: true },
  });
  if (!review) throw new Error("Review not found");

  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error("Unauthorized to access this comment");
  }

  // Step 3: Map to DTO, ensuring all date types are ISO strings and types are correct
  return {
    id: comment.id,
    post_id: comment.post_id ?? null,
    review_id: comment.review_id ?? null,
    parent_id: comment.parent_id ?? null,
    customer_id: comment.customer_id ?? null,
    body: comment.body,
    is_private: comment.is_private,
    created_at: toISOStringSafe(comment.created_at),
    updated_at: toISOStringSafe(comment.updated_at),
    deleted_at: comment.deleted_at ? toISOStringSafe(comment.deleted_at) : null,
  };
}

