/**
 * Create a channel assignment for a product (register product to channel).
 *
 * This endpoint allows administrators to assign a product to a new channel,
 * registering it for listing or management purposes on that platform. It
 * creates a new aimall_backend_channel_assignments record linking the specified
 * product to the desired channel and records the assignment timestamp.
 *
 * Input validation ensures that the referenced product and channel are valid
 * and not already assigned together. Errors are thrown for invalid or duplicate
 * requests, or on insufficient permission.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user making the
 *   request
 * @param props.productId - Unique identifier of the target product for the
 *   assignment
 * @param props.body - Input data defining the new channel assignment
 *   (channelId, assigned_at, etc)
 * @returns The assignment record as created
 * @throws {Error} When the product or channel does not exist
 * @throws {Error} When the assignment already exists
 * @throws {Error} When the productId in the route does not match the
 *   body.product_id
 */
export async function post__aimall_backend_administrator_products_$productId_channelAssignments(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendChannelAssignment.ICreate;
}): Promise<IAimallBackendChannelAssignment> {
  const { administrator, productId, body } = props;

  // Ensure the productId in the route matches the product_id in the body
  if (productId !== body.product_id) {
    throw new Error("ProductId in route does not match product_id in body.");
  }

  // Check product existence
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) {
    throw new Error("Product not found.");
  }

  // Check channel existence
  const channel = await MyGlobal.prisma.aimall_backend_channels.findUnique({
    where: { id: body.channel_id },
  });
  if (!channel) {
    throw new Error("Channel not found.");
  }

  // Prevent duplicate assignment
  const duplicate =
    await MyGlobal.prisma.aimall_backend_channel_assignments.findUnique({
      where: {
        product_id_channel_id: {
          product_id: productId,
          channel_id: body.channel_id,
        },
      },
    });
  if (duplicate) {
    throw new Error("Assignment already exists.");
  }

  // Create the channel assignment
  const created =
    await MyGlobal.prisma.aimall_backend_channel_assignments.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        product_id: productId,
        channel_id: body.channel_id,
        assigned_at: body.assigned_at,
      },
    });

  return {
    id: created.id,
    product_id: created.product_id,
    channel_id: created.channel_id,
    assigned_at: created.assigned_at,
  };
}

