import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCategory";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Creates a new child category under a specified parent category in the
 * category hierarchy.
 *
 * This endpoint enables administrators to add a child category (subcategory)
 * beneath an existing parent category in the aimall_backend_categories
 * taxonomy. The new child is created with the specified name and is assigned a
 * depth value one greater than its parent's depth. The (parent_id, name) pair
 * must be unique, ensuring no duplicate category names under the same parent.
 *
 * Authorization: Only authenticated administrator users may perform this
 * operation.
 *
 * Validation:
 *
 * - The parent category (categoryId) must exist; otherwise, an error is thrown.
 * - Category name uniqueness is enforced per parent; violation results in an
 *   error.
 * - The category id is generated with v4().
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing this
 *   action
 * @param props.categoryId - UUID of the parent category under which to create
 *   the child
 * @param props.body - The child category specification (name only; depth is
 *   determined automatically)
 * @returns The fully populated child category object, including id, parent_id,
 *   name, and depth
 * @throws {Error} If parent category does not exist
 * @throws {Error} If category name is not unique among siblings of the parent
 */
export async function post__aimall_backend_administrator_categories_$categoryId_childCategories(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.ICreate;
}): Promise<IAimallBackendCategory> {
  const { administrator, categoryId, body } = props;

  // Step 1: Verify parent category exists
  const parent = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!parent) {
    throw new Error("Parent category does not exist");
  }

  // Step 2: Generate UUID for the new child category
  const id = v4() as string & tags.Format<"uuid">;

  // Step 3: Attempt to create the category, enforcing uniqueness
  try {
    const created = await MyGlobal.prisma.aimall_backend_categories.create({
      data: {
        id,
        parent_id: categoryId,
        name: body.name,
        depth: parent.depth + 1,
      },
    });
    return {
      id: created.id,
      parent_id: created.parent_id,
      name: created.name,
      depth: created.depth,
    };
  } catch (err: unknown) {
    if (
      err instanceof Prisma.PrismaClientKnownRequestError &&
      err.code === "P2002"
    ) {
      throw new Error(
        "Category name must be unique among siblings under the same parent",
      );
    }
    throw err;
  }
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import { IPageIAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendPost";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Search/filter community posts with advanced filters and pagination.
 *
 * Enables users and admins to search and filter community posts using advanced
 * criteria, including author (customer_id), post title, date ranges, is_private
 * flag, and more. Results exclude soft-deleted posts. Implements paging and
 * sorting for large sets.
 *
 * - Soft-deleted posts (deleted_at not null) are not included.
 * - Pagination is supported via page and limit parameters (default 1/20).
 * - Results are ordered by created_at descending (most recent first).
 * - Filtering is case-insensitive for title; boolean/null checked for other
 *   criteria.
 *
 * @param props - Request properties
 * @param props.body - Search and filtering criteria with pagination parameters
 * @returns Paginated result set of posts matching the filter criteria
 * @throws {Error} If database query fails or invalid filters are provided
 */
export async function patch__aimall_backend_posts(props: {
  body: IAimallBackendPost.IRequest;
}): Promise<IPageIAimallBackendPost> {
  const { body } = props;
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;

  // Build the Prisma WHERE clause for flexible search
  const where = {
    deleted_at: null,
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && {
        customer_id: body.customer_id,
      }),
    ...(body.title !== undefined &&
      body.title !== null && {
        title: { contains: body.title, mode: "insensitive" as const },
      }),
    ...(body.is_private !== undefined &&
      body.is_private !== null && {
        is_private: body.is_private,
      }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
    (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined &&
              body.created_at_from !== null && {
                gte: body.created_at_from,
              }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && {
                lte: body.created_at_to,
              }),
          },
        }
      : {}),
  };

  // Perform paginated search and get total count
  const [rows, count] = await Promise.all([
    MyGlobal.prisma.aimall_backend_posts.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_posts.count({ where }),
  ]);

  // Map Prisma records to DTO, converting all date fields using toISOStringSafe
  const data = rows.map((row) => ({
    id: row.id,
    customer_id: row.customer_id ?? null,
    title: row.title,
    body: row.body,
    is_private: row.is_private,
    view_count: row.view_count,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  const pages = Math.max(1, Math.ceil(count / limit));
  return {
    pagination: {
      current: page,
      limit: limit,
      records: count,
      pages,
    },
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPost";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Update/edit a community post by postId.
 *
 * Updates an existing community post identified by postId. Only the post's
 * original author can update; application enforces ownership. Patch only allows
 * mutable fields (title, body, is_private) and sets modification timestamp.
 * Errors if not found, deleted, or unauthorized.
 *
 * @param props - Customer: Authenticated customer making the update (must be
 *   post author). postId: UUID of the post to update. body: Post fields to
 *   patch (title, body, is_private).
 * @returns The updated IAimallBackendPost entry with all fields properly
 *   branded.
 * @throws {Error} When post does not exist, is soft-deleted, or is not owned by
 *   the customer.
 */
export async function put__aimall_backend_customer_posts_$postId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendPost.IUpdate;
}): Promise<IAimallBackendPost> {
  const { customer, postId, body } = props;

  // 1. Lookup post by id, ensure not deleted
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post || post.deleted_at) throw new Error("Post not found or deleted");

  // 2. Ownership enforcement: only author can update
  if (!post.customer_id || post.customer_id !== customer.id) {
    throw new Error("Unauthorized: Only the post author can update this post");
  }

  // 3. Perform patch: update only provided mutable fields and always update timestamp
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.aimall_backend_posts.update({
    where: { id: postId },
    data: {
      ...(body.title !== undefined &&
        body.title !== null && { title: body.title }),
      ...(body.body !== undefined && body.body !== null && { body: body.body }),
      ...(body.is_private !== undefined &&
        body.is_private !== null && { is_private: body.is_private }),
      updated_at: now,
    },
  });

  // 4. Return API-compliant output, branding all id/datetime fields
  return {
    id: updated.id,
    customer_id: updated.customer_id ?? null,
    title: updated.title,
    body: updated.body,
    is_private: updated.is_private,
    view_count: updated.view_count,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Creates a new comment on a product review, supporting threads and privacy.
 *
 * This operation creates and assigns a new comment to the specified product
 * review, storing comment details (body, privacy flag, optional parent for
 * threading).
 *
 * Requirements enforced:
 *
 * - Only authenticated (active) customers may comment (authorization via
 *   props.customer)
 * - Target review (reviewId) must exist, or error is thrown
 * - If parent_id is provided, parent comment must exist, not be deleted, and be
 *   attached to the same review
 * - No native Date type is used; all date fields are cast via toISOStringSafe
 *
 * @param props - Operation props
 * @param props.customer Authenticated customer payload (must be active)
 * @param props.reviewId UUID of the target product review
 * @param props.body Comment creation payload (body, privacy flag, optional
 *   parent)
 * @returns IAimallBackendComment object containing all comment fields
 * @throws {Error} When review not found, parent comment invalid/non-matching,
 *   or other invariants fail
 */
export async function post__aimall_backend_customer_reviews_$reviewId_comments(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.ICreate;
}): Promise<IAimallBackendComment> {
  const { customer, reviewId, body } = props;
  // 1. Validate review exists
  await MyGlobal.prisma.aimall_backend_reviews.findUniqueOrThrow({
    where: { id: reviewId },
  });

  // 2. If parent_id is given, validate parent comment exists and threading rules
  if (body.parent_id !== undefined && body.parent_id !== null) {
    const parent = await MyGlobal.prisma.aimall_backend_comments.findUnique({
      where: { id: body.parent_id },
    });
    if (
      !parent ||
      parent.deleted_at !== null ||
      parent.review_id == null ||
      parent.review_id !== reviewId
    ) {
      throw new Error(
        "Parent comment does not exist, is deleted, or not in the same review thread.",
      );
    }
  }

  // 3. Create comment record (post_id is null for review comments)
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.aimall_backend_comments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      post_id: null,
      review_id: reviewId,
      parent_id: body.parent_id ?? null,
      customer_id: customer.id,
      body: body.body,
      is_private: body.is_private,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  // 4. Return all fields in expected DTO (convert/brand all date outputs)
  return {
    id: created.id,
    post_id: created.post_id,
    review_id: created.review_id,
    parent_id: created.parent_id,
    customer_id: created.customer_id,
    body: created.body,
    is_private: created.is_private,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendSnapshot";
