import { IAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSnapshot";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Lists all community snapshot (사진/이미지/미디어) entries as paginated metadata for
 * admin dashboards and analytics.
 *
 * This function exposes only snapshot metadata (not media content) for
 * authorized administrator users, for purposes such as moderation and
 * analytics. Returns records as IAimallBackendSnapshot[] in the
 * IPageIAimallBackendSnapshot envelope structure, ordered by most recent
 * upload. No filter/pagination parameters are currently supported (full list
 * returned, paginated if needed in future). Will throw an Error if the
 * authenticated user is not an active admin.
 *
 * @param props - Request props
 * @param props.administrator - Authenticated administrator (payload from
 *   RBAC/decorator)
 * @returns Paginated metadata of all community snapshot/media records, latest
 *   first
 * @throws {Error} If the requester is not an active administrator
 */
export async function get__aimall_backend_administrator_snapshots(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendSnapshot> {
  const { administrator } = props;

  // Authorization: must be a current active admin
  const admin = await MyGlobal.prisma.aimall_backend_administrators.findFirst({
    where: { id: administrator.id, status: "active" },
  });
  if (!admin) {
    throw new Error(
      "Unauthorized: Only active administrators may access community snapshots.",
    );
  }

  // Fetch all snapshot rows from DB, order by created_at descending
  const snapshots = await MyGlobal.prisma.aimall_backend_snapshots.findMany({
    orderBy: { created_at: "desc" },
  });
  // Map each DB row to IAimallBackendSnapshot
  const data = snapshots.map((snapshot) => ({
    id: snapshot.id,
    product_id: snapshot.product_id ?? undefined,
    post_id: snapshot.post_id ?? undefined,
    customer_id: snapshot.customer_id ?? undefined,
    media_uri: snapshot.media_uri,
    caption: snapshot.caption ?? undefined,
    created_at: toISOStringSafe(snapshot.created_at),
  }));
  // No real pagination as no parameters; pagination can be added in future
  return {
    data,
    pagination: undefined,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IPageIAimallBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendCart";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IAimallBackendCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCart";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Retrieve a list of shopping carts from the system for administrators.
 *
 * This endpoint supplies summary information for each cart including primary
 * key, owner customer ID (nullable for guest carts), session tokens (for
 * anonymous carts), creation/update timestamps, and per-cart item count. Full
 * authorization is required: only administrator users may access this endpoint.
 * Pagination is not natively handled by this endpoint, but can be incorporated
 * at the service layer.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 * @returns Paginated list of IAimallBackendCart objects for all carts in the
 *   system
 * @throws {Error} When authorization or database errors occur
 */
export async function get__aimall_backend_administrator_carts(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendCart> {
  const { administrator } = props;
  // Fetch all shopping carts in the system
  const carts = await MyGlobal.prisma.aimall_backend_carts.findMany({});

  // Extract all cart IDs for lookup
  const cartIds = carts.map((cart) => cart.id);

  // Count the number of cart items for each cart in a single grouped query
  const cartItemCounts =
    await MyGlobal.prisma.aimall_backend_cart_items.groupBy({
      by: ["aimall_backend_cart_id"],
      where: { aimall_backend_cart_id: { in: cartIds } },
      _count: { id: true },
    });
  const cartItemsCountMap: Record<string, number> = Object.fromEntries(
    cartItemCounts.map((entry) => [
      entry.aimall_backend_cart_id,
      entry._count.id,
    ]),
  );

  // Map carts to IAimallBackendCart with proper branding and conversions
  const data = carts.map((cart) => ({
    id: cart.id,
    aimall_backend_customer_id: cart.aimall_backend_customer_id ?? undefined,
    session_token: cart.session_token ?? undefined,
    created_at: toISOStringSafe(cart.created_at),
    updated_at: toISOStringSafe(cart.updated_at),
    cart_items_count: cartItemsCountMap[cart.id] ?? 0,
  }));

  return {
    data,
    pagination: undefined, // Pagination is handled at the service/front layer
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Creates and assigns a new comment to a specified product review.
 *
 * Checks that the seller is authorized (owns the product linked to the review),
 * and that threading/parent comment rules are met. Creates the new comment
 * atomically on the review thread.
 *
 * @param props - Request properties
 * @param props.seller The authenticated seller (SellerPayload)
 * @param props.reviewId The UUID of the review to comment on
 * @param props.body Comment creation request (body, privacy, optional parent)
 * @returns The newly created comment fully populated
 * @throws {Error} If the review or parent comment is not found, or if seller is
 *   not authorized to comment
 */
export async function post__aimall_backend_seller_reviews_$reviewId_comments(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.ICreate;
}): Promise<IAimallBackendComment> {
  const { seller, reviewId, body } = props;

  // 1. Fetch the review and validate existence (and that it's not deleted)
  const review = await MyGlobal.prisma.aimall_backend_reviews.findFirst({
    where: {
      id: reviewId,
      deleted_at: null,
    },
  });
  if (!review) throw new Error("Review not found");

  // 2. Ensure seller's authorization: must own the product for this review
  const product = await MyGlobal.prisma.aimall_backend_products.findFirst({
    where: {
      id: review.product_id,
    },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id)
    throw new Error(
      "Forbidden: You are not allowed to comment on reviews of products you do not own",
    );

  // 3. If parent_id is provided, validate that parent comment exists and is for the same review
  if (body.parent_id) {
    const parent = await MyGlobal.prisma.aimall_backend_comments.findFirst({
      where: {
        id: body.parent_id,
        review_id: reviewId,
      },
    });
    if (!parent)
      throw new Error(
        "Parent comment does not exist or does not belong to this review thread",
      );
  }

  // 4. Create the new comment with all required, optional, and audit fields
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  const created = await MyGlobal.prisma.aimall_backend_comments.create({
    data: {
      id: v4(),
      post_id: null,
      review_id: reviewId,
      parent_id: body.parent_id ?? null,
      customer_id: seller.id,
      body: body.body,
      is_private: body.is_private,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    post_id: created.post_id,
    review_id: created.review_id,
    parent_id: created.parent_id,
    customer_id: created.customer_id,
    body: created.body,
    is_private: created.is_private,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Add a new item to a shopping cart (aimall_backend_cart_items).
 *
 * Adds a new item to an existing shopping cart after verifying cart ownership
 * and ensuring item uniqueness for (cart, product, option, sku) combination.
 * Throws an error if the cart does not exist, does not belong to this customer,
 * or the item already exists in the cart with the same combination.
 *
 * All timestamps and UUIDs are strictly formatted as required by the API
 * contract.
 *
 * @param props - The parameter object.
 * @param props.customer - The authenticated customer (JWT payload).
 * @param props.cartId - UUID of the cart to which the item is being added.
 * @param props.body - Details for the new cart item.
 * @returns The newly created cart item with all atomic fields populated.
 * @throws {Error} When the cart does not exist, does not belong to this
 *   customer, or an item with the same cart/product/option/sku combination
 *   already exists.
 */
export async function post__aimall_backend_customer_carts_$cartId_cartItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IAimallBackendCartItem.ICreate;
}): Promise<IAimallBackendCartItem> {
  const { customer, cartId, body } = props;

  // 1. Ensure cart exists and is owned by this customer
  const cart = await MyGlobal.prisma.aimall_backend_carts.findUnique({
    where: { id: cartId },
    select: { id: true, aimall_backend_customer_id: true },
  });
  if (!cart || cart.aimall_backend_customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: Cart does not exist or does not belong to this customer.",
    );
  }

  // 2. Enforce uniqueness on [cart, product, option, sku]
