import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Permanently delete a SKU belonging to a product.
 *
 * This function enforces that:
 *
 * - The authenticated seller owns the product (authorization enforced).
 * - The SKU exists and is part of the specified product.
 * - No active order items reference this SKU via product_option_id.
 * - No inventory snapshot is associated with this SKU.
 *
 * If any of these conditions are not met, an error is thrown and deletion is
 * blocked. This is a hard delete: there is no soft-deletion (no deleted_at
 * field).
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request
 * @param props.productId - The product ID to which the SKU belongs
 * @param props.skuId - The SKU ID to be deleted
 * @returns Void
 * @throws {Error} When authorization fails, SKU does not exist for product, or
 *   is referenced elsewhere.
 */
export async function delete__aimall_backend_seller_products_$productId_skus_$skuId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { seller, productId, skuId } = props;

  // Step 1: Authorization and product existence
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
    select: { id: true, seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Cannot delete SKU for a product you don't own",
    );
  }

  // Step 2: SKU existence and association
  const sku = await MyGlobal.prisma.aimall_backend_skus.findUnique({
    where: { id: skuId },
    select: { id: true, product_id: true },
  });
  if (!sku || sku.product_id !== productId) {
    throw new Error("SKU does not exist for this product");
  }

  // Step 3: Check for active references in order items
  const orderItemRef =
    await MyGlobal.prisma.aimall_backend_order_items.findFirst({
      where: { product_option_id: skuId },
    });
  if (orderItemRef) {
    throw new Error(
      "Cannot delete: SKU is referenced in one or more order items",
    );
  }

  // Step 4: Check for references in inventory snapshots
  const inventoryRef =
    await MyGlobal.prisma.aimall_backend_inventory_snapshots.findFirst({
      where: { sku_id: skuId },
    });
  if (inventoryRef) {
    throw new Error("Cannot delete: SKU has inventory snapshot records");
  }

  // Step 5: Hard delete the SKU
  await MyGlobal.prisma.aimall_backend_skus.delete({
    where: { id: skuId },
  });
}

