/**
 * 지정한 리뷰에 첨부된 스냅샷(사진/동영상 등) 상세정보를 반환합니다. (aimall_backend_snapshots 테이블)
 *
 * 리뷰와의 외래키 관계(상품/고객 매칭)를 엄격히 검증하여, 고객 자신의 리뷰에 연결된 스냅샷만 조회할 수 있습니다.
 *
 * 1. 경로 파라미터로 주어진 리뷰(reviewId)가 고객 본인의(review.customer_id == 고객 id) 것이어야 하며, 삭제
 *    처리(deleted_at)된 리뷰는 허용하지 않습니다.
 * 2. 해당 리뷰의 상품(product_id)과 동일한 product_id를 가진 스냅샷(snapshotId)이 존재해야 하며, 스냅샷의
 *    customer_id도 본인 것인지 추가로 확인합니다.
 * 3. 권한/조건 불일치 또는 미존재 시 404 반환합니다.
 * 4. 모든 필드는 IAimallBackendSnapshot 타입에 맞게 변환하며, 날짜는 반드시 toISOStringSafe로 변환합니다.
 *
 * @param props - 요청 파라미터 및 인증정보
 * @param props.customer - 인증된 고객 정보(JWT)
 * @param props.reviewId - 스냅샷이 소속된 리뷰 UUID
 * @param props.snapshotId - 조회 대상 스냅샷 UUID
 * @returns 요청 리뷰에 연결된 스냅샷 상세
 * @throws {Error} 리뷰가 존재하지 않거나 고객 소유가 아닐 때
 * @throws {Error} 리뷰에 연결된 스냅샷이 없거나 고객 소유가 아닐 때
 */
export async function get__aimall_backend_customer_reviews_$reviewId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendSnapshot> {
  const { customer, reviewId, snapshotId } = props;

  // [1] 본인 소유 및 미삭제 상태의 리뷰 검증
  const review = await MyGlobal.prisma.aimall_backend_reviews.findFirst({
    where: {
      id: reviewId,
      customer_id: customer.id,
      deleted_at: null,
    },
  });
  if (!review) {
    throw new Error("Not found or forbidden");
  }

  // [2] 리뷰에 연결된(동일 product_id) 본인 스냅샷만 허용
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findFirst({
    where: {
      id: snapshotId,
      product_id: review.product_id,
      customer_id: customer.id,
    },
  });
  if (!snapshot) {
    throw new Error("Snapshot not found or not linked to review");
  }

  // [3] IAimallBackendSnapshot 타입 반환(날짜 변환 필수)
  return {
    id: snapshot.id,
    product_id: snapshot.product_id ?? undefined,
    post_id: snapshot.post_id ?? undefined,
    customer_id: snapshot.customer_id ?? undefined,
    media_uri: snapshot.media_uri,
    caption:
      typeof snapshot.caption === "string" ? snapshot.caption : undefined,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

