import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPayment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Create a new payment transaction for a specific order by submitting full
 * payment details (method, amount, currency, optional external TX code) in the
 * request body. The payment is linked to the specified order using the orderId
 * path parameter. Only parties directly involved in the order (usually the
 * customer or the seller) are permitted to use this endpoint, protecting
 * financial integrity and preventing unauthorized billing events.
 *
 * Business validation ensures the cumulative payment amount matches the
 * expected order total after payment creation. The returned response body
 * provides the complete payment record, linking to follow-up actions such as
 * refunds or transaction confirmation.
 *
 * @param props - Request parameters
 * @param props.customer - The authenticated customer making the payment
 * @param props.orderId - The order to attach the payment to
 * @param props.body - Payment transaction creation data (method, amount,
 *   currency, external tx/ref)
 * @returns The newly created payment record
 * @throws {Error} When the order does not exist, is not owned by the customer,
 *   currency mismatches, or cumulative paid amount is over order total
 */
export async function post__aimall_backend_customer_orders_$orderId_payments(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendPayment.ICreate;
}): Promise<IAimallBackendPayment> {
  const { customer, orderId, body } = props;

  // 1. Fetch order. Throws if not found.
  const order = await MyGlobal.prisma.aimall_backend_orders.findUniqueOrThrow({
    where: { id: orderId },
    select: {
      id: true,
      customer_id: true,
      total_amount: true,
      currency: true,
    },
  });
  if (order.customer_id !== customer.id) {
    throw new Error("Forbidden: You do not own this order");
  }
  if (order.currency !== body.currency) {
    throw new Error("Payment currency does not match order currency");
  }

  // 2. Enforce business validation on cumulative payment amount
  const previousPayments =
    await MyGlobal.prisma.aimall_backend_payments.findMany({
      where: { order_id: orderId },
      select: { amount: true },
    });
  const totalPaid = previousPayments.reduce((sum, p) => sum + p.amount, 0);
  if (totalPaid + body.amount > order.total_amount) {
    throw new Error("Payment amount exceeds order total");
  }

  // 3. Insert payment using branded values and safe date formatting
  const paymentId = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());
  const paidAt: string & tags.Format<"date-time"> =
    body.paid_at != null ? toISOStringSafe(body.paid_at) : now;
  const created = await MyGlobal.prisma.aimall_backend_payments.create({
    data: {
      id: paymentId,
      order_id: orderId,
      payment_method: body.payment_method,
      amount: body.amount,
      currency: body.currency,
      transaction_id: body.transaction_id ?? null,
      paid_at: paidAt,
    },
  });

  // 4. Return normalized response using ISO date string
  return {
    id: created.id,
    order_id: created.order_id,
    payment_method: created.payment_method,
    amount: created.amount,
    currency: created.currency,
    transaction_id: created.transaction_id ?? null,
    paid_at: toISOStringSafe(created.paid_at),
  };
}

import { MyGlobal } from "../MyGlobal";
