/**
 * Retrieves all discount campaigns from the campaign table.
 *
 * Fetches a complete list of discount campaigns from the
 * aimall_backend_discount_campaigns table, providing all campaigns with their
 * configuration fields such as code, name, type, date ranges, stackable flag,
 * and business status.
 *
 * Security: Only users with administrator privileges may access this endpoint,
 * as discount campaign data is sensitive and often managed by platform staff.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user making the
 *   request.
 * @returns Paginated list of all discount campaigns (single page, no
 *   filtering).
 * @throws {Error} When administrator authentication is missing or inactive.
 */
export async function get__aimall_backend_administrator_discountCampaigns(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendDiscountCampaign> {
  const { administrator } = props;

  // Defensive check: enforce administrator authentication
  if (
    !administrator ||
    administrator.type !== "administrator" ||
    administrator.status !== "active"
  ) {
    throw new Error("Administrator authorization required");
  }

  const campaigns =
    await MyGlobal.prisma.aimall_backend_discount_campaigns.findMany();

  const data = campaigns.map((row) => ({
