    max_uses_per_user: row.max_uses_per_user ?? null,
    priority: row.priority,
    description: row.description ?? null,
  }));

  return {
    pagination: {
      current: 1 as 1,
      limit: data.length as number & tags.Type<"int32">,
      records: data.length as number & tags.Type<"int32">,
      pages: 1 as 1,
    },
