/**
 * Edit a support ticket as its owning seller.
 *
 * Allows the seller who created the support ticket to update specific fields
 * (subject, body, status, priority, category) of their own ticket. Sellers
 * cannot update the admin assignee field; attempts to set assignee_admin_id
 * will be ignored. The updated_at timestamp is refreshed on update for audit
 * trail. Authorization is enforced: only the ticket owner may update fields.
 * Throws an error if the ticket does not exist or if the seller is not the
 * requester.
 *
 * @param props - Request parameters
 * @param props.seller - Authenticated seller (must be the requester/owner of
 *   the ticket)
 * @param props.supportTicketId - UUID of the ticket to update
 * @param props.body - Fields to update (subject, body, status, priority,
 *   category)
 * @returns The full ticket with updated fields, timestamps formatted as ISO
 *   strings
 * @throws {Error} If the ticket does not exist or seller is not authorized
 */
export async function put__aimall_backend_seller_supportTickets_$supportTicketId(props: {
  seller: SellerPayload;
  supportTicketId: string & tags.Format<"uuid">;
  body: IAimallBackendSupportTicket.IUpdate;
}): Promise<IAimallBackendSupportTicket> {
