/**
 * Update an existing address for a customer (aimall_backend_addresses).
 *
 * Update a specific address for a given customer using admin privileges. If
 * is_default is set to true, all other addresses for the customer will have
 * is_default reset to false to enforce the single-default address rule.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   update
 * @param props.customerId - UUID of the customer whose address will be updated
 * @param props.addressId - UUID of the address to update (must belong to
 *   customerId)
 * @param props.body - Fields for updating the address record per
 *   IAimallBackendAddress.IUpdate
 * @returns The updated address record matching IAimallBackendAddress
 * @throws {Error} If the address does not exist or does not belong to the
 *   specified customer
 */
export async function put__aimall_backend_administrator_customers_$customerId_addresses_$addressId(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  addressId: string & tags.Format<"uuid">;
  body: IAimallBackendAddress.IUpdate;
}): Promise<IAimallBackendAddress> {
  const { administrator, customerId, addressId, body } = props;

  // Fetch the address and ensure it belongs to the specified customer
  const address = await MyGlobal.prisma.aimall_backend_addresses.findUnique({
    where: { id: addressId },
  });
  if (!address) throw new Error("Address not found");
  if (address.customer_id !== customerId)
    throw new Error("Address does not belong to the specified customer");

  // If setting this as default, unset default for all other addresses for this customer
  if (body.is_default) {
    await MyGlobal.prisma.aimall_backend_addresses.updateMany({
      where: { customer_id: customerId, id: { not: addressId } },
      data: { is_default: false },
    });
  }

  // Update the address
  const updated = await MyGlobal.prisma.aimall_backend_addresses.update({
    where: { id: addressId },
    data: {
      alias: body.alias,
      recipient_name: body.recipient_name,
      phone: body.phone,
      address_line1: body.address_line1,
      address_line2: body.address_line2 ?? undefined,
      city: body.city,
      postal_code: body.postal_code,
      country: body.country,
      is_default: body.is_default,
      updated_at: body.updated_at,
    },
  });

  // Return the updated address, mapping all fields explicitly
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    alias: updated.alias,
    recipient_name: updated.recipient_name,
    phone: updated.phone,
    address_line1: updated.address_line1,
    address_line2: updated.address_line2 ?? undefined,
    city: updated.city,
    postal_code: updated.postal_code,
    country: updated.country,
    is_default: updated.is_default,
    updated_at: updated.updated_at,
  };
}

