/**
 * Retrieve a detailed snapshot record for a specified order and snapshot event.
 *
 * Returns the serialized history of the order at that snapshot, including all
 * base fields and structured metadata per the 'aimall_backend_order_snapshots'
 * schema. Only the assigned seller for the order is permitted to access the
 * snapshot.
 *
 * Errors are thrown if the snapshot or order does not exist, or if access is
 * denied due to mismatched seller authentication.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller making the request (RBAC enforced)
 * @param props.orderId - UUID of the parent order (must match order_id of
 *   snapshot and be owned by seller)
 * @param props.orderSnapshotId - UUID of the snapshot record to retrieve
 * @returns The full historical order snapshot at the event specified
 * @throws {Error} When snapshot is not found, the order does not exist, or
 *   seller is not assigned
 */
export async function get__aimall_backend_seller_orders_$orderId_orderSnapshots_$orderSnapshotId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  orderSnapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendOrderSnapshot> {
  const { seller, orderId, orderSnapshotId } = props;

  // First, find the snapshot with the correct order reference
  const snapshot =
    await MyGlobal.prisma.aimall_backend_order_snapshots.findFirst({
      where: {
        id: orderSnapshotId,
        order_id: orderId,
      },
    });
  if (!snapshot) throw new Error("Order snapshot not found");

  // Fetch the order for RBAC check
  const order = await MyGlobal.prisma.aimall_backend_orders.findFirst({
    where: { id: orderId },
  });
  if (!order || order.seller_id !== seller.id)
    throw new Error("Forbidden: You are not the assigned seller of this order");

  return {
    id: snapshot.id,
    order_id: snapshot.order_id,
    snapshot_type: snapshot.snapshot_type,
    snapshot_data: snapshot.snapshot_data,
    snapshot_at: toISOStringSafe(snapshot.snapshot_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSection";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update a section of a channel (aimall_backend_sections) by UUIDs.
 *
 * Perform an update on a section entity for a particular channel, providing the
 * list of allowed, mutable fields in the request body. Validation ensures the
 * unique key constraint (channel_id+code) and conforms all business rules
 * within the system and schema.
 *
 * Only users responsible for channel/section management should have access, and
 * updates should log all change events for compliance. This endpoint is used
 * alongside create, get, search, and delete operations to provide full CRUD
 * management for channel sections. The operation validates the request payload,
 * both for schema and for conflict with existing section data.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user making the
 *   request (authorization enforced)
 * @param props.channelId - UUID of the parent channel containing the section
 * @param props.sectionId - UUID of the section to update
 * @param props.body - Update payload for the section entity fields
 * @returns The updated section state as persisted
 * @throws {Error} When the section is not found or does not belong to the
 *   channel
 * @throws {Error} When updating code would violate the unique (channel, code)
 *   constraint
 */
export async function put__aimall_backend_administrator_channels_$channelId_sections_$sectionId(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  sectionId: string & tags.Format<"uuid">;
  body: IAimallBackendSection.IUpdate;
}): Promise<IAimallBackendSection> {
  const { administrator, channelId, sectionId, body } = props;

  // --- Authorization is enforced through administrator payload

  // --- 1. Find the section by id. Ensure belongs to channel.
  const section = await MyGlobal.prisma.aimall_backend_sections.findUnique({
    where: { id: sectionId },
  });
  if (!section || section.channel_id !== channelId) {
    throw new Error("Section not found or does not belong to channel");
  }

  // --- 2. If code changed, enforce unique constraint (channel, code)
  if (
    body.code !== undefined &&
    body.code !== null &&
    body.code !== section.code
  ) {
    const conflict = await MyGlobal.prisma.aimall_backend_sections.findFirst({
      where: {
        channel_id: channelId,
        code: body.code,
        id: { not: sectionId },
      },
    });
    if (conflict) {
      throw new Error("Section code must be unique within the channel");
    }
  }

  // --- 3. Update permitted fields, plus updated_at
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.aimall_backend_sections.update({
    where: { id: sectionId },
    data: {
      code: body.code === null ? undefined : (body.code ?? undefined),
      name: body.name === null ? undefined : (body.name ?? undefined),
      display_order:
        body.display_order === null
          ? undefined
          : (body.display_order ?? undefined),
      enabled: body.enabled === null ? undefined : (body.enabled ?? undefined),
      updated_at: now,
    },
  });

  // --- 4. Return full section object, with proper type conversions
  return {
    id: updated.id,
    channel_id: updated.channel_id,
    code: updated.code,
    name: updated.name,
    display_order: updated.display_order,
    enabled: updated.enabled,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: now, // use prepared value (above)
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

