 * item within their own cart, such as changing quantity, product option, or
 * price snapshot. Only the owner of the cart may update its items.
 *
 * Business logic strictly enforces that the cart must belong to the
 * authenticated customer, and the item must belong to the provided cart. Only
 * atomic, schema-supported fields are updatable. Returns the fully updated cart
 * item.
 *
 * @param props - Request parameters
 * @param props.customer - Authenticated customer payload
 * @param props.cartId - UUID of the cart to update
 * @param props.cartItemId - UUID of the cart item to update
 * @param props.body - Update payload (fields to change + updated_at is
 *   required)
 * @returns The updated cart item entity as per IAimallBackendCartItem DTO
 * @throws {Error} If the cart does not exist or is not owned by the customer
 * @throws {Error} If the cart item does not exist or does not belong to the
 *   provided cart
 */
export async function put__aimall_backend_customer_carts_$cartId_cartItems_$cartItemId(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  cartItemId: string & tags.Format<"uuid">;
  body: IAimallBackendCartItem.IUpdate;
}): Promise<IAimallBackendCartItem> {
