  // 2. Verify cart item belongs to this cart
  const item = await MyGlobal.prisma.aimall_backend_cart_items.findUnique({
    where: { id: cartItemId },
  });
  if (!item || item.aimall_backend_cart_id !== cartId)
    throw new Error("Cart item not found in specified cart");

