      discount_snapshot: body.discount_snapshot ?? undefined,
      selected_name_display: body.selected_name_display ?? undefined,
      updated_at: body.updated_at,
    },
  });

  // 4. Marshal result as IAimallBackendCartItem
  return {
    id: updated.id,
    aimall_backend_cart_id: updated.aimall_backend_cart_id,
    aimall_backend_product_id: updated.aimall_backend_product_id,
    aimall_backend_product_option_id:
      updated.aimall_backend_product_option_id ?? null,
