 *
 * Allows an authenticated customer (the original author) to update their
 * comment's text (body), privacy flag, or to soft-delete the comment. Only the
 * comment's author can perform the update. Attempting to modify an unauthorized
 * or logically deleted comment results in an error. Uses soft-delete by setting
 * deleted_at timestamp.
 *
 * @param props - Object containing all parameters
 * @param props.customer - Authenticated customer making this request (must be
 *   comment author)
 * @param props.commentId - UUID of the comment to update
 * @param props.body - Update DTO, may include new body text, privacy flag, or
 *   deleted_at timestamp for soft delete
 * @returns The updated comment reflecting all current database fields after
 *   update
 * @throws {Error} If comment not found, is deleted, or author mismatch
 */
export async function put__aimall_backend_customer_comments_$commentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IUpdate;
}): Promise<IAimallBackendComment> {
  const { customer, commentId, body } = props;

  // Find the comment (must exist and not soft-deleted)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      deleted_at: null,
    },
  });
  if (!comment) throw new Error("Comment not found or already deleted");
