/**
 * Update configuration of a specific SKU for a product (aimall_backend_skus).
 *
 * Modify the details of a SKU as a child of a given product. The endpoint uses
 * both productId and skuId to unambiguously locate the record within the
 * aimall_backend_skus table and updates one or more SKU fields (e.g.,
 * sku_code). Validation checks include that the updated code is unique and that
 * the SKU is subordinate to the stated product by product_id.
 *
 * If the validation passes, returns the full updated SKU record; otherwise,
 * errors indicate field conflicts or relationship mismatches. This is a
 * critical operation for catalog management and SKU lifecycle operations in
 * administrator and seller roles.
 *
 * @param props - Operation parameters
 * @param props.administrator - The authenticated administrator performing the
 *   update
 * @param props.productId - UUID of the product to which the SKU must belong
 * @param props.skuId - UUID of the SKU to update
 * @param props.body - Update details (sku_code)
 * @returns The full updated SKU record
 * @throws {Error} If SKU not found, SKU does not belong to product, or sku_code
 *   is not unique
 */
export async function put__aimall_backend_administrator_products_$productId_skus_$skuId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
  body: IAimallBackendSku.IUpdate;
}): Promise<IAimallBackendSku> {
  const { productId, skuId, body } = props;

  // 1. Verify SKU exists and is a child of the given product
  const sku = await MyGlobal.prisma.aimall_backend_skus.findUnique({
    where: { id: skuId },
    select: { id: true, product_id: true, sku_code: true },
  });
  if (!sku) throw new Error("SKU not found");
  if (sku.product_id !== productId)
    throw new Error("SKU does not belong to the given product");

  // 2. If updating sku_code, check for uniqueness within the table
  if ("sku_code" in body && body.sku_code !== undefined) {
    const duplicate = await MyGlobal.prisma.aimall_backend_skus.findFirst({
      where: {
        sku_code: body.sku_code,
        id: { not: skuId },
      },
    });
    if (duplicate) throw new Error("SKU code must be unique");
  }

  // 3. Perform update
  const updated = await MyGlobal.prisma.aimall_backend_skus.update({
    where: { id: skuId },
    data: {
      sku_code: body.sku_code ?? undefined,
    },
    select: { id: true, product_id: true, sku_code: true },
  });
  // 4. Return the updated SKU object
  return updated;
}

