/**
 * Update configuration of a specific SKU for a product (aimall_backend_skus).
 *
 * Modify the details of a SKU as a child of a given product. The endpoint uses
 * both productId and skuId to unambiguously locate the record within the
 * aimall_backend_skus table and updates one or more SKU fields (e.g.,
 * sku_code). Validation checks include that the updated code is unique and that
 * the SKU is subordinate to the stated product by product_id. Only the owning
 * seller may update.
 *
 * If the validation passes, returns the full updated SKU record; otherwise,
 * errors indicate field conflicts or relationship mismatches. This is a
 * critical operation for catalog management and SKU lifecycle operations in
 * administrator and seller roles.
 *
 * @param props - Request parameters
 * @param props.seller - Authenticated seller (must own the product)
 * @param props.productId - Product ID whose SKU is being updated
 * @param props.skuId - The SKU ID to update
 * @param props.body - Update data for the SKU (sku_code optional)
 * @returns The updated IAimallBackendSku record
 * @throws {Error} When SKU or product not found, unauthorized access, or SKU
 *   code conflict
 */
export async function put__aimall_backend_seller_products_$productId_skus_$skuId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
  body: IAimallBackendSku.IUpdate;
}): Promise<IAimallBackendSku> {
  const { seller, productId, skuId, body } = props;
  // Step 1: Lookup SKU and check product linkage
  const sku = await MyGlobal.prisma.aimall_backend_skus.findUnique({
    where: { id: skuId },
  });
  if (!sku) throw new Error("SKU not found");
  if (sku.product_id !== productId)
    throw new Error("SKU does not belong to the specified product");
  // Step 2: Lookup product for seller ownership
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id)
    throw new Error(
      "Unauthorized: Only the product owner seller can update its SKUs",
    );
  // Step 3: Perform update
  try {
    const updated = await MyGlobal.prisma.aimall_backend_skus.update({
      where: { id: skuId },
      data: {
        sku_code: body.sku_code ?? undefined,
      },
    });
    return {
      id: updated.id,
      product_id: updated.product_id,
      sku_code: updated.sku_code,
    };
  } catch (err: any) {
    // Prisma unique key error: sku_code must be unique
    if (typeof err === "object" && err && err.code === "P2002") {
      throw new Error("SKU code must be unique");
    }
    throw err;
  }
}

