 * won't conflict with an already-linked account.
 *
 * If update is not allowed (e.g., immutable provider), will reject with error.
 * All update attempts are audited.
 *
 * Returns updated external account info on success.
 *
 * @param props - Request properties
 * @param props.customer - Customer JWT payload making the request
 * @param props.customerId - Target customer ID (must match authenticated
 *   customer)
 * @param props.externalAccountId - External account linkage ID being updated
 * @param props.body - Fields to update (provider, external_user_id)
 * @returns The updated external account record
 * @throws {Error} If the account is not owned by the customer, doesn't exist,
 *   or update would cause a uniqueness conflict
 */
export async function put__aimall_backend_customer_customers_$customerId_externalAccounts_$externalAccountId(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  externalAccountId: string & tags.Format<"uuid">;
  body: IAIMallBackendExternalAccount.IUpdate;
}): Promise<IAIMallBackendExternalAccount> {
  const { customer, customerId, externalAccountId, body } = props;

  // 1. Fetch the external account and check ownership.
  const account =
    await MyGlobal.prisma.aimall_backend_external_accounts.findUnique({
      where: { id: externalAccountId },
    });
  if (!account || account.customer_id !== customer.id) {
    throw new Error(
      "External account not found or not owned by current customer.",
    );
  }

  // 2. Uniqueness check: ensure no other account uses this provider+external_user_id
  const conflict =
    await MyGlobal.prisma.aimall_backend_external_accounts.findFirst({
      where: {
        provider: body.provider,
        external_user_id: body.external_user_id,
        NOT: { id: externalAccountId },
      },
    });
  if (conflict) {
    throw new Error(
      "Another external account with this provider and user ID already exists.",
    );
  }

  // 3. Update only provider and external_user_id
  const updated = await MyGlobal.prisma.aimall_backend_external_accounts.update(
    {
      where: { id: externalAccountId },
      data: {
        provider: body.provider,
        external_user_id: body.external_user_id,
      },
    },
  );

  // 4. Return updated record with correctly-typed fields
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    provider: updated.provider,
    external_user_id: updated.external_user_id,
    linked_at: toISOStringSafe(updated.linked_at),
  };
}

