 * customer access rights.
 *
 * This operation checks that the specified order is owned by the requesting
 * customer and returns details of the requested order item if it belongs to the
 * same order. Throws errors if the order is not found, not owned by the
 * customer, or the item is not part of the order.
 *
 * @param props - Customer: The authenticated customer (CustomerPayload)
 *   orderId: UUID of the parent order orderItemId: UUID of the order item to
 *   retrieve
 * @returns IAimallBackendOrderItem with all fields populated
 * @throws {Error} If the order does not exist, is not owned by the customer, or
 *   the item is not found/belongs to a different order.
 */
export async function get__aimall_backend_customer_orders_$orderId_orderItems_$orderItemId(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendOrderItem> {
  const { customer, orderId, orderItemId } = props;

  // Step 1: Ensure the order exists and belongs to the customer
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { id: true, customer_id: true },
  });
  if (!order || order.customer_id !== customer.id) {
