/**
 * Create (upload) a new snapshot (photo/media) directly linked to a specific
 * community post (aimall_backend_snapshots).
 *
 * This function enforces all database and DTO constraints: attaches the
 * snapshot strictly to the target post, ensures all required fields (including
 * UUIDs and formatted date-times) are handled per schema, and only allows
 * authenticated customers to upload. If the target post does not exist, it will
 * throw an error.
 *
 * @param props - Operation properties
 * @param props.customer - The authenticated customer performing the upload
 *   (injected via CustomerAuth decorator)
 * @param props.postId - Target post's unique identifier to which the snapshot
 *   will be linked
 * @param props.body - The snapshot creation body (includes media_uri and
 *   optionally caption, product_id, created_at)
 * @returns The newly stored snapshot entity as persisted in the database
 * @throws {Error} When the post does not exist or is invalid
 */
export async function post__aimall_backend_customer_posts_$postId_snapshots(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.ICreate;
}): Promise<IAimallBackendSnapshot> {
