/**
 * Updates a customer's delivery address.
 *
 * This operation allows an authenticated customer to update the details of one
 * of their own address entries (alias, recipient, phone, city, etc.). It
 * enforces business constraints:
 *
 * - Only the owning customer may update.
 * - When an address is set to default (is_default: true), all other addresses for
 *   the customer are demoted to is_default: false.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the update
 * @param props.customerId - The customer's UUID whose address is to be updated
 * @param props.addressId - The address record's UUID to update
 * @param props.body - New address field values
 * @returns The updated address object
 * @throws {Error} If the customer does not own the address or business
 *   constraints are violated
 */
export async function put__aimall_backend_customer_customers_$customerId_addresses_$addressId(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  addressId: string & tags.Format<"uuid">;
  body: IAimallBackendAddress.IUpdate;
}): Promise<IAimallBackendAddress> {
  const { customer, customerId, addressId, body } = props;

  // Step 1: Authorization check
  if (customer.id !== customerId) {
    throw new Error("Unauthorized: Customer mismatch");
  }

  // Step 2: Retrieve the address and verify ownership
  const address = await MyGlobal.prisma.aimall_backend_addresses.findUnique({
    where: { id: addressId },
  });
  if (!address || address.customer_id !== customerId) {
    throw new Error("Address not found or does not belong to customer");
  }

  // Step 3: Enforce single is_default address, if necessary
  if (body.is_default && !address.is_default) {
    await MyGlobal.prisma.aimall_backend_addresses.updateMany({
      where: { customer_id: customerId, id: { not: addressId } },
      data: { is_default: false },
    });
  }

  // Step 4: Update the address record
  const updated = await MyGlobal.prisma.aimall_backend_addresses.update({
    where: { id: addressId },
    data: {
      alias: body.alias,
      recipient_name: body.recipient_name,
      phone: body.phone,
      address_line1: body.address_line1,
      address_line2:
        body.address_line2 !== undefined ? body.address_line2 : undefined,
      city: body.city,
      postal_code: body.postal_code,
      country: body.country,
      is_default: body.is_default,
      updated_at: toISOStringSafe(body.updated_at),
    },
  });

  // Step 5: Map the updated record to the API DTO
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    alias: updated.alias,
    recipient_name: updated.recipient_name,
    phone: updated.phone,
    address_line1: updated.address_line1,
    address_line2: updated.address_line2 ?? undefined,
    city: updated.city,
    postal_code: updated.postal_code,
    country: updated.country,
    is_default: updated.is_default,
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

