/**
 * Edit a reply (child comment) under a parent comment (atomic field update).
 *
 * Allows an administrator to edit the body or privacy status of a reply (child
 * comment) identified by childCommentId under the specified parent comment.
 * Edits update only atomic (non-relational) comment fields; parent_id and
 * thread integrity cannot be changed here. Only active, non-deleted comments
 * can be edited. The system updates updated_at for each modification.
 *
 * This supports audit-compliance by tracking changes to content. Unauthorized
 * edit attempts or edits to soft-deleted comments return an error. The endpoint
 * does not support creating, deleting, or reparenting comments.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator (must have active
 *   status)
 * @param props.commentId - UUID of the parent comment (thread being replied to)
 * @param props.childCommentId - UUID of the child comment to update
 * @param props.body - Fields to update on the reply (comment body, privacy,
 *   etc)
 * @returns The updated child comment, reflecting the modified fields
 * @throws {Error} If the child comment does not exist
 * @throws {Error} If the comment is soft-deleted
 * @throws {Error} If the parent-child relationship is invalid
 */
export async function put__aimall_backend_administrator_comments_$commentId_comments_$childCommentId(props: {
  administrator: AdministratorPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IUpdate;
}): Promise<IAimallBackendComment> {
  const { administrator, commentId, childCommentId, body } = props;

  // Fetch the target comment by childCommentId
  const comment =
    await MyGlobal.prisma.aimall_backend_comments.findUniqueOrThrow({
      where: { id: childCommentId },
    });

  // Only allow editing if comment is not deleted
  if (comment.deleted_at !== null) {
    throw new Error("Cannot edit a deleted comment.");
  }

  // The parent_id must match the provided commentId (thread integrity)
  if (comment.parent_id !== commentId) {
    throw new Error("Child comment parent mismatch.");
  }

  // Update atomic fields (body, is_private, deleted_at, updated_at ONLY)
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: childCommentId },
    data: {
      body: body.body ?? undefined,
      is_private: body.is_private ?? undefined,
      deleted_at: body.deleted_at ?? undefined,
      updated_at: now,
    },
  });

  return {
    id: updated.id,
    post_id: updated.post_id ?? null,
    review_id: updated.review_id ?? null,
    parent_id: updated.parent_id ?? null,
    customer_id: updated.customer_id ?? null,
    body: updated.body,
    is_private: updated.is_private,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

