/**
 * List coupons (Coupon table, paginated and role-based).
 *
 * Obtain a simple paginated or full list of all coupon records. Output includes
 * coupon atomic metadata as defined by the aimall_backend_coupons schema,
 * supporting basic management, user-facing voucher display, or analytics.
 *
 * Returns coupon code, campaign details, status (issued, redeemed, expired,
 * etc.), assignment, and timestamps but never returns information not present
 * in the schema (no soft-delete present). Result set is typically restricted
 * per authorization: customers see only their own coupons, while administrators
 * can see all coupons system-wide for compliance or monitoring.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user (payload)
 * @returns Paginated list of coupon records as IPageIAimallBackendCoupon
 * @throws {Error} If administrator is not authenticated or authorized
 */
export async function get__aimall_backend_administrator_coupons(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendCoupon> {
  const current = 1;
  const limit = 20;

  // Authorization: Provided via the AdministratorAuth decorator; payload is assumed valid

  // Query coupons with pagination
  const [coupons, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_coupons.findMany({
      orderBy: { issued_at: "desc" },
      skip: (current - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_coupons.count(),
  ]);
  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current,
      limit,
      records: total,
      pages,
    },
    data: coupons.map((c) => ({
      id: c.id,
      discount_campaign_id: c.discount_campaign_id,
      customer_id: c.customer_id ?? null,
      code: c.code,
      status: c.status,
      issued_at: toISOStringSafe(c.issued_at),
      expires_at: toISOStringSafe(c.expires_at),
      redeemed_at: c.redeemed_at ? toISOStringSafe(c.redeemed_at) : null,
    })),
  };
}

