export async function put__aimall_backend_seller_posts_$postId_attachments_$attachmentId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IUpdate;
}): Promise<IAimallBackendAttachment> {
  const { seller, postId, attachmentId, body } = props;

  // Step 1: Fetch and validate attachment existence and association to the correct post
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
    });
  if (!attachment) throw new Error("Attachment not found");
  if (attachment.post_id !== postId)
