  // Step 2: Fetch and validate the owning post, and ensure seller authority (must own original post as seller/customer)
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post) throw new Error("Post not found");
  if (!post.customer_id)
    throw new Error("Post is detached from any customer/account");
  if (post.customer_id !== seller.id)
    throw new Error(
      "Forbidden: Only original seller may update this post's attachments",
    );

  // Step 3: Update the attachment with supplied attributes if present
  const updated = await MyGlobal.prisma.aimall_backend_attachments.update({
    where: { id: attachmentId },
    data: {
      file_uri: body.file_uri ?? undefined,
      file_type: body.file_type ?? undefined,
      file_size: body.file_size ?? undefined,
    },
  });

  // Step 4: Return entity (created_at converted to ISO8601 string)
  return {
    id: updated.id,
    post_id: updated.post_id,
    comment_id: updated.comment_id,
    review_id: updated.review_id,
    file_uri: updated.file_uri,
    file_type: updated.file_type,
    file_size: updated.file_size,
    created_at: toISOStringSafe(updated.created_at),
  };
}

