/**
 * Update a comment under a post by commentId (Community, Comments).
 *
 * This endpoint updates a comment for a particular post by verifying that the
 * seller owns the product associated with the post. Only the seller of the
 * product associated with the post can update comments under that post. If not
 * found, or unauthorized, an error is thrown.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the update
 * @param props.postId - ID of the post holding the comment
 * @param props.commentId - ID of the comment being updated
 * @param props.body - The update payload matching the Community Comments update
 *   schema
 * @returns The updated comment entity matching normalization rules
 * @throws {Error} If the comment is not found or the seller is not authorized
 *   to update
 */
export async function put__aimall_backend_seller_posts_$postId_comments_$commentId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IUpdate;
}): Promise<IAimallBackendComment> {
  const { seller, postId, commentId, body } = props;

  // Fetch the comment, post, and product (join necessary to verify seller ownership)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      post_id: postId,
      deleted_at: null,
    },
    include: {
      fk_comments_post: {
        include: {
          // Assuming post has a field to product (e.g., product_id) and linking to products
          fk_aimall_backend_products_post: {
            select: { seller_id: true },
          },
        },
      },
    },
  });
  if (!comment)
    throw new Error("Comment not found for this post or already deleted");

  const postProductSellerId =
    comment.fk_comments_post?.fk_aimall_backend_products_post?.seller_id;
  if (postProductSellerId !== seller.id)
    throw new Error(
      "Unauthorized: Only the owner seller can update this comment.",
    );

  // Prune unprovided fields (do not update fields not present in body), set updated_at
  const updated = await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: {
      body: body.body ?? undefined,
      is_private: body.is_private ?? undefined,
      deleted_at: body.deleted_at ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    post_id: updated.post_id ?? null,
    review_id: updated.review_id ?? null,
    parent_id: updated.parent_id ?? null,
    customer_id: updated.customer_id ?? null,
    body: updated.body,
    is_private: updated.is_private,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

