 *
 * This function returns a paginated, filtered list of product taxonomy
 * categories based on provided filters. Allows advanced search on category name
 * (substring), hierarchy depth, and parent category. Only accessible by
 * authenticated administrators.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   active). Only users with administrator role can access this endpoint.
 * @param props.body - Filter/search parameters for querying categories,
 *   including optional parent_id, name, depth, page, and limit fields. All
 *   filters are optional.
 * @returns Paginated result: array of matching categories and pagination
 *   metadata (current, limit, records, pages).
 * @throws {Error} When authentication/authorization fails or if any internal DB
 *   error occurs.
 */
export async function patch__aimall_backend_administrator_categories(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendCategory.IRequest;
}): Promise<IPageIAimallBackendCategory> {
  const { administrator, body } = props;

  // Authorization is validated by decorator; props.administrator is present and active

  // Extract pagination parameters with defaults
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const offset = (page - 1) * limit;

  // Compose Prisma where clause (all optional filters, only if provided)
  const where = {
    ...(body.parent_id !== undefined && {
      parent_id: body.parent_id,
    }),
    ...(body.name !== undefined &&
      body.name.length > 0 && {
        name: {
          contains: body.name,
          mode: "insensitive" as const,
        },
      }),
    ...(body.depth !== undefined && {
      depth: body.depth,
    }),
  };

  // Perform DB queries for paginated results and total count
  const [rows, count] = await Promise.all([
    MyGlobal.prisma.aimall_backend_categories.findMany({
      where,
      orderBy: { id: "asc" },
      skip: offset,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_categories.count({ where }),
  ]);

  const data: IAimallBackendCategory[] = rows.map((row) => ({
    id: row.id,
    parent_id: row.parent_id ?? null,
    name: row.name,
    depth: row.depth,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: count,
      pages: Math.ceil(count / limit),
    },
    data,
  };
}

