import { IAIMallBackendExternalAccount } from "@ORGANIZATION/PROJECT-api/lib/structures/IAIMallBackendExternalAccount";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Link a new external (federated) account for the target customer.
 *
 * Used by sign-in, social login onboarding, or account linking settings.
 * Requires upstream validation that the external account is not already linked
 * elsewhere and that proper OAuth token verification has occurred. On success,
 * creates a new external account record with provider info, external user ID,
 * and linkage time. Only the authenticated customer may perform this action.
 * Returns the newly created external account entity on success.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer (CustomerPayload)
 * @param props.customerId - ID of the customer to link with (must match
 *   authenticated customer)
 * @param props.body - External account provider and external user info
 * @returns The newly created external account record
 * @throws {Error} When attempting to link for a different customerId (not self)
 * @throws {Error} When provider + external_user_id are already linked elsewhere
 *   (uniqueness conflict)
 */
export async function post__aimall_backend_customer_customers_$customerId_externalAccounts(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAIMallBackendExternalAccount.ICreate;
}): Promise<IAIMallBackendExternalAccount> {
  const { customer, customerId, body } = props;

  // Authorization: Only allow linking for self
  if (customer.id !== customerId) {
    throw new Error(
      "Unauthorized: You can only link external accounts with your own customer account.",
    );
  }

  // Uniqueness: provider + external_user_id must not be used
  const exists =
    await MyGlobal.prisma.aimall_backend_external_accounts.findFirst({
      where: {
        provider: body.provider,
        external_user_id: body.external_user_id,
      },
    });
  if (exists) {
    throw new Error(
      "Conflict: This external account is already linked to another user.",
    );
  }

  // Create the external account record
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.aimall_backend_external_accounts.create(
    {
      data: {
        id: v4() as string & tags.Format<"uuid">,
        customer_id: customerId,
        provider: body.provider,
        external_user_id: body.external_user_id,
        linked_at: now,
      },
    },
  );

  return {
    id: created.id,
    customer_id: created.customer_id,
    provider: created.provider,
    external_user_id: created.external_user_id,
    linked_at: toISOStringSafe(created.linked_at),
  };
}

