/**
 * Retrieve all comments linked to a specific product review
 * (aimall_backend_comments).
 *
 * Fetches all comments attached to the specified reviewId, including public,
 * private, and soft-deleted records, as per administrator/audit view
 * requirements. This includes all matching records without filtering by
 * visibility or deletion status.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 *   (authorization enforced at controller level)
 * @param props.reviewId - Unique identifier (UUID) of the parent product review
 *   whose comments should be listed
 * @returns List of all comments linked to the selected review, in ISummary
 *   format; pagination is omitted
 * @throws {Error} If the review does not exist (404)
 */
export async function get__aimall_backend_administrator_reviews_$reviewId_comments(props: {
  administrator: AdministratorPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendComment.ISummary> {
