}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * 특정 부모 분류 아래에 있는 자식 분류의 정보를 수정합니다.
 *
 * 이 엔드포인트는 판매자 역할의 인증된 사용자가 주어진 부모-자식 관계 내에서 지정된 자식 카테고리의 이름이나 깊이 값을 수정할 수 있도록
 * 합니다. (parent_id는 이 API로 변경이 불가) 입력한 parent_id와 실제 자식 카테고리의 parent_id가 일치하는지
 * 반드시 검증하며, 이름을 수정할 때는 동일 부모 아래에서 이름 중복이 발생하지 않는지 확인합니다. 수정에 성공하면 최신 상태가 반영된
 * 카테고리 객체를 반환합니다.
 *
 * @param props - 요청 속성
 * @param props.seller - 인증된 판매자 페이로드 (권한 확인은 데코레이터에서 보장)
 * @param props.categoryId - 부모 카테고리의 UUID
 * @param props.childCategoryId - 수정 대상 자식 카테고리의 UUID
 * @param props.body - 수정할 자식 카테고리 정보(이름과 깊이, parent_id는 변경 불가)
 * @returns 수정이 적용된 카테고리 엔티티 객체
 * @throws {Error} 부모-자식 관계가 일치하지 않거나 카테고리가 존재하지 않는 경우
 * @throws {Error} 동일한 부모 내에 같은 이름의 분류가 이미 존재할 경우(이름 중복)
 */
export async function put__aimall_backend_seller_categories_$categoryId_childCategories_$childCategoryId(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
  childCategoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.IUpdate;
}): Promise<IAimallBackendCategory> {
  const { categoryId, childCategoryId, body } = props;

  // 1. parent-child 관계 확인 및 자식 카테고리 존재성 체크
  const childCategory =
    await MyGlobal.prisma.aimall_backend_categories.findFirst({
      where: {
        id: childCategoryId,
        parent_id: categoryId,
      },
    });
  if (!childCategory) {
    throw new Error(
      "해당 자식 카테고리가 부모와의 관계에 없거나 존재하지 않습니다.",
    );
  }

  // 2. 이름이 수정되는 경우 동일 부모 내 중복 검증
  if (body.name !== undefined) {
    const conflict = await MyGlobal.prisma.aimall_backend_categories.findFirst({
      where: {
        parent_id: categoryId,
        name: body.name,
        NOT: { id: childCategoryId },
      },
    });
    if (conflict) {
      throw new Error(
        "동일한 부모 카테고리 내에 같은 이름의 분류가 이미 존재합니다.",
      );
    }
  }

  // 3. parent_id는 변경 허용하지 않고, name/depth만 수정
  const updated = await MyGlobal.prisma.aimall_backend_categories.update({
    where: { id: childCategoryId },
    data: {
      name: body.name ?? undefined,
      depth: body.depth ?? undefined,
    },
  });

  // 4. 결과 반환 (스키마 그대로)
  return {
    id: updated.id,
    parent_id: updated.parent_id,
    name: updated.name,
    depth: updated.depth,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPermission";
import { IPageIAimallBackendPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendPermission";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * RBAC 권한 목록을 필터 및 페이징하여 검색합니다.
 *
 * 본 엔드포인트는 관리자 인증(활성 상태)된 사용자가 RBAC 권한(permissions/roles) 정의 목록을 다양한 조건으로
 * 검색·필터링하고, 페이징된 결과를 제공합니다. 일반적으로 권한/역할 검색/생성/할당 UX 구현에 사용되며, 키워드(코드명/표시이름),
 * 생성일 범위, 페이징(page, limit) 조건을 지원합니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.administrator - 인증된 관리자 페이로드 (활성 상태 필수)
 * @param props.body - 권한 목록 필터 및 페이징 파라미터 (이름, display_name, 생성일 등)
 * @returns RBAC 권한 요약 리스트 (IPageIAimallBackendPermission.ISummary)
 * @throws {Error} 인증되지 않았거나 권한 없는 경우(비활성 관리자 등)
 */
export async function patch__aimall_backend_administrator_permissions(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendPermission.IRequest;
}): Promise<IPageIAimallBackendPermission.ISummary> {
  const { administrator, body } = props;
  if (administrator.status !== "active") {
    throw new Error("권한이 없는 관리자이거나 비활성 계정입니다.");
  }

  const page: number = body.page ?? 1;
  const limit: number = body.limit ?? 20;

  const where = {
    ...(body.name && {
      name: { contains: body.name, mode: "insensitive" as const },
    }),
    ...(body.display_name && {
      display_name: {
        contains: body.display_name,
        mode: "insensitive" as const,
      },
    }),
    ...(body.created_at_from || body.created_at_to
      ? {
          created_at: {
            ...(body.created_at_from && { gte: body.created_at_from }),
            ...(body.created_at_to && { lte: body.created_at_to }),
          },
        }
      : {}),
  };

  const [records, data] = await Promise.all([
    MyGlobal.prisma.aimall_backend_permissions.count({ where }),
    MyGlobal.prisma.aimall_backend_permissions.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

  const pages = records === 0 ? 0 : Math.ceil(records / limit);

  return {
    pagination: {
      current: page,
      limit,
      records,
      pages,
    },
    data: data.map((x) => ({
      id: x.id,
      name: x.name,
      display_name: x.display_name,
      description: x.description,
      created_at: toISOStringSafe(x.created_at),
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProductOption";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update a product option for a specific product
 * (aimall_backend_product_options).
 *
 * Allows administrators to update the name and/or value of a product option,
 * verifying data integrity and preventing duplicates. Ensures the product and
 * option both exist and validates proper association. Enforces unique
 * (product_id, name, value) constraint per product variant.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   operation
 * @param props.productId - UUID of the parent product which owns the option
 * @param props.productOptionId - UUID of the product option being updated
 * @param props.body - Update DTO for name and/or value mutation
 * @returns The updated product option entity
 * @throws {Error} When the product or product option does not exist, the option
 *   does not belong to the product, no updatable fields are provided, or if the
 *   new name/value would cause a duplicate variant
 */
export async function put__aimall_backend_administrator_products_$productId_productOptions_$productOptionId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  productOptionId: string & tags.Format<"uuid">;
  body: IAimallBackendProductOption.IUpdate;
}): Promise<IAimallBackendProductOption> {
  const { administrator, productId, productOptionId, body } = props;

  // 1. Product existence check
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) throw new Error("Product not found");

  // 2. Option existence and ownership check
  const option =
    await MyGlobal.prisma.aimall_backend_product_options.findUnique({
      where: { id: productOptionId },
    });
  if (!option) throw new Error("Product option not found");
  if (option.product_id !== productId)
    throw new Error("Option does not belong to the specified product");

  // 3. Validation: at least one updatable field provided
  if (body.name === undefined && body.value === undefined)
    throw new Error("No updatable fields were provided");

  // 4. Unique constraint check: prevent duplicates
  const newName = body.name ?? option.name;
  const newValue = body.value ?? option.value;
  const duplicate =
    await MyGlobal.prisma.aimall_backend_product_options.findFirst({
      where: {
        product_id: productId,
        name: newName,
        value: newValue,
        NOT: { id: productOptionId },
      },
    });
  if (duplicate)
    throw new Error(
      "A variant with this name and value already exists for this product",
    );

  // 5. Perform update (inline object for type clarity)
  const updated = await MyGlobal.prisma.aimall_backend_product_options.update({
    where: { id: productOptionId },
    data: {
      name: body.name ?? undefined,
      value: body.value ?? undefined,
    },
  });

  // 6. Return updated entity as IAimallBackendProductOption (all string fields)
  return {
    id: updated.id,
    product_id: updated.product_id,
    name: updated.name,
    value: updated.value,
  };
}

