 * permission roles, email, name, or creation/updated date ranges.
 *
 * This endpoint supports compliance scenarios where platform operators must
 * audit administrator roles by various segments, investigate configuration
 * changes, or analyze admin account behaviors. Pagination and ordering are
 * supported to ensure efficient UX with large datasets.
 *
 * Accessible to administrator users with role/permission sufficient under the
 * RBAC system (see aimall_backend_permissions). Response structure is optimized
 * for admin dashboard integration. Search operations may be logged to ensure
 * auditability and monitor for inappropriate data access patterns.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user making the
 *   request
 * @param props.body - Flexible search criteria and pagination params for
 *   administrator list filtering
 * @returns Paginated and filtered result set of administrator data matching
 *   criteria
 * @throws {Error} When the administrator is not active or unauthorized
 */
export async function patch__aimall_backend_administrator_administrators(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAdministrator.IRequest;
}): Promise<IPageIAimallBackendAdministrator.ISummary> {
  const { administrator, body } = props;

  // Authorization: only active admins
  if (administrator.status !== "active") {
    throw new Error("Unauthorized: Only active administrators allowed");
  }

  // Pagination calculations and defaults
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // Build where clause using only available filters
  const where = {
    ...(body.permission_id && { permission_id: body.permission_id }),
    ...(body.email && {
      email: { contains: body.email, mode: "insensitive" as const },
    }),
    ...(body.status && { status: body.status }),
    ...(body.name && {
      name: { contains: body.name, mode: "insensitive" as const },
    }),
    ...(body.created_at_gte || body.created_at_lte
      ? {
          created_at: {
            ...(body.created_at_gte && { gte: body.created_at_gte }),
            ...(body.created_at_lte && { lte: body.created_at_lte }),
          },
        }
      : {}),
  };

  const [admins, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_administrators.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_administrators.count({ where }),
  ]);

  // Result mapping: strictly conform to ISummary type
  const data = admins.map((a) => ({
    id: a.id,
    email: a.email,
    name: a.name,
    permission_id: a.permission_id,
    status: a.status,
    created_at: toISOStringSafe(a.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

