/**
 * Update details of an order item (Order Items table).
 *
 * Edits the details of a specific order item, as referenced by both parent
 * order and item UUIDs. Only attributes present in the corresponding schema
 * (product, option, quantity, name, prices) may be modified. The mutation is
 * disallowed for finalized/archived orders. Permissions are checked for the
 * seller of record, administrators, or customers where policies permit.
 *
 * All updates are logged for audit/compliance. Endpoint strictly validates the
 * linkage between provided orderId and orderItemId, and returns errors if these
 * do not match or are not found.
 *
 * @param props - Request parameters:
 *
 *   - Props.administrator: Authenticated administrator making this request.
 *   - Props.orderId: UUID of the parent order containing the item to be updated.
 *   - Props.orderItemId: UUID of the order item to update.
 *   - Props.body: Fields (from IAimallBackendOrderItem.IUpdate) to update on the
 *       referenced order item.
 *
 * @returns The updated order item as per current record.
 * @throws {Error} When the order item does not exist, does not belong to the
 *   specified order, or the order is archived/finalized.
 */
export async function put__aimall_backend_administrator_orders_$orderId_orderItems_$orderItemId(props: {
  administrator: AdministratorPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.IUpdate;
}): Promise<IAimallBackendOrderItem> {
  const { orderId, orderItemId, body } = props;

  // 1. Fetch and verify the order item by ID and its parent order linkage
  const orderItem = await MyGlobal.prisma.aimall_backend_order_items.findUnique(
    {
      where: { id: orderItemId },
    },
  );
  if (!orderItem || orderItem.order_id !== orderId) {
    throw new Error(
      "Order item not found or does not belong to the specified order.",
    );
  }

  // 2. Fetch the parent order and make sure it's not archived/finalized
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order || order.archived_at !== null) {
    throw new Error("Order is archived/finalized and cannot be modified.");
  }

  // 3. Update only permitted fields from IAimallBackendOrderItem.IUpdate
  const updated = await MyGlobal.prisma.aimall_backend_order_items.update({
    where: { id: orderItemId },
    data: {
      item_name: body.item_name ?? undefined,
      quantity: body.quantity ?? undefined,
      unit_price: body.unit_price ?? undefined,
      total_price: body.total_price ?? undefined,
      product_option_id: body.product_option_id ?? undefined,
    },
  });

  // 4. Return the updated order item directly
  return updated;
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendProductOption";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Update a product option for a specific product
 * (aimall_backend_product_options).
 *
 * Update an existing product option record by composite reference to productId
 * and productOptionId. Allows sellers or administrators to update atomic option
 * fields (name or value) for variants associated with their own products.
 *
 * Access is permission-restricted; integrity/audit checks ensure the option
 * belongs to the product and that new values do not violate data consistency
 * (no duplicate variants, all references are valid). On update, the endpoint
 * returns the fully updated aimall_backend_product_options entity. Improper
 * updates—such as attempting to reassign an option to another product, or
 * creating duplicate name/value pairs—are denied with specific error feedback.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller payload (must own the product)
 * @param props.productId - UUID of the parent product which owns the product
 *   option
 * @param props.productOptionId - UUID of the product option being updated
 * @param props.body - Update DTO for the product option record, containing name
 *   and/or value to update
 * @returns The updated product option entity as stored in the system
 * @throws {Error} If the product option does not exist
 * @throws {Error} If the product option does not belong to the specified
 *   product
 * @throws {Error} If the seller does not own the product
 * @throws {Error} If updating would create a duplicate (name, value) option for
 *   the product
 */
export async function put__aimall_backend_seller_products_$productId_productOptions_$productOptionId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  productOptionId: string & tags.Format<"uuid">;
  body: IAimallBackendProductOption.IUpdate;
}): Promise<IAimallBackendProductOption> {
  const { seller, productId, productOptionId, body } = props;

  // 1. Fetch the option
  const option =
    await MyGlobal.prisma.aimall_backend_product_options.findUnique({
      where: { id: productOptionId },
    });
  if (!option) throw new Error("Product option not found");

  // 2. Make sure the option belongs to the provided productId
  if (option.product_id !== productId)
    throw new Error("Product option does not belong to the specified product");

  // 3. Check ownership: fetch product, verify seller
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id)
    throw new Error("Unauthorized: You do not own this product");

  // 4. If name or value changes: check uniqueness for (product_id, name, value)
  const newName = body.name ?? option.name;
  const newValue = body.value ?? option.value;
  if (newName !== option.name || newValue !== option.value) {
    const exists =
      await MyGlobal.prisma.aimall_backend_product_options.findFirst({
        where: {
          product_id: productId,
          name: newName,
          value: newValue,
          NOT: { id: productOptionId },
        },
      });
    if (exists)
      throw new Error("Duplicate option (name, value) for this product");
  }

  // 5. Perform update
  const updated = await MyGlobal.prisma.aimall_backend_product_options.update({
    where: { id: productOptionId },
    data: {
      name: body.name ?? undefined,
      value: body.value ?? undefined,
    },
  });
  return {
    id: updated.id,
    product_id: updated.product_id,
    name: updated.name,
    value: updated.value,
  };
}

