import { IAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendConfiguration";
import { IPageIAimallBackendConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendConfiguration";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Performs a filtered and paginated search of system configurations
 * (aimall_backend_configurations).
 *
 * This endpoint allows administrators and DevOps to precisely search
 * configuration records (e.g., feature flags, keys, channel- or
 * section-specific settings). Supports advanced filters (key, channel_id,
 * section_id, value substring) as well as pagination and flexible sorting.
 *
 * Requires administrator authentication; only enabled for users with active
 * admin status.
 *
 * @param props - Request specification
 * @param props.administrator - The authenticated administrator payload
 * @param props.body - Search and pagination criteria following
 *   IAimallBackendConfiguration.IRequest schema
 * @returns A paginated list of configuration summaries matching the filter and
 *   pagination criteria
 * @throws {Error} If the administrator is not active or unauthorized
 */
export async function patch__aimall_backend_administrator_configurations(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendConfiguration.IRequest;
}): Promise<IPageIAimallBackendConfiguration.ISummary> {
  const { administrator, body } = props;

  // Authorization enforcement: Only active administrators may search
  if (administrator.status !== "active") throw new Error("Forbidden");

  // Pagination setup with safe defaults
  const page = body.page ?? 1;
  const limit = body.limit ?? 100;
  const skip = (page - 1) * limit;

  // Build dynamic filtering conditions
  const where = {
    ...(body.key !== undefined &&
      body.key !== null && {
        key: { contains: body.key, mode: "insensitive" as const },
      }),
    ...(body.channel_id !== undefined &&
      body.channel_id !== null && {
        channel_id: body.channel_id,
      }),
    ...(body.section_id !== undefined &&
      body.section_id !== null && {
        section_id: body.section_id,
      }),
    ...(body.value_contains !== undefined &&
      body.value_contains !== null && {
        value: { contains: body.value_contains, mode: "insensitive" as const },
      }),
  };

  // Validate/limit sortable fields
  const allowedSortBy = ["key", "created_at", "updated_at"] as const;
  const allowedSortOrder = ["asc", "desc"] as const;
  const sortBy: "key" | "created_at" | "updated_at" =
    body.sort_by && allowedSortBy.includes(body.sort_by)
      ? body.sort_by
      : "created_at";
  const sortOrder: "asc" | "desc" =
    body.sort_order && allowedSortOrder.includes(body.sort_order)
      ? body.sort_order
      : "desc";

  // Fetch result set and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_configurations.findMany({
      where,
      orderBy: { [sortBy]: sortOrder },
      skip,
      take: limit,
      select: {
        id: true,
        key: true,
        value: true,
        channel_id: true,
        section_id: true,
      },
    }),
    MyGlobal.prisma.aimall_backend_configurations.count({ where }),
  ]);

  // Compose paginated result per API contract
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      key: row.key,
      value: row.value,
      channel_id: row.channel_id ?? null,
      section_id: row.section_id ?? null,
    })),
  };
}

