 */
export async function patch__aimall_backend_administrator_snapshots(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendSnapshot.IRequest;
}): Promise<IPageIAimallBackendSnapshot> {
  const { body } = props;

  // Set pagination params with defaults
  const limit = body.limit ?? 20;
  const page = body.page ?? 1;
  if (limit <= 0 || page <= 0)
    throw new Error("Pagination parameters must be positive integers");

  // Build where clause for Prisma, only including present/non-null filters
  const where = {
    ...(body.post_id !== undefined &&
      body.post_id !== null && { post_id: body.post_id }),
    ...(body.product_id !== undefined &&
      body.product_id !== null && { product_id: body.product_id }),
