  const [total, rows] = await Promise.all([
    MyGlobal.prisma.aimall_backend_snapshots.count({ where }),
    MyGlobal.prisma.aimall_backend_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

