/**
 * Update an existing snapshot (photo/media) on a post
 * (aimall_backend_snapshots).
 *
 * Updates an existing snapshot entity attached to a target community post. Only
 * editable fields (caption, media_uri) can be updated.
 *
 * Requires both postId and snapshotId to ensure correct context and linkage.
 * Permission: Only the owner seller of the post may edit. If post or snapshot
 * does not exist, or if the snapshot is not linked to the post, or the seller
 * does not own the post (see schema note), an error is thrown.
 *
 * @param props - Parameters for snapshot update
 * @param props.seller - Authenticated SellerPayload (authorization required)
 * @param props.postId - UUID of the post to which the snapshot is attached
 * @param props.snapshotId - UUID of the snapshot to update
 * @param props.body - Fields to update (caption and/or media_uri)
 * @returns The updated IAimallBackendSnapshot object
 * @throws {Error} If the post or snapshot does not exist, or unauthorized
 *   update attempted
 */
export async function put__aimall_backend_seller_posts_$postId_snapshots_$snapshotId(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IUpdate;
}): Promise<IAimallBackendSnapshot> {
  const { seller, postId, snapshotId, body } = props;

  // 1. Find the post (required for context/auth)
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
  });
  if (!post) throw new Error("Post not found");

  // 2. Find the snapshot, ensure it's attached to the post
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot || snapshot.post_id !== postId)
    throw new Error("Snapshot not found for this post");

  // 3. Enforce ownership: given current schema, post.customer_id references customers, not sellers.
  //    Unless there is app-level logic mapping posts to sellers, we cannot check seller->post ownership in DB safely.
  //    By spec, we must only allow update if post.customer_id is null (i.e. platform context/admin post).
  //    SELLERS CANNOT update a snapshot for a post unless this linkage is explicit in schema.
  if (post.customer_id !== null) {
    throw new Error("Forbidden: Seller does not own this post");
  }

  // 4. Update: Only allowed fields per IAimallBackendSnapshot.IUpdate
  const updated = await MyGlobal.prisma.aimall_backend_snapshots.update({
    where: { id: snapshotId },
    data: {
      caption: body.caption ?? undefined,
      media_uri: body.media_uri ?? undefined,
    },
  });

  // 5. Return with correct types, converting date to ISO string
  return {
    id: updated.id,
    product_id: updated.product_id ?? undefined,
    post_id: updated.post_id ?? undefined,
    customer_id: updated.customer_id ?? undefined,
    media_uri: updated.media_uri,
    caption: updated.caption ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
  };
}

