/**
 * Delete or archive a snapshot record linked to a review, using reviewId and
 * snapshotId for record identification.
 *
 * Performs hard delete from aimall_backend_snapshots because there is no
 * soft-delete (deleted_at) column in this model. Only the owner of the snapshot
 * (customer) may perform this action. Checks permission and linkage before
 * deletion. Returns 404 if snapshot does not exist or does not belong to the
 * given review. Throws 403 if the customer is not the owner.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer requesting the deletion
 * @param props.reviewId - UUID of the review to which the snapshot must be
 *   attached
 * @param props.snapshotId - UUID of the snapshot to delete
 * @returns Void on successful deletion
 * @throws {Error} 404 when the snapshot does not exist or is not linked to
 *   specified review
 * @throws {Error} 403 when the customer is not the owner of the snapshot
 */
export async function delete__aimall_backend_customer_reviews_$reviewId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, reviewId, snapshotId } = props;
  // 1. Fetch the snapshot; throw if not found
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot) throw new Error("Snapshot not found");
  // 2. Check that snapshot is linked to the correct review
  if (snapshot.review_id !== reviewId) {
    throw new Error("Snapshot does not belong to the specified review");
  }
  // 3. Check that customer owns the snapshot
  if (snapshot.customer_id !== customer.id) {
    throw new Error("Unauthorized: Only the owner can delete this snapshot");
  }
  // 4. Hard delete; forbidden to use Date type (no soft delete available)
  await MyGlobal.prisma.aimall_backend_snapshots.delete({
    where: { id: snapshotId },
  });
}

