/**
 * 장바구니 목록을 검색 및 필터링/페이징 반환 (관리자용)
 *
 * 쇼핑몰 장바구니를 다양한 조건(회원ID, 세션토큰, 생성/수정일 범위 등)으로 검색/페이징하여 반환합니다. 관리자만 모든 장바구니 전체에
 * 대해 검색 가능하며, 응답에는 요약 정보와 페이징 메타데이터가 포함됩니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.administrator - 인증된 관리자 페이로드 (관리자 인증 필수)
 * @param props.body - 검색/필터/페이징조건 등 요청 데이터 (IAimallBackendCart.IRequest 참고)
 * @returns 페이징된 장바구니 요약 리스트 및 메타데이터 (IPageIAimallBackendCart)
 * @throws {Error} 관리자 인증이 누락되거나 비활성화 상태일 경우, 유효하지 않은 페이지/리밋 파라미터 등 잘못된 요청시
 */
export async function patch__aimall_backend_administrator_carts(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendCart.IRequest;
}): Promise<IPageIAimallBackendCart> {
  const { administrator, body } = props;
  // 관리자 인증 및 활성 상태 체크 (방어적)
  if (!administrator || administrator.status !== "active") {
    throw new Error("관리자 권한이 없습니다.");
  }

  // WHERE 조건 빌드: 제공된 모든 필터 적용
  const where = {
    ...(body.aimall_backend_customer_id !== undefined &&
      body.aimall_backend_customer_id !== null && {
        aimall_backend_customer_id: body.aimall_backend_customer_id,
      }),
    ...(body.session_token !== undefined &&
      body.session_token !== null && {
        session_token: body.session_token,
      }),
    ...(body.created_from || body.created_to
      ? {
          created_at: {
            ...(body.created_from ? { gte: body.created_from } : {}),
            ...(body.created_to ? { lte: body.created_to } : {}),
          },
        }
      : {}),
    ...(body.updated_from || body.updated_to
      ? {
          updated_at: {
            ...(body.updated_from ? { gte: body.updated_from } : {}),
            ...(body.updated_to ? { lte: body.updated_to } : {}),
          },
        }
      : {}),
  };

  // 페이지네이션 계산
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit =
    body.limit && body.limit > 0 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // 장바구니 목록 및 총 카운트 병렬 조회
  const [carts, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_carts.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_carts.count({ where }),
  ]);

  // 각 장바구니별 아이템 카운트 집계
  const cartIds = carts.map((cart) => cart.id);
  const itemsPerCart =
    cartIds.length === 0
      ? []
      : await MyGlobal.prisma.aimall_backend_cart_items.groupBy({
          by: ["aimall_backend_cart_id"],
          where: { aimall_backend_cart_id: { in: cartIds } },
          _count: { id: true },
        });
  const itemsCountMap: Record<string, number> = Object.fromEntries(
    itemsPerCart.map((x) => [x.aimall_backend_cart_id, x._count.id]),
  );

  // 응답 데이터 생성
  const data = carts.map((cart) => ({
    id: cart.id,
    aimall_backend_customer_id: cart.aimall_backend_customer_id ?? undefined,
    session_token: cart.session_token ?? undefined,
    created_at: toISOStringSafe(cart.created_at),
    updated_at: toISOStringSafe(cart.updated_at),
    cart_items_count: itemsCountMap[cart.id] ?? 0,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

