/**
 * Update external account linkage for a customer (Actors DB).
 *
 * Updates an existing external account record for a customer, ensuring only
 * privileged admins may perform the operation. Checks for record existence,
 * uniqueness of the provider/external_user_id combination, and applies update.
 * All update attempts are auditable events (audit implementation not shown
 * here).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated AdministratorPayload
 * @param props.customerId - UUID of the customer
 * @param props.externalAccountId - UUID of the external account linkage to
 *   update
 * @param props.body - Fields for updating the external account
 *   (provider/external_user_id)
 * @returns Updated IAIMallBackendExternalAccount record
 * @throws {Error} If the target account doesn't exist, is owned by a different
 *   customer, or provider/external_user_id is already linked elsewhere
 */
export async function put__aimall_backend_administrator_customers_$customerId_externalAccounts_$externalAccountId(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  externalAccountId: string & tags.Format<"uuid">;
  body: IAIMallBackendExternalAccount.IUpdate;
}): Promise<IAIMallBackendExternalAccount> {
  const { administrator, customerId, externalAccountId, body } = props;
  // Fetch and verify external account linkage exists and belongs to customer
  const record =
    await MyGlobal.prisma.aimall_backend_external_accounts.findUnique({
      where: { id: externalAccountId },
    });
  if (!record || record.customer_id !== customerId) {
    throw new Error("External account linkage not found for this customer.");
  }
  // Enforce uniqueness: no other external account may have this provider/external_user_id
  const conflict =
    await MyGlobal.prisma.aimall_backend_external_accounts.findFirst({
      where: {
        provider: body.provider,
        external_user_id: body.external_user_id,
        id: { not: externalAccountId },
      },
    });
  if (conflict) {
    throw new Error(
      "Another account with this provider and external_user_id exists.",
    );
  }
  // Update record (refresh linked_at)
  const updated = await MyGlobal.prisma.aimall_backend_external_accounts.update(
    {
      where: { id: externalAccountId },
      data: {
        provider: body.provider,
        external_user_id: body.external_user_id,
        linked_at: toISOStringSafe(new Date()),
      },
    },
  );
  // Map to DTO (dates properly formatted)
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    provider: updated.provider,
    external_user_id: updated.external_user_id,
    linked_at: toISOStringSafe(updated.linked_at),
  };
}

