import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPayment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create a payment transaction associated with the specified order in
 * aimall_backend_payments.
 *
 * Creates a new payment transaction for a specific order, ensuring the seller
 * is authorized for the order. Performs business validation that the sum of all
 * payment amounts matches the order's expected total.
 *
 * @param props - Function parameters
 * @param props.seller - The authenticated seller's payload (SellerPayload)
 * @param props.orderId - Unique identifier of the target order
 * @param props.body - Payment creation data (IAimallBackendPayment.ICreate)
 * @returns The successfully created payment object for the order.
 * @throws {Error} When the order does not exist
 * @throws {Error} When the seller is not authorized for this order
 * @throws {Error} When the sum of order payments does not match the order's
 *   total amount
 */
export async function post__aimall_backend_seller_orders_$orderId_payments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendPayment.ICreate;
}): Promise<IAimallBackendPayment> {
  const { seller, orderId, body } = props;
  // 1. Fetch and validate the target order, restrict to seller
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { id: true, seller_id: true, total_amount: true },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id) {
    throw new Error("Unauthorized: Seller does not own this order");
  }

  // 2. Resolve paid_at: use client value if present, else generate server timestamp
  const paidAt: string & tags.Format<"date-time"> =
    body.paid_at && typeof body.paid_at === "string"
      ? toISOStringSafe(body.paid_at)
      : toISOStringSafe(new Date());

  // 3. Create payment row
  const created = await MyGlobal.prisma.aimall_backend_payments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      order_id: orderId,
      payment_method: body.payment_method,
      amount: body.amount,
      currency: body.currency,
      transaction_id: body.transaction_id ?? null,
      paid_at: paidAt,
    },
  });

  // 4. Validate total order payments
  const aggResult = await MyGlobal.prisma.aimall_backend_payments.aggregate({
    _sum: { amount: true },
    where: { order_id: orderId },
  });
  const paymentSum =
    typeof aggResult._sum?.amount === "number" ? aggResult._sum.amount : null;
  if (paymentSum === null) {
    throw new Error("Aggregation failed for payments sum");
  }
  if (Math.abs(paymentSum - order.total_amount) > 1e-6) {
    throw new Error("Payment total does not match order expected total");
  }

  // 5. Build and return DTO-compliant payment response
  return {
    id: created.id,
    order_id: created.order_id,
    payment_method: created.payment_method,
    amount: created.amount,
    currency: created.currency,
    transaction_id: created.transaction_id ?? null,
    paid_at: toISOStringSafe(created.paid_at),
  };
}

