 *
 * 본 엔드포인트는 행동 이벤트(로그인, 장바구니 담기 등)의 상세 이력을 event_type, 기간 등으로 필터링하여 해당 고객의 활동
 * 기록을 반환합니다. 본인만 접근 허용하며, 모든 요청은 감사 기록으로 남습니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 payload (JWT)
 * @param props.customerId - 검색 대상 고객 UUID (본인과 일치해야 함)
 * @param props.body - 이벤트 유형/기간/페이지네이션 등 검색 조건
 * @returns 페이징 메타 및 필터링된 행동 이력 리스트
 * @throws {Error} 인증 실패 시 (본인 아님)
 */
export async function patch__aimall_backend_customer_customers_$customerId_behaviorTrackings(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAIMallBackendBehaviorTracking.IRequest;
}): Promise<IPageIAIMallBackendBehaviorTracking> {
  const { customer, customerId, body } = props;
  // 인증: 본인만 조회 가능
  if (customer.id !== customerId)
    throw new Error("Unauthorized: 자신만 행동 이력에 접근 가능합니다.");

  // 페이지네이션 기본값 처리
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 조건부 WHERE 절 구성: event_type, occurred_at(range), 고객 UUID
  const where = {
    customer_id: customerId,
    ...(body.event_type !== undefined &&
      body.event_type !== null && {
        event_type: body.event_type,
      }),
    ...(body.date_from !== undefined &&
    body.date_from !== null &&
    body.date_to !== undefined &&
    body.date_to !== null
      ? { occurred_at: { gte: body.date_from, lte: body.date_to } }
      : body.date_from !== undefined && body.date_from !== null
        ? { occurred_at: { gte: body.date_from } }
        : body.date_to !== undefined && body.date_to !== null
          ? { occurred_at: { lte: body.date_to } }
          : {}),
  };

  // 동시 쿼리: 데이터 + 전체 카운트
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_behavior_trackings.findMany({
      where,
      orderBy: { occurred_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_behavior_trackings.count({ where }),
  ]);

  // 결과 매핑 (브랜딩 및 날짜 변환)
  const data: IAIMallBackendBehaviorTracking[] = rows.map((row) => ({
    id: row.id,
    customer_id: row.customer_id,
    event_type: row.event_type,
    event_data: row.event_data,
    occurred_at: toISOStringSafe(row.occurred_at),
  }));

  // 총 페이지 계산 (최소 1페이지)
  const pages = Math.max(1, Math.ceil(total / limit));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

