/**
 * Updates a comment under a post by commentId (Community, Comments).
 *
 * This function allows a customer to update their own comment in a community
 * post, ensuring:
 *
 * - The comment exists, belongs to the specified post, and is not soft-deleted;
 * - The updating user is the comment's author (authorization);
 * - Only permitted fields are updated (body, is_private, deleted_at);
 * - All audit date fields are converted to strict ISO 8601 string format.
 *
 * @param props - Request properties.
 * @param props.customer - The authenticated customer (owner) performing the
 *   update.
 * @param props.postId - The UUID of the post holding the target comment.
 * @param props.commentId - The UUID of the comment being updated.
 * @param props.body - The update payload (fields: body, is_private, deleted_at)
 *   to apply.
 * @returns The updated IAimallBackendComment, reflecting all changes.
 * @throws {Error} If the comment does not exist (for this post) or has been
 *   deleted.
 * @throws {Error} If the customer is not the owner (forbidden).
 */
export async function put__aimall_backend_customer_posts_$postId_comments_$commentId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IUpdate;
}): Promise<IAimallBackendComment> {
  const { customer, postId, commentId, body } = props;

  // Fetch comment for this post (not soft-deleted)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findFirst({
    where: {
      id: commentId,
      post_id: postId,
      deleted_at: null,
    },
  });
  if (!comment) throw new Error("Comment not found for post");

  // Authorize owner (customer)
  if (!comment.customer_id || comment.customer_id !== customer.id) {
    throw new Error("You are not authorized to update this comment");
  }

  // Always update updated_at to now (ISO string)
  const now = toISOStringSafe(new Date());

  // Update comment only for fields present in body
  const updated = await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: commentId },
    data: {
      body: body.body ?? undefined,
      is_private: body.is_private ?? undefined,
      deleted_at: body.deleted_at ?? undefined,
      updated_at: now,
    },
  });

  // Return strict IAimallBackendComment (all date fields ISO, nullable correct)
  return {
    id: updated.id,
    post_id: updated.post_id ?? null,
    review_id: updated.review_id ?? null,
    parent_id: updated.parent_id ?? null,
    customer_id: updated.customer_id ?? null,
    body: updated.body,
    is_private: updated.is_private,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

