    throw new Error("Product not found");
  }
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: not owner of product related to this review");
  }

  // 4. Hard delete the attachment
  await MyGlobal.prisma.aimall_backend_attachments.delete({
    where: { id: attachmentId },
  });
}

