import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Retrieve all comments linked to a specific product review
 * (seller-restricted).
 *
 * Fetches all comments attached to the specified product review
 * (aimall_backend_comments) in the community system. Only the seller who owns
 * the product for that review can access all comments (including public and
 * private). Authorization is strictly enforced.
 *
 * @param props - Request context and parameters
 * @param props.seller - The authenticated seller's payload. Only sellers are
 *   permitted.
 * @param props.reviewId - The UUID of the product review whose comments are to
 *   be fetched.
 * @returns List of all comments for this review, each as a summary object
 *   (ISummary[]), without pagination.
 * @throws {Error} If the review does not exist
 * @throws {Error} If the seller does not own the review's product
 */
export async function get__aimall_backend_seller_reviews_$reviewId_comments(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendComment.ISummary> {
  const { seller, reviewId } = props;

  // 1. Fetch the review and its product_id
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { product_id: true },
  });
  if (!review) throw new Error("Review not found");

  // 2. Fetch the product and verify seller ownership
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: You can only view comments for reviews of your own products.",
    );
  }

  // 3. Fetch all comments linked to this review (soft-deleted filtered)
  const comments = await MyGlobal.prisma.aimall_backend_comments.findMany({
    where: {
      review_id: reviewId,
      deleted_at: null,
    },
    orderBy: { created_at: "desc" },
    select: {
      id: true,
      body: true,
      customer_id: true,
      created_at: true,
      is_private: true,
    },
  });

  // 4. Map raw comments to ISummary (date conversion, strong typing)
  const data = comments.map((c) => ({
    id: c.id,
    body: c.body,
    customer_id: c.customer_id ?? undefined,
    created_at: toISOStringSafe(c.created_at),
    is_private: c.is_private,
  }));

  return {
    pagination: undefined,
    data,
  };
}

