/**
 * Retrieves a list of all payment transactions made for a specific order.
 *
 * Returns all payment events (credit card, coupon, points, etc) for the
 * specified order from aimall_backend_payments. Only the seller who owns the
 * order is authorized to access this endpoint. This enables robust audit and
 * reconciliation support for seller account managers.
 *
 * @param props - Request parameters
 * @param props.seller - Authenticated SellerPayload from SellerAuth
 * @param props.orderId - Target order UUID
 * @returns Object (IPageIAimallBackendPayment) containing an array of payment
 *   records
 * @throws {Error} When the order is not found or the user is not the involved
 *   seller
 */
export async function get__aimall_backend_seller_orders_$orderId_payments(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendPayment> {
  const { seller, orderId } = props;
  // 1. Authorization: seller must own the order
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { seller_id: true },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id)
    throw new Error("Unauthorized: You are not the seller for this order");
  // 2. Get all payments for the order
  const payments = await MyGlobal.prisma.aimall_backend_payments.findMany({
    where: { order_id: orderId },
    orderBy: { paid_at: "desc" },
  });
  // 3. Map payments to IAimallBackendPayment (convert all dates)
  const mapped = payments.map((payment) => ({
    id: payment.id,
    order_id: payment.order_id,
    payment_method: payment.payment_method,
    amount: payment.amount,
    currency: payment.currency,
    transaction_id: payment.transaction_id ?? null,
    paid_at: toISOStringSafe(payment.paid_at),
  }));
  // 4. Assemble page result (all at once)
  const total = mapped.length;
  return {
    pagination: {
      current: 1,
      limit: total,
      records: total,
      pages: 1,
    },
    data: mapped,
  };
}

