import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Update an existing snapshot attached to a product review.
 *
 * Updates fields (media_uri, caption) of a snapshot attached to the given
 * product review, but only if the authenticated customer is the owner of both
 * review and snapshot. Throws 404 if review or snapshot does not exist. Throws
 * 403 if the permission check fails.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the update
 * @param props.reviewId - The unique identifier of the product review
 * @param props.snapshotId - The unique identifier of the snapshot
 * @param props.body - Object with any updated fields (caption, media_uri)
 * @returns The full updated snapshot entity per IAimallBackendSnapshot
 * @throws {Error} When not found or permission denied
 */
export async function put__aimall_backend_customer_reviews_$reviewId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IUpdate;
}): Promise<IAimallBackendSnapshot> {
  const { customer, reviewId, snapshotId, body } = props;

  // 1. Find the snapshot by ID
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot) throw new Error("Snapshot not found");

  // 2. Find the review by ID
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) throw new Error("Review not found");

  // 3. Permission: Snapshot and review must both belong to customer
  if (
    snapshot.customer_id !== customer.id ||
    review.customer_id !== customer.id
  ) {
    throw new Error("Permission denied: Only the owner may update");
  }

  // 4. Update the allowed fields (caption, media_uri)
  const updated = await MyGlobal.prisma.aimall_backend_snapshots.update({
    where: { id: snapshotId },
    data: {
      caption: body.caption ?? undefined,
      media_uri: body.media_uri ?? undefined,
    },
  });

  // 5. Convert to API DTO and return
  return {
    id: updated.id,
    product_id: updated.product_id ?? undefined,
    post_id: updated.post_id ?? undefined,
    customer_id: updated.customer_id ?? undefined,
    media_uri: updated.media_uri,
    caption: updated.caption ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
  };
}

