 * of comments, supporting filtering by post, review, thread, author, privacy,
 * and date range. Returns a paginated result according to the
 * IAimallBackendComment and IPageIAimallBackendComment schema.
 *
 * This function is admin-restricted and returns both public and private (as
 * well as soft-deleted) records. Dates are handled as ISO8601 strings, strictly
 * enforcing string & tags.Format<'date-time'>, with no use of native Date
 * types.
 *
 * @param props - Request object
 * @param props.administrator - Administrator authentication payload (must be
 *   present and validated by decorator)
 * @param props.body - Query/filter parameters for advanced comment search and
 *   pagination
 * @returns Paginated, filtered comment records matching given criteria,
 *   including pagination metadata
 * @throws {Error} When database errors occur or if filtering is invalid
 */
export async function patch__aimall_backend_administrator_comments(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendComment.IRequest;
}): Promise<IPageIAimallBackendComment> {
  const { administrator, body } = props;

  // Enforce admin authentication contract (even if decorator already did it)
  if (
    !administrator ||
    administrator.type !== "administrator" ||
    administrator.status !== "active"
  ) {
    throw new Error("Administrator authentication or status is invalid.");
  }

  // Pagination defaults and limit enforcement
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? Math.min(body.limit, 100) : 20;
  const skip = (page - 1) * limit;

  // Build dynamic where clause from request
  const where = {
    ...(body.post_id !== undefined &&
      body.post_id !== null && { post_id: body.post_id }),
    ...(body.review_id !== undefined &&
      body.review_id !== null && { review_id: body.review_id }),
    ...(body.parent_id !== undefined &&
      body.parent_id !== null && { parent_id: body.parent_id }),
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(body.is_private !== undefined &&
      body.is_private !== null && { is_private: body.is_private }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
    (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined &&
              body.created_at_from !== null && { gte: body.created_at_from }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && { lte: body.created_at_to }),
          },
        }
      : {}),
  };

  // Fetch comments list and total count in parallel
  const [comments, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_comments.count({ where }),
  ]);

  // Convert result objects strictly to IAimallBackendComment (handling date and nullable fields)
  const data = comments.map((c) => ({
    id: c.id,
    post_id: c.post_id ?? null,
    review_id: c.review_id ?? null,
    parent_id: c.parent_id ?? null,
    customer_id: c.customer_id ?? null,
    body: c.body,
    is_private: c.is_private,
    created_at: toISOStringSafe(c.created_at),
    updated_at: toISOStringSafe(c.updated_at),
    deleted_at: c.deleted_at ? toISOStringSafe(c.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
