 * Update a channel's configuration by its UUID, supporting code, name, and
 * enabled status. Enforces unique constraints and business rules:
 *
 * - Only authenticated administrator can perform this operation.
 * - 'code' is globally unique; 'name' must not conflict with another channel's
 *   name.
 * - No-ops (no actual change) are rejected.
 * - Does not allow modification of immutable fields (id, created_at).
 * - Only returns allowed IAimallBackendChannel fields, all date values use ISO
 *   strings.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   active)
 * @param props.channelId - Channel UUID (must exist)
 * @param props.body - Update request: at least one field different from
 *   existing values.
 * @returns The updated channel entity as IAimallBackendChannel
 * @throws {Error} If channel not found, unauthorized, duplicate code/name, or
 *   no changes detected
 */
export async function put__aimall_backend_administrator_channels_$channelId(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  body: IAimallBackendChannel.IUpdate;
}): Promise<IAimallBackendChannel> {
  const { administrator, channelId, body } = props;

  // [Authorization] Only administrator can proceed (decorator enforces this, but documented)
  if (
    !administrator ||
    administrator.type !== "administrator" ||
    administrator.status !== "active"
  ) {
    throw new Error("Unauthorized: Administrator rights required");
  }

  // Fetch target channel
  const existing = await MyGlobal.prisma.aimall_backend_channels.findUnique({
    where: { id: channelId },
  });
  if (!existing) throw new Error("Channel not found");

  // Check if any updatable fields are actually changed
  const codeChanged = body.code != null && body.code !== existing.code;
  const nameChanged = body.name != null && body.name !== existing.name;
  const enabledChanged =
    body.enabled != null && body.enabled !== existing.enabled;
  if (!codeChanged && !nameChanged && !enabledChanged) {
    throw new Error("No changes detected");
  }

  // Enforce uniqueness of code (DB constraint/logic)
  if (codeChanged) {
    const duplicateCode =
      await MyGlobal.prisma.aimall_backend_channels.findFirst({
        where: { code: body.code!, id: { not: channelId } },
      });
    if (duplicateCode) {
      throw new Error("A channel with this code already exists");
    }
  }
  // Enforce uniqueness of name (business logic)
  if (nameChanged) {
    const duplicateName =
      await MyGlobal.prisma.aimall_backend_channels.findFirst({
        where: { name: body.name!, id: { not: channelId } },
      });
    if (duplicateName) {
      throw new Error("Another channel with this name already exists");
    }
  }

  // Build update input with only changed fields
  // Never use intermediate update variables for Prisma (define inline)
  const updated = await MyGlobal.prisma.aimall_backend_channels.update({
    where: { id: channelId },
    data: {
      code: codeChanged ? body.code! : undefined,
      name: nameChanged ? body.name! : undefined,
      enabled: enabledChanged ? body.enabled! : undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Return the new object, enforcing branded types on id and all date fields
  return {
    id: updated.id,
    code: updated.code,
    name: updated.name,
    enabled: updated.enabled,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

