    product_id: productId,
    ...(body.sku_code !== undefined &&
      body.sku_code !== null && {
        sku_code: { contains: body.sku_code, mode: "insensitive" as const },
      }),
  };

  // Query paginated SKUs and count in parallel
  const [data, records] = await Promise.all([
    MyGlobal.prisma.aimall_backend_skus.findMany({
      where: skuFilter,
      orderBy: { sku_code: "asc" },
      skip,
      take: limit,
      select: {
        id: true,
        product_id: true,
        sku_code: true,
      },
    }),
    MyGlobal.prisma.aimall_backend_skus.count({ where: skuFilter }),
  ]);
  const pages = records > 0 ? Math.ceil(records / limit) : 1;

  return {
    pagination: {
      current: page,
      limit,
      records,
      pages,
