/**
 * Adds a new order item to an existing order (Order Items table).
 *
 * This endpoint allows an authenticated customer to add a new line item to one
 * of their own orders. It validates order existence, ownership, archived state,
 * and allowed status (e.g., not delivered/cancelled). All inputs are validated
 * by typia or framework at the boundary; this function focuses on business
 * logic enforcement.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer (must be owner of the order)
 * @param props.orderId - UUID of the order to which the item is to be added
 * @param props.body - Order item creation payload, including product/option
 *   refs, item name, quantity, unit & total price
 * @returns Fully populated order item record (matching IAimallBackendOrderItem)
 * @throws {Error} If order does not exist, customer does not own the order, or
 *   order status forbids mutation
 */
export async function post__aimall_backend_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.ICreate;
}): Promise<IAimallBackendOrderItem> {
  const { customer, orderId, body } = props;

  // 1. Fetch the order; check existence and ownership
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: {
      id: true,
      customer_id: true,
      order_status: true,
      archived_at: true,
    },
  });
  if (!order) throw new Error("Order not found");
  if (order.customer_id !== customer.id)
    throw new Error("Forbidden: You do not own this order");

  // 2. Validate order mutability/state
  if (order.archived_at !== null)
    throw new Error("Cannot add items to an archived order");
  if (["delivered", "cancelled", "returned"].includes(order.order_status)) {
    throw new Error("Cannot add items to completed or cancelled orders");
  }

  // 3. Insert new order item (generate UUID)
  const created = await MyGlobal.prisma.aimall_backend_order_items.create({
    data: {
      id: v4(),
      order_id: orderId,
      product_id: body.product_id,
      product_option_id: body.product_option_id ?? null,
      item_name: body.item_name,
      quantity: body.quantity,
      unit_price: body.unit_price,
      total_price: body.total_price,
    },
  });

  // 4. Return result in IAimallBackendOrderItem shape
  return {
    id: created.id,
    order_id: created.order_id,
    product_id: created.product_id,
    product_option_id: created.product_option_id ?? null,
    item_name: created.item_name,
    quantity: created.quantity,
    unit_price: created.unit_price,
    total_price: created.total_price,
  };
}

