/**
 * Update details of an order item (Order Items table).
 *
 * Edits the details of a specific order item, as referenced by both parent
 * order and item UUIDs. Only attributes present in the corresponding schema
 * (product, option, quantity, name, prices) may be modified. The mutation is
 * disallowed for finalized/archived orders. Permissions are checked for the
 * seller of record, administrators, or customers where policies permit.
 *
 * All updates are logged for audit/compliance. Endpoint strictly validates the
 * linkage between provided orderId and orderItemId, and returns errors if these
 * do not match or are not found.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the action
 * @param props.orderId - UUID of the parent order containing the item
 * @param props.orderItemId - UUID of the order item to update
 * @param props.body - The fields to update on the order item
 * @returns The updated IAimallBackendOrderItem object
 * @throws {Error} When not found, unauthorized, archived, or fails validation
 */
export async function put__aimall_backend_seller_orders_$orderId_orderItems_$orderItemId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  orderItemId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.IUpdate;
}): Promise<IAimallBackendOrderItem> {
  const { seller, orderId, orderItemId, body } = props;

  const orderItem = await MyGlobal.prisma.aimall_backend_order_items.findFirst({
    where: { id: orderItemId, order_id: orderId },
  });
  if (!orderItem) throw new Error("Order item not found for this order");

  const order = await MyGlobal.prisma.aimall_backend_orders.findFirst({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id)
    throw new Error(
      "Unauthorized: Cannot update order belonging to another seller",
    );
  if (order.archived_at !== null)
    throw new Error("Order is archived/finalized and cannot be changed");

  if ("quantity" in body && body.quantity != null && body.quantity <= 0)
    throw new Error("Quantity must be positive");
  if ("unit_price" in body && body.unit_price != null && body.unit_price <= 0)
    throw new Error("Unit price must be positive");
  if (
    "total_price" in body &&
    body.total_price != null &&
    body.total_price <= 0
  )
    throw new Error("Total price must be positive");

  const updated = await MyGlobal.prisma.aimall_backend_order_items.update({
    where: { id: orderItemId },
    data: {
      item_name:
        "item_name" in body ? (body.item_name ?? undefined) : undefined,
      quantity: "quantity" in body ? (body.quantity ?? undefined) : undefined,
      unit_price:
        "unit_price" in body ? (body.unit_price ?? undefined) : undefined,
      total_price:
        "total_price" in body ? (body.total_price ?? undefined) : undefined,
      product_option_id:
        "product_option_id" in body
          ? (body.product_option_id ?? undefined)
          : undefined,
    },
  });

  return {
    id: updated.id,
    order_id: updated.order_id,
    product_id: updated.product_id,
    product_option_id:
      typeof updated.product_option_id === "string"
        ? updated.product_option_id
        : null,
    item_name: updated.item_name,
    quantity: updated.quantity,
    unit_price: updated.unit_price,
    total_price: updated.total_price,
  };
}

