import { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Adds a new order item to an order (Order Items table).
 *
 * Adds a new order item line to an existing order using the parent order's
 * UUID. Input payload must supply all fields as per the
 * 'aimall_backend_order_items' schema (product, SKU/option, item name,
 * quantity, unit/total price). Use case includes administrator corrections,
 * seller adjustment after customer request, or test data.
 *
 * Order state is validated to reject additions for immutable or already
 * delivered orders. Permissions ensure only sellers/administrators and the
 * owning customer (where allowed) may mutate items in an open order.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the operation
 * @param props.orderId - UUID of the order to which a new item is added
 * @param props.body - Payload for the order item to add
 * @returns The newly created order item record
 * @throws {Error} When order does not exist, seller does not own the order, or
 *   the order is not mutable
 */
export async function post__aimall_backend_seller_orders_$orderId_orderItems(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.ICreate;
}): Promise<IAimallBackendOrderItem> {
  const { seller, orderId, body } = props;

  // 1. Fetch the order and validate it exists, throwing if not found
  const order = await MyGlobal.prisma.aimall_backend_orders.findUniqueOrThrow({
    where: { id: orderId },
    select: {
      id: true,
      seller_id: true,
      order_status: true,
      archived_at: true,
    },
  });

  // 2. Authorization: Only allow the owning seller to mutate their order
  if (order.seller_id !== seller.id) {
    throw new Error("Unauthorized: You do not own this order");
  }

  // 3. Validate the order is still modifiable (not delivered, cancelled, returned, or archived)
  if (
    ["delivered", "cancelled", "returned"].includes(order.order_status) ||
    order.archived_at !== null
  ) {
    throw new Error("Order is immutable and cannot be modified");
  }

  // 4. Attempt to insert new order item
  const created = await MyGlobal.prisma.aimall_backend_order_items.create({
    data: {
      id: v4(),
      order_id: orderId,
      product_id: body.product_id,
      product_option_id: body.product_option_id ?? null,
      item_name: body.item_name,
      quantity: body.quantity,
      unit_price: body.unit_price,
      total_price: body.total_price,
    },
  });

  // 5. Return typed record
  return {
    id: created.id,
    order_id: created.order_id,
    product_id: created.product_id,
    product_option_id: created.product_option_id ?? null,
    item_name: created.item_name,
    quantity: created.quantity,
    unit_price: created.unit_price,
    total_price: created.total_price,
  };
}

