}): Promise<IPageIAimallBackendSupportTicket> {
  const { customer, body } = props;

  // Defensive normalize page/limit (min 1 for page, min 1 for limit -- default 20)
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit =
    typeof body.limit === "number" && body.limit > 0 ? body.limit : 20;

  // Build date filters (ISO8601 strings ONLY, never Date type)
  const created_at_filter =
    (body.create_from !== undefined && body.create_from !== null) ||
