/**
 * List all item lines for an order (Order Items table).
 *
 * Fetches all item lines associated with a single order, using the order's
 * UUID. The API enumerates over all records in the 'aimall_backend_order_items'
 * table for the specified order. Each item provides full details as per
 * schema—product linkage, option/SKU, quantity, item and total prices.
 *
 * Authorization: Only the customer who owns the order may access this endpoint.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer payload injected by
 *   CustomerAuth
 * @param props.orderId - The UUID of the parent order whose items are being
 *   listed
 * @returns Paginated item list for the order (all items returned in one page)
 * @throws {Error} If order does not exist or the customer is not the owner
 */
export async function get__aimall_backend_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendOrderItem> {
  const { customer, orderId } = props;

  // 1. Verify order exists and is owned by the requester
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order || order.customer_id !== customer.id) {
    throw new Error(
      "Order not found or you are not authorized to view its items.",
    );
  }

  // 2. Retrieve all order items for the specified order
  const items = await MyGlobal.prisma.aimall_backend_order_items.findMany({
    where: { order_id: orderId },
    orderBy: { id: "asc" },
  });

  // 3. Compose paginated response (all items returned in a single page)
  return {
    pagination: {
      current: 1,
      limit: items.length as number & tags.Type<"int32">,
      records: items.length as number & tags.Type<"int32">,
      pages: 1 as number & tags.Type<"int32">,
    },
    data: items.map((item) => ({
      id: item.id,
      order_id: item.order_id,
      product_id: item.product_id,
      // product_option_id is nullable, always ensure null not undefined
      product_option_id: item.product_option_id ?? null,
      item_name: item.item_name,
      quantity: item.quantity,
      unit_price: item.unit_price,
      total_price: item.total_price,
    })),
  };
}

