 * use this endpoint. Search results return only addresses directly associated
 * with the customerId provided.
 *
 * Related API: GET /customers/{customerId}/addresses returns all addresses,
 * while this endpoint enables filtered and paginated queries. Error handling
 * covers invalid customerId, out-of-bound paging parameters, and access
 * violations.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request.
 * @param props.customerId - The UUID of the customer whose addresses are being
 *   searched.
 * @param props.body - Filter, sort, and pagination options for search.
 * @returns A filtered and paginated list of the customer's addresses matching
 *   the criteria.
 * @throws {Error} If the customer does not exist.
 * @throws {Error} If an unauthorized access is attempted.
 */
export async function patch__aimall_backend_customer_customers_$customerId_addresses(props: {
  customer: CustomerPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAimallBackendAddress.IRequest;
}): Promise<IPageIAimallBackendAddress> {
