  // 1. Verify customer existence
  const dbCustomer = await MyGlobal.prisma.aimall_backend_customers.findFirst({
    where: { id: customerId },
  });
  if (!dbCustomer) throw new Error("Customer not found");

  // 2. Permission check: customerId must match authenticated customer
  if (customer.id !== customerId) throw new Error("Forbidden");

  // 3. Extract filters and pagination options
  const { alias, recipient_name, city, is_default, page, limit } = body;
  const pageNum = typeof page === "number" && page > 0 ? page : 1;
  const pageSize = typeof limit === "number" && limit > 0 ? limit : 20;

  // 4. Build where condition
  const where = {
    customer_id: customerId,
    ...(typeof alias === "string" && alias.length > 0
      ? { alias: { contains: alias, mode: "insensitive" as const } }
      : {}),
    ...(typeof recipient_name === "string" && recipient_name.length > 0
      ? {
          recipient_name: {
            contains: recipient_name,
            mode: "insensitive" as const,
          },
        }
      : {}),
    ...(typeof city === "string" && city.length > 0
      ? { city: { contains: city, mode: "insensitive" as const } }
      : {}),
    ...(typeof is_default === "boolean" ? { is_default } : {}),
  };

  // 5. Query DB (addresses and total count in parallel)
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_addresses.findMany({
      where,
      orderBy: { updated_at: "desc" },
      skip: (pageNum - 1) * pageSize,
      take: pageSize,
    }),
    MyGlobal.prisma.aimall_backend_addresses.count({ where }),
  ]);

  // 6. Map DB rows to DTO, converting updated_at
  const data = rows.map((row) => {
    const obj: IAimallBackendAddress = {
      id: row.id,
      customer_id: row.customer_id,
      alias: row.alias,
      recipient_name: row.recipient_name,
      phone: row.phone,
      address_line1: row.address_line1,
      city: row.city,
      postal_code: row.postal_code,
      country: row.country,
      is_default: row.is_default,
      updated_at: toISOStringSafe(row.updated_at),
    };
    if (typeof row.address_line2 === "string" && row.address_line2.length > 0) {
      obj.address_line2 = row.address_line2;
    }
    return obj;
  });

  // 7. Pagination metadata
  const pages = total > 0 ? Math.ceil(total / pageSize) : 1;

  return {
    pagination: {
      current: pageNum,
      limit: pageSize,
      records: total,
      pages,
    },
    data,
  };
}

