  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error(
      "Forbidden: You do not have permission to update snapshots on reviews for products you do not own",
    );
  }
  // 3. Fetch snapshot and check correct ownership
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
  });
  if (!snapshot) throw new Error("Snapshot not found");
  if (snapshot.product_id !== review.product_id) {
    throw new Error("Snapshot does not belong to review product");
  }
  // 4. Update snapshot, updating only present fields
  const updated = await MyGlobal.prisma.aimall_backend_snapshots.update({
    where: { id: snapshotId },
    data: {
      ...(body.caption !== undefined && { caption: body.caption }),
      ...(body.media_uri !== undefined && { media_uri: body.media_uri }),
    },
  });
  return {
    id: updated.id,
    product_id: updated.product_id ?? undefined,
    post_id: updated.post_id ?? undefined,
    customer_id: updated.customer_id ?? undefined,
    media_uri: updated.media_uri,
    caption: updated.caption ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
  };
}

