/**
 * Advanced, paginated search of snapshots (user-generated photos/videos) for a
 * specific community post.
 *
 * This endpoint retrieves paginated and filtered snapshot records for a
 * specific post, supporting advanced filtering on media attributes, uploader,
 * and creation date. Only snapshots attached to the given post are included.
 *
 * Applies server-side pagination and sorts by most recent first. If no matches
 * found, returns empty data with full pagination.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (enforces account is
 *   active)
 * @param props.postId - UUID of the community post to search for snapshots
 * @param props.body - Filtering, keyword, and pagination parameters per
 *   IAimallBackendSnapshot.IRequest
 * @returns Paginated snapshot results matching filters, or an empty page if
 *   none match
 */
export async function patch__aimall_backend_customer_posts_$postId_snapshots(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IRequest;
}): Promise<IPageIAimallBackendSnapshot> {
  const { postId, body } = props;
  // Normalize pagination
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit =
    body.limit && body.limit > 0 && body.limit <= 100 ? body.limit : 20;

  // Inline where condition
  const where = {
    post_id: postId,
    ...(body.product_id !== undefined &&
      body.product_id !== null && { product_id: body.product_id }),
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(body.caption && {
      caption: { contains: body.caption, mode: "insensitive" as const },
    }),
    ...(body.media_uri && {
      media_uri: { contains: body.media_uri, mode: "insensitive" as const },
    }),
    ...(body.created_from || body.created_to
      ? {
          created_at: {
            ...(body.created_from && { gte: body.created_from }),
            ...(body.created_to && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // Query data and count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_snapshots.count({ where }),
  ]);

  // Map to API output (convert created_at, brand types)
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: total > 0 ? Math.ceil(total / limit) : 1,
    },
    data: rows.map((row) => ({
      id: row.id,
      product_id: row.product_id ?? undefined,
      post_id: row.post_id ?? undefined,
      customer_id: row.customer_id ?? undefined,
      media_uri: row.media_uri,
      caption: row.caption ?? undefined,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

