/**
 * Performs a filtered, paginated search for attachments uploaded to a product
 * review.
 *
 * This endpoint enables sellers to search and filter attachments linked to
 * their own product reviews using advanced criteria like file type, size, and
 * upload date. Results are paginated. Security: Only sellers for the product
 * can view attachments for its reviews. Throws 404 if the review does not
 * exist, and 403 if access is denied.
 *
 * @param props - Props object containing seller authentication, review ID, and
 *   request body with filters
 * @param props.seller - The authenticated seller making the request
 * @param props.reviewId - The UUID of the review context for attachment search
 * @param props.body - Filtering and pagination parameters for search
 * @returns Paginated set of attachments matching the query for this review
 * @throws {Error} When the review does not exist (404)
 * @throws {Error} When the seller does not own the product for the review (403)
 */
export async function patch__aimall_backend_seller_reviews_$reviewId_attachments(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IRequest;
}): Promise<IPageIAimallBackendAttachment> {
  const { seller, reviewId, body } = props;

  // Authorization: Fetch review and product, check seller owns the product.
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) throw new Error("Review not found"); // 404

  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
  });
  if (!product || product.seller_id !== seller.id)
    throw new Error("Forbidden: Seller is not authorized for this review"); // 403

  // Pagination
  const limit =
    body.limit !== undefined && body.limit !== null && body.limit > 0
      ? body.limit
      : 20;
  const page =
    body.page !== undefined && body.page !== null && body.page > 0
      ? body.page
      : 1;
  const skip = (page - 1) * limit;

  // Build where condition
  const whereCondition = {
    review_id: reviewId,
    ...(body.post_id !== undefined &&
      body.post_id !== null && { post_id: body.post_id }),
    ...(body.comment_id !== undefined &&
      body.comment_id !== null && { comment_id: body.comment_id }),
    ...(body.file_type !== undefined &&
      body.file_type !== null && { file_type: body.file_type }),
    ...(body.file_size_min !== undefined &&
      body.file_size_min !== null && {
        file_size: { gte: body.file_size_min },
      }),
    ...(body.file_size_max !== undefined &&
      body.file_size_max !== null && {
        file_size: {
          ...(body.file_size_min !== undefined &&
            body.file_size_min !== null && { gte: body.file_size_min }),
          lte: body.file_size_max,
        },
      }),
    ...(body.created_from !== undefined &&
      body.created_from !== null && {
        created_at: { gte: body.created_from },
      }),
    ...(body.created_to !== undefined &&
      body.created_to !== null && {
        created_at: {
          ...(body.created_from !== undefined &&
            body.created_from !== null && { gte: body.created_from }),
          lte: body.created_to,
        },
      }),
  };

  // Query attachments and count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where: whereCondition,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({ where: whereCondition }),
  ]);

  // Map DB rows to IAimallBackendAttachment
  const data = rows.map((item) => ({
    id: item.id,
    post_id: item.post_id ?? null,
    comment_id: item.comment_id ?? null,
    review_id: item.review_id ?? null,
    file_uri: item.file_uri,
    file_type: item.file_type,
    file_size: item.file_size,
    created_at: toISOStringSafe(item.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  } satisfies IPageIAimallBackendAttachment;
}

