/**
 * Fetches all audit snapshots for a specific order for the authorized customer
 * (Order Snapshots table).
 *
 * Only the customer who owns the order is authorized to view the complete list
 * of order audit snapshot records.
 *
 * This function verifies the current customer owns the targeted order, then
 * retrieves all "aimall_backend_order_snapshots" rows for that orderId. Each
 * snapshot contains a point-in-time audit of the order's business state. All
 * date values are converted to branded ISO strings for API compliance.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload (authorization
 *   enforced)
 * @param props.orderId - Target order's universally unique identifier (UUID) to
 *   retrieve snapshot records for
 * @returns Wrapper object containing array of all order audit snapshot records
 *   for the specified order
 * @throws {Error} When the order does not exist, or if the current customer
 *   does not own the order
 */
export async function get__aimall_backend_customer_orders_$orderId_orderSnapshots(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendOrderSnapshot> {
  const { customer, orderId } = props;
  // 1. Check order existence and ownership
  const order = await MyGlobal.prisma.aimall_backend_orders.findFirst({
    where: { id: orderId },
    select: { customer_id: true },
  });
  if (!order || order.customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: You can only access snapshots for your own orders",
    );
  }
  // 2. Fetch all snapshots for this order
  const records = await MyGlobal.prisma.aimall_backend_order_snapshots.findMany(
    {
      where: { order_id: orderId },
      orderBy: { snapshot_at: "asc" },
    },
  );
  // 3. Map records to API DTO (enforce type branding for id, order_id, and snapshot_at)
  const result: IPageIAimallBackendOrderSnapshot = {
