      id: snap.id as string & tags.Format<"uuid">,
      order_id: snap.order_id as string & tags.Format<"uuid">,
      snapshot_type: snap.snapshot_type,
      snapshot_data: snap.snapshot_data,
      snapshot_at: toISOStringSafe(snap.snapshot_at),
    })),
    pagination: undefined,
  };
  return result;
}

