 * @param props.orderId - UUID of the parent order to search within
 * @param props.body - Search/filter and pagination parameters for order items
 * @returns Paginated results of order items matching the filters
 * @throws {Error} When the order does not exist or access is denied
 */
export async function patch__aimall_backend_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.IRequest;
}): Promise<IPageIAimallBackendOrderItem> {
  const { customer, orderId, body } = props;

  // 1. Authorization: Ensure customer owns the order
  const order = await MyGlobal.prisma.aimall_backend_orders.findFirst({
    where: { id: orderId, customer_id: customer.id },
  });
  if (!order) throw new Error("Order not found or access denied");

  // 2. Build WHERE condition for order items
  const where = {
    order_id: orderId,
    ...(body.product_id !== undefined && { product_id: body.product_id }),
    ...(body.product_option_id !== undefined &&
      body.product_option_id !== null && {
        product_option_id: body.product_option_id,
      }),
    ...(body.item_name !== undefined &&
      body.item_name !== null && {
        item_name: { contains: body.item_name, mode: "insensitive" as const },
      }),
  };

  // 3. Pagination
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // 4. Sorting
  let orderBy;
  if (body.sort_by === "item_name") {
    orderBy = { item_name: body.sort_order === "asc" ? "asc" : "desc" };
  }

  // 5. Query items and total count
  const [items, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_order_items.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: orderBy ?? undefined,
    }),
    MyGlobal.prisma.aimall_backend_order_items.count({ where }),
  ]);

  // 6. Map to API structure
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items.map((item) => ({
      id: item.id,
      order_id: item.order_id,
      product_id: item.product_id,
      product_option_id: item.product_option_id ?? null,
      item_name: item.item_name,
      quantity: item.quantity,
      unit_price: item.unit_price,
      total_price: item.total_price,
    })),
  };
}

