/**
 * Advanced search and pagination of comments for a seller's product review,
 * with full filtering and role-based access control.
 *
 * This endpoint allows a seller to search and paginate comments attached to a
 * specific review for one of their products, using flexible filter criteria
 * (author, privacy, parent, date range, etc). The seller is strictly limited to
 * comments for reviews on their own products and can always view all comments
 * (including private) for such reviews. Pagination and ordering are supported,
 * and all date fields are handled as branded ISO8601 strings (no Date type
 * usage).
 *
 * @param props - Request parameters
 * @param props.seller - Authenticated seller payload (authorization is enforced
 *   for self-owned product reviews)
 * @param props.reviewId - UUID of the target product review to search comments
 *   against
 * @param props.body - Search and pagination filter structure (see
 *   IAimallBackendComment.IRequest)
 * @returns Paginated set of community comments matching the query
 * @throws {Error} When the review does not exist or the seller does not own the
 *   associated product
 */
export async function patch__aimall_backend_seller_reviews_$reviewId_comments(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IRequest;
}): Promise<IPageIAimallBackendComment> {
  const { seller, reviewId, body } = props;

  // 1. Ownership enforcement — seller can only access reviews of their own products
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { product_id: true },
  });
  if (!review) throw new Error("Review not found");

  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: seller does not own the target product for this review",
    );
  }

  // 2. Filtering: required by business rules
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Build composite where object with robust null/undefined checks
  const where = {
    review_id: reviewId,
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(body.parent_id !== undefined &&
      body.parent_id !== null && { parent_id: body.parent_id }),
    ...(body.is_private !== undefined &&
      body.is_private !== null && { is_private: body.is_private }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
    (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined &&
              body.created_at_from !== null && {
                gte: body.created_at_from,
              }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && {
                lte: body.created_at_to,
              }),
          },
        }
      : {}),
  };

  // 3. Query paginated comments and the total count
  const [comments, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_comments.count({ where }),
  ]);

  // 4. Map and brand all date fields; deleted_at is nullable
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit) as number & tags.Type<"int32">,
    },
    data: comments.map((comment) => ({
      id: comment.id,
      post_id: comment.post_id,
      review_id: comment.review_id,
      parent_id: comment.parent_id,
      customer_id: comment.customer_id,
      body: comment.body,
      is_private: comment.is_private,
      created_at: toISOStringSafe(comment.created_at),
      updated_at: toISOStringSafe(comment.updated_at),
      deleted_at: comment.deleted_at
        ? toISOStringSafe(comment.deleted_at)
        : null,
    })),
  };
}

