 * (aimall_backend_categories).
 *
 * Modify one or more fields of a specified child category directly under a
 * parent category. The operation validates that the relationship is legal,
 * i.e., the target child's parent_id matches the supplied categoryId. Updatable
 * fields include the category name (subject to uniqueness among siblings under
 * the same parent), and optionally the depth.
 *
 * If the uniqueness constraint or parent-child relationship is violated, an
 * error is thrown. Moving categories between parents is not permitted by this
 * operation.
 *
 * Role-based access restricts this endpoint to administrators responsible for
 * product taxonomy management.
 *
 * @param props - Object containing required parameters
 * @param props.administrator - Authenticated administrator (authorization
 *   enforced)
 * @param props.categoryId - ID of the parent category (must match child's
 *   parent_id)
 * @param props.childCategoryId - ID of the child category to update (target for
 *   update)
 * @param props.body - Fields to update on the child category (name or depth;
 *   parent_id cannot be changed)
 * @returns The updated child category object
 * @throws {Error} If the child does not exist, if it is not under the given
 *   parent, or if a sibling name clash occurs
 */
export async function put__aimall_backend_administrator_categories_$categoryId_childCategories_$childCategoryId(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
  childCategoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.IUpdate;
}): Promise<IAimallBackendCategory> {
  const { categoryId, childCategoryId, body } = props;

  // 1. Fetch the target child category
  const target =
    await MyGlobal.prisma.aimall_backend_categories.findFirstOrThrow({
      where: { id: childCategoryId },
    });

  // 2. Validate parent-child relationship
  if (target.parent_id !== categoryId) {
    throw new Error(
      "Child category is not under the specified parent category",
    );
  }

  // 3. Uniqueness check: If updating name, ensure no sibling with the same name (excluding self)
  if (body.name !== undefined) {
    const sibling = await MyGlobal.prisma.aimall_backend_categories.findFirst({
      where: {
        parent_id: target.parent_id ?? null,
        name: body.name,
        NOT: { id: target.id },
      },
    });
    if (sibling) {
      throw new Error(
        "A sibling category with this name already exists under this parent",
      );
    }
  }

  // 4. Update permitted fields (never id or parent_id)
  const updated = await MyGlobal.prisma.aimall_backend_categories.update({
    where: { id: childCategoryId },
    data: {
      ...(body.name !== undefined ? { name: body.name } : {}),
      ...(body.depth !== undefined ? { depth: body.depth } : {}),
    },
  });

  // 5. Map fields to IAimallBackendCategory
  return {
    id: updated.id,
    parent_id: updated.parent_id ?? null,
    name: updated.name,
    depth: updated.depth,
  };
}

