/**
 * Retrieves all direct (non-deleted) child comments under a parent comment
 * (thread expansion) for administrator moderation/audit.
 *
 * This endpoint fetches replies to a specific parent comment as identified by
 * 'commentId' in the aimall_backend_comments schema. All direct child comments
 * (where parent_id matches) are included, as long as they are active
 * (deleted_at == null). Only an active parent comment may be expanded.
 *
 * Administrators are authorized to view both public and private threads, with
 * audit compliance and privacy logic. Pagination uses defaults (page=1,
 * limit=20) and can be extended.
 *
 * All date/datetime fields are provided as ISO8601 strings with format
 * branding. No native Date usage occurs within this function. All types are
 * fully respected and immutable.
 *
 * @param props - Properties for this operation
 * @param props.administrator - Authenticated AdministratorPayload performing
 *   this operation (for admin auth and audit compliance)
 * @param props.commentId - UUID of the parent comment to retrieve children of
 * @returns Paginated container of active direct child comments
 *   (IAimallBackendComment[]), including full pagination metadata
 *   (IPageIPagination)
 * @throws {Error} If the parent comment does not exist, is soft-deleted, or
 *   commentId is invalid
 */
export async function get__aimall_backend_administrator_comments_$commentId_comments(props: {
  administrator: AdministratorPayload;
  commentId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendComment> {
  const { administrator, commentId } = props;

  // 1. Verify parent exists and is not deleted
  const parent = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: commentId },
  });
  if (!parent || parent.deleted_at !== null) {
    throw new Error("Parent comment not found or has been deleted");
  }

  // 2. Pagination params (defaults for now)
  const limit = 20 as number & tags.Type<"int32">;
  const page = 1 as number & tags.Type<"int32">;

  // 3. Query child comments (active only, direct children)
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.count({
      where: { parent_id: commentId, deleted_at: null },
    }),
    MyGlobal.prisma.aimall_backend_comments.findMany({
      where: { parent_id: commentId, deleted_at: null },
      orderBy: { created_at: "asc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

  // 4. Map and convert all fields to strict DTO types
  const data = rows.map((row) => ({
    id: row.id,
    post_id: row.post_id ?? null,
    review_id: row.review_id ?? null,
    parent_id: row.parent_id ?? null,
    customer_id: row.customer_id ?? null,
    body: row.body,
    is_private: row.is_private,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  // 5. Build pagination DTO (branding as needed for int32)
  const pages = total > 0 ? Math.ceil(total / limit) : 1;
  const pagination = {
    current: page,
    limit: limit,
    records: total as number & tags.Type<"int32">,
    pages: pages as number & tags.Type<"int32">,
  };

  return { pagination, data };
}

