/**
 * List all order items for a specific order (Seller-side).
 *
 * Fetches the individual item lines (products/options) associated with a given
 * order, as seen by the specified seller. Ensures only the order's owning
 * seller can access its items.
 *
 * Returns results paginated (single page – all items in order) and strictly
 * typed as IPageIAimallBackendOrderItem.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller account requesting the items
 * @param props.orderId - The UUID of the order whose items are listed
 * @returns Paginated list of order item records compliant with
 *   IPageIAimallBackendOrderItem
 * @throws {Error} If the order does not exist or the seller is not authorized
 *   to view the order's items
 */
export async function get__aimall_backend_seller_orders_$orderId_orderItems(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendOrderItem> {
  const { seller, orderId } = props;

  // Step 1: Authorization – seller must own the order
  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
    select: { seller_id: true },
  });
  if (!order || order.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Seller does not own this order or order not found.",
    );
  }

  // Step 2: Fetch order items
  const dbOrderItems =
    await MyGlobal.prisma.aimall_backend_order_items.findMany({
      where: { order_id: orderId },
      orderBy: { id: "asc" },
    });

  // Step 3: Map order items to DTO with strict branding and tags
  const data = dbOrderItems.map((item) => ({
    id: typia.assert<string & tags.Format<"uuid">>(item.id),
    order_id: typia.assert<string & tags.Format<"uuid">>(item.order_id),
    product_id: typia.assert<string & tags.Format<"uuid">>(item.product_id),
    product_option_id:
      item.product_option_id != null
        ? typia.assert<string & tags.Format<"uuid">>(item.product_option_id)
        : null,
    item_name: item.item_name,
    quantity: typia.assert<number & tags.Type<"int32">>(item.quantity),
    unit_price: typia.assert<
      number & tags.JsonSchemaPlugin<{ format: "double" }>
    >(item.unit_price),
    total_price: typia.assert<
      number & tags.JsonSchemaPlugin<{ format: "double" }>
    >(item.total_price),
  }));

  // Step 4: Pagination (all order items as a single page)
  const pageSize = data.length;
  const pagination = {
    current: typia.assert<number & tags.Type<"int32">>(1),
    limit: typia.assert<number & tags.Type<"int32">>(pageSize),
    records: typia.assert<number & tags.Type<"int32">>(pageSize),
    pages: typia.assert<number & tags.Type<"int32">>(1),
  };

  return {
    pagination,
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
