import { IAimallBackendSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendSnapshot";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Retrieves a paginated list of snapshots associated with a specific community
 * post.
 *
 * Snapshot records enrich the community timeline by capturing user image/photo
 * moments tied to posts and social engagement events. Only public posts or
 * private posts owned by the requester can be viewed.
 *
 * @param props - The request properties
 * @param props.customer - The authenticated customer (JWT payload)
 * @param props.postId - The UUID of the community post whose snapshots are
 *   being queried
 * @returns Paginated list of snapshot records linked to the target post
 *   (IPageIAimallBackendSnapshot)
 * @throws {Error} If the post is not found, deleted, or the customer does not
 *   have permission to view private post snapshots
 */
export async function get__aimall_backend_customer_posts_$postId_snapshots(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendSnapshot> {
  const { customer, postId } = props;

  // Step 1: Retrieve the post, ensure it exists and is not deleted
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
    select: { id: true, customer_id: true, is_private: true, deleted_at: true },
  });
  if (!post || post.deleted_at != null) {
    throw new Error("Post not found");
  }

  // Step 2: Permission check for private posts
  if (post.is_private && post.customer_id !== customer.id) {
    throw new Error("Not authorized to view this post's snapshots");
  }

  // Step 3: Fetch all snapshots for the post (no pagination params, return all ordered by created_at desc)
  const snapshots = await MyGlobal.prisma.aimall_backend_snapshots.findMany({
    where: { post_id: postId },
    orderBy: { created_at: "desc" as const },
  });

  // Step 4: Map to IAimallBackendSnapshot[] and package as IPageIAimallBackendSnapshot
  return {
    pagination: {
      current: 1 as number & tags.Type<"int32">,
      limit: snapshots.length as number & tags.Type<"int32">,
      records: snapshots.length as number & tags.Type<"int32">,
      pages: 1 as number & tags.Type<"int32">,
    },
    data: (snapshots ?? []).map((s) => ({
      id: s.id,
      product_id: s.product_id ?? undefined,
      post_id: s.post_id ?? undefined,
      customer_id: s.customer_id ?? undefined,
      media_uri: s.media_uri,
      caption: s.caption ?? undefined,
      created_at: toISOStringSafe(s.created_at),
    })),
  };
}

