    ...(body.order_id !== undefined &&
      body.order_id !== null && { order_id: body.order_id }),
    ...(body.product_id !== undefined &&
      body.product_id !== null && { product_id: body.product_id }),
    ...((body.redeemed_from !== undefined && body.redeemed_from !== null) ||
    (body.redeemed_to !== undefined && body.redeemed_to !== null)
      ? {
          redeemed_at: {
            ...(body.redeemed_from !== undefined &&
              body.redeemed_from !== null && { gte: body.redeemed_from }),
            ...(body.redeemed_to !== undefined &&
