      orderBy: { redeemed_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_coupon_redemptions.count({ where }),
  ]);

  // Map results to proper DTO shape, ensuring all date fields are ISO strings
  const data = rows.map(
    (row): IAimallBackendCouponRedemption => ({
      id: row.id,
      coupon_id: row.coupon_id,
      customer_id: row.customer_id,
      discount_campaign_id: row.discount_campaign_id ?? null,
      redeemed_at: toISOStringSafe(row.redeemed_at),
      redemption_status: row.redemption_status,
      order_id: row.order_id ?? null,
      product_id: row.product_id ?? null,
