/**
 * Advanced SKUs search/filtering for a product, with pagination
 * (aimall_backend_skus).
 *
 * Fetch all SKUs affiliated with a specified product, with support for advanced
 * query features such as search by SKU code, partial code, and pagination. The
 * aimall_backend_skus table supports many-to-product relationships and allows
 * efficient traversal and filtering of SKUs for high-variant products, as used
 * by administrative or seller inventory dashboards.
 *
 * The API enforces product validation, returning only SKUs that are subordinate
 * to the given productId, and applies security constraints as necessary (e.g.,
 * sellers can only see their own products’ SKUs). Malformed filters or invalid
 * productId parameters will trigger errors as appropriate.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator user
 * @param props.productId - The product for which to filter/search SKUs
 * @param props.body - Filtering and searching details for querying this
 *   product’s SKUs
 * @returns Paginated filtered list of SKUs for the specified product.
 * @throws {Error} If the referenced productId does not exist
 */
export async function patch__aimall_backend_administrator_products_$productId_skus(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendSku.IRequest;
}): Promise<IPageIAimallBackendSku> {
  const { administrator, productId, body } = props;

  // 1. Make sure the product exists
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: productId },
  });
  if (!product) {
    throw new Error("Product not found");
  }

  // 2. Prepare filter
  const skuCode = typeof body.sku_code === "string" ? body.sku_code.trim() : "";
  const page: number =
    body.page != null && typeof body.page === "number" && body.page > 0
      ? body.page
      : 1;
  const limit: number =
    body.limit != null &&
    typeof body.limit === "number" &&
    body.limit > 0 &&
    body.limit <= 100
      ? body.limit
      : 20;

  // 3. Query SKUs and total count in parallel, strict to the productId
  const where = {
    product_id: productId,
    ...(skuCode && {
      sku_code: { contains: skuCode, mode: "insensitive" as const },
    }),
  };

  const [skus, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_skus.findMany({
      where,
      orderBy: { sku_code: "asc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_skus.count({ where }),
  ]);

  // 4. Compose result object strictly per DTOs
  const result: IPageIAimallBackendSku = {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data: skus.map((sku) => ({
      id: sku.id,
      product_id: sku.product_id,
      sku_code: sku.sku_code,
    })),
  };
  return result;
}

