 * attachments on a specific post, using advanced filters for file size, type,
 * and upload date range. Returns results in paginated form, visible only to
 * sellers permitted to view the post (i.e., seller must be allowed business
 * access).
 *
 * @param props - Properties for the search
 * @param props.seller - The authenticated seller account (SellerPayload), only
 *   permitted sellers may view their attachments
 * @param props.postId - The parent post's unique UUID
 * @param props.body - The attachment search/filter and pagination options
 *   (file_type, size, created_at range, page, limit)
 * @returns Paginated and filtered list of matching attachment objects
 * @throws {Error} If the post does not exist or the seller is not authorized to
 *   access it
 */
export async function patch__aimall_backend_seller_posts_$postId_attachments(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IRequest;
}): Promise<IPageIAimallBackendAttachment> {
  const { seller, postId, body } = props;

  // Step 1: Verify the post exists
  const post = await MyGlobal.prisma.aimall_backend_posts.findUnique({
    where: { id: postId },
    select: { id: true },
  });
  if (!post) throw new Error("Post not found or inaccessible");
  // TODO (production): Enforce that the seller is authorized to view this post's attachments.

  // Step 2: Build dynamic filter object for attachments
  // Safe merging of optional filter bounds (file_size, created_at)
  const fileSizeCondition =
    body.file_size_min != null || body.file_size_max != null
      ? {
          file_size: {
            ...(body.file_size_min != null ? { gte: body.file_size_min } : {}),
            ...(body.file_size_max != null ? { lte: body.file_size_max } : {}),
          },
        }
      : {};
  const createdAtCondition =
    body.created_from != null || body.created_to != null
      ? {
          created_at: {
            ...(body.created_from != null ? { gte: body.created_from } : {}),
            ...(body.created_to != null ? { lte: body.created_to } : {}),
          },
        }
      : {};

  const whereClause = {
    post_id: postId,
    ...(body.file_type != null ? { file_type: body.file_type } : {}),
    ...fileSizeCondition,
    ...createdAtCondition,
  };

  // Step 3: Pagination (defaults)
  const limit = body.limit ?? 20;
  const page = body.page ?? 1;
  const skip = (page - 1) * limit;

  // Step 4: Query for paged results and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where: whereClause,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({ where: whereClause }),
  ]);

  // Step 5: Map rows to DTO shape, always using string & tags.Format<'date-time'> for datetime values
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((item) => ({
      id: item.id,
      post_id: item.post_id ?? null,
      comment_id: item.comment_id ?? null,
      review_id: item.review_id ?? null,
      file_uri: item.file_uri,
      file_type: item.file_type,
      file_size: item.file_size,
      created_at: toISOStringSafe(item.created_at),
    })),
  };
}

