/**
 * Advanced, filterable search API for user snapshots associated with a review
 * (aimall_backend_snapshots).
 *
 * Allows sellers to query snapshots linked to reviews of their own products
 * only. Supports pagination and all documented filtering (customer, caption,
 * media uri, created_at range).
 *
 * @param props - Request context and parameters
 * @param props.seller - The authenticated seller performing the search
 * @param props.reviewId - UUID of the review to search snapshots for
 * @param props.body - Snapshot filter and pagination options
 *   (IAimallBackendSnapshot.IRequest)
 * @returns Paginated result of snapshots matching the review and filters
 *   (IPageIAimallBackendSnapshot)
 * @throws {Error} If review not found
 * @throws {Error} If requesting seller is not owner of product related to
 *   review
 */
export async function patch__aimall_backend_seller_reviews_$reviewId_snapshots(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IRequest;
}): Promise<IPageIAimallBackendSnapshot> {
  const { seller, reviewId, body } = props;

  // 1. Find the review (and ensure it exists)
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { product_id: true },
  });
  if (!review) {
    throw new Error("Review not found");
  }

  // 2. Fetch product for seller check
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error(
      "Forbidden: Only the review's product owner can view its snapshots",
    );
  }

  // 3. Build dynamic where clause for snapshot filters
  const where = {
    product_id: review.product_id,
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(body.caption !== undefined &&
      body.caption !== null && { caption: { contains: body.caption } }),
    ...(body.media_uri !== undefined &&
      body.media_uri !== null && { media_uri: { contains: body.media_uri } }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // 4. Pagination logic
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 5. Query paginated snapshots and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_snapshots.count({ where }),
  ]);

  // 6. Map results and guarantee correct types
  const result: IPageIAimallBackendSnapshot = {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((s) => ({
      id: s.id,
      product_id: s.product_id ?? undefined,
      post_id: s.post_id ?? undefined,
      customer_id: s.customer_id ?? undefined,
      media_uri: s.media_uri,
      caption: s.caption ?? undefined,
      created_at: toISOStringSafe(s.created_at),
    })),
  };
  return result;
}

