/**
 * Attach a new file to a comment (aimall_backend_attachments).
 *
 * Allows an authenticated customer to attach a file (image, doc, video) to
 * their own comment. Only the comment's owner can upload attachments. Only
 * whitelisted file types allowed and a strict 10MB size limit enforced. All
 * fields immutable with correct types.
 *
 * @param props - Request props
 * @param props.customer - Authenticated customer
 * @param props.commentId - Target comment UUID
 * @param props.body - Attachment data (file_uri, file_type, file_size)
 * @returns The created attachment record (IAimallBackendAttachment)
 * @throws {Error} When comment is not found, or not owned by the customer, or
 *   validation fails
 */
export async function post__aimall_backend_customer_comments_$commentId_attachments(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.ICreate;
}): Promise<IAimallBackendAttachment> {
  const { customer, commentId, body } = props;

  // 1. Find comment & check ownership
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: commentId },
    select: { customer_id: true },
  });
  if (!comment) throw new Error("Comment not found");
  if (!comment.customer_id || comment.customer_id !== customer.id) {
    throw new Error("Forbidden: customer does not own this comment");
  }

  // 2. File validation
  const allowedTypes = [/^image\//, /^video\//, /^application\/pdf$/];
  if (!allowedTypes.some((r) => r.test(body.file_type))) {
    throw new Error("Unsupported file_type: only images, video, PDF allowed");
  }
  const MAX_SIZE = 10 * 1024 * 1024;
  if (body.file_size > MAX_SIZE) {
    throw new Error("File too large: maximum is 10MB");
  }

  // 3. Create record (all fields inline; no intermediate variables)
  const created = await MyGlobal.prisma.aimall_backend_attachments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      post_id: null,
      comment_id: commentId,
      review_id: null,
      file_uri: body.file_uri,
      file_type: body.file_type,
      file_size: body.file_size,
      created_at: toISOStringSafe(new Date()),
    },
  });

  // 4. Return API DTO, all fields, date string as required
  return {
    id: created.id,
    post_id: created.post_id,
    comment_id: created.comment_id,
    review_id: created.review_id,
    file_uri: created.file_uri,
    file_type: created.file_type,
    file_size: created.file_size,
    created_at: toISOStringSafe(created.created_at),
  };
}

