/**
 * Permanently deletes a customer account by UUID (hard-delete).
 *
 * Only administrator users are authorized. This operation irreversibly removes
 * the customer from the database. Related PII in external records must be
 * anonymized in advance to meet compliance. An audit log is created for this
 * operation. If the customer does not exist, throws a 404 error.
 *
 * @param props.administrator Authenticated administrator user performing the
 *   deletion
 * @param props.customerId UUID of the customer account to delete
 * @returns No content
 * @throws {Error} When customer does not exist
 */
export async function delete__aimall_backend_administrator_customers_$customerId(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, customerId } = props;

  // Step 1: Confirm customer existence
  const customer = await MyGlobal.prisma.aimall_backend_customers.findUnique({
    where: { id: customerId },
  });
  if (customer === null) throw new Error("Customer not found");

  // Step 2: Hard delete customer account (no soft-delete)
  await MyGlobal.prisma.aimall_backend_customers.delete({
    where: { id: customerId },
  });

  // Step 3: Write audit log for destructive action
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "CUSTOMER_ACCOUNT_DELETE",
      event_target: customerId,
      ip_address: undefined,
      outcome: "SUCCESS",
      detail_json: JSON.stringify({
        action: "Customer hard deleted",
        deleted_customer_id: customerId,
        performed_by_admin_id: administrator.id,
        performed_at: toISOStringSafe(new Date()),
      }),
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Step 4: No content returned (void)
  return;
