import { IAimallBackendCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCategory";
import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * Create a new child category nested under the given parent
 * (aimall_backend_categories).
 *
 * This endpoint allows an authorized seller to create a child category directly
 * under a specified parent category. It ensures the (parent_id, name)
 * uniqueness constraint and calculates the correct depth (parent's depth + 1)
 * as required by the product taxonomy model.
 *
 * - Only administrator and seller roles are allowed to use this endpoint.
 * - The operation will fail if a sibling with the same name exists or if the
 *   parent category ID is invalid.
 *
 * @param props - The function parameters.
 * @param props.seller - Authenticated seller (authorization enforced
 *   externally).
 * @param props.categoryId - Parent category ID under which the child will be
 *   created.
 * @param props.body - Specification for the new category (name is required;
 *   depth is auto-calculated).
 * @returns The full IAimallBackendCategory object for the newly created
 *   category.
 * @throws {Error} If the parent category does not exist.
 * @throws {Error} If a sibling category with the same name already exists under
 *   this parent.
 */
export async function post__aimall_backend_seller_categories_$categoryId_childCategories(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.ICreate;
}): Promise<IAimallBackendCategory> {
  const { seller, categoryId, body } = props;

  // 1. Fetch parent category (ensure it exists, get depth)
  const parent = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!parent) throw new Error("Parent category not found");

  // 2. Enforce uniqueness of (parent_id, name) under same parent
  const exists = await MyGlobal.prisma.aimall_backend_categories.findFirst({
    where: {
      parent_id: categoryId,
      name: body.name,
    },
  });
  if (exists)
    throw new Error(
      "A sibling with this name already exists under this parent",
    );

  // 3. Generate ID & create the new category
  const created = await MyGlobal.prisma.aimall_backend_categories.create({
    data: {
      id: v4() as string & tags.Format<"uuid">, // Acceptable branding for uuid
      parent_id: categoryId,
      name: body.name,
      depth: parent.depth + 1,
    },
  });

  // 4. Return the DTO strictly typed (convert parent_id undefined to null per API)
  return {
    id: created.id,
    parent_id: created.parent_id ?? null,
    name: created.name,
    depth: created.depth,
  };
}

