 * @param props - The request properties
 * @param props.administrator - The authenticated administrator making the
 *   request
 * @param props.commentId - The parent comment's UUID to which the attachment
 *   must belong
 * @param props.attachmentId - The UUID of the attachment being updated
 * @param props.body - The fields to update (file_uri, file_type, file_size);
 *   any omitted field is not changed
 * @returns The updated attachment with all columns populated, including proper
 *   ISO date/time types
 * @throws {Error} If the attachment is not found for the given comment ID
 */
export async function put__aimall_backend_administrator_comments_$commentId_attachments_$attachmentId(props: {
