/**
 * Delete or archive a snapshot record linked to a review, using reviewId and
 * snapshotId for record identification.
 *
 * This function performs a hard delete from aimall_backend_snapshots because
 * there is NO deleted_at (soft delete) field defined in the schema. Only the
 * owner of the snapshot (customer) may perform this action, and
 * ownership/linkage are strictly validated.
 *
 * Algorithm:
 *
 * 1. Select the snapshot by `snapshotId`. If not found, throw 404.
 * 2. Validate that its `review_id` matches `reviewId`. If mismatch, throw 404 to
 *    avoid resource scanning.
 * 3. Check that the snapshot's `customer_id` equals the caller's customer.id. If
 *    not, throw 403.
 * 4. Perform hard delete.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (JWT, validated)
 * @param props.reviewId - The UUID of the product review the snapshot is
 *   attached to
 * @param props.snapshotId - The UUID of the snapshot to delete
 * @returns Void if deletion is successful
 * @throws {Error} 404 when the snapshot is not found or not linked to the
 *   specified review
 * @throws {Error} 403 when the snapshot is not owned by the requesting customer
 */
export async function delete__aimall_backend_customer_reviews_$reviewId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, reviewId, snapshotId } = props;
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
