/**
 * Retrieve details for a single snapshot attached to a review
 * (aimall_backend_snapshots).
 *
 * Returns all fields of a single snapshot record, belonging to a specified
 * review. Validates that the snapshot relates to the review's product. Returns
 * 404 if not found. Only the seller owning the product (of the review) can
 * retrieve this resource. Throws if snapshot is not part of the same product as
 * the review.
 *
 * @param props - Request parameter object
 * @param props.seller - Authenticated seller payload
 * @param props.reviewId - Unique review UUID
 * @param props.snapshotId - Unique snapshot UUID
 * @returns Detailed snapshot entity linked to the review
 * @throws {Error} If review or product or snapshot not found
 * @throws {Error} If seller does not own the product of the review (403)
 * @throws {Error} If snapshot does not relate to this review (404)
 */
export async function get__aimall_backend_seller_reviews_$reviewId_snapshots_$snapshotId(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendSnapshot> {
  const { seller, reviewId, snapshotId } = props;

  // 1. Fetch review (to get product association)
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
    select: { product_id: true },
  });
  if (!review) throw new Error("Review not found");

  // 2. Ensure the product belongs to the requesting seller
  const product = await MyGlobal.prisma.aimall_backend_products.findUnique({
    where: { id: review.product_id },
    select: { seller_id: true },
  });
  if (!product) throw new Error("Product not found for review");
  if (product.seller_id !== seller.id) throw new Error("Forbidden");

  // 3. Fetch the snapshot
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findUnique({
    where: { id: snapshotId },
    select: {
      id: true,
      product_id: true,
      post_id: true,
      customer_id: true,
      media_uri: true,
      caption: true,
      created_at: true,
    },
  });
  if (!snapshot) throw new Error("Snapshot not found");
  if (snapshot.product_id !== review.product_id)
    throw new Error(
      "Snapshot does not belong to this review (product mismatch)",
    );

  // 4. Map result to IAimallBackendSnapshot
  return {
    id: snapshot.id,
    product_id: snapshot.product_id ?? undefined,
    post_id: snapshot.post_id ?? undefined,
    customer_id: snapshot.customer_id ?? undefined,
    media_uri: snapshot.media_uri,
    caption: snapshot.caption ?? undefined,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

