    customer_id: updated.customer_id ?? null,
    code: updated.code,
    status: updated.status,
    issued_at: toISOStringSafe(updated.issued_at),
    expires_at: toISOStringSafe(updated.expires_at),
    redeemed_at: updated.redeemed_at
