import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAttachment";
import { IPageIAimallBackendAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendAttachment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Advanced search/filter for comment attachments (aimall_backend_attachments).
 *
 * Query/filter list of all attachments for a particular comment (by UUID). Only
 * attachments of comments belonging to the authenticated customer can be
 * listed. Supports advanced moderation scenarios, pagination, sorting, and
 * advanced filtering.
 *
 * @param props - Customer: authenticated customer, commentId: UUID, body:
 *   filter (IAimallBackendAttachment.IRequest)
 * @returns IPageIAimallBackendAttachment: paginated attachments list
 * @throws {Error} If comment does not belong to the customer
 */
export async function patch__aimall_backend_customer_comments_$commentId_attachments(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IRequest;
}): Promise<IPageIAimallBackendAttachment> {
  const { customer, commentId, body } = props;

  // Step 1: Ensure this comment belongs to the authenticated customer
  const comment =
    await MyGlobal.prisma.aimall_backend_comments.findUniqueOrThrow({
      where: { id: commentId },
      select: { customer_id: true },
    });
  if (comment.customer_id !== customer.id) {
    throw new Error(
      "Forbidden: You can only view your own comment attachments.",
    );
  }

  // Step 2: Pagination parameters
  const limit = body.limit ?? 20;
  const page = body.page ?? 1;
  const skip = (page - 1) * limit;

  // Step 3: Build filters (avoid spreading undefined)
  const fileSizeFilter =
    (body.file_size_min !== undefined && body.file_size_min !== null) ||
    (body.file_size_max !== undefined && body.file_size_max !== null)
      ? {
          ...(body.file_size_min !== undefined &&
            body.file_size_min !== null && { gte: body.file_size_min }),
          ...(body.file_size_max !== undefined &&
            body.file_size_max !== null && { lte: body.file_size_max }),
        }
      : undefined;

  const createdAtFilter =
    (body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          ...(body.created_from !== undefined &&
            body.created_from !== null && { gte: body.created_from }),
          ...(body.created_to !== undefined &&
            body.created_to !== null && { lte: body.created_to }),
        }
      : undefined;

  const where = {
    comment_id: commentId,
    ...(body.post_id !== undefined &&
      body.post_id !== null && { post_id: body.post_id }),
    ...(body.review_id !== undefined &&
      body.review_id !== null && { review_id: body.review_id }),
    ...(body.file_type !== undefined &&
      body.file_type !== null && { file_type: body.file_type }),
    ...(fileSizeFilter && { file_size: fileSizeFilter }),
    ...(createdAtFilter && { created_at: createdAtFilter }),
  };

  // Step 4: Query DB & total
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({ where }),
  ]);

  // Step 5: Map result
  const data = rows.map((row) => ({
    id: row.id,
    post_id: row.post_id ?? null,
    comment_id: row.comment_id ?? null,
    review_id: row.review_id ?? null,
    file_uri: row.file_uri,
    file_type: row.file_type,
    file_size: row.file_size,
    created_at: toISOStringSafe(row.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendOrderItem";
import { IPageIAimallBackendOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendOrderItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Allows advanced searching and filtering among all item lines of a specified
 * order (Order Items table). Enables queries such as filtering by product, SKU,
 * quantity, or item price. Supports pagination and complex search via request
 * body parameters. Results mirror the relation schema fields exactly. Only
 * accessible to actors with rights to the parent order (customer must be the
 * order owner).
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.orderId - UUID of the parent order whose items are being
 *   searched
 * @param props.body - Search/filter and pagination parameters for order items
 *   within the order
 * @returns Paginated search result for the order's items
 * @throws {Error} When the order does not exist or the customer does not have
 *   access
 */
export async function patch__aimall_backend_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrderItem.IRequest;
}): Promise<IPageIAimallBackendOrderItem> {
  const { customer, orderId, body } = props;

  // Authorization: must own this order
  const order = await MyGlobal.prisma.aimall_backend_orders.findFirst({
    where: { id: orderId, customer_id: customer.id },
  });
  if (!order) throw new Error("Order not found or access denied");

  // Pagination
  const limit = body.limit ?? 20;
  const page = body.page ?? 1;
  const skip = (page - 1) * limit;

  // WHERE clause
  const where = {
    order_id: orderId,
    ...(body.product_id !== undefined &&
      body.product_id !== null && { product_id: body.product_id }),
    ...(body.product_option_id !== undefined &&
      body.product_option_id !== null && {
        product_option_id: body.product_option_id,
      }),
    ...(body.item_name !== undefined &&
      body.item_name !== null && {
        item_name: { contains: body.item_name, mode: "insensitive" as const },
      }),
    ...((body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined &&
              body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined &&
              body.created_to !== null && { lte: body.created_to }),
          },
        }
      : {}),
  };

  // SORTING
  const validSortFields = ["created_at", "updated_at", "item_name"];
  const sortBy = validSortFields.includes(body.sort_by ?? "")
    ? body.sort_by
    : "created_at";
  const sortOrder = body.sort_order === "asc" ? "asc" : "desc";
  const orderBy = { [sortBy!]: sortOrder };

  // Main query and total count in parallel
  const [items, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_order_items.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_order_items.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items.map((row) => ({
      id: row.id,
      order_id: row.order_id,
      product_id: row.product_id,
      product_option_id: row.product_option_id ?? null,
      item_name: row.item_name,
      quantity: row.quantity,
      unit_price: row.unit_price,
      total_price: row.total_price,
      // add more fields if needed in future (but all API keys are covered)
    })),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
