import { IAimallBackendCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCoupon";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create or issue a new coupon for a specific discount campaign, using
 * aimall_backend_coupons.
 *
 * Issues a new coupon for a given discount campaign, ensuring code uniqueness
 * and administrator authorization. All date/time values are enforced as string
 * & tags.Format<'date-time'>, and UUIDs as string & tags.Format<'uuid'>. No
 * native Date type is used.
 *
 * @param props - Request properties containing the authorized administrator,
 *   campaign UUID, and coupon creation body.
 * @param props.administrator - The authenticated administrator payload (must be
 *   active).
 * @param props.discountCampaignId - The UUID of the target discount campaign.
 * @param props.body - Coupon creation input including code, expiry, status,
 *   issued_at, and optional customer assignment.
 * @returns The full coupon object of type IAimallBackendCoupon, matching
 *   persisted database state.
 * @throws {Error} If administrator is not active
 * @throws {Error} If a coupon with the same code already exists
 */
export async function post__aimall_backend_administrator_discountCampaigns_$discountCampaignId_coupons(props: {
  administrator: AdministratorPayload;
  discountCampaignId: string & tags.Format<"uuid">;
  body: IAimallBackendCoupon.ICreate;
}): Promise<IAimallBackendCoupon> {
  const { administrator, discountCampaignId, body } = props;

  if (administrator.status !== "active") {
    throw new Error("Administrator is not active");
  }

  const duplicate = await MyGlobal.prisma.aimall_backend_coupons.findFirst({
    where: { code: body.code },
    select: { id: true },
  });
  if (duplicate) {
    throw new Error("Coupon code must be unique");
  }

  const created = await MyGlobal.prisma.aimall_backend_coupons.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      discount_campaign_id: discountCampaignId,
      customer_id: body.customer_id ?? null,
      code: body.code,
      status: body.status,
      issued_at: body.issued_at,
      expires_at: body.expires_at,
    },
  });

  return {
    id: created.id as string & tags.Format<"uuid">,
    discount_campaign_id: created.discount_campaign_id as string &
      tags.Format<"uuid">,
    customer_id: (typeof created.customer_id === "string"
      ? created.customer_id
      : null) as (string & tags.Format<"uuid">) | null,
    code: created.code,
    status: created.status,
    issued_at: created.issued_at as string & tags.Format<"date-time">,
    expires_at: created.expires_at as string & tags.Format<"date-time">,
    redeemed_at:
      created.redeemed_at !== null && created.redeemed_at !== undefined
        ? (created.redeemed_at as string & tags.Format<"date-time">)
        : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Add a new item to a shopping cart (aimall_backend_cart_items).
 *
 * Adds a new item to an existing shopping cart, verifying customer ownership
 * and enforcing uniqueness on the (cart, product, option, SKU) combination for
 * cart items. Throws an error if a same-combination item already exists or if
 * the cart does not belong to the requesting customer.
 *
 * Follows all API contract and TypeScript branding requirements:
 *
 * - No native Date type, all date values use string & tags.Format<'date-time'>
 * - No 'as' type assertions; proper type propagation or validation only
 * - UUIDs generated with v4(), timestamps with toISOStringSafe
 *
 * @param props - Function argument object
 * @param props.customer - JWT payload for authenticated customer
 * @param props.cartId - UUID of the cart in which to add the item
 * @param props.body - Cart item details per IAimallBackendCartItem.ICreate
 * @returns The newly created IAimallBackendCartItem with all properties
 * @throws {Error} When the cart does not exist, is not owned by the customer,
 *   or a duplicate item with the same combination exists in the cart
 */
export async function post__aimall_backend_customer_carts_$cartId_cartItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IAimallBackendCartItem.ICreate;
}): Promise<IAimallBackendCartItem> {
  const { customer, cartId, body } = props;

  // Step 1: Validate cart ownership
  const cart = await MyGlobal.prisma.aimall_backend_carts.findUnique({
    where: { id: cartId },
    select: { aimall_backend_customer_id: true },
  });
  if (!cart || cart.aimall_backend_customer_id !== customer.id) {
    throw new Error(
      "Unauthorized: Cart does not exist or does not belong to this customer.",
    );
  }

  // Step 2: Prevent duplicates for composite unique key
  const duplicate = await MyGlobal.prisma.aimall_backend_cart_items.findFirst({
    where: {
      aimall_backend_cart_id: cartId,
      aimall_backend_product_id: body.aimall_backend_product_id,
      aimall_backend_product_option_id:
        body.aimall_backend_product_option_id ?? undefined,
      aimall_backend_sku_id: body.aimall_backend_sku_id ?? undefined,
    },
    select: { id: true },
  });
  if (duplicate) {
    throw new Error(
      "Duplicate cart item: An item with this product, option, and SKU already exists in this cart.",
    );
  }

  // Step 3: Prepare new cart item details
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());
  const id: string & tags.Format<"uuid"> = v4();

  // Step 4: Create the cart item and format result properly
  const created = await MyGlobal.prisma.aimall_backend_cart_items.create({
    data: {
      id,
      aimall_backend_cart_id: cartId,
      aimall_backend_product_id: body.aimall_backend_product_id,
      aimall_backend_product_option_id:
        body.aimall_backend_product_option_id ?? null,
      aimall_backend_sku_id: body.aimall_backend_sku_id ?? null,
      quantity: body.quantity,
      unit_price_snapshot: body.unit_price_snapshot,
      discount_snapshot: body.discount_snapshot ?? null,
      selected_name_display: body.selected_name_display ?? null,
      created_at: now,
      updated_at: now,
    },
  });

  // Step 5: Return full result with correct date and uuid branding
  return {
    ...created,
    id,
    created_at: now,
    updated_at: now,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendAddress";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Register a new delivery address for the specified customer by customerId.
 *
 * The operation inserts a normalized address record into
 * aimall_backend_addresses, enforcing referential integrity and uniqueness
 * constraints as defined in the schema.
 *
 * Only the account owner (customer) or administrative actors may use this
 * endpoint. The implementation ensures the new address is strictly associated
 * with the user in path parameter. If is_default is specified, the API ensures
 * it's the only default for the customer by unsetting others.
 *
 * Related endpoints: PUT for address updates, GET for address retrieval. Errors
 * include invalid input, exceeding allowed addresses, or access violations.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   operation (injected via AdministratorAuth decorator)
 * @param props.customerId - The unique identifier (UUID) of the customer for
 *   whom the address is being added
 * @param props.body - Address creation details conforming to
 *   IAimallBackendAddress.ICreate
 * @returns The newly created address record as stored in the database
 * @throws {Error} When the customer does not exist
 * @throws {Error} When maximum allowed addresses per customer is exceeded
 */
export async function post__aimall_backend_administrator_customers_$customerId_addresses(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAimallBackendAddress.ICreate;
}): Promise<IAimallBackendAddress> {
  const { administrator, customerId, body } = props;

  // 1. Ensure the customer exists
  await MyGlobal.prisma.aimall_backend_customers.findUniqueOrThrow({
    where: { id: customerId },
    select: { id: true },
  });

  // 2. Enforce maximum allowed addresses for customer (limit 10)
  const addressCount = await MyGlobal.prisma.aimall_backend_addresses.count({
    where: { customer_id: customerId },
  });
  if (addressCount >= 10)
    throw new Error("Maximum allowed addresses exceeded for customer.");

  // 3. If is_default is true, unset all existing default addresses for this customer (atomic step)
  const now = toISOStringSafe(new Date());
  if (body.is_default) {
    await MyGlobal.prisma.aimall_backend_addresses.updateMany({
      where: { customer_id: customerId, is_default: true },
      data: {
        is_default: false,
        updated_at: now,
      },
    });
  }

  // 4. Insert new address row
  const created = await MyGlobal.prisma.aimall_backend_addresses.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      customer_id: customerId,
      alias: body.alias,
      recipient_name: body.recipient_name,
      phone: body.phone,
      address_line1: body.address_line1,
      address_line2: body.address_line2 ?? undefined,
      city: body.city,
      postal_code: body.postal_code,
      country: body.country,
      is_default: body.is_default,
      updated_at: now,
    },
    select: {
      id: true,
      customer_id: true,
      alias: true,
      recipient_name: true,
      phone: true,
      address_line1: true,
      address_line2: true,
      city: true,
      postal_code: true,
      country: true,
      is_default: true,
      updated_at: true,
    },
  });

  // 5. Return mapped (strict) DTO (ensure all date strings are branded)
  return {
    id: created.id,
    customer_id: created.customer_id,
    alias: created.alias,
    recipient_name: created.recipient_name,
    phone: created.phone,
    address_line1: created.address_line1,
    address_line2: created.address_line2,
    city: created.city,
    postal_code: created.postal_code,
    country: created.country,
    is_default: created.is_default,
    updated_at: toISOStringSafe(created.updated_at),
  };
}

