import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendComment";
import { IPageIAimallBackendComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendComment";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

/**
 * Enables advanced search and paginated results for comments where 'parent_id'
 * is the given commentId. Supports filters by author, privacy, created_at, and
 * free-text in body. Ensures customers see only public comments or their own
 * private comments. Soft-deleted comments are always excluded.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer payload
 * @param props.commentId - The UUID of the parent comment whose child comments
 *   are to be searched
 * @param props.body - Search and filter criteria for finding child comments
 *   (author, privacy, date, keyword, pagination)
 * @returns Filtered, paginated list of child comments matching the search
 *   criteria.
 * @throws {Error} If the commentId is invalid, or for internal database errors
 */
export async function patch__aimall_backend_customer_comments_$commentId_comments(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IRequest;
}): Promise<IPageIAimallBackendComment> {
  const { customer, commentId, body } = props;
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;

  const where = {
    parent_id: commentId,
    deleted_at: null,
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(body.is_private !== undefined &&
      body.is_private !== null && { is_private: body.is_private }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
    (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined &&
              body.created_at_from !== null && { gte: body.created_at_from }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && { lte: body.created_at_to }),
          },
        }
      : {}),
    ...(body.body && {
      body: {
        contains: body.body,
        mode: "insensitive" as const,
      },
    }),
    OR: [{ is_private: false }, { is_private: true, customer_id: customer.id }],
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_comments.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
      id: row.id,
      post_id: row.post_id ?? null,
      review_id: row.review_id ?? null,
