/**
 * Updates an order's details by its ID (for the owning seller).
 *
 * Allows a seller to update permitted fields of an existing order, enforcing
 * strict authentication, authorization, and immutability if the order is
 * archived.
 *
 * - Only the owning seller may update their order (checked via seller_id).
 * - All changes are blocked if the order is archived (archived_at is not null).
 * - Only permitted fields (address_id, order_status, total_amount, currency,
 *   updated_at) can be updated.
 * - All date and UUID values are handled with strict branding and conversion.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request (must match
 *   order's seller_id)
 * @param props.orderId - UUID of the order to update
 * @param props.body - The update fields allowed to be changed
 * @returns The fully updated order, with all fields strictly branded and
 *   compliant
 * @throws {Error} When the order does not exist
 * @throws {Error} When the seller does not own the order
 * @throws {Error} When the order is archived
 */
export async function put__aimall_backend_seller_orders_$orderId(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IAimallBackendOrder.IUpdate;
}): Promise<IAimallBackendOrder> {
  const { seller, orderId, body } = props;

  const order = await MyGlobal.prisma.aimall_backend_orders.findUnique({
    where: { id: orderId },
  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id)
    throw new Error("Forbidden: not your order");
  if (order.archived_at !== null)
    throw new Error("Order is archived and cannot be modified");

  // Prepare update fields inline (null/undefined handling as required per API)
  const updated = await MyGlobal.prisma.aimall_backend_orders.update({
    where: { id: orderId },
    data: {
      address_id: body.address_id ?? undefined,
      order_status: body.order_status ?? undefined,
      total_amount: body.total_amount ?? undefined,
      currency: body.currency ?? undefined,
      updated_at: toISOStringSafe(body.updated_at),
    },
  });

  return {
    id: updated.id,
    customer_id: updated.customer_id,
    seller_id: updated.seller_id,
    address_id: updated.address_id,
    order_number: updated.order_number,
    order_status: updated.order_status,
    total_amount: updated.total_amount,
    currency: updated.currency,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    archived_at:
      updated.archived_at !== null
        ? toISOStringSafe(updated.archived_at)
        : null,
  };
}

