/**
 * Retrieve all delivery addresses for a customer (aimall_backend_addresses).
 *
 * Fetches all delivery addresses for a given customer as stored in the
 * aimall_backend_addresses table. Each address includes details such as alias,
 * recipient name, phone, address lines, city, postal code, country, is_default
 * flag, and update timestamp.
 *
 * Requires administrator authentication—only administrators can use this
 * function. Returns an empty list if customer has no addresses. Throws an error
 * if customer does not exist.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator making the
 *   request
 * @param props.customerId - UUID of the customer to retrieve addresses for
 * @returns Paginated list (single page) of all delivery addresses for the
 *   customer
 * @throws {Error} If specified customer does not exist
 */
export async function get__aimall_backend_administrator_customers_$customerId_addresses(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendAddress> {
  const { administrator, customerId } = props;

  // Step 1: Ensure customer exists
  const customer = await MyGlobal.prisma.aimall_backend_customers.findUnique({
    where: { id: customerId },
  });
  if (!customer) throw new Error("Customer does not exist");

  // Step 2: Retrieve all addresses for the given customer
  const addresses = await MyGlobal.prisma.aimall_backend_addresses.findMany({
    where: { customer_id: customerId },
    orderBy: { updated_at: "desc" },
  });

  // Step 3: Map to IAimallBackendAddress[] with formatted dates
  const data: IAimallBackendAddress[] = addresses.map((addr) => {
    const address: IAimallBackendAddress = {
      id: addr.id,
      customer_id: addr.customer_id,
      alias: addr.alias,
      recipient_name: addr.recipient_name,
      phone: addr.phone,
      address_line1: addr.address_line1,
      city: addr.city,
      postal_code: addr.postal_code,
      country: addr.country,
      is_default: addr.is_default,
      updated_at: toISOStringSafe(addr.updated_at),
    };
    if (addr.address_line2 !== undefined && addr.address_line2 !== null) {
      address.address_line2 = addr.address_line2;
    }
    return address;
  });

  // Step 4: Return single-page pagination with all addresses
  return {
    pagination: {
      current: 1 as number & tags.Type<"int32">,
      limit: data.length as number & tags.Type<"int32">,
      records: data.length as number & tags.Type<"int32">,
      pages: 1 as number & tags.Type<"int32">,
    },
    data,
  };
}

