/**
 * Retrieves all attachments for a community post by postId, for sellers
 * (moderation/overview).
 *
 * This endpoint returns all media/file attachment records belonging to the
 * specified post. Sellers can retrieve attachments for moderation or rendering
 * purposes. Pagination is fixed to page 1, limit 50, sorted by most recent
 * first.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller account context for
 *   authorization/audit
 * @param props.postId - UUID of the post for which attachments are fetched
 * @returns Paginated list of attachments (IPageIAimallBackendAttachment) for
 *   that post
 * @throws {Error} When the post does not exist
 */
export async function get__aimall_backend_seller_posts_$postId_attachments(props: {
  seller: SellerPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendAttachment> {
  const { seller, postId } = props;
  // Step 1: Check the post exists. Sellers do not "own" posts per schema.
  const post = await MyGlobal.prisma.aimall_backend_posts.findFirst({
    where: { id: postId },
  });
  if (!post) {
    throw new Error("Post not found");
  }
  // Step 2: Fetch paged attachments for the post (static page 1, limit 50)
  const page = 1;
  const limit = 50;
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where: { post_id: postId },
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({
      where: { post_id: postId },
    }),
  ]);
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: rows.map((raw) => ({
      id: raw.id,
      post_id: raw.post_id,
      comment_id: raw.comment_id,
      review_id: raw.review_id,
      file_uri: raw.file_uri,
      file_type: raw.file_type,
      file_size: raw.file_size,
      created_at: toISOStringSafe(raw.created_at),
    })),
  };
}

