 *   expiry, and initial status.
 * - Enforces uniqueness and campaign-level issuance rules as per platform
 *   business logic.
 * - Only administrators with active status may invoke.
 * - Dates must be string & tags.Format<'date-time'>, not Date.
 * - UUIDs use v4() and must be branded as string & tags.Format<'uuid'>.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator (must be
 *   active).
 * @param props.discountCampaignId - Unique identifier of the discount campaign
 *   for which the coupon is issued.
 * @param props.body - Coupon creation information, including code/status and
 *   possible customer association.
 * @returns The resulting coupon entity after creation.
 * @throws {Error} If administrator is not active or coupon code is duplicated.
 */
export async function post__aimall_backend_administrator_discountCampaigns_$discountCampaignId_coupons(props: {
  administrator: AdministratorPayload;
  discountCampaignId: string & tags.Format<"uuid">;
  body: IAimallBackendCoupon.ICreate;
}): Promise<IAimallBackendCoupon> {
