import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Permanently remove a coupon redemption event (hard delete).
 *
 * Hard delete of a coupon redemption record from the event/audit log. Only
 * available to admin/support roles with permissible access. Not permitted for
 * resolved/closed/caseful fraud events. Immediate removal from underlying
 * storage. Tracks the operation for auditing. Returns no content.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator performing the
 *   operation
 * @param props.couponId - Coupon under which the redemption event is deleted
 *   (UUID)
 * @param props.couponRedemptionId - Redemption event unique identifier to
 *   delete (UUID)
 * @returns Void
 * @throws {Error} When coupon redemption event does not exist or is locked by
 *   status
 */
export async function delete__aimall_backend_administrator_coupons_$couponId_couponRedemptions_$couponRedemptionId(props: {
  administrator: AdministratorPayload;
  couponId: string & tags.Format<"uuid">;
  couponRedemptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, couponId, couponRedemptionId } = props;

  // 1. Find and verify coupon redemption event belongs to the provided coupon
  const redemption =
    await MyGlobal.prisma.aimall_backend_coupon_redemptions.findFirst({
      where: { id: couponRedemptionId, coupon_id: couponId },
    });
  if (!redemption) {
    throw new Error("Coupon redemption event not found for the given coupon.");
  }

  // 2. Block deletion if the status is forbidden
  if (
    ["resolved", "closed", "caseful_fraud"].includes(
      redemption.redemption_status,
    )
  ) {
    throw new Error(
      "This coupon redemption event is locked and cannot be deleted.",
    );
  }

  // 3. Perform hard delete
  await MyGlobal.prisma.aimall_backend_coupon_redemptions.delete({
    where: { id: couponRedemptionId },
  });

  // 4. Log the deletion for compliance
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "COUPON_REDEMPTION_DELETE",
      event_target: couponRedemptionId,
      outcome: "SUCCESS",
      created_at: toISOStringSafe(new Date()),
    },
  });
  // No return
}

