 * This endpoint supports admin-facing scenarios and is restricted to
 * authenticated administrators. Soft-deleted comments (deleted_at not null) are
 * always excluded from result sets in compliance with audit requirements.
 *
 * @param props -
 * @param props.administrator - The authenticated administrator payload
 *   (required for admin access).
 * @param props.commentId - The UUID of the parent comment whose child comments
 *   are to be searched.
 * @param props.body - Search and filter criteria for finding child comments
 *   (author, privacy, date, keyword, pagination).
 * @returns Paginated, filtered list of child comments matching the search
 *   criteria and all compliance rules.
 * @throws {Error} When inappropriate parameter values or DB errors occur.
 */
export async function patch__aimall_backend_administrator_comments_$commentId_comments(props: {
  administrator: AdministratorPayload;
  commentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IRequest;
}): Promise<IPageIAimallBackendComment> {
  const { commentId, body } = props;
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Build where clause for filtering child comments
  const where = {
    parent_id: commentId,
    deleted_at: null,
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && {
        customer_id: body.customer_id,
      }),
    ...(body.is_private !== undefined &&
      body.is_private !== null && {
        is_private: body.is_private,
      }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
    (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined &&
              body.created_at_from !== null && {
                gte: body.created_at_from,
              }),
            ...(body.created_at_to !== undefined &&
              body.created_at_to !== null && {
                lte: body.created_at_to,
              }),
          },
        }
      : {}),
    // Text search for comment body if field is present
    ...(typeof (body as any).body === "string" &&
      (body as any).body.length > 0 && {
        body: { contains: (body as any).body, mode: "insensitive" as const },
      }),
  };

  const [records, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_comments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_comments.count({ where }),
  ]);

  const data = records.map((rec) => ({
    id: rec.id,
    post_id: rec.post_id ?? null,
    review_id: rec.review_id ?? null,
    parent_id: rec.parent_id ?? null,
    customer_id: rec.customer_id ?? null,
    body: rec.body,
    is_private: rec.is_private,
    created_at: toISOStringSafe(rec.created_at),
    updated_at: toISOStringSafe(rec.updated_at),
    deleted_at: rec.deleted_at ? toISOStringSafe(rec.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

