/**
 * Retrieves all platform channels (aimall_backend_channels) for administrative
 * use.
 *
 * This operation is restricted to authenticated administrators and returns a
 * paginated list of all channels currently defined in the platform, including
 * internal identifiers, codes, display names, enabled flags, and audit
 * timestamps. No denormalized fields are present; response strictly matches the
 * business entity as defined in the database schema and DTO.
 *
 * @param props - The request properties.
 * @param props.administrator - The authenticated administrator performing the
 *   operation.
 * @returns Paginated channel entities and page metadata.
 * @throws {Error} If a database or infrastructure error occurs.
 */
export async function get__aimall_backend_administrator_channels(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendChannel> {
  // Retrieve all channel records from database
  const channels = await MyGlobal.prisma.aimall_backend_channels.findMany({
    orderBy: { created_at: "asc" },
  });

  // Map and transform return type: no Date (use toISOStringSafe), fully branded
  const data = channels.map((ch) => ({
    id: ch.id,
    code: ch.code,
    name: ch.name,
    enabled: ch.enabled,
    created_at: toISOStringSafe(ch.created_at),
    updated_at: toISOStringSafe(ch.updated_at),
  }));

  // Calculate pagination (single page)
  const pagination = {
    current: 1,
    limit: channels.length as number & tags.Type<"int32">,
    records: channels.length as number & tags.Type<"int32">,
    pages: 1 as number & tags.Type<"int32">,
  };

  return {
    pagination,
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
