 */
export async function patch__aimall_backend_administrator_channels_$channelId_sections(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  body: IAimallBackendSection.IRequest;
}): Promise<IPageIAimallBackendSection> {
  const { administrator, channelId, body } = props;

  // Must be active administrator
  if (administrator.status !== "active") {
    throw new Error("Unauthorized: Administrator account is not active");
  }

  // Normalize pagination (page>=1, default 1; limit default 100)
  const page: number & tags.Type<"int32"> =
