/**
 * 소프트 삭제: 채널 하위의 섹션을 논리적으로 삭제합니다.
 *
 * 이 함수는 특정 채널과 섹션 ID로 주어진 섹션을 소프트 삭제(논리 삭제)합니다. '삭제'란 실제 레코드 삭제가 아닌 deleted_at
 * 필드를 현재 시각으로 마킹하는 것을 의미합니다. 섹션이 존재하지 않거나 이미 삭제된 경우, 또는 채널이 일치하지 않으면 404 에러를
 * 반환합니다. 삭제 이벤트는 aimall_backend_audit_logs에 감사 로그로 남깁니다.
 *
 * @param props - 요청 파라미터
 * @param props.administrator - 인증된 관리자 페이로드
 * @param props.channelId - 소속 채널 UUID
 * @param props.sectionId - 삭제 대상 섹션 UUID
 * @returns 없음(void)
 * @throws {Error} 섹션이 존재하지 않거나 이미 삭제된 경우 (404)
 */
export async function delete__aimall_backend_administrator_channels_$channelId_sections_$sectionId(props: {
  administrator: AdministratorPayload;
  channelId: string & tags.Format<"uuid">;
  sectionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, channelId, sectionId } = props;

  // 1. 삭제 전 대상을 검증한다 (존재, 채널 일치, 삭제 안됨)
  const section = await MyGlobal.prisma.aimall_backend_sections.findFirst({
    where: {
      id: sectionId,
      channel_id: channelId,
      deleted_at: null,
    },
  });
  if (!section) {
    const err = new Error("Section not found");
    (err as any).status = 404;
    throw err;
  }

  // 2. 현재 시각 ISO 문자열 준비
  const now = toISOStringSafe(new Date());

  // 3. 소프트 삭제 처리
  await MyGlobal.prisma.aimall_backend_sections.update({
    where: { id: sectionId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });

  // 4. 감사 로그 기록
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: administrator.id,
      event_type: "SECTION_DELETE",
      event_target: sectionId,
      outcome: "SUCCESS",
      detail_json: JSON.stringify({ channelId }),
      created_at: now,
    },
  });

  // 5. 반환 없음
  return;
}

