/**
 * Updates a customer account with the given fields.
 *
 * This endpoint allows administrators to update fields of an existing customer
 * account, supporting mutation of email, phone, password_hash, and status.
 * Unique constraints for email and phone are enforced. The operation fails if
 * updating to a value that is already assigned to another customer. All updates
 * automatically set the audit field `updated_at` to the current time (ISO 8601
 * string).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   active)
 * @param props.customerId - Target customer UUID to update
 * @param props.body - Partial updated fields per IAimallBackendCustomer.IUpdate
 *   DTO
 * @returns The updated IAimallBackendCustomer entity (all fields, never Date
 *   type)
 * @throws {Error} If the customer does not exist
 * @throws {Error} If email or phone is already used by another account
 */
export async function put__aimall_backend_administrator_customers_$customerId(props: {
  administrator: AdministratorPayload;
  customerId: string & tags.Format<"uuid">;
  body: IAimallBackendCustomer.IUpdate;
}): Promise<IAimallBackendCustomer> {
  const { administrator, customerId, body } = props;

  // STEP 1: Fetch the customer to ensure existence
  const customer = await MyGlobal.prisma.aimall_backend_customers.findUnique({
    where: { id: customerId },
  });
  if (!customer) throw new Error("Customer not found");

  // STEP 2: If updating email, ensure uniqueness
  if (
    body.email !== undefined &&
    body.email !== null &&
    body.email !== customer.email
  ) {
    const exists = await MyGlobal.prisma.aimall_backend_customers.findFirst({
      where: { email: body.email, id: { not: customerId } },
    });
    if (exists) throw new Error("Email already in use by another customer");
  }

  // STEP 3: If updating phone, ensure uniqueness
  if (
    body.phone !== undefined &&
    body.phone !== null &&
    body.phone !== customer.phone
  ) {
    const exists = await MyGlobal.prisma.aimall_backend_customers.findFirst({
      where: { phone: body.phone, id: { not: customerId } },
    });
    if (exists) throw new Error("Phone already in use by another customer");
  }

  // STEP 4: Update customer with provided fields and audit timestamp
  const now = toISOStringSafe(new Date());
  const updated = await MyGlobal.prisma.aimall_backend_customers.update({
    where: { id: customerId },
    data: {
      email: body.email ?? undefined,
      phone: body.phone ?? undefined,
      password_hash: body.password_hash ?? undefined,
      status: body.status ?? undefined,
      updated_at: now,
    },
  });

  // STEP 5: Return complete customer entity (convert date fields to string format)
  return {
    id: updated.id,
    email: updated.email,
    phone: updated.phone,
    password_hash: updated.password_hash,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: now,
  };
}

