/**
 * Search, filter, and paginate the list of sellers.
 *
 * This endpoint returns a pageable, filterable, and search-capable list of
 * sellers (`aimall_backend_sellers`) for system administrators. Allows
 * filtering on business name (partial, case-insensitive), status, email, and
 * registration date range. Supports pagination and returns page metadata.
 *
 * Only available to authenticated administrators (must have status='active').
 *
 * @param props - Request parameters
 * @param props.administrator - Authenticated administrator payload
 * @param props.body - Filter and pagination payload matching
 *   `IAimallBackendSeller.IRequest`
 * @returns Paginated/filtered result as `IPageIAimallBackendSeller`
 * @throws {Error} When the user is not an active administrator or supplies
 *   invalid input
 */
export async function patch__aimall_backend_administrator_sellers(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendSeller.IRequest;
}): Promise<IPageIAimallBackendSeller> {
  const { administrator, body } = props;

  // Authorization: Only allow active administrators
  if (administrator.status !== "active") {
    throw new Error("Administrator access denied: inactive or unauthorized");
  }

  // Extract safe paging
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  const where = {
    ...(body.business_name !== undefined &&
      body.business_name.length > 0 && {
        business_name: {
          contains: body.business_name,
          mode: "insensitive" as const,
        },
      }),
    ...(body.email !== undefined &&
      body.email.length > 0 && {
        email: { contains: body.email, mode: "insensitive" as const },
      }),
    ...(body.status !== undefined &&
      body.status.length > 0 && {
        status: body.status,
      }),
    ...((body.created_at_gte !== undefined ||
      body.created_at_lte !== undefined) && {
      created_at: {
        ...(body.created_at_gte !== undefined && { gte: body.created_at_gte }),
        ...(body.created_at_lte !== undefined && { lte: body.created_at_lte }),
      },
    }),
  };

  // Fetch paged data and count in parallel
  const [rows, records] = await Promise.all([
    MyGlobal.prisma.aimall_backend_sellers.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_sellers.count({ where }),
  ]);

  // Transform to IAimallBackendSeller structure with correct date strings
  const data = rows.map((row) => ({
    id: row.id,
    business_name: row.business_name,
    email: row.email,
    contact_phone: row.contact_phone,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records,
      pages: Math.ceil(records / limit),
    },
    data,
  };
}

