import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Update a seller's data (aimall_backend_sellers).
 *
 * Update the details of an existing seller. Supply the sellerId and update
 * fields to apply. This directly modifies aimall_backend_sellers fields for the
 * record. Only admins may perform this operation (authenticated by
 * AdministratorPayload).
 *
 * Role constraints: only admin may edit other sellers; self-edit requires owner
 * match. Changes are moderated for compliance if necessary.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator performing the
 *   operation
 * @param props.sellerId - The UUID of the seller to update
 * @param props.body - Fields and values to update (full overwrite)
 * @returns The updated seller record after changes have been committed
 * @throws {Error} If sellerId does not exist or update fails
 */
export async function put__aimall_backend_administrator_sellers_$sellerId(props: {
  administrator: AdministratorPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IAimallBackendSeller.IUpdate;
}): Promise<IAimallBackendSeller> {
  const { sellerId, body } = props;

  // 1. Ensure the seller exists (findUnique)
  const seller = await MyGlobal.prisma.aimall_backend_sellers.findUnique({
    where: { id: sellerId },
  });
  if (!seller) throw new Error("Seller not found");

  // 2. Update the seller with provided details
  const updated = await MyGlobal.prisma.aimall_backend_sellers.update({
    where: { id: sellerId },
    data: {
      business_name: body.business_name,
      email: body.email,
      contact_phone: body.contact_phone,
      status: body.status,
      updated_at: body.updated_at, // input is string & tags.Format<'date-time'>
    },
  });

  // 3. Return the updated seller, normalizing all date fields
  return {
    id: updated.id,
    business_name: updated.business_name,
    email: updated.email,
    contact_phone: updated.contact_phone,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

