 *
 * 주어진 sellerId로 판매자 계정을 삭제합니다. 이 작업은 aimall_backend_sellers 테이블에서 행을 직접 삭제하며,
 * 소프트 삭제 필드는 존재하지 않습니다.
 *
 * 오직 관리자(administrator)만 삭제 권한이 있습니다. 연관 데이터(상품, 주문 등)는 별도 비즈니스 규칙에 따라 시스템에서
 * 무결성 보장이 필요합니다.
 *
 * @param props - 요청 속성
 * @param props.administrator - 삭제를 수행하는 인증된 관리자 페이로드
 * @param props.sellerId - 삭제 대상 판매자 계정의 UUID
 * @returns 없음(void). 삭제 성공 시 아무 것도 반환하지 않습니다.
 * @throws {Error} 대상 판매자를 찾을 수 없을 때
 * @throws {Error} 관리자 권한이 없는 경우(실제로는 데코레이터로 사전 검증됨)
 */
export async function delete__aimall_backend_administrator_sellers_$sellerId(props: {
  administrator: AdministratorPayload;
  sellerId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, sellerId } = props;

  // 관리자 권한 체크: 데코레이터로 인증받지만 추가로 재확인
  if (!administrator || administrator.type !== "administrator") {
    throw new Error("권한 없음: 관리자만 판매자를 삭제할 수 있습니다.");
  }

  // 판매자 존재 여부 확인 (없으면 에러 반환)
  const seller = await MyGlobal.prisma.aimall_backend_sellers.findUnique({
    where: { id: sellerId },
  });
  if (!seller) {
    throw new Error("판매자를 찾을 수 없습니다.");
  }

  // 하드 삭제 실행
  await MyGlobal.prisma.aimall_backend_sellers.delete({
    where: { id: sellerId },
  });
}

