import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Create a new platform administrator account (Actors domain).
 *
 * Creates a new administrator account, referencing the
 * aimall_backend_administrators schema. Only authenticated super administrators
 * or permission managers may invoke this operation (authorization handled
 * upstream).
 *
 * On successful creation, an audit log entry is recorded as required by
 * compliance. Account status can be set via input (active, pending, etc).
 * Sensitive credentials such as password are managed externally and not part of
 * this operation.
 *
 * @param props - Request properties
 * @param props.administrator - The currently authenticated administrator
 *   performing the creation
 * @param props.body - Administrator account data: permission_id, email, display
 *   name, and status
 * @returns The newly created administrator resource as confirmation and for
 *   profile display
 * @throws {Error} If the email is already used, permission_id is invalid, or
 *   database errors occur
 */
export async function post__aimall_backend_administrator_administrators(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAdministrator.ICreate;
}): Promise<IAimallBackendAdministrator> {
  const now = toISOStringSafe(new Date());

  // Create administrator record
  const created = await MyGlobal.prisma.aimall_backend_administrators.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      permission_id: props.body.permission_id,
      email: props.body.email,
      name: props.body.name,
      status: props.body.status,
      created_at: now,
      updated_at: now,
    },
  });

  // Write audit log for compliance
  await MyGlobal.prisma.aimall_backend_audit_logs.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      actor_id: props.administrator.id,
      event_type: "ADMIN_CREATE",
      event_target: props.body.email,
      outcome: "SUCCESS",
      created_at: now,
    },
  });

  // Return full administrator profile resource
  return {
    id: created.id,
    permission_id: created.permission_id,
    email: created.email,
    name: created.name,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

