/**
 * Update an AIMall administrator record (Actors domain).
 *
 * Update an administrator record's information for an existing platform admin
 * account identified by administratorId. The request body includes new values
 * for permission_id, name, status, and may include email if required. Business
 * logic ensures that changes are allowed only by admins with sufficient
 * permission. All changes are logged for compliance, supporting security
 * reviews or escalation.
 *
 * The update operation never modifies sensitive authentication data (like
 * password), which is handled via dedicated flows. The response returns the
 * updated administrator record including all main attributes and audit
 * information for display or further inspection.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator making the request
 * @param props.administratorId - UUID of the administrator to update
 * @param props.body - Fields to update: permission_id, email, name, status,
 *   updated_at
 * @returns The updated administrator record
 * @throws {Error} When the target administrator does not exist or admin
 *   attempts to self-escalate permission
 */
export async function put__aimall_backend_administrator_administrators_$administratorId(props: {
  administrator: AdministratorPayload;
  administratorId: string & tags.Format<"uuid">;
  body: IAimallBackendAdministrator.IUpdate;
}): Promise<IAimallBackendAdministrator> {
  const { administrator, administratorId, body } = props;

  // Security: cannot self-elevate permission/role
  if (
    administrator.id === administratorId &&
    administrator.permission_id !== body.permission_id
  ) {
    throw new Error("Administrators may not update their own permission/role.");
  }

  // Fetch the target administrator
  const target = await MyGlobal.prisma.aimall_backend_administrators.findUnique(
    {
      where: { id: administratorId },
    },
  );
  if (!target) {
    throw new Error("Administrator not found.");
  }

  // Optionally, verify permission hierarchy rules here (not implemented)

  // Execute the update
  const updated = await MyGlobal.prisma.aimall_backend_administrators.update({
    where: { id: administratorId },
    data: {
      permission_id: body.permission_id,
      email: body.email,
      name: body.name,
      status: body.status,
      updated_at: body.updated_at,
    },
  });

  return {
    id: updated.id,
    permission_id: updated.permission_id,
    email: updated.email,
    name: updated.name,
    status: updated.status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

