import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { IAimallBackendPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IAimallBackendPermission";
import { IPageIAimallBackendPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAimallBackendPermission";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * RBAC 권한 목록을 필터 및 페이징하여 검색합니다.
 *
 * 본 엔드포인트는 관리자 인증(활성 상태)된 사용자가 RBAC 권한(permissions/roles) 정의 목록을 다양한 조건으로
 * 검색·필터링하고, 페이징된 결과를 제공합니다. 일반적으로 권한/역할 검색/생성/할당 UX 구현에 사용되며, 키워드(코드명/표시이름),
 * 생성일 범위, 페이징(page, limit) 조건을 지원합니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.administrator - 인증된 관리자 페이로드 (활성 상태 필수)
 * @param props.body - 권한 목록 필터 및 페이징 파라미터 (이름, display_name, 생성일 등)
 * @returns RBAC 권한 요약 리스트 (IPageIAimallBackendPermission.ISummary)
 * @throws {Error} 인증되지 않았거나 권한 없는 경우(비활성 관리자 등)
 */
export async function patch__aimall_backend_administrator_permissions(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendPermission.IRequest;
}): Promise<IPageIAimallBackendPermission.ISummary> {
  const { administrator, body } = props;
  if (administrator.status !== "active") {
    throw new Error("권한이 없는 관리자이거나 비활성 계정입니다.");
  }

  const page: number = body.page ?? 1;
  const limit: number = body.limit ?? 20;

  const where = {
    ...(body.name && {
      name: { contains: body.name, mode: "insensitive" as const },
    }),
    ...(body.display_name && {
      display_name: {
        contains: body.display_name,
        mode: "insensitive" as const,
      },
    }),
    ...(body.created_at_from || body.created_at_to
      ? {
          created_at: {
            ...(body.created_at_from && { gte: body.created_at_from }),
            ...(body.created_at_to && { lte: body.created_at_to }),
          },
        }
      : {}),
  };

  const [records, data] = await Promise.all([
    MyGlobal.prisma.aimall_backend_permissions.count({ where }),
    MyGlobal.prisma.aimall_backend_permissions.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

  const pages = records === 0 ? 0 : Math.ceil(records / limit);

  return {
    pagination: {
      current: page,
      limit,
      records,
      pages,
    },
    data: data.map((x) => ({
      id: x.id,
      name: x.name,
      display_name: x.display_name,
      description: x.description,
      created_at: toISOStringSafe(x.created_at),
    })),
  };
}

