/**
 * Retrieve a paginated list of product records from the core product catalog.
 *
 * This endpoint returns only 'active' products, ordered by creation date
 * descending, with default pagination (page 1, limit 20). No authentication
 * required. Sensitive/supplier fields are excluded by schema; associated data
 * not included. Only core fields are returned as specified by the
 * IAimallBackendProduct structure.
 *
 * @returns {IPageIAimallBackendProduct} Paginated list of active product
 *   catalog entries including summary/detail fields as per catalog schema.
 * @throws {Error} Database failure or invalid schema field mapping.
 */
export async function get__aimall_backend_products(): Promise<IPageIAimallBackendProduct> {
  const current = 1;
  const limit = 20;

  // Fetch product data and count total records in parallel for performance
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_products.findMany({
      where: { status: "active" },
      orderBy: { created_at: "desc" },
      skip: (current - 1) * limit,
      take: limit,
      select: {
        id: true,
        category_id: true,
        seller_id: true,
        title: true,
        description: true,
        main_thumbnail_uri: true,
        status: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.aimall_backend_products.count({
      where: { status: "active" },
    }),
  ]);

  // Map to API structure, ensuring date fields are strings and branding is maintained
  const data = rows.map((row) => ({
    id: row.id,
    category_id: row.category_id,
    seller_id: row.seller_id,
    title: row.title,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    ...(row.description != null && { description: row.description }),
    ...(row.main_thumbnail_uri != null && {
      main_thumbnail_uri: row.main_thumbnail_uri,
    }),
  }));

  // Compose pagination block
  const pages = Math.max(1, Math.ceil(total / limit));
  const pagination = {
    current: current,
    limit: limit,
    records: total,
    pages: pages,
  };

  return {
    pagination,
    data,
  };
}

