 * aimall_backend_products model and supports multi-faceted queries, such as
 * category, seller, status, and keyword match against the product title and
 * description.
 *
 * The endpoint is available to any requesting party due to its role in powering
 * product search, advanced discovery, and backoffice product management tools.
 * The request body must conform to the expected DTO schema, encapsulating
 * search terms, filter options, pagination controls, and sorting preferences.
 * Results are strictly limited to normalized, non-deleted products per the
 * schema—sensitive details are withheld from the base response. The endpoint is
 * performance-optimized, enabling scalable product discovery as required by
 * frontend web/mobile layers. Output provides both data and necessary
 * pagination metadata, ensuring complete client handling.
 *
 * @param props Request properties
 * @param props.body Filtering and search criteria for product catalog advanced
 *   queries.
 * @returns Paginated list of products matching search and filter criteria.
 * @throws {Error} Database errors, type safety violations, or internal
 *   failures.
 */
export async function patch__aimall_backend_products(props: {
  body: IAimallBackendProduct.IRequest;
}): Promise<IPageIAimallBackendProduct> {
  const { body } = props;
  // Defensive defaults for page/limit
  const page = body.page != null && body.page >= 1 ? body.page : 1;
  const limit =
    body.limit != null && body.limit >= 1 && body.limit <= 100
      ? body.limit
      : 20;

  // Build where clause only with verified fields
  const where = {
    ...(body.title && {
      OR: [
        { title: { contains: body.title, mode: "insensitive" as const } },
        { description: { contains: body.title, mode: "insensitive" as const } },
      ],
    }),
    ...(body.category_id && { category_id: body.category_id }),
    ...(body.seller_id && { seller_id: body.seller_id }),
    ...(body.status && { status: body.status }),
    ...((body.created_at_from || body.created_at_to) && {
      created_at: {
        ...(body.created_at_from && { gte: body.created_at_from }),
        ...(body.created_at_to && { lte: body.created_at_to }),
      },
    }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_products.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_products.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit),
    },
    data: rows.map((row) => ({
