 *
 * 지정된 productId에 대한 상품 옵션(aimall_backend_product_options) 레코드를 Advanced
 * Search/Filter 방식으로 조회합니다.
 *
 * 이 엔드포인트는 고객, 판매자, 관리자 모두 사용 가능하며, 주어진 productId의 옵션 정보를 이름/값으로 상세 검색 및 페이징
 * 처리할 수 있도록 지원합니다. 반환 데이터는 IAimallBackendProductOption[] 배열과 페이지네이션 메타데이터로
 * 구성됩니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.productId - 조회 대상 상품의 UUID
 * @param props.body - 검색/필터/페이징 DTO (이름/값 검색 조건 등)
 * @returns 검색/필터 조건에 일치하는 상품 옵션 목록 및 페이지네이션 정보
 */
export async function patch__aimall_backend_products_$productId_productOptions(props: {
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProductOption.IRequest;
}): Promise<IPageIAimallBackendProductOption> {
  const { productId, body } = props;
  // 페이지/limit 기본값
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // 검색/필터 조건 생성
  const where = {
    product_id: productId,
    ...(body.name !== undefined &&
      body.name !== null &&
      body.name.length > 0 && {
        name: { contains: body.name, mode: "insensitive" as const },
      }),
    ...(body.value !== undefined &&
      body.value !== null &&
      body.value.length > 0 && {
        value: { contains: body.value, mode: "insensitive" as const },
      }),
  };

  const [rows, count] = await Promise.all([
    MyGlobal.prisma.aimall_backend_product_options.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { id: "asc" },
    }),
    MyGlobal.prisma.aimall_backend_product_options.count({ where }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: count,
      pages: count === 0 ? 0 : Math.ceil(count / limit),
    },
    data: rows,
  };
}

