 * of product_id, option name, and value is unique within that product. If an
 * option with the same name and value already exists for the product, the
 * operation is rejected.
 *
 * Ownership is enforced: only sellers with rights to the target product can add
 * options. The new product option is stored in the option table (product
 * variant definitions) and returned in full on success.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller (ownership enforced)
 * @param props.productId - UUID of the product for which the option is created
 * @param props.body - Product option creation data (name and value, product FK)
 * @returns The persisted product option entity with all fields, including
 *   generated UUID
 * @throws {Error} If product does not exist
 * @throws {Error} If seller does not own product
 * @throws {Error} If duplicate product option exists
 */
export async function post__aimall_backend_seller_products_$productId_productOptions(props: {
  seller: SellerPayload;
  productId: string & tags.Format<"uuid">;
  body: IAimallBackendProductOption.ICreate;
}): Promise<IAimallBackendProductOption> {
