 * @param props - Seller: Authenticated seller payload categoryId: UUID of the
 *   category to update body: Fields to update (name, parent_id, depth)
 * @returns The updated IAimallBackendCategory entity
 * @throws {Error} If category not found (404)
 * @throws {Error} If unique constraint or foreign key constraint fails
 *   (409/422)
 */
export async function put__aimall_backend_seller_categories_$categoryId(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
  body: IAimallBackendCategory.IUpdate;
}): Promise<IAimallBackendCategory> {
  const { categoryId, body } = props;
  const category = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!category) {
    throw new Error("Category not found");
  }
  try {
    const updated = await MyGlobal.prisma.aimall_backend_categories.update({
      where: { id: categoryId },
      data: {
        parent_id: body.parent_id ?? undefined,
        name: body.name ?? undefined,
        depth: body.depth ?? undefined,
      },
    });
    return {
      id: updated.id,
      parent_id: updated.parent_id,
      name: updated.name,
