    if (conflict) {
      throw new Error(
        "A category with this name already exists for the same parent.",
      );
    }
  }

  // 3. Update only supplied fields; skip undefined
  const updated = await MyGlobal.prisma.aimall_backend_categories.update({
    where: { id: categoryId },
    data: {
      parent_id: body.parent_id ?? undefined,
      name: body.name ?? undefined,
      depth: body.depth ?? undefined,
    },
  });

  // 4. Return entity per IAimallBackendCategory
  return {
    id: updated.id,
