 *
 * 이 엔드포인트는 지정한 상품 카테고리를 영구적으로 삭제합니다. 삭제 전에 하위 카테고리 또는 해당 카테고리에 소속된 상품이 없어야 합니다.
 * 조건을 만족하지 않으면 에러를 반환합니다. 이 작업은 인증된 셀러 또는 관리자만 수행할 수 있습니다.
 *
 * @param props - 요청 속성
 * @param props.seller - 인증된 셀러(판매자) 인증 정보
 * @param props.categoryId - 삭제할 카테고리의 UUID
 * @returns Void (삭제 성공 시 204 No Content)
 * @throws {Error} 카테고리가 존재하지 않으면 예외 발생
 * @throws {Error} 하위 카테고리 또는 소속 상품이 존재하면 예외 발생
 */
export async function delete__aimall_backend_seller_categories_$categoryId(props: {
  seller: SellerPayload;
  categoryId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { categoryId } = props;

  // (1) 해당 카테고리가 실제로 존재하는지 확인
  const category = await MyGlobal.prisma.aimall_backend_categories.findUnique({
    where: { id: categoryId },
  });
  if (!category) {
    throw new Error("Category not found");
  }

  // (2) 하위 카테고리가 존재하는지 확인
  const childCategory =
    await MyGlobal.prisma.aimall_backend_categories.findFirst({
      where: { parent_id: categoryId },
    });
  if (childCategory) {
    throw new Error("Cannot delete category: child categories exist");
  }

  // (3) 해당 카테고리에 소속된 상품이 있는지 확인
  const productInCategory =
    await MyGlobal.prisma.aimall_backend_products.findFirst({
      where: { category_id: categoryId },
    });
  if (productInCategory) {
    throw new Error("Cannot delete category: products exist in this category");
  }

  // (4) 모든 조건을 통과하면 카테고리 하드 삭제 실행
  await MyGlobal.prisma.aimall_backend_categories.delete({
    where: { id: categoryId },
  });
