 * This function permanently deletes a child category in the
 * aimall_backend_categories table, under a specified parent category. It first
 * checks that the target category's parent_id matches the provided parent, and
 * then verifies that the category is not referenced as a parent by any other
 * categories (i.e., it has no children) and is not assigned to any products. If
 * all checks pass, the category is hard-deleted. Otherwise, a clear error is
 * thrown for each business rule violation.
 *
 * Restrictions:
 *
 * - Only administrator users may perform this operation.
 * - Category must exist, and its parent_id must match categoryId.
 * - Category cannot be deleted if it has subcategories, or is assigned to any
 *   products.
 * - The operation is a hard delete (no soft delete/deleted_at field exists).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   valid and active)
 * @param props.categoryId - UUID of the parent category (the direct parent
 *   under which the child sits)
 * @param props.childCategoryId - UUID of the target child category for deletion
 * @returns Void
 * @throws {Error} When the child category does not exist
 * @throws {Error} When the parent-child relationship does not match
 * @throws {Error} When the target category has subcategories (children) still
 *   present
 * @throws {Error} When the category is still assigned to one or more products
 */
export async function delete__aimall_backend_administrator_categories_$categoryId_childCategories_$childCategoryId(props: {
  administrator: AdministratorPayload;
  categoryId: string & tags.Format<"uuid">;
  childCategoryId: string & tags.Format<"uuid">;
