 * @param props.skuId - UUID of the SKU (variant) to be deleted
 * @returns Void
 * @throws {Error} If the SKU does not exist or does not belong to the specified
 *   product
 * @throws {Error} If the SKU is referenced by an order item
 * @throws {Error} If the SKU is referenced by an inventory snapshot
 */
export async function delete__aimall_backend_administrator_products_$productId_skus_$skuId(props: {
  administrator: AdministratorPayload;
  productId: string & tags.Format<"uuid">;
  skuId: string & tags.Format<"uuid">;
}): Promise<void> {
