  const snapshot =
    await MyGlobal.prisma.aimall_backend_inventory_snapshots.findFirst({
      where: { sku_id: skuId },
    });
  if (snapshot) {
    throw new Error(
      "Cannot delete SKU: It is referenced by at least one inventory snapshot",
