 * access this list. Data returned includes all atomic SKU-level information as
 * dictated by the schema, permitting context for inventory actions, listing
 * management, and reporting.
 *
 * Returns paginated result in IPageIAimallBackendSku format for catalog
 * operations. Pagination currently uses fixed defaults (page=1, limit=20). Can
 * be extended for external param support.
 *
 * @param props - Provider input containing authenticated administrator user.
 * @returns Paginated page of SKU records as IPageIAimallBackendSku.
 * @throws {Error} If administrator is not active, or has been revoked, or
 *   unauthorized.
 * @field administrator - AdministratorPayload. Ensures operation performed by authorized admin.
 */
export async function get__aimall_backend_administrator_skus(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendSku> {
