 * @throws {Error} When the post is not found
 * @throws {Error} When the post is already deleted
 */
export async function delete__aimall_backend_administrator_posts_$postId(props: {
  administrator: AdministratorPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<void> {
