/**
 * Retrieves all media/file attachments for a specified community post, scoping
 * by ownership and privacy rules.
 *
 * Only the post's owner may access attachments for private posts. For public
 * posts, any authenticated customer can view attachments. Results are strictly
 * filtered by post_id and sorted by upload timestamp. Results are returned in a
 * single-page IPageIAimallBackendAttachment response (pagination can be added
 * as needed).
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request (must be
 *   post owner for private posts)
 * @param props.postId - Unique ID of the target post to fetch attachments for
 * @returns Paginated list of attachments for the target post including all
 *   relevant file metadata
 * @throws {Error} When the post does not exist or the customer is not
 *   authorized
 */
export async function get__aimall_backend_customer_posts_$postId_attachments(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendAttachment> {
  const { customer, postId } = props;

  // 1. Fetch the post and validate ownership/privacy
  const post = await MyGlobal.prisma.aimall_backend_posts.findFirst({
    where: {
      id: postId,
      deleted_at: null,
    },
    select: {
      id: true,
      customer_id: true,
      is_private: true,
    },
  });
  if (!post) {
    throw new Error("Post not found");
  }
  // Only the owner can access private posts
  if (post.is_private && post.customer_id !== customer.id) {
    throw new Error("You do not have access to this post");
  }

  // 2. Retrieve attachments for this post
  const attachments = await MyGlobal.prisma.aimall_backend_attachments.findMany(
    {
      where: { post_id: postId },
      orderBy: { created_at: "asc" },
    },
  );

  // 3. Assemble paginated response (all results in one page)
  return {
    pagination: {
      current: 1,
      limit: attachments.length,
      records: attachments.length,
      pages: 1,
    },
    data: attachments.map((a) => ({
      id: a.id,
      post_id: a.post_id ?? null,
      comment_id: a.comment_id ?? null,
      review_id: a.review_id ?? null,
      file_uri: a.file_uri,
      file_type: a.file_type,
      file_size: a.file_size,
      created_at: toISOStringSafe(a.created_at),
    })),
  };
}

