      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_comments.count({ where }),
  ]);

  // Convert result objects strictly to IAimallBackendComment (handling date and nullable fields)
  const data = comments.map((c) => ({
    id: c.id,
    post_id: c.post_id ?? null,
    review_id: c.review_id ?? null,
    parent_id: c.parent_id ?? null,
