  const skip = (page - 1) * limit;

  // Step 3: Build filters (avoid spreading undefined)
  const fileSizeFilter =
    (body.file_size_min !== undefined && body.file_size_min !== null) ||
    (body.file_size_max !== undefined && body.file_size_max !== null)
      ? {
          ...(body.file_size_min !== undefined &&
            body.file_size_min !== null && { gte: body.file_size_min }),
          ...(body.file_size_max !== undefined &&
            body.file_size_max !== null && { lte: body.file_size_max }),
        }
      : undefined;

  const createdAtFilter =
    (body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          ...(body.created_from !== undefined &&
            body.created_from !== null && { gte: body.created_from }),
          ...(body.created_to !== undefined &&
            body.created_to !== null && { lte: body.created_to }),
        }
      : undefined;

  const where = {
    comment_id: commentId,
    ...(body.post_id !== undefined &&
      body.post_id !== null && { post_id: body.post_id }),
    ...(body.review_id !== undefined &&
      body.review_id !== null && { review_id: body.review_id }),
    ...(body.file_type !== undefined &&
      body.file_type !== null && { file_type: body.file_type }),
    ...(fileSizeFilter && { file_size: fileSizeFilter }),
    ...(createdAtFilter && { created_at: createdAtFilter }),
  };

  // Step 4: Query DB & total
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({ where }),
  ]);

  // Step 5: Map result
  const data = rows.map((row) => ({
    id: row.id,
    post_id: row.post_id ?? null,
    comment_id: row.comment_id ?? null,
    review_id: row.review_id ?? null,
    file_uri: row.file_uri,
    file_type: row.file_type,
    file_size: row.file_size,
    created_at: toISOStringSafe(row.created_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
