 *
 * - 오직 본인만 수정 가능하며, 삭제된 댓글(soft deleted)은 수정할 수 없습니다.
 * - 부모-자식 관계가 올바른지 확인합니다.
 * - 오직 atomic 필드(body, is_private, deleted_at)만 수정됩니다. parent_id, post_id 등은 변경
 *   불가합니다.
 * - 변경 시 updated_at이 항상 최신 시각으로 갱신되며, 모든 날짜/시간 필드는 ISO8601 문자열로 반환됩니다.
 *
 * @param props - 요청 객체
 * @param props.customer - 인증된 고객 페이로드
 * @param props.commentId - 상위 댓글(쓰레드)의 UUID
 * @param props.childCommentId - 하위(답글) 댓글의 UUID (수정 대상)
 * @param props.body - 수정할 필드 정보 (body, is_private, deleted_at)
 * @returns 수정된 댓글 객체
 * @throws {Error} - 댓글 없음, 부모-자식 불일치, 권한 없음, 삭제된 댓글 등
 */
export async function put__aimall_backend_customer_comments_$commentId_comments_$childCommentId(props: {
  customer: CustomerPayload;
  commentId: string & tags.Format<"uuid">;
  childCommentId: string & tags.Format<"uuid">;
  body: IAimallBackendComment.IUpdate;
}): Promise<IAimallBackendComment> {
  const { customer, commentId, childCommentId, body } = props;

  // (1) 하위 댓글을 조회 (존재 & 삭제되지 않은 댓글만)
  const comment = await MyGlobal.prisma.aimall_backend_comments.findUnique({
    where: { id: childCommentId },
  });
  if (!comment) throw new Error("댓글을 찾을 수 없습니다.");
  if (comment.deleted_at !== null)
    throw new Error("삭제된 댓글은 수정할 수 없습니다.");

  // (2) 상위 댓글(부모)과의 관계 확인
  if (comment.parent_id !== commentId)
    throw new Error("해당 상위 댓글의 답글이 아닙니다.");

  // (3) 본인(작성자) 여부 확인
  if (comment.customer_id !== customer.id)
    throw new Error("본인만 해당 댓글을 수정할 수 있습니다.");

  // (4) 업데이트 (허용 필드만)
  const updated = await MyGlobal.prisma.aimall_backend_comments.update({
    where: { id: childCommentId },
    data: {
      body: body.body ?? undefined,
      is_private: body.is_private ?? undefined,
      deleted_at: body.deleted_at === undefined ? undefined : body.deleted_at,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // (5) DTO 변환 및 날짜 필드 표준화
  return {
    id: updated.id,
    post_id: updated.post_id ?? null,
    review_id: updated.review_id ?? null,
    parent_id: updated.parent_id ?? null,
    customer_id: updated.customer_id ?? null,
    body: updated.body,
    is_private: updated.is_private,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

