 * identity, product, rating range, creation or update date ranges, and
 * full-text in title/body, via a request body aligned with
 * IAimallBackendReview.IRequest. The returned list is paginated and sorted per
 * request. Access may be role-dependent: customers are scoped to their own
 * reviews; sellers/admins have wider access as per RBAC. All soft-deleted rows
 * (i.e., deleted_at not null) are excluded from the normal result set.
 *
 * Designed for moderation panels, seller dashboards, and personalized customer
 * review view. Behavior closely follows Prisma schema (atomic only, no
 * denormalized aggregates).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 * @param props.body - Search and pagination filter criteria for reviews.
 * @returns Paginated result set with review summaries
 * @throws {Error} When database errors occur
 */
export async function patch__aimall_backend_administrator_reviews(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendReview.IRequest;
}): Promise<IPageIAimallBackendReview.ISummary> {
  const { body } = props;

  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // rating filter object (merge min/max if both present)
  const ratingFilter =
    (body.rating_min !== undefined && body.rating_min !== null) ||
    (body.rating_max !== undefined && body.rating_max !== null)
      ? {
          ...(body.rating_min !== undefined &&
            body.rating_min !== null && { gte: body.rating_min }),
          ...(body.rating_max !== undefined &&
            body.rating_max !== null && { lte: body.rating_max }),
        }
      : undefined;

  // created_at filter object (merge from/to if both present)
  const createdAtFilter =
    (body.created_from !== undefined && body.created_from !== null) ||
    (body.created_to !== undefined && body.created_to !== null)
      ? {
          ...(body.created_from !== undefined &&
            body.created_from !== null && { gte: body.created_from }),
          ...(body.created_to !== undefined &&
            body.created_to !== null && { lte: body.created_to }),
        }
      : undefined;

  const where = {
    deleted_at: null,
    ...(body.product_id !== undefined &&
      body.product_id !== null && { product_id: body.product_id }),
    ...(body.customer_id !== undefined &&
      body.customer_id !== null && { customer_id: body.customer_id }),
    ...(ratingFilter && { rating: ratingFilter }),
    ...(createdAtFilter && { created_at: createdAtFilter }),
    ...(body.title_keyword !== undefined &&
      body.title_keyword !== null && {
        title: { contains: body.title_keyword, mode: "insensitive" as const },
      }),
    ...(body.body_keyword !== undefined &&
      body.body_keyword !== null && {
        body: { contains: body.body_keyword, mode: "insensitive" as const },
      }),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_reviews.findMany({
      where,
      select: {
        id: true,
        product_id: true,
        title: true,
        rating: true,
        created_at: true,
      },
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_reviews.count({ where }),
  ]);

  const pages = Math.ceil(total / limit);
  const pagination = {
    current: page,
    limit,
    records: total,
    pages,
  };

  const data = rows.map((row) => ({
    id: row.id,
    product_id: row.product_id,
    title: row.title,
    rating: row.rating,
    created_at: toISOStringSafe(row.created_at),
