/**
 * Retrieve all comments linked to a specific product review
 * (aimall_backend_comments).
 *
 * Fetches all comments attached to the given reviewId, with privacy
 * enforcement:
 *
 * - Customers can see public comments (is_private === false) and their own
 *   private comments (is_private === true && customer_id === self). Comments
 *   are sorted in ascending creation order (oldest first) and only non-deleted
 *   comments (deleted_at is null) are included.
 *
 * If the given review does not exist or is soft-deleted, returns empty result.
 * This endpoint does not paginate since there are no page parameters; all
 * matching comments are returned.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer
 * @param props.reviewId - UUID of the review to fetch comments for
 * @returns Paginated (no pagination metadata) comment summaries for the
 *   specified review
 */
export async function get__aimall_backend_customer_reviews_$reviewId_comments(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendComment.ISummary> {
