  // Step 2: Query comments for this review (not deleted)
  const comments = await MyGlobal.prisma.aimall_backend_comments.findMany({
    where: { review_id: reviewId, deleted_at: null },
    orderBy: { created_at: "asc" },
  });

  // Step 3: Filter for privacy rules (public, or customer's own private)
