/**
 * Performs a filtered, paginated search for attachments uploaded to a product
 * review.
 *
 * Advanced filtering assists customer UIs and admin tools in rapidly
 * enumerating user-submitted content, enforcing business moderation, or
 * handling content overload on popular reviews. Security: Only customers who
 * own a review are authorized to search attachments for that review.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer requesting attachment
 *   search
 * @param props.reviewId - UUID identifier for the review to search attachments
 *   under
 * @param props.body - Advanced search/filter and pagination criteria
 * @returns Paginated result set of attachments matching the filters
 * @throws {Error} If the customer does not own the review, or the review does
 *   not exist
 */
export async function patch__aimall_backend_customer_reviews_$reviewId_attachments(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  body: IAimallBackendAttachment.IRequest;
}): Promise<IPageIAimallBackendAttachment> {
  const { customer, reviewId, body } = props;
  // 1. Authorization: ensure customer owns the review
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUniqueOrThrow(
    {
      where: { id: reviewId },
      select: { customer_id: true },
    },
  );
  if (review.customer_id !== customer.id) {
    throw new Error(
      "You are not authorized to search attachments for this review.",
    );
  }

  // 2. Pagination
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // 3. Build where condition (may include ranges)
  const fileSizeRange =
    body.file_size_min != null || body.file_size_max != null
      ? {
          ...(body.file_size_min != null && { gte: body.file_size_min }),
          ...(body.file_size_max != null && { lte: body.file_size_max }),
        }
      : undefined;
  const createdAtRange =
    body.created_from != null || body.created_to != null
      ? {
          ...(body.created_from != null && { gte: body.created_from }),
          ...(body.created_to != null && { lte: body.created_to }),
        }
      : undefined;

  const where = {
    review_id: reviewId,
    ...(body.post_id != null && { post_id: body.post_id }),
    ...(body.comment_id != null && { comment_id: body.comment_id }),
    ...(body.file_type != null && { file_type: body.file_type }),
    ...(fileSizeRange && { file_size: fileSizeRange }),
    ...(createdAtRange && { created_at: createdAtRange }),
  };

  // 4. Query DB for page and total
  const [attachments, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_attachments.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_attachments.count({ where }),
  ]);

  // 5. Map results to DTO, ensure date string formatting
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: attachments.map((att) => ({
      id: att.id,
      post_id: att.post_id ?? null,
      comment_id: att.comment_id ?? null,
      review_id: att.review_id ?? null,
      file_uri: att.file_uri,
      file_type: att.file_type,
      file_size: att.file_size,
      created_at: toISOStringSafe(att.created_at),
    })),
  };
}

