/**
 * 특정 상품 리뷰에 연결된 첨부파일의 자세한 메타데이터를 조회합니다.
 *
 * 이 엔드포인트는 인증된 고객이 자신의 리뷰에 소속된 첨부파일을 식별자(attachmentId)로 조회할 때 사용합니다. 첨부파일이 요청한
 * 리뷰(reviewId)에 속하며, 해당 리뷰의 소유자(고객)만 접근할 수 있도록 권한 검사도 수행합니다.
 *
 * @param props - 요청 속성 객체
 *
 *   - Customer: 인증된 고객 Payload (JWT 기준)
 *   - ReviewId: 조회할 리뷰의 UUID
 *   - AttachmentId: 조회할 첨부파일의 UUID
 *
 * @returns IAimallBackendAttachment - 첨부파일의 전체 메타데이터
 * @throws {Error} 첨부파일(Attachment)이 존재하지 않거나 요청한 리뷰에 속하지 않을 때
 * @throws {Error} 리뷰가 존재하지 않거나, 해당 고객의 소유가 아닐 때(권한 없음)
 */
export async function get__aimall_backend_customer_reviews_$reviewId_attachments_$attachmentId(props: {
  customer: CustomerPayload;
  reviewId: string & tags.Format<"uuid">;
  attachmentId: string & tags.Format<"uuid">;
}): Promise<IAimallBackendAttachment> {
  const { customer, reviewId, attachmentId } = props;
  // 1. 첨부파일 조회
  const attachment =
    await MyGlobal.prisma.aimall_backend_attachments.findUnique({
      where: { id: attachmentId },
    });
  if (!attachment) throw new Error("Attachment not found");
  // 2. 첨부파일이 요청한 리뷰(reviewId)에 속하는지 확인
  if (!attachment.review_id || attachment.review_id !== reviewId) {
    throw new Error("Attachment does not belong to the specified review");
  }
  // 3. 리뷰 조회
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUnique({
    where: { id: reviewId },
  });
  if (!review) throw new Error("Review not found");
  // 4. 권한 검사(리뷰와 고객 일치 여부)
  if (review.customer_id !== customer.id) {
    throw new Error(
      "Forbidden: only the owner can view this review attachment",
    );
  }
  // 5. DTO로 매핑 및 날짜 변환
  return {
    id: attachment.id,
    post_id: attachment.post_id ?? null,
    comment_id: attachment.comment_id ?? null,
    review_id: attachment.review_id ?? null,
    file_uri: attachment.file_uri,
    file_type: attachment.file_type,
    file_size: attachment.file_size,
    created_at: toISOStringSafe(attachment.created_at),
  };
}

