/**
 * Update an existing snapshot (photo/media) on a post.
 *
 * Only the owner (authenticated customer) can edit their snapshot entity.
 * Returns the updated entity if and only if the user is authorized and the
 * entity exists. Throws an error on not found or permission denied.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer payload (must own the
 *   snapshot)
 * @param props.postId - Parent post's unique identifier
 * @param props.snapshotId - Snapshot's unique identifier
 * @param props.body - Editable fields (caption or media URI)
 * @returns Updated snapshot entity
 * @throws {Error} If not found or forbidden
 */
export async function put__aimall_backend_customer_posts_$postId_snapshots_$snapshotId(props: {
  customer: CustomerPayload;
  postId: string & tags.Format<"uuid">;
  snapshotId: string & tags.Format<"uuid">;
  body: IAimallBackendSnapshot.IUpdate;
}): Promise<IAimallBackendSnapshot> {
  const { customer, postId, snapshotId, body } = props;

  // Step 1: Find the snapshot by id and post_id
  const snapshot = await MyGlobal.prisma.aimall_backend_snapshots.findFirst({
    where: {
      id: snapshotId,
      post_id: postId,
    },
  });
  if (!snapshot) throw new Error("Snapshot not found");

  // Step 2: Authorization: Only owner may edit
  if (!snapshot.customer_id || snapshot.customer_id !== customer.id) {
