import { SellerPayload } from "../decorators/payload/SellerPayload";

/**
 * List all snapshots (user moments/photos) associated with a specific product
 * review entity. Response is paginated and contains all fields mapped from
 * aimall_backend_snapshots, filtered to match the supplied review.
 *
 * Permissions: Only authenticated sellers may access. Results are filtered to
 * ensure only sellers who own the product of the review can list snapshots. If
 * the review or product does not exist, or permission is denied, an error is
 * thrown. Snapshots are paginated (default page 1, limit 20).
 *
 * @param props - Seller: Authenticated seller payload reviewId: The unique
 *   identifier of the review being queried
 * @returns Paginated list of snapshots (user media) for the review's product
 * @throws {Error} When the review does not exist, product does not exist, or
 *   the seller does not own the product
 */
export async function get__aimall_backend_seller_reviews_$reviewId_snapshots(props: {
  seller: SellerPayload;
  reviewId: string & tags.Format<"uuid">;
}): Promise<IPageIAimallBackendSnapshot> {
  const { seller, reviewId } = props;

  // 1. Load the review for the provided reviewId
  const review = await MyGlobal.prisma.aimall_backend_reviews.findUniqueOrThrow(
    {
      where: { id: reviewId },
      select: { id: true, product_id: true },
    },
  );

  // 2. Load the product, verify seller authorization
  const product =
    await MyGlobal.prisma.aimall_backend_products.findUniqueOrThrow({
      where: { id: review.product_id },
      select: { id: true, seller_id: true },
    });

  if (product.seller_id !== seller.id) {
    throw new Error(
      "Unauthorized: Seller does not own the product related to this review.",
    );
  }

  // 3. List (paginated) all aimall_backend_snapshots with matching product_id.
  const page = 1;
  const limit = 20;
  const skip = (page - 1) * limit;

  const [snapshots, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_snapshots.findMany({
      where: { product_id: review.product_id },
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
      select: {
        id: true,
        product_id: true,
        post_id: true,
        customer_id: true,
        media_uri: true,
        caption: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.aimall_backend_snapshots.count({
      where: { product_id: review.product_id },
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: snapshots.map((row) => ({
      id: row.id,
      product_id: row.product_id ?? undefined,
      post_id: row.post_id ?? undefined,
      customer_id: row.customer_id ?? undefined,
      media_uri: row.media_uri,
      caption: row.caption ?? undefined,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

