/**
 * Retrieve a list of shopping carts from the system for administrators.
 *
 * This endpoint supplies summary information for each cart including primary
 * key, owner customer ID (nullable for guest carts), session tokens (for
 * anonymous carts), creation/update timestamps, and per-cart item count. Full
 * authorization is required: only administrator users may access this endpoint.
 * Pagination is not natively handled by this endpoint, but can be incorporated
 * at the service layer.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 * @returns Paginated list of IAimallBackendCart objects for all carts in the
 *   system
 * @throws {Error} When authorization or database errors occur
 */
export async function get__aimall_backend_administrator_carts(props: {
  administrator: AdministratorPayload;
}): Promise<IPageIAimallBackendCart> {
  const { administrator } = props;
  // Fetch all shopping carts in the system
  const carts = await MyGlobal.prisma.aimall_backend_carts.findMany({});

  // Extract all cart IDs for lookup
  const cartIds = carts.map((cart) => cart.id);

  // Count the number of cart items for each cart in a single grouped query
  const cartItemCounts =
    await MyGlobal.prisma.aimall_backend_cart_items.groupBy({
      by: ["aimall_backend_cart_id"],
      where: { aimall_backend_cart_id: { in: cartIds } },
      _count: { id: true },
    });
  const cartItemsCountMap: Record<string, number> = Object.fromEntries(
    cartItemCounts.map((entry) => [
      entry.aimall_backend_cart_id,
      entry._count.id,
    ]),
  );

  // Map carts to IAimallBackendCart with proper branding and conversions
  const data = carts.map((cart) => ({
