      : {}),
    ...(body.updated_from || body.updated_to
      ? {
          updated_at: {
            ...(body.updated_from ? { gte: body.updated_from } : {}),
            ...(body.updated_to ? { lte: body.updated_to } : {}),
          },
        }
      : {}),
  };

  // 페이지네이션 계산
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit =
    body.limit && body.limit > 0 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // 장바구니 목록 및 총 카운트 병렬 조회
  const [carts, total] = await Promise.all([
    MyGlobal.prisma.aimall_backend_carts.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.aimall_backend_carts.count({ where }),
  ]);

  // 각 장바구니별 아이템 카운트 집계
  const cartIds = carts.map((cart) => cart.id);
  const itemsPerCart =
    cartIds.length === 0
      ? []
      : await MyGlobal.prisma.aimall_backend_cart_items.groupBy({
          by: ["aimall_backend_cart_id"],
          where: { aimall_backend_cart_id: { in: cartIds } },
          _count: { id: true },
        });
  const itemsCountMap: Record<string, number> = Object.fromEntries(
    itemsPerCart.map((x) => [x.aimall_backend_cart_id, x._count.id]),
  );

  // 응답 데이터 생성
  const data = carts.map((cart) => ({
    id: cart.id,
    aimall_backend_customer_id: cart.aimall_backend_customer_id ?? undefined,
    session_token: cart.session_token ?? undefined,
    created_at: toISOStringSafe(cart.created_at),
    updated_at: toISOStringSafe(cart.updated_at),
    cart_items_count: itemsCountMap[cart.id] ?? 0,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

