 */
export async function post__aimall_backend_administrator_carts(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendCart.ICreate;
}): Promise<IAimallBackendCart> {
  const { administrator, body } = props;

  // Enforce that at least one of customer ID or session_token is present
  if (!body.aimall_backend_customer_id && !body.session_token) {
    throw new Error(
      "Either aimall_backend_customer_id or session_token must be provided",
    );
  }

  // Uniqueness: If creating for a customer, ensure no cart exists for that customer
  if (body.aimall_backend_customer_id) {
