  });
  if (!order) throw new Error("Order not found");
  if (order.seller_id !== seller.id) {
    throw new Error("Unauthorized: Seller does not own this order");
  }

  // 2. Resolve paid_at: use client value if present, else generate server timestamp
  const paidAt: string & tags.Format<"date-time"> =
    body.paid_at && typeof body.paid_at === "string"
      ? toISOStringSafe(body.paid_at)
      : toISOStringSafe(new Date());

  // 3. Create payment row
  const created = await MyGlobal.prisma.aimall_backend_payments.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      order_id: orderId,
      payment_method: body.payment_method,
      amount: body.amount,
      currency: body.currency,
      transaction_id: body.transaction_id ?? null,
      paid_at: paidAt,
