/**
 * Permanently deletes a coupon redemption log from the system.
 *
 * This operation performs a hard (irreversible) delete of a coupon redemption
 * log record. Administrator privileges are required. The operation will be
 * blocked if the redemption is referenced by any unresolved abuse/compliance
 * incidents.
 *
 * Related business implications: Permanent deletion can impact analytics or
 * ongoing investigations.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must be
 *   active)
 * @param props.couponRedemptionId - UUID for the coupon redemption log to be
 *   deleted
 * @returns Void
 * @throws {Error} If the coupon redemption log does not exist
 * @throws {Error} If deletion is blocked due to unresolved abuse/compliance
 *   incidents
 */
export async function delete__aimall_backend_administrator_couponRedemptions_$couponRedemptionId(props: {
  administrator: AdministratorPayload;
  couponRedemptionId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, couponRedemptionId } = props;

  // Step 1: Find the coupon redemption record, throw if not found
  const record =
    await MyGlobal.prisma.aimall_backend_coupon_redemptions.findUnique({
      where: { id: couponRedemptionId },
    });
  if (!record) {
    throw new Error("Coupon redemption log not found");
  }

  // Step 2: Prevent deletion if referenced by unresolved abuse incidents
  const unresolvedIncident =
    await MyGlobal.prisma.aimall_backend_abuse_incidents.findFirst({
      where: {
        resolved: false,
        OR: [
          { coupon_id: record.coupon_id },
          { order_id: record.order_id ?? undefined },
        ],
      },
    });
  if (unresolvedIncident) {
    throw new Error(
      "Deletion blocked: coupon redemption is referenced by an unresolved abuse/compliance incident",
    );
  }

  // Step 3: Hard delete
  await MyGlobal.prisma.aimall_backend_coupon_redemptions.delete({
    where: { id: couponRedemptionId },
  });
}

