/**
 * Create a new loyalty transaction (admin only).
 *
 * Inserts a new atomic loyalty transaction into the
 * aimall_backend_loyalty_transactions table. The transaction may be an accrual,
 * redemption, expiration, or adjustment, as controlled by the type and amount
 * provided via the IAimallBackendLoyaltyTransaction.ICreate DTO. Admins,
 * compliance users, or authorized system actors use this endpoint for
 * adjustments, bulk events, or resolving customer disputes.
 *
 * Business restrictions (e.g., no duplicate accrual for same order/coupon,
 * minimum/maximum per-event limits, negative amount checking per type) must be
 * enforced at the service/business logic tier. Created records are immutable
 * except where reversal is required by business rules. Privilege is restricted
 * to administrative roles and the audit log must record every use of this
 * creation endpoint for compliance integrity.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator (must be active)
 * @param props.body - Details for creating a new loyalty transaction event
 * @returns The newly created loyalty transaction record, as persisted in Coins
 *   domain.
 * @throws {Error} When database insertion fails
 */
export async function post__aimall_backend_administrator_loyaltyTransactions(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendLoyaltyTransaction.ICreate;
}): Promise<IAimallBackendLoyaltyTransaction> {
  const { administrator, body } = props;

  // Explicitly fetch and verify administrator (should already be enforced by decorator, but extra safety)
  const admin = await MyGlobal.prisma.aimall_backend_administrators.findFirst({
    where: {
      id: administrator.id,
      status: "active",
    },
  });
  if (!admin) {
    throw new Error("Unauthorized: administrator not found or inactive.");
  }

  // Generate ID and created_at
  const id = v4() as string & tags.Format<"uuid">;
  const now = toISOStringSafe(new Date());

  // Insert new loyalty transaction
  const created =
    await MyGlobal.prisma.aimall_backend_loyalty_transactions.create({
      data: {
        id,
        customer_id: body.customer_id,
        order_id: body.order_id ?? null,
        coupon_id: body.coupon_id ?? null,
        amount: body.amount,
        type: body.type,
        description: body.description ?? null,
        created_at: now,
        expired_at: body.expired_at ?? null,
      },
    });

  // Always convert date/datetime fields via toISOStringSafe()
  return {
    id: created.id,
    customer_id: created.customer_id,
    order_id: created.order_id ?? null,
    coupon_id: created.coupon_id ?? null,
    amount: created.amount,
    type: created.type,
    description: created.description ?? null,
    created_at: toISOStringSafe(created.created_at),
    expired_at: created.expired_at ? toISOStringSafe(created.expired_at) : null,
  };
}

