/**
 * Delete a support ticket by ID (hard delete, no soft deletion).
 *
 * Deletes a support ticket by its UUID. This is a hard deletion due to absence
 * of soft-delete field in the Prisma schema—once removed, the record cannot be
 * restored. Operation is allowed only for ticket owners (customers) per
 * platform policy.
 *
 * Business logic blocks deletion of tickets still pending action; only tickets
 * not in 'pending' status may be deleted. Role verification is enforced. An
 * audit log is created for traceability.
 *
 * @param props - Parameters for deletion
 * @param props.customer - The authenticated customer performing the deletion
 *   (must own the ticket)
 * @param props.supportTicketId - UUID of the support ticket to delete
 * @returns Void
 * @throws {Error} When the ticket does not exist, the customer does not own the
 *   ticket, or the ticket status is 'pending'.
 */
export async function delete__aimall_backend_customer_supportTickets_$supportTicketId(props: {
  customer: CustomerPayload;
  supportTicketId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { customer, supportTicketId } = props;

  // Fetch the support ticket by ID
  const ticket =
    await MyGlobal.prisma.aimall_backend_support_tickets.findUnique({
      where: { id: supportTicketId },
    });
  if (!ticket) throw new Error("Support ticket not found");

  // Only the ticket owner can delete
  if (ticket.requester_id !== customer.id)
    throw new Error("Forbidden: Only the ticket owner may delete this ticket");

  // Business logic: block deletion if still pending
  if (ticket.status === "pending")
    throw new Error("Cannot delete a support ticket that is pending");

  // Hard delete the ticket
  await MyGlobal.prisma.aimall_backend_support_tickets.delete({
    where: { id: supportTicketId },
