/**
 * Create a new FAQ entry (knowledge base record).
 *
 * Add a new FAQ record representing a knowledge base entry. Requires complete
 * input for question, answer, category, visible, and sort_order fields as
 * described in the schema. This operation is permitted to administrator or
 * knowledge manager roles; guests/customers may not add FAQs by policy.
 *
 * All values are validated for normalization and correct answer/question scope.
 * Audit trail is ensured for all creations for compliance and reporting.
 * Returns the full inserted record for admin review.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload. Must be
 *   present and valid for operation.
 * @param props.body - FAQ creation data, including question, answer, category,
 *   visible flag, and sort_order (manual sort index).
 * @returns The new FAQ record, normalized and including id and timestamps.
 * @throws {Error} When a FAQ entry with the same category and sort_order
 *   already exists.
 */
export async function post__aimall_backend_administrator_faqs(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendFaq.ICreate;
}): Promise<IAimallBackendFaq> {
  const { administrator, body } = props;

  // Admin authentication enforced by decorator/parameter
  // Uniqueness: ensure no duplicate (category, sort_order)
  const existing = await MyGlobal.prisma.aimall_backend_faqs.findFirst({
    where: {
      category: body.category,
      sort_order: body.sort_order,
    },
    select: { id: true },
  });
  if (existing) {
    throw new Error(
      `FAQ with category '${body.category}' and sort_order '${body.sort_order}' already exists.`,
    );
  }

  // Prepare timestamps
  const now = toISOStringSafe(new Date());
  // Generate new ID
  // v4() returns a string, but we want to guarantee branding statically
  // Here, parse as IAimallBackendFaq['id'] type (string & tags.Format<'uuid'>) via variable
  const faqId = v4();

  // Insert new record
  const created = await MyGlobal.prisma.aimall_backend_faqs.create({
    data: {
      id: faqId,
      question: body.question,
      answer: body.answer,
      category: body.category,
      sort_order: body.sort_order,
      visible: body.visible,
      created_at: now,
      updated_at: now,
    },
  });

  // Return as normalized result (all date values are already string, see above)
  return {
    id: created.id,
    question: created.question,
    answer: created.answer,
    category: created.category,
    sort_order: created.sort_order,
    visible: created.visible,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

