/**
 * Creates a new analytics dashboard configuration within the analytics
 * subsystem.
 *
 * Only users with administrative privileges may perform this operation. This
 * function enforces uniqueness of dashboard codes and returns the full
 * configuration entity with all fields populated. All timestamps are ISO 8601
 * strings using correct brand types. Throws when code already exists or
 * administrator is not authorized.
 *
 * @param props - Request properties
 * @param props.administrator - The authenticated administrator making the
 *   request
 * @param props.body - The dashboard creation payload, including code, title,
 *   description, config_json
 * @returns The created dashboard entity with all fields populated
 * @throws {Error} If the dashboard code is not unique or the administrator is
 *   unauthorized
 */
export async function post__aimall_backend_administrator_analyticsDashboards(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAnalyticsDashboard.ICreate;
}): Promise<IAimallBackendAnalyticsDashboard> {
  const { administrator, body } = props;

  // Authorization: Only "active" administrator may create dashboards
  if (!administrator || administrator.status !== "active") {
    throw new Error(
      "Unauthorized: Only active administrators can create dashboards.",
    );
  }

  // Uniqueness: Dashboard code must be unique
  const existing =
    await MyGlobal.prisma.aimall_backend_analytics_dashboards.findFirst({
      where: { code: body.code },
    });
  if (existing) {
    throw new Error("Dashboard code already exists");
  }

  // Generate required fields for insertion
  const now = toISOStringSafe(new Date());
  const dashboardEntity =
    await MyGlobal.prisma.aimall_backend_analytics_dashboards.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        code: body.code,
        title: body.title,
        description: body.description ?? null,
        config_json: body.config_json ?? null,
        created_at: now,
        updated_at: now,
      },
    });

  // All returned fields conform to IAimallBackendAnalyticsDashboard model
  return {
    id: dashboardEntity.id,
    code: dashboardEntity.code,
    title: dashboardEntity.title,
    description: dashboardEntity.description,
    config_json: dashboardEntity.config_json,
    created_at: toISOStringSafe(dashboardEntity.created_at),
    updated_at: toISOStringSafe(dashboardEntity.updated_at),
  };
}

