/**
 * Updates an analytics dashboard configuration by its unique ID.
 *
 * Allows administrative users to update a specific analytics dashboard
 * configuration by its ID. Enforces code uniqueness, validates existence, and
 * updates only allowed fields. Only accessible to administrator-role users
 * (authorization assumed via decorator but can be verified).
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload
 * @param props.analyticsDashboardId - The UUID of the analytics dashboard being
 *   updated
 * @param props.body - Fields to update: code, title, description, config_json
 * @returns The updated analytics dashboard entity
 * @throws {Error} When the dashboard doesn't exist
 * @throws {Error} When the new code is already taken
 */
export async function put__aimall_backend_administrator_analyticsDashboards_$analyticsDashboardId(props: {
  administrator: AdministratorPayload;
  analyticsDashboardId: string & tags.Format<"uuid">;
  body: IAimallBackendAnalyticsDashboard.IUpdate;
}): Promise<IAimallBackendAnalyticsDashboard> {
  const { administrator, analyticsDashboardId, body } = props;

  // [Authorization] - Only administrators allowed; status already checked by decorator (type and status)

  // Find the dashboard by id
  const dashboard =
    await MyGlobal.prisma.aimall_backend_analytics_dashboards.findUnique({
      where: { id: analyticsDashboardId },
    });
  if (!dashboard) throw new Error("Analytics dashboard not found");

  // If code is being updated, check for uniqueness (other than this dashboard)
  if (
    body.code !== undefined &&
    body.code !== null &&
    body.code !== dashboard.code
  ) {
    const existingWithCode =
      await MyGlobal.prisma.aimall_backend_analytics_dashboards.findFirst({
        where: { code: body.code, NOT: { id: analyticsDashboardId } },
      });
    if (existingWithCode)
      throw new Error("Code already in use by another dashboard");
  }

  // Prepare the updated_at timestamp
  const now: string & tags.Format<"date-time"> = toISOStringSafe(new Date());

  // Update dashboard with provided fields only
  const updated =
    await MyGlobal.prisma.aimall_backend_analytics_dashboards.update({
      where: { id: analyticsDashboardId },
      data: {
        code: body.code ?? undefined,
        title: body.title ?? undefined,
        description: body.description ?? undefined,
        config_json: body.config_json ?? undefined,
        updated_at: now,
      },
    });

  // Return object with proper type/branding
  return {
    id: updated.id,
    code: updated.code,
    title: updated.title,
    description: updated.description ?? null,
    config_json: updated.config_json ?? null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: now,
  };
}

