import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Search for and retrieve a filtered, paginated audit trail of log records from
 * the analytics subsystem.
 *
 * Supports field-level querying (event_type, actor_id, event_target, outcome,
 * timestamp, etc), as well as advanced sorting and pagination options for
 * administrator users. Returns atomic log records with pagination.
 *
 * @param props - Request properties
 * @param props.administrator - Authenticated administrator payload (must have
 *   status "active")
 * @param props.body - Audit log query input (filters, date ranges, pagination,
 *   sorting)
 * @returns Paginated list of filtered audit log records
 * @throws {Error} If the administrator is inactive or not authorized
 */
export async function patch__aimall_backend_administrator_auditLogs(props: {
  administrator: AdministratorPayload;
  body: IAimallBackendAuditLog.IRequest;
}): Promise<IPageIAimallBackendAuditLog> {
  const { administrator, body } = props;
  if (administrator.status !== "active") {
    throw new Error("관리자 권한이 없거나 비활성 관리자입니다.");
  }
  const { page, limit } = body;
  const where = {
    ...(body.event_type !== undefined &&
      body.event_type !== null && { event_type: body.event_type }),
    ...(body.actor_id !== undefined &&
      body.actor_id !== null && { actor_id: body.actor_id }),
    ...(body.event_target !== undefined &&
      body.event_target !== null && { event_target: body.event_target }),
    ...(body.outcome !== undefined &&
      body.outcome !== null && { outcome: body.outcome }),
    ...(body.ip_address !== undefined &&
      body.ip_address !== null && { ip_address: body.ip_address }),
    ...((body.start_at !== undefined && body.start_at !== null) ||
    (body.end_at !== undefined && body.end_at !== null)
      ? {
          created_at: {
            ...(body.start_at !== undefined &&
              body.start_at !== null && { gte: body.start_at }),
            ...(body.end_at !== undefined &&
              body.end_at !== null && { lte: body.end_at }),
          },
        }
      : {}),
    ...(body.keyword !== undefined &&
    body.keyword !== null &&
    body.keyword.length > 0
      ? {
          OR: [
            {
              event_type: {
                contains: body.keyword,
                mode: "insensitive" as const,
              },
            },
            {
              event_target: {
                contains: body.keyword,
                mode: "insensitive" as const,
              },
            },
            {
              outcome: { contains: body.keyword, mode: "insensitive" as const },
            },
            {
              detail_json: {
                contains: body.keyword,
                mode: "insensitive" as const,
              },
            },
          ],
        }
      : {}),
  };
  // Always build orderBy as a single-element array for Prisma type safety
  const orderBy =
    body.sort === "event_type"
      ? [{ event_type: "asc" as const }]
      : body.sort === "-event_type"
        ? [{ event_type: "desc" as const }]
        : body.sort === "created_at"
          ? [{ created_at: "asc" as const }]
          : [{ created_at: "desc" as const }];

  const [rows, records] = await Promise.all([
    MyGlobal.prisma.aimall_backend_audit_logs.findMany({
      where,
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
      select: {
        id: true,
        actor_id: true,
        event_type: true,
        event_target: true,
        ip_address: true,
        outcome: true,
        detail_json: true,
        created_at: true,
      },
    }),
    MyGlobal.prisma.aimall_backend_audit_logs.count({ where }),
  ]);

  const data: IAimallBackendAuditLog[] = rows.map((row) => ({
    id: row.id,
    actor_id: row.actor_id ?? null,
    event_type: row.event_type,
    event_target: row.event_target ?? null,
    ip_address: row.ip_address ?? null,
    outcome: row.outcome,
    detail_json: row.detail_json ?? null,
    created_at: toISOStringSafe(row.created_at),
  }));
  const pages = Math.ceil(records / limit);
  return {
    pagination: {
      current: page,
      limit,
      records,
      pages,
    },
    data,
  };
}

