import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe";
import { AdministratorPayload } from "../decorators/payload/AdministratorPayload";

/**
 * Delete a specific audit log entry by unique ID (hard delete).
 *
 * Delete a specific audit log entry from the analytics system by unique
 * identifier. This operation irreversibly removes the audit log from the
 * aimall_backend_audit_logs records (hard delete) since there is no soft delete
 * field, and is intended only for seldom, administratively authorized
 * use-cases. All deletions are performed under strict auditing and
 * authorization to prevent compliance violations.
 *
 * Executions of this operation cannot be undone—the audit log is fully removed
 * and cannot be recovered by any backend API. Suitable only for super-admin
 * roles or compliance-driven manual deletions with full consent. If the ID does
 * not exist or the caller lacks permission, an error occurs.
 *
 * @param props - Object containing the authenticated administrator payload and
 *   the audit log UUID to delete
 * @param props.administrator - The authenticated administrator user making the
 *   request with validated payload
 * @param props.auditLogId - Unique identifier of the audit log record to be
 *   deleted (string & tags.Format<'uuid'>)
 * @returns 삭제 성공시 void 반환
 * @throws {Error} When the audit log record does not exist
 * @throws {Error} When the administrator does not have 'super_admin' permission
 */
export async function delete__aimall_backend_administrator_auditLogs_$auditLogId(props: {
  administrator: AdministratorPayload;
  auditLogId: string & tags.Format<"uuid">;
}): Promise<void> {
  const { administrator, auditLogId } = props;

  // 1. 권한 검증: 'super_admin'이 아닌 경우 거부
  const permission = await MyGlobal.prisma.aimall_backend_permissions.findFirst(
    {
      where: { id: administrator.permission_id },
    },
  );
  if (!permission || permission.name !== "super_admin") {
    throw new Error(
      "Unauthorized: Only super_admin administrators may delete audit logs.",
    );
  }

  // 2. 대상 감사로그 존재 여부 확인
  const auditLog = await MyGlobal.prisma.aimall_backend_audit_logs.findUnique({
    where: { id: auditLogId },
  });
  if (!auditLog) {
    throw new Error("Audit log not found.");
  }

  // 3. 실제 하드 딜리트 수행
  await MyGlobal.prisma.aimall_backend_audit_logs.delete({
    where: { id: auditLogId },
  });
}

