import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { CustomerPayload } from "../../decorators/payload/CustomerPayload";

/**
 * Verifies and authorizes a customer via JWT access token.
 * Handles token authentication, role check, and DB existence/status validation.
 * Throws ForbiddenException for invalid or suspended status.
 *
 * @param request Express.js style request object containing headers
 * @returns The decoded and verified CustomerPayload
 */
export async function customerAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<CustomerPayload> {
  const payload: CustomerPayload = jwtAuthorize({ request }) as CustomerPayload;

  if (payload.type !== "customer") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  // Only valid customers: not deleted, not suspended
  // status field is main validator, e.g., 'active', 'pending', 'suspended', 'deleted'
  const customer = await MyGlobal.prisma.aimall_backend_customers.findFirst({
    where: {
      id: payload.id,
      // Only active customer accounts are authorized
      status: "active",
