import { ForbiddenException } from "@nestjs/common";

import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { SellerPayload } from "../../decorators/payload/SellerPayload";

/**
 * Authenticate and authorize a seller account.
 *
 * Verifies JWT token, validates seller role, and ensures the seller exists and is approved.
 * Throws ForbiddenException if not enrolled or not approved.
 *
 * @param request The HTTP request containing the bearer token in the headers.
 * @returns {Promise<SellerPayload>} The authenticated seller payload.
 */
export async function sellerAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<SellerPayload> {
  const payload: SellerPayload = jwtAuthorize({ request }) as SellerPayload;

  if (payload.type !== "seller") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  const seller = await MyGlobal.prisma.aimall_backend_sellers.findFirst({
    where: {
      id: payload.id,
      status: "approved"
    }
  });

  if (seller === null) {
    throw new ForbiddenException("You're not enrolled or not approved as a seller");
  }

  return payload;
}

